

local __rs={
[1]="你生于一个穷苦的农耕之家，父母识字不过百，因你的父亲姓牛，农村有贱名好养活的习俗，故给你取名叫——{0}。",
[2]="牛马之子",
[3]="你出生于牛马世家。",
[4]="一名算命先生路过村口，见你骨骼惊奇，于是给你算了一卦，随后大惊失色道：你竟是先天牛马圣体！",
[5]="逐渐长大的你开始帮扶农务，你的父母发现，你干得比别人多，吃得比别人少，比家里的老黄牛还要吃苦耐劳，高兴地夸你真是好牛马。",
[6]="你长成了一名身强力壮的小伙子，为了给家里赚钱，你开始到地主家打工搬砖，一天若搬不够一万块砖，还要倒赔钱给地主家。",
[7]="今天你又搬了一万多块砖，可地主一口咬定你只搬了一千块砖，你想要自证清白，除非再搬一次给他看，否则就老老实实赔钱。",
[8]="当年那位算命先生回来了，称附近的宗门正缺一名先天牛马圣体的杂务弟子，问你愿不愿跟他去给宗门做牛做马",
[9]="招募杂务",
[10]="答应前去",
[11]="婉言拒绝",
[12]="你跟着算命先生来到一处仙门，恭恭敬敬地拜师成为一位杂务弟子。你看到算命先生从师父手中领了一笔银子，还叫你过来帮忙数一下看看数目对不对。",
[13]="你的师父安排你去开垦灵田，你花了大半天方才完成，可是师父回来瞥了一眼，说你挖得太深了，赶紧重做。",
[14]="一群同门师兄弟御剑从你头顶上飞过，你看着十分羡慕，不知什么时候能够轮到自己？",
[15]="某天你不幸在工作中受伤，想找师父讨两颗丹药疗伤。师父却说，丹药是给人吃的，不是给牛马吃的，把你赶了出去。",
[16]="你发现宗门里的狗吃得都比你好，找师父要求改善伙食。师父拿起狗吃剩的饭盘扔到你的脚下，说：“给，改善伙食了吧”",
[17]="你要求师父给你传授一点功法，结果师父听了笑个半死，简直要笑出内伤，吃了两颗疗伤丹方才好转。",
[18]="某天宗门有一条蛟龙来袭，师父给你发了一把草叉说：“你去把蛟龙除掉”，你不禁疑惑道：“我打蛟龙？诶...真的假的？”",
[19]="蛟龙来袭",
[20]="去打蛟龙！",
[21]="逃离宗门",
[22]="你冲向蛟龙，却被蛟龙一口气吐死了。",
[23]="机灵的你，趁着蛟龙作乱顺利逃离了宗门。",
[24]="你拿着草叉义无反顾地冲向蛟龙，结果蛟龙只是轻轻吐了口气，你整个人就被吹风出去，就此失去知觉",
[25]="你假装操起草叉向蛟龙冲去，在中途就一个急转弯，趁着蛟龙作乱顺利逃离了宗门",
[26]="你回到家乡，假称自己学成归来，如今已经是个仙人了。父老乡亲皆表示热烈欢迎，希望你能带他们一起鸡犬升天。",
[27]="你假装自己学会了算命，到处给人算命，看到曾经和你一样的人，就装作惊叹一句：”你竟是先天牛马圣体！“",
[28]="你学着师父的样子画符纸，得益于你的字特别丑，画出来的鬼画符竟然还有模有样，骗过了不少人的眼睛。",
[29]="恰逢大旱，人们纷纷来求你祈雨。你站在田里念经，念了三天三夜，就在你即将气绝之际，上天竟然真的下雨了。",
[30]="你给自己取了个道号叫”牛马大仙“，真是朗朗上口，你不禁怀疑，难道自己真是天才？",
[31]="当初让你搬砖的那名地主找上门，恭恭敬敬地称你一声大仙，并希望把女儿嫁给你，不知你意下如何？",
[32]="地主嫁女",
[33]="欣然答应",
[34]="断然拒绝",
[35]="你高兴地答应下来，迎娶了地主家的女儿，从此过上了大富大贵的生活",
[36]="你断然拒绝，还把地主给轰了出去。地主从此对你怀恨在心，从此你在此地不得安生，只能匆匆逃离",
[37]="成为地主家的一员后，你每天的生活就是混吃等死，衣来伸手饭来张口，好不快活。",
[38]="你找到了几个和你一样的先天牛马圣体的年轻人，让他们给你搬砖，每天都要搬完一万块砖，否则还要倒赔钱给你",
[39]="你通过强取豪夺拿下来不少穷人的土地，让他们连田都没得种，被迫给你当包身工，借此获利颇丰。",
[40]="恰逢灾年，父老乡亲来找你借粮，你只是回了一句：“地主家也没有余粮啊。”",
[41]="听说家里的老黄牛死了，你赶紧跑回家，含泪吃了三大碗，感叹道——牛肉真好吃。",
[42]="你觉得当地主来钱还是太慢了，为了更好的敛财，你想出一个点子，建立一个假宗门，以仙人的名义大肆敛财",
[43]="假建宗门",
[44]="说干就干",
[45]="还是作罢",
[46]="你在附近的一座山上建立了一处宗门，自称开山祖师，到处广招弟子，主要就收和你一样先天牛马圣体的人",
[47]="成为宗门师父之后，你捞钱的名目更多了，手下还有一大群弟子给你做牛做马，好不快活",
[48]="某天一群真正的仙人从宗门上空飞过，你便告诉所有弟子，这些人都是你教出来的，都是你们的师兄弟",
[49]="你以开垦灵田为由，让手下的弟子替你开荒拓土，然后把开垦好的土地卖给地主赚钱",
[50]="你建了一个炼丹房，假模假样地炼出几个“仙丹”，声称有活死人生白骨之效，但从来没有让人吃过",
[51]="你收买了许多算命先生，让他们到处寻找先天牛马圣体的人，带到宗门来收为弟子",
[52]="你看到了仙人，仙人引你踏进修仙之路",
[53]="一日在睡梦之中，你忽然感到好像有人在喊你，那个声音熟悉而又陌生，好像是曾经的你自己",
[54]="谁人唤我",
[55]="睁开双眼，直面自我",
[56]="不要放弃你的梦，继续睡！",
[57]="很不幸，你死了",
[58]="此生已了",
[59]="忽然你从梦中惊醒，发现自己睡在一个草堆之中，旁边还躺着你家的老黄牛。原来那位算命先生没有回来，之前经历的一切都只是南柯一梦，如今你又该起床出去搬砖了。",
[60]="你努力搬砖多年，却始终未能有半点积蓄，想要回家种田，家里的田也被地主强取豪夺走了。某日你忽然积劳成疾，两眼一黑，便草草结束了牛马的一生。",
[61]="南柯一梦",
[62]="今日无事，勾栏听曲",
[63]="你诞生在普通的农户之家，爹娘都是老实人，亲戚挺多，爷爷也还健在。你的大名是爷爷起的，叫{0}。村里都说贱名好养活，你娘就给你起了个小名叫狗剩。",
[64]="农户之子",
[65]="你出生于农户之家。",
[66]="从不挑食的你给啥都吃，吃啥都香，结实得像头小牛犊。",
[67]="你在家门口看到一条大蜈蚣，竟然像条小蛇那么大，连忙拿起石头就砸！没想到一下没砸死，蜈蚣正朝你爬来时，邻居家猎户的孩子大壮也冲了出来，用一块大石头用力压死了差点咬到你的蜈蚣。自此，你们成为了好朋友。",
[68]="你爹拎了一袋好米和一只肥鸡，带着你敲开了村东头那位老儒生的家门，让你每日过来念书识字。你决定……？",
[69]="念书识字",
[70]="认真念书",
[71]="勉强应付",
[72]="你深知有机会念书识字十分不易，所以非常珍惜每日念书识字的时间。老儒生看你勤奋好学，也十分欣慰，除了书本上的知识，还教了你不少道理。",
[73]="比起念书，你还是更喜欢跟爹下田，或者去山上砍柴时顺便玩一玩。但是老儒生为人严厉，你只能每日老实完成对方布置的课业，但绝不愿意多看一个字。",
[74]="你跟着村里的几个大孩子去掏马蜂窝，被蛰了一头包。爹娘急忙去找村医给你拿药，给你上完药后紧接着就是一顿胖揍。",
[75]="你和大壮相约在山间玩耍。大壮去摘野果，你馋鱼肥，想要捞两条鱼解馋，却意外在小溪中摸到一枚晶莹剔透的石头，你十分喜欢。正好此时大壮拨开树丛向你跑来，要告诉他吗？",
[76]="晶莹剔透的石头",
[77]="告诉对方",
[78]="一声不吭",
[79]="大壮也很喜欢这枚石头，用你心心念念的竹弓把石头换走了。你对这把竹弓爱不释手，有空时就拿出来把玩，打飞虫打小兔，一来二去的，好像力气也大了一些。",
[80]="你觉得这也许就是大人说的“宝石”，数量只有一个的宝贝是不能随便分享的……你这么想着，悄悄地将它放进了兜里。",
[81]="今岁丰年，收成极好。全村都喜气洋洋，你也得帮家中收割粮食，天天在烈日下忙碌抢收，几乎晒成黑炭。",
[82]="你跟随爹娘去集市采买，食物的香气让你连咽口水。你娘看你馋，给你买了个夹了葱肉馅的煎饼，香得你这辈子都难以忘怀。",
[83]="在你生辰那日，爷爷给了你一本泛黄的小册子，里面记载着一些关于种植的经验总结，爷爷语重心长地叫你认真翻阅。你决定……？",
[84]="泛黄的小册子",
[85]="认真翻阅",
[86]="随便看看",
[87]="爷爷的叮嘱令你认真起来。闲暇时，你认真翻阅这本册子，从中学到不少种植相关的方法，对田地和土壤又有了进一步的了解。",
[88]="不就是一本农书？从书里学种田的经验，还不如多下几次田，多问问村老们。你这么想着，只是随便看了看便把这册子抛之脑后了，反倒是下田干活愈发勤快了起来。",
[89]="跟着爹娘下田干活也有几年了，你日渐熟练，已经可以帮家里分担很多农活。",
[90]="你被爷爷告知，家中代代为仙人培育一种仙草，到你爹已是第八代了。如今你爹年事已高，恐怕难以担当那仙草的种植所需，需要你接过这个培育之责了。",
[91]="成年之路",
[92]="你接过责任，成为培育仙草的第九代继承者。",
[93]="你看到培育这株仙草的秘田时，仙草已经微微破土，你觉得很快就能培育好仙草了。",
[94]="爹说仙草每天需要大量的水，你要每天挑3个时辰的井水来浇灌它。你在秘田与村中的井之间往返，好累。",
[95]="爹说仙草不是很耐寒，你要每天劈3个时辰的柴火，用来为仙草保持合适的温度。冬天的你劈了三千担柴，好累。",
[96]="爹说仙草不是很耐热，你要每天扇风3个时辰，来给它降温。夏天的你晒成了黑炭，脱了几层皮，手都要扇脱臼了，好累。",
[97]="你觉得自己这一代应该是看不到仙草长好了，有些失落，挑水都洒了两次。",
[98]="你每天只花2个时辰来挑水了，舒服了不少，也有闲心和村里人打趣了。",
[99]="你在冬天只花两个时辰去砍柴烧柴了，轻松了很多，也有时间在农忙时给邻里乡亲搭把手了。",
[100]="你在夏天只花两个时辰给仙草扇风了，省力了许多，有能力思考自己的未来了。",
[101]="你觉得仙草好像比之前要长高了一些，你非常兴奋，白天走路都笑出了声。",
[102]="你觉得仙草好像比之前要长高了一些，你非常兴奋，晚上睡觉都笑出了声。",
[103]="你觉得仙草好像比之前要长高了一些，你非常兴奋，去茅房蹲坑都笑出了声。",
[104]="仙草真的变高了！甚至开始长出了小的花苞！难道有生之年，自己竟然能看到仙草彻底长成的样子吗？",
[105]="你更积极地挑水，用来浇灌仙草。每天要挑四个时辰的井水。",
[106]="你把铺盖都挪到了秘田边，每天一睁眼就开始悉心照料仙草。冬天要砍四个时辰的柴火，夏天要扇四个时辰的风。",
[107]="你每天连睡觉吃饭的时候都要省着用来培育灵草，你越来越晕，走路像飘，食不知味。终于，你过劳死了。",
[108]="用力过猛",
[109]="培育仙草时用力过猛，你因此过劳而死。",
[110]="你严格遵循祖训，保持了一样的培育措施，持续了很多年。",
[111]="平平无奇的一天，你早上起来，一如既往地去秘田劳作时，发现仙草终于开花了。",
[112]="已经开花的仙草旁边站着一位身着白衣之人，气质非凡，他用欣慰的目光看向了你……",
[113]="你忐忑地上前攀谈，方才得知，这仙草的幼苗正是这位白衣仙人赠与先祖的宝物，其实并不需要特别长的年月也可成熟开花，可惜之前的每一代人都没有严格遵守祖训，时至今日才开出花来。",
[114]="仙草看起来十分普通，却十分娇贵，你十分不解，却还是十分认真地培育它。",
[115]="春夏多雨多虫，你意外发现仙草附近竟然没有蚊虫出没，不由得在培育仙草的秘田待得更久了。",
[116]="通往秘田的小路两旁有许多树丛和藤蔓，在秋天结满了五颜六色的浆果。你每日往返时都会摘上许多，吃得很是畅快。",
[117]="看着你每日悉心照料仙草，你爹非常欣慰，亲自去镇上找最好的铁匠给你打造了趁手的农具。",
[118]="看着你每日悉心照料仙草，你爹非常欣慰，嘱咐你娘每天给你的伙食多加两个鸡蛋。",
[119]="你下午有空四处闲逛了，可以去邻村围观别人斗鸡了。",
[120]="你中午有空睡午觉了，睡醒还能去村医家讨一杯明目健气的药茶喝。",
[121]="你晚上有空遛弯了，还能时不时去大壮家蹭一顿饭，一起喝上两杯酒。",
[122]="你每天早上来到秘田，都会笑眯眯地叮嘱仙草好好吸收，快快生长。",
[123]="你每天晚上离开秘田，都会笑眯眯地叮嘱仙草好好休息，第二天快快生长。",
[124]="你每天都会给仙草松土，方便它的根须舒展。",
[125]="你每天都会给仙草擦拭叶片，保证它的草叶干净无尘。",
[126]="你梦里都想着培育仙草，在梦里持续着白天的劳作。",
[127]="家人让你在农忙时搭把手，都被你拒绝了，你只肯一心一意地培育仙草。",
[128]="已经过了很多年了，但是仙草一直都没有变化，你决定……？",
[129]="一成不变的仙草",
[130]="摆一点烂",
[131]="继续努力",
[132]="你觉得可以稍微偷一点懒。不多，就一点点。",
[133]="毕竟是代代相传的使命，还是再坚持些年月吧！",
[134]="这辈子只为了这棵不一定有希望的草而努力，未免有些太浪费了，你决定……？",
[135]="思考未来",
[136]="让后辈替代自己",
[137]="继续奋斗",
[138]="你不再费心培育仙草，回归正常的农户生活，娶妻生子，一生很快就过去了。",
[139]="有志者事竟成！你决定继续奋斗，坚持一下说不定就有转机呢？",
[140]="仙草居然有了这么大的变化，你觉得自己的努力是有回报的，你决定……？",
[141]="努力的回报",
[142]="更加努力",
[143]="按照祖训来",
[144]="再弱小的小草也会有长成参天大树的那天！",
[145]="循规蹈矩，日复一日",
[146]="白衣仙人使了个术法将那灵花摘下交给你，告知你此花能起死回生，千年不腐。你将花收好后，仙人问道：“我看你性格坚毅，且身具灵根，是个修仙的好苗子，可愿意随我修行？”你决定……？",
[147]="仙人授法",
[148]="答应修仙",
[149]="摇头婉拒",
[150]="踏上仙途",
[151]="你成功让仙草开花，由此踏上仙途。",
[152]="这天大的机缘砸在头上，怎能错过！你当即行了拜师之礼，匆匆与家人告别后，跟着仙人离开了你出生的小村庄。",
[153]="你这辈子费了很多功夫，只会和这田地打交道，自认没什么修仙的慧根，还是婉拒了对方。对方也不强求，一转眼就消失不见了，令你暗暗称奇。你回归正常的农户生活，一生很快就过去了。",
[154]="你看到了仙人，仙人引你踏进修仙之路。",
[155]="你在家中收拾农具，突然眼前一阵发黑，有些喘不上气。你意识到或许是大限将至，此时一抹虚幻的玄妙身影出现在你的面前，说与你有缘，可赠你一枚寿元丹续命。你决定……？",
[156]="大限将至",
[157]="吞服仙丹",
[158]="不为所动",
[159]="你求生欲望强烈，决定冒险一试。随着丹药的吞服，你只觉得一股神秘之力充盈全身，又能多活一些年岁。",
[160]="你只觉生死有命，婉拒了神秘身影的好意，坦然面对此生的终点。",
[161]="你这一代依旧没能让这株仙草成熟，你一边感到遗憾，一边将祖训一五一十的告知了你的后辈，或许未来你的后代中能够有配养出这株仙草的人吧。",
[162]="代代相传",
[163]="培育仙草之责代代相传，你寄望后人能够成功。",
[164]="这一生儿孙成群，仙草育成，你已无遗憾。那朵奇花被你当作传家之宝交给了儿子，欣慰地含笑而终。",
[165]="寿终正寝",
[166]="这一生儿孙成群，仙草育成，你已无遗憾。",
[167]="田间辛勤劳碌一生，终是生死有命，已行至尽头。",
[168]="日出而作日落而息，春耕秋收，光阴似水，终是一世尘缘已尽。",
[169]="今日无事，勾栏听曲。",
[170]="你诞生于一户颇有名望的富农之家，是个男孩。因为出生时东边天空有红色霞光，而得名{0}。",
[171]="家中条件甚好，你不愁吃穿，被养得很壮实。",
[172]="爹娘很重视你的成长，请了两位各有所长的先生到家中，专门教你读书。你年纪虽小，却也有自己的偏好……",
[173]="读书的偏好",
[174]="偏爱诗书兵法",
[175]="偏爱传说奇谈",
[176]="你竟不觉得诗书和兵法枯燥，学得十分认真，令先生大感惊讶的同时也十分欣慰。",
[177]="虽然你对诗书兵法的学习十分认真，但却常常缠着先生给你多讲些仙人传说奇谈之类的故事，听得一知半解，也兴趣浓厚。",
[178]="从小你便表现得聪明伶俐，熟读诗书，双亲希望你将来能考取功名，让家族更进一步。",
[179]="你闲暇时也爱看话本，行侠仗义的江湖侠客、运筹帷幄的安国将军之类的故事让你沉迷不已。",
[180]="你在村里玩了许久，天黑时正准备回家，却意外发现村头李家的小儿子阿福被几个小孩欺负。大宝经常进山摘好吃的野果分给你，你有心帮他一把，决定……？",
[181]="被欺负的阿福",
[182]="以理服人",
[183]="装神弄鬼",
[184]="你冲过去大喊：“不可欺人，官差会来抓了你们的！”几名劣童被你吓到，四散逃走，你把阿福送回家并告知了他爹娘此事，他娘感激地给你塞了一篮子鸡蛋作为谢礼。",
[185]="你扯了一把干枯的树枝，躲在巷口发出奇怪的叫声。树枝的影子在昏暗的光线下显得诡异渗人，吓得几个劣童一边喊着“有鬼啊”一边屁滚尿流地逃走了，你连忙上前扶起阿福，把他送回了家。",
[186]="你已经不能满足于书本上的知识，让爹娘请了有经验的师傅，开始学习骑马和武艺。",
[187]="今年生辰，你爹娘答应满足你一个愿望。你心里有两个想法，最终决定……？",
[188]="生日愿望",
[189]="一把宝剑",
[190]="一笔钱财",
[191]="你不假思索地说出了想要一把宝剑的心愿。你爹虽然有些惊讶，但还是爽快地答应下来，特地带你一同去城里最好的铁匠铺打造了一把利剑。只是你年纪尚小，想要熟练使用这把剑，还得再等几年。",
[192]="你开心地要了一笔钱，爹娘虽有不解，还是答应了你。第二日，你便带着下人去城里买回了大批话本和各种诗书、兵法典籍，爹娘看你如此好学，十分欣慰。",
[193]="你在武艺和骑术上的天赋普普通通，但是对兵法计谋却领悟极快，与先生辩论时经常语出惊人，令其称赞。",
[194]="你爹进城办事，你非要跟着一起去。但你爹忙碌，无暇照顾你，便给了你一些零钱，让下人陪你四处走走逛逛。你决定……？",
[195]="进城办事",
[196]="去吃顿好的",
[197]="去坊市闲逛",
[198]="你带着下人去了城里的一处小酒楼，计划用爹给的钱吃点平时没吃过的好东西。正好酒楼今日有说书人讲故事，你津津有味地边吃边听，竟学到不少道理。",
[199]="坊市之中，小摊一个接一个，杂货繁多，令人目不暇接，你一摊一摊逛过去，只觉得啥都有意思。半途中，有个老乞丐冲你鞠躬乞讨，你心软地给了对方一枚铜板，对方连连道谢，嘴里叨叨着：“小少爷一定会有好运的。”",
[200]="你努力打磨自身，做好了各种准备，决心成年就去考取功名，为家族增添荣耀。",
[201]="可惜事与愿违，你的成年宴刚举办不过三日，一群山匪突然闯入村中烧杀掳掠，你决定……？",
[202]="山匪劫掠",
[203]="弃明投暗",
[204]="拼命逃离",
[205]="成年抉择",
[206]="为保性命，你被迫与山匪为伍，落草为寇。",
[207]="为保性命，你被迫逃离家乡，沦落成乞丐。",
[208]="这伙山匪凶悍，不是你们农户之家可以抵抗的。眼见村中众人倒在血泊之中，你为了保全众人性命，决定加入山匪，落草为寇。",
[209]="山匪强势，一路烧杀抢掠，很快就冲入了你家。情急之下，你的族人和你爹娘拼尽全力也只能将你送出，你别无他法，只能拼命逃离。",
[210]="山匪们本打算杀光你的家人，可你力排众议，带着家人与能打的长工加入了这批山匪，时过数年，你已经当上三当家。",
[211]="饱读经书的你为山匪们出谋划策，让组织越发壮大，逐渐在周围打响了名号，就连大夏朝廷都听闻了你们的名号。",
[212]="你带队袭击一处村庄时，有一位村长声称愿意用传家之宝换取自己的性命。他献上了一颗闪烁着星光的宝石，你冥冥中感到这并非凡物，将其作为传家之宝珍藏起来。",
[213]="你频繁地为大当家肆意屠杀村庄百姓而擦屁股，心中已有不满。",
[214]="你时常为二当家在小城中挑选外表艳丽的女子做妾，心中不满。",
[215]="一日，你在山顶眺望周围的地形，规划寨子接下来的进攻方向时，突然瞧见两道弧光在空中闪烁，一道形如雷电，一道则形如红霞，飞快地从天的东边划过西边。你震惊不已，莫非，这是仙人踪迹？",
[216]="你在一次袭掠时遇见了一位美丽的女子，你从大当家的屠刀下救下了她，还因此与二当家大吵一架。你与她结为夫妻，此后还生下了几个孩子。",
[217]="你的长子在一次与官兵的冲突中死于乱箭之下，令你非常心痛，仿佛瞬间苍老了十岁。",
[218]="你一看镜子，原来自己已经步入中年，不再年轻了。",
[219]="你的爹娘天寿将尽，你带着他们回到了儿时的村落。两日后，双亲安详而去，你却心中悲苦。",
[220]="你听说朝廷有招安山匪的意向，抗拒朝廷的大当家与想被招安的二当家为此事激烈的争吵起来，你虽然表面不动声色，但内心还是想起了父母对自己的期望。",
[221]="朝廷似乎调动了更多的军队，双拳难敌四手，在某一场战斗中，总是身先士卒的大当家战死后，你意识到了自己已经陷入了死局。",
[222]="你将传家之宝交给了已经成年的孩子，让他们赶紧逃离山寨，这里很快就会变成战场。",
[223]="大当家带队成功劫了一批富商的货，你也随行其中，检查时发现这批宝贝多得差点没闪瞎大伙的眼睛。你趁众人不注意，偷偷昧下数坛好酒独享。",
[224]="夏季多雨，寨子里蚊虫众多。你不堪其扰，找了个时间进城直奔药堂，差点搬空人家半个库房，配了大量的驱蚊虫的药囊回来，寨子里的兄弟们都对你十分感激。",
[225]="大当家寿宴，你送上的宝剑比二当家送的玉佛更讨大当家欢心，大当家高兴得赏赐了你许多金银，引得二当家眼红。",
[226]="你去城中办事时路过一个卖杂书的小摊，鬼使神差地停下了脚步。你在一堆有些破旧的杂书中找到了几本兵书，翻了翻，内容竟颇为合意，便掏钱买了下来。",
[227]="你与二当家下棋，假意棋差一招输给对方，再动动嘴皮吹捧几句，把二当家哄得飘飘欲仙，怎么看你怎么顺眼。",
[228]="你带队抢到了一大批今年的新粮，正和弟兄们美滋滋地往寨子运，突然乌云遮日，朗朗晴空变作暴雨倾盆，淋湿了大半粮食，当真晦气。",
[229]="临近年关，寨子里举办宴会，热闹了三天三夜，大都喝得酩酊大醉。不知哪个烂醉的混球不小心撞翻了火把，差点把半个寨子烧了，万幸你喝得不多，被浓烟呛醒，吼醒众人及时扑灭了大火。",
[230]="你时常把玩那颗闪烁着星光的宝石，但未能发现它有什么神异之处，你对此物的热情也逐渐消散，你决定……？",
[231]="闪烁的宝石",
[232]="找个机会卖了它",
[233]="放入宝库，不再关注",
[234]="你打算找个机会将这颗奇异的宝石出手，但这寨子里可没啥识货的家伙，只得暂时作罢",
[235]="你对这宝石没了兴趣，便把它扔进了自己的私藏宝库里，渐渐把它忘之脑后。",
[236]="你的长子逐渐长大，如今已经能帮得上你的忙了，要让他在寨中担任什么样的职务呢？",
[237]="长子的职务",
[238]="身先士卒",
[239]="出谋划策",
[240]="长子不似你这般聪慧，倒是有一身好力气，可领人冲锋。",
[241]="长子聪慧如你，正可分担出谋划策之事。",
[242]="大当家与二当家的矛盾随着地盘的扩大而变得激烈，恐怕此处已经不再是合适的容身之地，你决定……？",
[243]="激烈的矛盾",
[244]="接受招安 [聪慧判定]",
[245]="拒绝招安",
[246]="接受招安",
[247]="举旗造反",
[248]="你接受朝廷的招安，成了一名县令。",
[249]="你与大当家举旗反旗，对抗朝廷。",
[250]="<color=#549327>[判定成功]</color> 你和二当家一起杀了大当家，以大当家的头颅作为投名状，接受了朝廷的招安。朝廷分散安置了接受招安的山匪，给了你个偏远县令的清闲官职。",
[251]="<color=#c82c2c>[判定失败]</color> 你和二当家准备接受招安的谋划不知怎么走漏了风声，在大当家的威胁之下，你被迫与之同流合污，一起对抗朝廷。",
[252]="你杀了想要被招安的二当家，与大当家一同对朝廷掀起了反旗。",
[253]="用那颗传家之宝的宝石，能否让官军放过自己？",
[254]="传家之宝",
[255]="献上宝石 [聪慧判定]",
[256]="死战到底",
[257]="绝处逢生",
[258]="造反失败",
[259]="献宝换命，你以招安的身份成了个清闲县令。",
[260]="造反失败的你，落得个问斩的下场。",
[261]="造反失败的你，落得个乱箭穿心的下场。",
[262]="<color=#549327>[判定成功]</color> 一番打点之后，宝石被递到了负责此事的上官手中。对方深感此宝不凡，大为满意，便设法保下了你一条命，让你以接受招安的形式得了个偏远县令的清闲官职。",
[263]="<color=#c82c2c>[判定失败]</color> 小鬼难缠，你没能说服官兵让你面见上官，战败被俘后，只能在冰冷的牢狱中等待死亡的到来",
[264]="生死看淡，不服就干，大不了十八年后又是一条好汉！",
[265]="朝廷如你所料的给予了你们一官半职，你实现了小时候的愿望，过上了悠闲自在的生活。",
[266]="岁月如梭，你膝下子女成群，安度晚年。",
[267]="有一天，你的一个小孙子偶然闯入家中宝库，从一众宝物里挑出那颗闪烁着星光的宝石，来问你是什么，你才意识到你并未给它取过名字。",
[268]="春季出游登高，你攀爬许久，站到山顶俯瞰山下，不禁喊出“吾辈岂是蓬蒿人，鸿鹄有志尽高飞”，只觉得心中无比畅快！",
[269]="途径一寺庙，你眼见一名壮硕和尚用左手向下抱住树干，右手抓紧树的上半截，腰往上一挺，竟将大树连根拔起，附近一众泼皮吓得跌坐在地。你暗自惊叹，何时自己也能有如此体魄。",
[270]="你看人的眼光毒辣，亲自挑选了一名务实的主簿，再招了一批勤快机灵的衙役。手下人办事周全，让你甚是满意。",
[271]="你去坊市买东西，意外发现坊市的管理混乱，不利于长期发展。回去后，你专门整理了适合的规则，给坊市立下规矩，没过多久坊市就比先前热闹了数倍，来往的客商越发多了。",
[272]="现在的官职还是太小了，你想起了那颗闪烁着星光的宝石，把它赠与自己相熟的高官，或许还能让自己更进一步？",
[273]="献上宝石",
[274]="不献",
[275]="或许是看不起你的出身，这珍贵的宝物最后只是令那高官笑着赞扬了你一句。",
[276]="无事献殷勤，万一惹人反感岂不是得不偿失？你这么想着，还是作罢。",
[277]="现在的生活虽然并不窘迫，但是拿无用之物换些钱财来，或许是好的，你决定找个路子将这颗宝石出手。",
[278]="无用之物",
[279]="找个当铺",
[280]="问问熟人",
[281]="卖掉宝石",
[282]="当上县令的你找了个当铺，随手把宝石卖了。",
[283]="当铺管事见了此物，也只觉得有些稀罕，出了个不高不低的价格。你亦无所谓，随手便卖了。",
[284]="在你前往拜访城中一位富商的路上，迎面撞上了一位赤袍道人，此人声称愿意为你算上一卦。你决定……？",
[285]="赤袍道人",
[286]="算一卦",
[287]="不予理会",
[288]="赤袍道士",
[289]="路遇赤袍道士，宝石变作敲门砖，你得以踏上仙途。",
[290]="路遇赤袍道士算卦，你不曾理会，还是将宝石卖了。",
[291]="这赤袍道士掐指一算，竟然将你一生经历娓娓道来，并愿意以你手中宝石为交换，将你带回其所在的仙宗，给你一个弟子身份。你心知此等仙缘恐怕百年难遇，当即行了弟子礼，将那颗宝石献上，得以踏上仙途。",
[292]="你没有理会道士，拜访富商之后便找了个当铺将宝石卖了。",
[293]="失去了一切的你一路来到了最近的一处城镇，举目无亲且身无分文的你没过多久就只能以乞讨为生。",
[294]="你在东城区的市场里乞讨，每日能得到些烂掉一半的瓜果蔬菜，堪堪能够果腹。",
[295]="你在东城区的市场里乞讨，被市场里的摊贩赶走，饿了好多天。",
[296]="你在西城区的酒馆前乞讨，偶尔能得到好心人的打赏，堪堪能够果腹。",
[297]="你在西城区的酒馆前乞讨，被酒馆的小二赶走，饿了好多天。",
[298]="你在南城区的住宅前乞讨，偶尔有些大娘给你一些吃食，堪堪能够果腹。",
[299]="你在南城区的大道边乞讨，被巡逻的官差赶走，饿了好多天。",
[300]="你在北城区的大桥上乞讨，偶尔有好心的公子小姐路过，给你几枚铜板，堪堪能够果腹。",
[301]="你在北城区的大桥上乞讨，这里常有贵人的马车经过，你在饥饿之际没有即时注意到，悲惨地死在了马蹄之下，留下一阵嘲笑声。",
[302]="死于蹄下",
[303]="你在乞讨时被马蹄踩死，结束悲惨的一生。",
[304]="你在这样的生活中，逐渐摸索出了独特的乞讨方式，找到了活下去的方法。",
[305]="乞讨大师",
[306]="四方乞讨顺利的你，成为了精通乞讨的大师。",
[307]="已经成为乞讨大师的你，学会了认出什么样的人才可能乞讨到东西，已经很久没有饿过肚子了。",
[308]="你作为乞讨大师的名声逐渐让丐帮也有所耳闻，他们盛情将你奉为了丐帮长老。",
[309]="丐帮长老",
[310]="乞讨大师声名远扬，你被奉为丐帮长老。",
[311]="衣衫褴褛的你经过卖馄饨的摊子，闻到香味，不由自主地咽了下口水，店主却皱眉捏着鼻子让你赶紧走开。",
[312]="今夜电闪雷鸣，大雨瓢泼，你好不容易在一处小巷中找到能容身的角落蜷缩着，希望自己不会被淋得太狼狈。",
[313]="有个孩童走路时不小心弄掉了大半个肉包子，你和一条流浪狗同时发现，一番惨烈争斗后，你艰难地吃上了不完整的包子。",
[314]="你在垃圾堆里发现了一条手链，不料被旁边几个乞丐看到，对你一顿拳打脚踢后，嚣张地抢走了那条手链离开。",
[315]="你看到有个乞丐在街上鬼鬼祟祟地行窃，不由得出声喝止，不料失主和路人却把你当成了那乞丐的同伙，害你莫名挨了一顿揍。",
[316]="有个老乞丐热情地邀请你加入他们，你差点就答应了，还好及时发现他们打算将你卖给别人为奴，你慌忙躲得远远的。",
[317]="连着两天没吃到东西的你实在太饿，晕了过去，迷糊中你感觉有人一直在亲自己，睁眼却发现竟是一条脏兮兮的黑狗在舔你。",
[318]="你看着地上的破碗发呆，突然有个人往你的碗里放了个包子。你激动地拿起包子狼吞虎咽，抬头时却怎么也看不清那人的背影。",
[319]="今年的寒冬特别冷，夜里，你蜷缩在一间破屋角落，找了些干草勉强盖在身上御寒。睡前你还在想明天怎么度过，却没想到却一睡不醒……",
[320]="一睡不醒",
[321]="饥寒交迫，遍体鳞伤的你，就此一睡不醒。",
[322]="你成为丐帮长老，每日都有丐帮小弟给你奉上吃食，过得很是逍遥。很快你便得意忘形了起来，不料大意之下，被一个心怀歹意的弟子献上的一只烧鸡给毒死了。",
[323]="你发现一户富商每月十五都会举行宴会，宴后吃不完的食物都会从后门运出扔掉。于是你每逢十五便去蹲点，运气好时不需与人争抢也能吃顿饱饭。",
[324]="趁着大雨，你找了个无人的角落痛快地洗了个澡。低头时无意中在水洼看到自己瘦得脱相的模样，你难过得流下了眼泪。",
[325]="风和日丽的一天，无所事事的你爬到一处小山坡上晒太阳。温和的阳光洒在身上十分舒服，你不禁回想起童年的富足生活，有一种恍如隔世之感。",
[326]="今天初一，听闻城外的普渡寺要施粥一日，你早早就赶了过去，排在前头得了碗飘着菜叶的热粥，吃得十分满足。",
[327]="辛苦乞讨一整天，只得了半个馒头。你疲惫地来到一座破庙准备睡觉，看到月光照在落满灰尘的佛像上，鬼使神差地就朝着佛像拜了三拜。",
[328]="让我吃顿饱饭吧……你含糊地念叨着，也不知道佛祖听见了没有。",
[329]="难得睡了个好觉，你第二日刚出破庙，就碰到一户富家小姐在街口施粮。你连忙过去排队，领到了两个热腾腾的大肉包，不禁在心里说了句多谢佛祖。",
[330]="<color=#3375c0>[机缘判定]</color> 你还是坚持继续修炼下去，又过了数个月，你发现……",
[331]="<color=#549327>[判定成功]</color> 你的身体里似乎有一股气息流转，令你感觉暖洋洋的。",
[332]="<color=#c82c2c>[判定失败]</color> 你还是什么都没有感觉到，这本书里的内容对你没有任何意义，你终于下定决心不再继续修炼，再次回到了乞讨之外无所事事的日子。",
[333]="风和日丽的一天，你转过熟悉的街角，竟再一次遇到了那名道士，他非常惊讶于你居然已经练出了气，欣喜地带你前往了他所在的宗门。",
[334]="风和日丽的一天，你转过熟悉的街角，竟再一次遇到了那名道士，他热情地询问你是否有照着书籍上的法诀修炼，你无奈地说起自己练了大半年都毫无作用，这书大概是乱写的吧。",
[335]="不料那道士听罢，竟瞬间变了嘴脸，嘲讽你毫无慧根，活该做一世乞丐。言毕，对方竟在你眼前瞬间消失了。到了此时，你哪还不知道自己遇到了仙人，却没能把握住机会……你直愣愣地呆站了许久，直到天黑才摇摇晃晃地离开了……",
[336]="你自此变得浑浑噩噩，不再努力乞食，反而每日念叨着：为何我没有慧根……为何不是我成仙……没过多久，你便郁郁而终，死在了一个无人在意的阴冷角落里……",
[337]="郁郁而终",
[338]="你身怀功法却不得窍门，终至郁郁而终。",
[339]="你最近总是频繁的饿肚子，再这样下去就要饿死了，你决定……？",
[340]="加入丐帮",
[341]="学会识人",
[342]="加入了丐帮之后，虽然有人教你如何乞讨，但是也被强制要求上交大部分的乞讨所得。最初你曾认为自己找到了新的家人，但有一天你没能乞讨到足够的财物，被打断了一条右腿。难以移动的你反而更加依赖于其他丐帮弟子的帮助，却更被搜刮一空，最终没过几年就凄惨死去。",
[343]="你觉得自己一直失败的原因是自己缺少识人能力，你决心努力让自己能够学会辨识出心善之人。",
[344]="某天你发现了一位正在路边摆摊的算命道士，一时兴起和他聊了起来。你讲述了自己在城里见过的奇人异事，他听完后决定给你一份礼物，你选择……？",
[345]="一册书",
[346]="一笔钱",
[347]="你很久没有看过书了，虽然不知道这本书写了什么内容，还是决定选它。",
[348]="你毫不犹豫地拿了一笔钱，可以舒舒服服地过一段时日了。",
[349]="你试着翻阅了一下那本书，貌似记载了某种法诀，反正平常除了乞讨也无所事事，便决定照着这法诀试试修炼。但你修炼了数个月都没有什么明显的进展，逐渐失去了热情，你决定……？",
[350]="不再修炼",
[351]="继续修炼",
[352]="你觉得这功法大概是骗人的，便撕了它用来引火，不再继续修炼。",
[353]="虽然一直没有什么进展……但万一是真的呢？内心十分挣扎的你还是没有放弃修炼。",
[354]="你在巷子里看到有个孩童在哭，身边却没其他人，心想应该是走丢了，你想帮孩童找父母，但又想到自己只是个乞丐，你决定……？",
[355]="帮他寻找父母",
[356]="转身离去",
[357]="你耐心地哄着孩童不再哭，便带着他寻找爹娘。花了半天才找到这孩童的双亲，对方并没因为你是乞丐而冷眼相待，很是感激地拿了一些吃食和银钱给你作为酬谢。",
[358]="你狠心走出巷子，孩童哭声在身后变得越来越小。自身难保的你哪还有精力去帮助他人……",
[359]="你早晨醒来时，突然感到一阵心悸，天旋地转。你意识到或许是大限将至，此时一抹虚幻的玄妙身影出现在你的面前，说与你有缘，可赠你一枚寿元丹续命。你决定……？",
[360]="你凭借那颗奇妙的丹药，多活了十数年。然而山匪终非正道，你还是死在了官兵的围剿中。",
[361]="你的顽抗令官兵久攻不下，最终官兵决定调动弓兵齐射。你的右腿被箭矢穿入，无法逃离，只能蜷缩起来，祈祷着自己的运气能保全一命。但是这样的好运并没有到来，一支箭矢从你的背后穿心而过，你临死前心想：大夏尚在盛世，或许……不该与朝廷为敌。",
[362]="乱箭穿心",
[363]="你起兵造反，被朝廷所派的官兵乱箭穿心而亡。",
[364]="你问斩在一个傍晚，天空中莫名出现一道雷光与红色霞云相争，一旁监管的官人惊呼“莫不是仙人斗法？！”你却在这时想起了自己得到的那颗宝石，或许那是仙人之物？可惜事到如今，已经没有了验证之法。仙人斗法甚久，行刑时辰已到。锋利的斧刃分开了你的头颅与身体，红霞最终也被雷光消灭殆尽。",
[365]="判罪问斩",
[366]="你起兵造反，被朝廷判罪问斩而死。",
[367]="烧杀抢掠的一生，午夜梦回终惶惶。生死有命，死亦解脱。",
[368]="你凭借那颗奇妙的丹药，多活了十数年。年纪愈长，你愈感慨世界之玄奇，在一个普通的夜晚陷入永眠。",
[369]="步入老年后，你顺势安排了自己的孩子进入官场，自己则告老辞官。市井中常有仙人传闻，但你却并未实际见过。你想起自己曾经得到过的宝石，如果没有失去宝石，或许自己也能窥见仙途。可惜……你遗憾地闭上了双眼。",
[370]="安度晚年",
[371]="告老辞官，虽无仙缘，亦得安度晚年。",
[372]="你临死前，将那颗宝石亲手交托给自己的小孙子。他为宝石取名\"星尘\"，你听到这个词的时候本能地意识到，这就应该它的名字。将宝石深藏在宝库中，却反而导致自己遗忘了它。或许应该让其他人也看看此物，才能弄清它的真面目……",
[373]="传承宝石",
[374]="死前你将宝石传给孙子，却仍未知其真面目。",
[375]="一生动荡起伏，终是生死有命，已行至尽头。",
[376]="你诞生在夏天，是个男孩，爹娘都是本分老实的庄稼人。村长做主给你起了名字，叫{0}。村里都说贱名好养活，你娘就给你起了个小名叫狗剩。",
[377]="你确实好养，你娘给啥你都吃，吃啥都香，结实得像头小牛犊。",
[378]="你看着院子里满地乱跑的小鸡崽，很是喜欢，便吵着闹着要去鸡窝孵蛋养小鸡……你娘拗不过你，索性随你去了。你兴冲冲地跑进鸡窝想掏个鸡蛋来孵，不料却被抱窝的母鸡给啄得一蹦三尺高，痛得拔腿就跑的你哭嚎了大半日，再也不提要孵小鸡了。",
[379]="你爹拎了一篮子鸡蛋和一筐萝卜，带你去到村长家，让你每周过来跟着村长念两日书，好歹要能识字。",
[380]="你跟着村里的几个大孩子去掏蚂蚁窝，捉到的蚂蚁用袋子装好，拿到镇上的医馆，能换好几个铜板。",
[381]="你在山脚下的小溪玩耍，意外摸到了一枚晶莹剔透的石头，你十分喜欢……这也许就是大人说的“宝石”吧，你这样想着，仔细地把它贴身放好，没有告诉任何人。",
[382]="今岁多雨，粮食收成不好。为了帮补家里，你时常去溪河捉鱼摸蚌，跟着爹娘去集市售卖，也能有些收入。",
[383]="农闲时你四处闲逛，看到村尾的王婶在编蒲扇斗笠，瞧着有趣，你便卖乖地央她教你。到了夏季炎热时，你头顶斗笠遮阳，手握蒲扇扇风，别提多畅快了。",
[384]="成年的生日格外不同，你娘给你煮了窝荷包蛋的长寿面，还宰了鸡，你爹与你喝了两杯酒。从这年起，你便要正式务农劳作了。",
[385]="成年的你便要独当一面，正式开始下田劳作。",
[386]="今年大旱，产量甚微，听闻隔壁村某户种出的小麦耐旱性强，你趁着夜色过去拔起数株麦苗带回家中加以种植，培养研究。",
[387]="听闻村中老者闲谈，传闻世上有仙，可辟谷数日不进食。你想起曾经三天饿九顿的日子，对此嗤之以鼻。",
[388]="某夜狂风突起，伴随着红色闪电及倾盆大雨，天空时有流光闪过，看着此景，你想着农作已然不保，明天可以睡个懒觉了。",
[389]="不愿做出改变的你日复一日的操劳着，虽付出了100%的汗水，但与常人无异，如父辈一样，平平无奇泯然众人间。",
[390]="你开始查阅祖上手记，记录作物生长规律，加以调整农耕方法，一年比一年收获丰盛，隔壁村长都听闻前来请教种植良方。",
[391]="你与众人分享种植经验，相互学习，带领这方土地的农民共同走上致富之路。",
[392]="你开始查阅祖上手记，发现一粒晶莹翠绿的种子，手记中对此并无记载，好奇驱使下将其种下。",
[393]="你费尽心思，翻遍祖上手记，未能有丝毫进展，心想难道这不是种子，而是块宝玉？",
[394]="耗时数年却未见种子有发芽的迹象，你开始请教村中老者，是否识得此物，众人却尽皆摇头，表示不知。",
[395]="你发现田边有一棵瘦弱的树，有点挡路，便想把它砍掉。不料砍树的时候发现树洞里竟然有蜜蜂和蜂蜜，尝了蜂蜜后，非常甜美，决定将其留下。",
[396]="你嫉妒邻居田里的庄稼长得好，趁着夜半无人，去对方田里放火，不料风向突变，自己田里的庄稼被烧毁，损失惨重。",
[397]="你经过多次试验，培育出了良种，提高了作物的产量。十里八乡的农户都过来求取良种，你趁机大赚一笔。",
[398]="冬天去镇里赶集的路上，你发现一条冻僵奄奄一息的小蛇，善心大发地将其放入怀中取暖，不料被苏醒后的蛇咬了一口，从此看到井绳都害怕。",
[399]="你发现田里的禾苗长势缓慢，决定逐根拔起帮助禾苗成长，不料几天后，禾苗都死了，损失惨重。",
[400]="你遵循祖辈的教导，按时播种、施肥、浇灌、收割，这一年平平无奇。",
[401]="你发现现实的天气跟祖辈的经验有所偏差，大胆调整了播种和耕耘计划，作物的产量得到了提高，村里的人纷纷效仿，大家都变得富裕起来。",
[402]="你试种了外来的新作物，由于经验不足，这一年颗粒无收，差点过不了冬。",
[403]="正在田里干活的你，看到乌云汇聚于远处高山，似有人似有神。不久后阵阵雷鸣不止，狂雷劈落山巅，你在想怎么就不下雨，虚张声势。",
[404]="邻居赵大山因农耕受伤，你主动伸出援手，帮助对方完成剩余耕作。赵大山非常感激地赠送了一些粮食给你当做谢礼。",
[405]="你在喂养家禽时发现少了一只鸡，觉得是村里的老流氓石头干的，便找他理论。不料此恶人不但不承认，反而将你打一顿，你只能自掏腰包去看大夫治伤。",
[406]="天有不测风云，由于大风肆虐，农田被摧毁得非常严重，你叹了一口气：“今年真的亏麻了！”",
[407]="你带着一些粮食和家禽到镇上售卖，刚好有大户人家正在为宴席大肆采购，所有东西一下就被对方的管家高价打包带走。",
[408]="你在耕田时发现有一只鸟一直在头顶环绕飞行，你不以为意，只是锄头较钝，已不太适合继续劳作，便提前回家，准备第二日城里维修农具。",
[409]="第二日，你因为一些琐事忙碌到邻村忙碌，未能进城，不料晚上回到仓库时发现锄头和镰刀等农具都焕然一新，心想：真是奇了个怪，难怪是神仙帮我修了锄头？",
[410]="你在田里松土时，锄头一挥，“铛”的一声响，把锄头都磕崩了一角。你寻思到底啥玩意这么硬？挖出来一看，竟是块奇怪的铁疙瘩。",
[411]="你从城里赶夜路回家，遇见个矮个子躲在树后阴测测的问你“我像什么”，你瞥见树的另外一侧居然有一条黄色的大尾巴，把你狠狠吓了一跳。你头都不回地跑回家中，后来大病了一场。",
[412]="最近山里不知道发生了什么，很多动物都往山下跑，你在田里干活时，竟能时不时看见狐狸和山鸡。摸了摸镰刀，你想：不知道能不能趁机逮住几只，加个餐。",
[413]="今年的稻子竟然早了两个月就成熟了，你也不知道为什么。但这确实是喜事一桩，还是抓紧时间收割吧。",
[414]="一日，你在朋友家喝得大醉，回家的路上实在太困，迷糊间瞅见一座破庙便进去对付一宿。不料早上醒，却来发现自己竟然睡在一片荒坟地里，吓出一身冷汗。",
[415]="暴雨来得突然，把晒在院中的谷子浸湿了大半。你很生气地朝天大骂老天爷，谁知当空劈下一道闪电，吓得你兔子似地躲回了屋中。",
[416]="进城赶集时，你看见一个虚弱的老乞丐正在乞食，想了想，便把身上仅剩的烧饼给了他。对方连连致谢，说与你有缘，要报答你的善心。你张口正欲拒绝……",
[417]="只见老头微微一笑，从腋下掏出一枚丹药弹射进你的嘴里，你猝不及防地吞服下去，发现力气莫名大了不少。",
[418]="今年你成家了，娶的正是你们村的村花，村花贤惠漂亮，让全村的老少爷们特别羡慕。",
[419]="今年你的儿子平安出生了，你们夫妻二人特别高兴，在自家院子里摆了几桌，邀请亲朋友好友过来吃席，很是热闹了一番。",
[420]="一日，你正在田间辛勤劳作，挥汗如雨，忽然头顶一阵凉意袭来。抬头望去，竟是一人在御剑飞行，你吓得跪倒在地，大呼“仙人显灵”！",
[421]="你坐在田埂上发呆，看着天空时不时路过的御剑飞行的仙人，好生羡慕，心想自己要是也能御空飞行那该多好呀，不知道这辈子还有没有机会。",
[422]="家里的老黄牛寿终正寝了，你只能到集市上购买新牛。只见一头黑牛被挤在牛棚的角落，十分可怜，不知怎么你竟有些心软……这就是缘吧，你这样想着，决定掏钱将它买下。",
[423]="睡梦中，一个黑衣老头缓缓向你走来，朝你拜谢道：“谢谢主人体谅之恩！”梦中的你非常惊讶，你从未见过此人，他为何喊你主人？",
[424]="老头像是看出了你的惊讶，续道：“主人，我就是你养的黑牛呀！”为了感谢你的体谅之恩，他告知了你一个地点，说那处地下藏有一脉暗泉，灵气十分浓郁。",
[425]="第二日醒来，你按照梦中指引，真的找到了一处地下暗泉。那泉水含有丰富的灵力，对农作物生长有着不可思议的促进作用。",
[426]="你选了一块最为贫瘠的土地，按照《农耕仙诀》的指引，进行了一次大胆的实验，以特殊阵法引导月华之气，又在特定时刻进行灌溉。",
[427]="几周之后，那块土地竟奇迹般地长出了翠绿的嫩芽，且速度极快，长势惊人。",
[428]="你依据《农耕仙诀》中的古老配方，尝试培育出传说中的五彩水稻。",
[429]="你精心调配土壤，经过数月辛劳，终于在收获季节，田间呈现出一片斑斓景象。",
[430]="五彩稻穗在阳光下熠熠生辉，吸引了远近好几个村子的村民前来观赏，一时之间，你名声大噪。",
[431]="一场突入其来的蝗灾侵袭了周边地区，唯有你们村幸免于难。",
[432]="原来是你预先察觉到了异象，依据《农耕仙诀》中的自然和谐之道，开垦了一块荒地种植了一片特殊的香草，其散发的香气能驱散害虫，形成一道天然的屏障，保护住了全村的田地。",
[433]="你决定开垦一块试验田，用来进行特殊的灵植培育。利用《农耕仙诀》中的方法，你成功培育出几种罕见的灵植，有商人闻讯前来收购，开出高价，让你大赚了一笔。",
[434]="今日，你在地里拔草，瞧见个怪模样的草，长得像蒿子，摸着凉飕飕的，还老冒烟儿。大中午的日头晒得慌，你顺手扯了一把，试着咬了一口，乖乖，居然是甜的！",
[435]="地里的萝卜熟了，你正在拔萝卜，突然拔出一颗萝卜竟犹如小人一样有四肢，还水盈盈的。你曾听老人说，萝卜久了可会成精，所以还是煮了吧，真香！",
[436]="夏夜大雨，雷声轰隆隆的，吵得你睡不着觉，索性爬起来趴在窗边歇凉。只见天边那闪电一道接一道，闪得刺眼。",
[437]="突然，好像有个黑乎乎的东西往天上蹿，接着几条闪电“咔嚓”一下全打在那黑影上，就见那小黑点冒着烟儿，直往下坠……",
[438]="你困惑地挠了挠头，心想：这年头的鸟儿胆子这么大？打雷天也往外飞？！",
[439]="你在去水井打水，捞上来一块亮闪闪的石头。于是你琢磨着，井水这么甜，这井里的石头没准也有用处。",
[440]="你顺手就把石头揣进兜里，想着之后泡茶时扔茶壶里试试。还真别说，有了这石头，茶香味确实更浓了，真是捡到宝了！",
[441]="你与村里的老王斗鸡，赢了一壶酒，喝得迷迷糊糊的，你竟觉得自己成了仙人，可以御剑飞行……酒醒时你才发现正躺在自家屋顶上，结果一个不稳，跌下来摔断了腿！",
[442]="一天夜里，一枚流星砸坏了谷仓，怪的是非但没有着火，反而留下了一块冒着寒气的铁块。你瞅着这铁块应该不是凡物，便找铁匠打了把镰刀，嘿！割稻子飞快！",
[443]="已有三旬没有下雨了，眼瞅着水塘快要见底，正着急时，忽然雷鸣大作，下起雨来，大伙儿都乐坏了！你抬头看天，真是一场及时雨啊~咦？云中的那是……白龙？",
[444]="今日赶集，半道上给个古怪的游商拦下了，他翻出几本厚书，说啥无字天书、橙色上品，还讲了一堆练功的门道。你心想，咱斗大的字不识一筐，买这些花哨玩意儿有啥用？",
[445]="今天在田地里割麦子，瞧见田里有一颗野草，便想着顺手用镰刀给割了，可镰刀一挥过后，这野草仿佛挪到了一边，没能割到。",
[446]="你又连续试了几次，都是如此，怕不是见鬼了！惊得你拔腿就往家里跑，第二天才敢来田中，却是没再见到那颗怪草了……",
[447]="今年酷热，夏日在田间劳作相当辛苦。你摸了摸怀中的宝石，其散发出的清凉感让你不惧烈日，真是一枚好宝贝。",
[448]="又是一年生辰，你娘欣慰地说起你从小到大很少生病，小名起得真好。",
[449]="你爹得一场怪病，大夫治不好，家中的钱财已是散尽。一名云游的道人用符箓治好了他，无以为报的你将那枚宝石送给了道人，道人一惊，直言此物贵重，竟取出一本经书交给我，说是为了却这因果。",
[450]="深夜明月皎洁，失眠的你索性起身推窗远眺，竟看见一人坐在院外的古树树梢上对月独饮，衣袂飘飘似仙。待你揉眼再瞧时，人却不见了。",
[451]="你近日身体不适，在田间干活难免有些体虚气短，正准备稍作歇息，一名赤脚医生路过，看出你的不适，主动为你诊治并开了个偏方。你将信将疑地按偏方抓药服下，竟真的感觉身体明显好转了不少。",
[452]="在一次清理旧仓时，无意中发现一本泛黄的古籍《五行农耕术》，上面似乎讲诉着闻所未闻的种田方法，你决定……？",
[453]="五行农耕术",
[454]="学着试试",
[455]="拿来垫桌脚",
[456]="你参照着书中的模样大致效仿了下，不消多日耕地作物统统枯死，气得破口大骂。",
[457]="农耕多年的你认为，没人比你更懂农作！将其垫在多年咿呀作响的桌脚之下，感受着久违的清静，你由衷的佩服自己的智慧。",
[458]="听闻隔壁村花跟土财主喜结连理，你一气之下气了一下，为了振兴壮大家族，你决定……？",
[459]="喜结连理",
[460]="外出发展",
[461]="努力耕种",
[462]="与父母协商后你决定外出发展，另寻挣钱契机，毕竟你深知种地是没有前途的。",
[463]="正所谓行行出状元，你坚信当你成为种田大师的时候，金钱权利也都能轻而易举的获得",
[464]="你带着地里挖到的铁疙瘩进城想卖掉，随意找了家铁匠铺子，朝店家道：“这玩意能卖个好价格不？”店家扫了一眼便愣了一下，定睛观察许久，道：“此物不简单，你在哪里获得的？还有更多的吗？我全都要！我愿意用比精铁价高百倍的价格跟你购买，如何？”",
[465]="铁疙瘩",
[466]="卖",
[467]="不卖",
[468]="你一听，发财咯！便毫不犹豫选择将此物卖掉，带走了大笔钱财。",
[469]="你寻思店家都愿出大价钱购买，此物必定不凡，说不定留着更好，便带着铁疙瘩离开了，不料在巷子里被人套麻袋揍了一顿，铁疙瘩也不翼而飞。只能自认倒霉。",
[470]="去种田路上莫名出现了一个巨大的坑，看着挺深，黑黢黢的，但似乎有亮晶晶的东西在里面发光。你有些犹豫，要不要下去看看？",
[471]="亮晶晶的东西",
[472]="下去看看",
[473]="种田要紧",
[474]="你摸索着下了巨坑，却发现里面亮晶晶的东西是一头妖兽的眼珠！还不等你大喊出声，你已经被妖兽吞入腹中……",
[475]="最近正是稻子拔节的时候，可没有闲工夫做这些，还是赶紧去田里吧。",
[476]="开垦荒地时，你竟意外挖到一个石雕神像。石像半掩在土里，双目紧闭，总让你有不好的感觉，是否要继续挖下去？",
[477]="石雕神像",
[478]="挖出石像",
[479]="重新填埋",
[480]="你还是不太想放弃这块地，决定把石像挖出来扔掉。不料你刚刚伸手碰到石像，它的双目便突然睁开，与你对视。你忽然就失去了意识，倒在地上再也没有醒来，石像也瞬间消失了……",
[481]="你感觉四周的气氛越来越诡异，连忙抄起锄头赶紧把石像掩埋回去，这块荒地也不要了。",
[482]="你拉着新买的黑牛到田里耕地，耕了几亩地之后，它看起来很累，开始不停地喘着粗气，你决定……？",
[483]="黑牛耕地",
[484]="继续耕地",
[485]="让其休息",
[486]="你并未理会黑牛的状况，拉着它继续耕地。",
[487]="你十分心疼，急忙把犁枷从黑牛身上卸下来，将它带到树荫下休息。",
[488]="你正在田里清除杂草，一名风尘仆仆但气质不凡的青年突然出现眼前，他说自己因门派纷争而受伤，需要一处安全的藏身之地用以养伤，见此地正好偏僻，看你不像歹人，便贸然现身求助，希望你能提供一处住所供其休息。你决定……？",
[489]="气质不凡的青年",
[490]="出手相助",
[491]="农耕仙诀",
[492]="机缘巧合，一本《农耕仙诀》给你带来了无尽好处。",
[493]="因为你的冷漠，错失了一本《农耕仙诀》",
[494]="你朝青年拱手说道：“仙人如不嫌弃，便在小人家中住下吧。”随后你带领青年回到家中，对方为了为了报答你的收留之恩，赠予你一本古旧的《农耕仙诀》，并将内容全部传授给你，其中正是提升作物收成与土壤肥沃的法诀。",
[495]="你看了一眼青年，很是嫌弃，没有理会对方，继续埋头干活。青年微微叹气，转瞬就消失无踪了。",
[496]="一个风尘仆仆的行脚商途径此地，正好碰上你在大树底下悠闲泡茶。他渴得紧，过来讨碗茶喝。茶水刚沾唇，他眼神猛地一亮，说这茶不简单，是灵茶。你虽然没听明白，却想着应该是夸你茶泡得好？你便很是得意地掏出泡茶秘诀——那枚石头给他看。谁知他瞅你的眼神，跟看个傻瓜似的，弄得你一头雾水。",
[497]="喝完一碗茶后，行脚商想向你买下这枚被他称为灵石的石头，只见他拿出一块比石头大得多的狗头金，和你说道；“兄弟这是中品灵石，其中灵气还算充盈，与我有用，我用这金子与你交换，你这辈子自是衣食无忧的。”你决定……？",
[498]="风尘仆仆的行脚商",
[499]="卖给对方",
[500]="不愿卖出",
[501]="富贵泼天",
[502]="你用一枚灵石换了一生富贵。",
[503]="行脚商这样一说，你哪还不知这小小石头的不凡？但看着那块狗头金，这又是你种多少亩地都得不到的钱财，泼天富贵之下，你只是略作犹豫，便递出灵石，接过了那沉甸甸的狗头金。",
[504]="行脚商见你竟然不愿交出，略作犹豫，便取出一卷玉简，看着颇为贵重，行脚商说道：“你既然不要富贵，想必也是心有思量，这灵石虽然宝贵，却不是你等凡人可以留下的，你拿着如幼童执金于闹市。我用这修道法诀与你交换，这法诀虽是下品，但也可让你修成练气，去看看那高处的风景，只是后续的机缘，就看你自己了”。",
[505]="你毫不犹豫地用灵石换取了那玉简，如宝贝一般细细看着，才发现……你不识字啊！抬头正想询问，却已不见那人，一阵微风吹过院子，依稀带来一句话“把玉简贴在额头，自能读懂其中的口诀，因果已了，好自为之……”",
[506]="你用一枚灵石，换来了窥探仙途的机缘。",
[507]="你在田埂歇息，一头白鹤从天而降，羽毛间夹杂血迹，显然受伤颇重，无法再飞。它望向你时，眼神里仿佛含着人的情愫，满是求助的意味。你决定……？",
[508]="受伤的白鹤",
[509]="救治白鹤",
[510]="要不炖了",
[511]="你把受伤的白鹤带回了家，找来干净布块蘸了点清水，一点点给它清理伤口。白鹤虽疼，却也乖巧，一动不动任莫摆弄，眼神里满是感激。清理完毕后，你寻思着白鹤大概跟大公鸡差不多，就把它抱到鸡窝，前头撒了把粮食。那白鹤一脸茫然，瞅了瞅你，又看了看地上的谷子，最后像是认了命，低下头，憋屈地啄起食来。",
[512]="你嘀咕着：“这天上掉馅饼，不对，掉仙鹤的好事，怎可错过？”左顾右盼你像是干了啥亏心事一样，悄悄地把白鹤带回了家。",
[513]="就这么过了几日，白鹤的伤慢慢好了，羽毛也恢复了光泽。有天清晨，你刚出屋子，它就围着你转了几圈，叫了几声，好似在告别。随后，它腾空而起，盘旋几圈，朝着太阳升起的方向飞去，化作一点白光消失在天际。",
[514]="自那以后，村里的庄稼长得格外好，连年丰收，大伙儿都说是你救了仙鹤，得了福报。每当想起那只白鹤，你心里就暖洋洋的，觉得这世上的善举，终究是不会白费的。",
[515]="炖锅咕嘟嘟冒泡，你一边搅和着锅里的“秘制鹤汤”，一边幻想着这一锅下去，说不定能得个百病不侵、延年益寿的奇效。可正当你准备大快朵颐之时，突然，一道耀眼的金光从锅中迸发，直射屋顶，吓得你连忙后退。光芒散去，锅中竟只剩下一汪清水，水面漂浮着几片羽毛，闪着淡淡的蓝光。你瞠目结舌，锅里的鹤就这样奇地消失了……",
[516]="岁月匆匆，转眼已是暮年，你在院子的躺椅上歇息，如今眼目不明，耳朵也背，但几个儿孙那争夺家产的话语却如针扎在心中，如果当初没有将灵石卖给那人，不知又是怎样的境况？罢了罢了~你长长的呼出一口气，沉沉地合上了双眼……",
[517]="你于初春诞生在一户猎人家，是个女孩。你娘生你时难产，落下病根。你爹是有名的好猎手，用一只野兔跟村老讨了你的名字：{0}。",
[518]="猎户之子",
[519]="你于初春诞生在一户猎人家。",
[520]="你在院中玩耍，不大的院子杂乱地摆放着不少东西，令你感到无比好奇。你似乎看中了什么，伸出手一把抓住……？",
[521]="院中玩耍",
[522]="一把旧弓",
[523]="一根箭杆",
[524]="你伸手抓住了一把旧弓，看上去有些年头了，对现在的你来说这把弓太重，你还拿不起来。看着你跟旧弓较劲的模样，你爹不由得笑了起来。",
[525]="箭杆很新，还没有装上箭镞，尾羽是漂亮的山雉毛做的。你拿起来挥个不停，玩得十分开心。",
[526]="你在箭术上很有天赋，已经能像模像样地拉开小弓射中野兔。你爹却时常叹气，念叨着“咱丫头是个男孩就好了”。",
[527]="你爹狩猎时遭逢意外，从熊瞎子掌下死里逃生，却瞎了一只眼睛，没了一条胳膊。你家里的处境一下子窘迫起来。",
[528]="身为女孩，你的力气不如男孩大，不服输的你决定……？",
[529]="不服输的你",
[530]="扎实基础",
[531]="努力劳作",
[532]="邻居梁伯曾经参过军，你每日清晨起床就去跟着梁伯训练，扎马步、绕村跑……如此坚持下来，收获不小。",
[533]="你决心每天给家里多砍两担柴，挑四趟水，借此锻炼自己……如此坚持下来，收获不小。",
[534]="为了照顾残父病母，你以孩童之龄跟随别的猎人外出狩猎已两年有余，在箭术上进步惊人，艰难地撑起了这个家。",
[535]="有些不服气的年轻猎人找上你，说要与你比一比箭术，如何比试，你说了算。你想了想，决定……？",
[536]="不服气的年轻猎人",
[537]="比射靶",
[538]="比猎雁",
[539]="村外有一个老猎人搭建的旧靶场，你将比试定在这处，连比三场，每场十箭，你皆是正中靶心，其他人皆有脱靶，终于让这群年轻的猎人心服口服。",
[540]="如今正是雁群出没的季节。你决定与他们比猎雁，以日落为限，谁射中的雁多谁便胜了。最终，你一人射到了五只雁，其余人至多三只，他们终于对你心服口服。",
[541]="你的箭术胜过许多老猎人，可以独自狩猎，在附近小有名气。你爹的念叨也已经换成了“丫头厉害，多多注意安全”。",
[542]="今冬大雪，家中存粮告急。你外出打猎时，遇到一名青年晕倒在地，气息奄奄，衣衫破损，一看就是在深山老林里迷路饿晕了。\n雪天捕猎不易，身上只有勉强够一人果腹的干粮的你，有些为难地决定……",
[543]="深冬救人",
[544]="救人一命良心安",
[545]="生存艰难己为先",
[546]="你艰难地将这青年扶到背风处，生火取暖。待对方醒转，你把身上的干粮都给了他，并为其指明了离开的方向。对方疲惫而感激地问了你的姓名，说日后必将报答。你没有放在心上，很快先行离开，饿着肚子堪堪在天黑前逮了两只野兔回家。",
[547]="你想了想自家的处境，只将这青年扶到背风处，生了堆火，就离开了。这人能否活命，就看老天爷吧……你这样想着，边赶路边吃完了干粮，努力地赶在天黑前逮了一窝野兔回家。",
[548]="你进山检查捕兽笼时，捡到一块似玉非玉的绿色石块，散发着令人舒适的暖光。你虽然不知道这是什么，但还是下意识地将其贴身携带。",
[549]="今年的征兵开始了，你已到了可以入伍的年纪。你决定……？",
[550]="今岁征兵",
[551]="入伍参军",
[552]="维持现状",
[553]="你决定入伍参军，换取军饷改善家中境况。",
[554]="你决定继续做一名猎人，以捕猎为生。",
[555]="为了改善家中境况，你决意参军。女子参军不易，条件严苛，你狠狠下了一番功夫努力，为自己挣得了入伍名额。",
[556]="你的父母希望你留在他们身边，你没有去从军入伍",
[557]="你出生在一户猎人家，是个哭声洪亮的大胖小子，你娘因此给你起名{0}。你爹娘是一对经验丰富的好猎手。",
[558]="出身于猎户人家，爹娘是一对经验丰富的好猎手。",
[559]="一把刀柄",
[560]="一副刀鞘",
[561]="你伸手抓住了一把刀柄，刀柄是新制的，上面涂的漆还未干透。你看着手上又粘又黑的漆料，哇的一声哭了起来。你娘从屋里冲到院中，看清状况不由失笑，赶紧抱着你先去洗手，又哄了许久才止住哭声。",
[562]="这副刀鞘漆绘着古朴的花纹，很是好看。你爹走过来抱起你，指着这刀鞘说道：“这刀鞘可是城里最好的老匠人打造的，可惜这把刀在十年前断了，不然爹还能拿它多猎几头狼回来。”",
[563]="你对捕猎的技巧兴趣很浓，经常屁颠屁颠地跟在爹娘身后做一些简单的小陷阱，捕到小鸟都很兴奋。",
[564]="你在雨季乱摘野菌烤了偷吃，差点因为中毒丢了性命。被大夫救回来之后，爹娘把你暴揍了一顿。",
[565]="除了学习捕猎的技巧，你爹娘还押着你跟村里的大夫学习如何辨认毒物和草药。",
[566]="以你现在的体力，外出狩猎一天便要回家修整，不能像爹娘那般进山数日乃至一旬都是常事。为了尽早跟上爹娘的脚步，你决定……？",
[567]="跟上爹娘的脚步",
[568]="村东头的赵伯曾经当过伍长，你便每日清晨过去缠着他给你打基础。扎马步、绕村跑……如此坚持下来，收获不小。",
[569]="你决心每天给家里多砍四担柴，挑六趟水，借此锻炼自己……如此坚持下来，收获不小。",
[570]="你在河里下的机关网捕到了一尾长角的怪异红鲤，宰杀时从它肚中剖出一颗纯红似宝石的圆珠，你鬼使神差地把这珠子藏了起来。",
[571]="你闹着跟爹娘一起去捕猎，不料此行遇到猛虎，虽然你爹娘最终合力将其猎杀，但中途你不慎挨了一爪子，从肩膀到腰腹留下一道狰狞疤痕。",
[572]="听说近来有行脚商大量收购毒蛇，你忙不迭地到处布置捕蛇陷阱，狠狠赚了一大笔，被爹娘一顿夸赞。",
[573]="今年生辰，你爹娘说可以满足你一个心愿。你决定要……？",
[574]="一套皮甲",
[575]="一把强弓",
[576]="当年被猛虎所伤令你心有余悸，你深知狩猎并非易事，合身的皮甲能更好地保护住你。你爹娘明白你的想法，特地带你进城量身定制了一套合适的皮甲。",
[577]="强弓射程更远，威力更大，如今的你壮得像头牛，理应能拉开强弓了。你爹笑着答应下来，进城找最好的匠人给你打了一把强弓。",
[578]="你的刀法在双亲和长辈们的指点下略有小成，已经可以独自猎狼。",
[579]="你决定入伍参军，历练一番。",
[580]="身为男儿，雄心勃勃想入伍历练一番。你说服爹娘，决定参军。",
[581]="你的父母希望你留在他们身边，你没有去参加征兵选拔",
[582]="你已错过了适合嫁人的年纪。除了打猎换取物资之外，你用心侍奉父母，日子过得平淡知足。",
[583]="春回日暖，你在河面冰层融化时找了个好位置，收获了许多肥鱼。",
[584]="你通过连环陷阱，成功捕杀了一头壮硕的雄鹿，卖出了很好的价钱。",
[585]="你捕猎回家时途径一条水流湍急的小河，救下了一名溺水的孩童，对方的双亲是附近有名的富农，千恩万谢地塞了不少谢礼给你。",
[586]="这年冬天极冷，你娘身子太弱，终究是没有扛过去。你爹大恸之下，半月后也随着去了。留下你孤身一人，悲叹生命无常。",
[587]="你收了村里的一名孤女做徒弟，说是徒弟，却更像是养女。小娃娃年仅六岁，很是刻苦地学习你的捕猎本事，让你回想起了当初的自己。",
[588]="你在深山发现两头成年野猪在激烈地决斗，便沉住气守在暗处。直至它们两败俱伤，你果断上前两刀毙命，成功把两头野猪都收入囊中。",
[589]="你提了一笼兔子进城售卖，遇到个约莫十岁的孩童，对方见到乖巧白嫩的兔子便挪不开眼，竟掏出一块奇特的石头，眼巴巴地想要跟你换两只兔子。",
[590]="你看这孩子唇红齿白的可爱模样，不由心软地答应了他，用两只兔子换回了这块奇特的石头。",
[591]="一条巨蟒钻到了你邻居的屋中，差点将人吓破胆。你赶过去解决了巨蟒，邻居心有余悸，任你处理此物，你卖了蟒皮蛇胆，狠赚了一笔。",
[592]="你追捕一头鹿时不小心进入了熊瞎子的领地，在熊掌下艰难逃生，肩上上挨了道深可见骨的伤，不得不在家养了两个月的伤。",
[593]="你为了捕猎方便，在山中找了个安全之处搭了间简易的木屋，猎人们都可随意使用。此举传开，猎人之间多有夸赞。",
[594]="每次深入密林，你都能带回丰富的猎物，保障村里的食物供应，赢得了乡亲的尊敬与感激。",
[595]="听闻村中族中长辈说世上有仙，随手便可斩杀豺狼虎豹，你随手一箭射杀百米外的毒蛇，对此不以为意。",
[596]="时常有野兽袭击村落，你都毫不畏惧，站在战斗的前线，被村民视为守护神。",
[597]="进山打猎时，你发现了一只从未见过的机敏小兽，却未能成功将其捕获。回来后跟村长谈起，村长也不知道那是什么。",
[598]="最近山里的猎物越来越少了，老一辈的人说可能是山里来了个大家伙，最近进山务必小心谨慎。",
[599]="你追击猎物时不小心掉进了其他猎人布置的陷阱里，摔断了腿，卧床一个多月才好起来。",
[600]="你深山处发现一潭清泉，旁边有一棵果树，结着不少散发异香的彤红小果，你好奇大胆地摘来食用，力气大增，村里的人后面都叫你“大力士”。",
[601]="附近的山林突发山火，你嗅到风中味道不对，及时通知了村里的人转移，虽然造成了一些财产损失，还好无人员伤亡。",
[602]="打猎时你遇到一名在山里迷路的行脚商，你好心为其领路，对方给了你一笔钱表示感谢。",
[603]="进山打猎时，你发现了一株老山参，看那个头年份可不少。正当你高兴地寻摸工具时，再低头看去，那老山参竟在眼皮子地下消失了。",
[604]="你进山狩猎时忘记带干粮，老半天也没发现一只猎物，正饿着的时候看到一棵大树脚下有些颜色艳丽大蘑菇，心想吃一些应该没事吧，结果吃下之后，眼前浮现出很多小人在跳舞。",
[605]="你正在追捕一头鹿，突然一只的奇怪的大蛤蟆跳出来挡在你身前，并不断向你吐着舌头，你觉得它长相实在丑陋，顺手用刀给了它两下，大蛤蟆落荒而逃。",
[606]="你正在山中狩猎，不料天气骤变，雷雨交加，你背上的铁刀引来一道天雷，差点把你劈成焦炭。",
[607]="家里的干柴用完了，你去山里砍树，突然一只狐狸出现在你眼前，你追它逃，追着追着还是追丢了。你抬头才突然察觉天色已晚，回到砍树的地方，却发现自己砍的柴火和斧头都消失不见了。",
[608]="你在山中发现一棵果树，其上硕果累累，果实饱满金黄，十分诱人。你忍不住摘下一枚果实放入口中，登时口舌生津，体内散发浓浓的暖意，再抬头一看，整棵树竟快速枯萎下去。",
[609]="深夜林间，你误入一处隐秘的洞穴，月华如练，万物生长迅速，摘得几枚奇果，食后精神倍增。次日想再去时，却是再也没见到洞穴入口了。",
[610]="一日，你在林中捕兔，追逐之下进到深山，山雾渐浓不知归处。正困惑时，却听见铃铛之声，你寻声一路跟去，不觉间竟已走出深山。",
[611]="<color=#3375c0>[概率判定]</color> 你在山间遇到一名迷路的孩童，孩童说家在山上，你看其天真可爱，也不作他想，便带其入山寻家。",
[612]="自从你放走了那只狼后，夜里偶尔会听到山中传出狼嚎，次日在庭院中总会出现一些死去的野兽，想来便是那只黑狼叼来的。",
[613]="今天那黑狼叼来了一只肥大的山鸡，此外竟还有……一株带着露水的山花？闻之清香扑鼻，你顿觉浑身舒泰。",
[614]="今夜，你如往常般听到了狼嚎，但声音却在院子中响起，夹杂着痛苦的呜咽。你赶忙打开门，只见院子中趴着一团黑影，是那黑狼！只见它浑身上下似乎都有伤口，肚子仿佛被开膛，血水留满了一地，眼看是活不了了……",
[615]="黑狼看到你，眼中却是露出了少许光彩，只见它张嘴吐出一枚闪光的宝石，勉强用鼻子将其顶到你手边，便合起了眼睛，没了声息……莫名的情绪占据了你的胸膛，你只觉得眼前一片模糊……",
[616]="连日大雨，强行进山捕猎的你非但没有任何收获，反而还因路滑不慎扭伤了脚。",
[617]="自从上次被虫子咬到后，你渐渐感觉浑身有使不完的劲儿，每日都神采奕奕，不见疲态。",
[618]="你进城购买物资，瞧见一处热闹的擂台，碎石者可领不菲奖赏。你想到被那怪虫咬到后自己的身体变化，决定上去一试身手。上台之后，你深吸一口气，凝神出力，一拳就砸碎了需要五名壮士才能抬起的巨石，美滋滋地领了丰厚的赏钱回家。",
[619]="一天夜里，忽然电闪雷鸣，几欲撕裂天空。你隐约看到空中有一个残影，被劈了几下后，坠向深山。",
[620]="<color=#3375c0>[机缘判定]</color> 一日进山，你辨认出山崖边有一株价值连城的奇花，正欲摘取，不料一脚踏空坠入山崖……",
[621]="<color=#549327>[判定成功]</color> 你本以为小命休矣，不料却摔到一处崖间石洞中，洞中有一副打坐的遗骸，一旁的石桌上放着一枚令牌与一副书简，令牌上赫然写着“升仙令”，你将其收入怀中，向着遗骸拜了三拜，便出洞寻路下了山。",
[622]="今日雨大，你想着家中吃食尚够，便没有进山打猎。闲来无事，你便取出那刻着“升仙”的令牌把玩，只见此令非金非木，其后刻有诸多字迹，却无法辨认清楚。",
[623]="子夜，雨越下越大，你被一道剧烈的电光惊醒，在巨大的轰隆声后，屋外传来一道清冷的人声：“朝天盛何在？携升仙令出来拜见！”",
[624]="你推开房门，便看见一名脚踏飞剑的仙人悬在半空，漫天磅礴的大雨似乎无法近其身，恰逢一道闪电从其身后劈过，映照出他剑眉星目的五官……好一名风姿不凡的出尘少年。这位剑仙恐怕喊的是那具枯骨之名，你紧张地握住令牌，怀抱着期待拜倒下去……",
[625]="原来那令牌是仙门的接引令牌，得此令便可入仙宗修行，你无意中捡了那遗骸的漏……站在剑上，你小心翼翼地拽紧少年袍袖的一角，感受着铺面而来的狂风，看着脚下转瞬即逝的山林，明白人生将有所不同！",
[626]="坠崖奇遇",
[627]="大难不死必有后福，坠崖奇遇让你得窥仙途。",
[628]="<color=#549327>[判定成功]</color> 最后却是寻到一处洞口，原来这孩童实为修炼百年的小狐妖，妖狐一家为报恩，指点你找到一处隐秘泉水，饮之明目提神。",
[629]="<color=#c82c2c>[判定失败]</color> 你带着孩童在山中寻到夜晚，忽然一阵寒风吹过，孩童却已不见，林中传来嘻嘻哈哈的笑声。你顿觉毛骨悚然，吓得拔腿就跑，却怎么也无法逃离山林。直到天边冒起鱼肚白，你才发现原来一直围着一棵参天古树绕圈，赶忙慌张地下了山。",
[630]="你带着新鲜的猎物去集市易货时，遇到一群无赖调戏一个卖簪花的妙龄少女，你决定……？",
[631]="被调戏的少女",
[632]="事不关己",
[633]="你狠狠教训了那群无赖一顿，打得他们滚地求饶。少女为表谢意，将最精致的簪花作为酬谢，亲手为你簪上。",
[634]="也不知那群无赖有何背景，你不欲惹祸上身，只是默默经过。",
[635]="你从虎口救下一名僧人。对方道谢之后说你有慧根，与佛有缘，问你是否愿意入佛门修行。你决定……？",
[636]="虎口救僧",
[637]="剃发出家",
[638]="恶徒诓骗",
[639]="你被伪装成和尚的恶徒诓骗，争执时中刀身亡。",
[640]="你思忖一阵，自觉此生暂无情缘缠身，说不定真如这僧人所言，与佛有缘呢？不如随他去看看，便答应下来。不料这和尚竟是个骗子，暗中联系了同伙，准备将你卖作奴隶，混乱之中，你不慎被对方一刀刺中胸口……倒在血泊之中。",
[641]="身体发肤受之父母，你拒绝了对方的邀请，继续打猎去了。",
[642]="狩猎中途忽逢大雨，你在山洞中避雨休息，却听到山洞深处传来奇异声响。你往声源寻去，意外来到一处开阔的山谷腹地，鸟语花香，其中竟有两人漂浮在半空中，剑光呼啸难以辨识！这两位恐怕就是传说中的仙人，你决定……？",
[643]="仙人对弈",
[644]="上前拜见",
[645]="悄然离开",
[646]="冒犯仙家",
[647]="偶遇仙家比剑，上前拜见却成冒犯，你因此而亡。",
[648]="见到生人，两名仙人停下动作，你还未来得及开口，便只听到一声冷哼，令你感到额间一凉，便失去了知觉。",
[649]="不知仙人脾气，你不欲冒犯，悄然离开了。",
[650]="某次见一头小鹿被猛虎追捕，强烈的正义感油然而生，仅三箭便将猛虎射杀。小鹿见状对你表示感激，示意你跟随着它，你决定……？",
[651]="正义之弓",
[652]="跟随 [概率判定]",
[653]="<color=#549327>[判定成功]</color> 小鹿带着你来到一棵奇特的果树前，示意你吃了树上唯一的果子。你吃下那颗果子，一股暖流顿时流向四肢，仿佛力气又大了几分。",
[654]="<color=#c82c2c>[判定失败]</color> 小鹿带着你来到一棵奇特的果树前，示意你吃了树上唯一的果子。你吃下那颗果子，一股热浪在肚中翻腾，你因此拉了三天肚子。",
[655]="你挥挥手打发小鹿离去，便扛起虎尸回到村中。",
[656]="在林中被群狼围住，它们悍不畏死，你也到了精疲力尽之际，被逼至悬崖边，你决定……？",
[657]="群狼围攻",
[658]="拼死一搏",
[659]="坠入崖中 [概率判定]",
[660]="坠崖而亡",
[661]="你被狼群逼至崖边，最终坠崖而亡。",
[662]="棱角锋利的石块，尖利的硬树枝……你用尽目之所及的一切与狼群相博，悍不畏死，每一击虽然能对狼群造成伤害，却也激起了它们更为疯狂的攻势。你的体力随着每一次挥动、每一次躲避而急剧流失。",
[663]="<color=#549327>[判定成功]</color> 你纵身一跃跳了下去，挂在一颗歪脖子树上，发现底下有具枯骨，周遭放着本被岁月侵蚀破烂不堪的书籍。",
[664]="<color=#c82c2c>[判定失败]</color> 你纵身一跃跳了下去，哪料底下怪石嶙峋，摔的粉身碎骨。",
[665]="回到家中研究书籍，你隐约能感受到书中所记应是某种强身健体的方法，便试着效仿起来……",
[666]="奇书专研",
[667]="开始修习",
[668]="不欲修习",
[669]="不得窍门",
[670]="一次坠崖，一本奇书，你由此踏上仙途。",
[671]="虽有奇书，你却不得窍门，反而因此身亡。",
[672]="你学着锻炼了数年，开始隐约感受到一股气流在体内游荡，颇有成效。你十分欣喜，想了想书中提到的仙山奇谷、瀚海灵泉；还有那些腾云驾雾、一剑分海，一刀断水的修仙者……你决定离开凡俗之地，寻求仙途。",
[673]="虽然也许能强身健体，但万一有问题，怕是要丢了小命。你谨慎地斟酌许久，最终决定烧了这本书，当作一切都从未发生过。",
[674]="你在山中挖到一块硕大的块茎，凭借经验，大致确定其并无毒性。此时已至正午，你正是腹饥，是否将之烹煮食用？",
[675]="硕大的块茎",
[676]="煮来吃了 [根骨判定]",
[677]="谨慎为上",
[678]="误食毒物",
[679]="你误食了有毒的块茎，因此中毒身亡。",
[680]="<color=#549327>[判定成功]</color> 块茎似有毒性，但多年山野生活，你好歹也打熬出一副铁胃……一番石破天惊、轰然倾泻之后，你却是没有受到太大影响，反而感觉气血还强健了少许。",
[681]="<color=#c82c2c>[判定失败]</color> 判断失误！这块茎竟有剧毒，你恍惚看见满天星辰旋转，终究两眼一黑，晕了过去……",
[682]="未能辨别的食材，还是不要食用为好，你最后还是把块茎扔了，吃起了干粮。",
[683]="一日，你正在山间巡猎，遥遥听见狼嚎之声，寻声而去，竟发现了一只落入陷阱中的黑狼，在坑中被捕兽夹钳住了后腿，这狼见到来人便发出警惕的嘶吼，眼神中已满是绝望，竟似有泪光闪烁。你决定……？",
[684]="山间巡猎",
[685]="趁机猎狼 [根骨判定]",
[686]="放狼归山",
[687]="因果报应",
[688]="你杀一黑狼，却也因此被其族中巨狼所杀。",
[689]="<color=#549327>[判定成功]</color> 没有花费太多的功夫你就解决了这匹狼。只是这狼皮颇为不同，油光水滑的，你小心地将其完整剥下，赶集时果然卖了个好价钱。",
[690]="<color=#c82c2c>[判定失败]</color> 没有花费太多的功夫你就解决了这匹狼。正欲将其剥皮拆骨，忽然一阵黑风扑面而来，你定睛一看，前方是一匹如人高的巨狼，巨狼盯着你手中的狼尸，咆哮着冲你扑来，你最后看见的便是一只闪着寒光的利爪……",
[691]="一种莫名的心绪涌起，你鬼使神差地替其解开了捕兽夹，一时间狼和你仿佛都愣住了……这狼跳出坑口后，朝你轻声地叫唤了两声，便迅速没入了山林之中。",
[692]="一日，你进山打猎时，在路边的草丛上发现了一只通体散发着紫光的虫子，此虫模样怪异，此前从未见过。你决定……？",
[693]="进山打猎",
[694]="一脚踩扁",
[695]="小心抓获",
[696]="视而不见",
[697]="你掏出一个小袋子，小心地捉住了这只怪虫。翌日，你把怪虫拿到城中售卖，不料几名行脚商竟争相对你许以高价，你随意挑了个顺眼的商人，把虫子卖了个好价钱。",
[698]="不过是只虫子，你不欲理会，不料这虫子猛地飞起来咬了你一口。刹那间，你头晕目眩，直接原地栽倒。",
[699]="虫子被你一脚踩得稀烂，溅出的紫血沾染在了你的鞋上。你继续\n前行，突然发现四周的环境变得异常安静，只有草丛中传来窸窸\n窣窣的声音，你决定……？",
[700]="立刻下山",
[701]="继续往前",
[702]="怪异紫虫",
[703]="你踩死一紫虫，却因紫虫的血液被狼妖所杀。",
[704]="你心中警惕，打算从另一个方向下山，不料身后的草丛中突然窜出来几头狼妖，它们齐齐扑向你！最终，你倒在了血泊之中……临死前你看到几头狼妖争先恐后地撕咬着你的鞋子，你好像明白了什么……",
[705]="你谨慎地一路往前，发现了一个小小的湖泊，附近有些动物在喝水。你上前补充水囊，顺便洗了洗鞋子上沾染的紫血。简单修整过后，你顺手射了一只山鸡，捉了一对野兔，慢悠悠地下山回家了。",
[706]="终于，伤痕累累的你在一次勉强避开头狼的猛扑后，跌倒在地，体力已被消耗殆尽。四周的狼群步步紧逼，将你团团围住……",
[707]="一声声凄厉的狼嚎划破夜空，狼群一拥而上！剧痛如潮水般涌来，你的意识在痛苦中逐渐模糊……",
[708]="狼吻",
[709]="与狼群拼死相博，寡不敌众的你最终难逃“狼吻”的烙印。",
[710]="醒来时发现自己躺在家中，原来是被同村猎人发现，把你送回了家。你活动了一下手脚觉得并无大碍，又想起那只奇怪的虫子，暗暗发誓，下次见到一定把它狠狠踩扁碾碎！",
[711]="女子入伍颇为罕见，总有人质疑你，甚至拿你调侃——女人就合该去那花街柳巷做个美娇娘。你不作口舌之争，凭实力让那些人闭嘴。",
[712]="你的力量确实不如男子，所以暗中观察总结，学会了许多以巧破力的手段，近身相搏也有一定自保之力。",
[713]="你训练刻苦勤奋，将大部分军饷都攒下来送回了家里。",
[714]="春雷响，蛰虫醒。营地周围的毒蛇毒虫多了起来。有士兵不慎被毒蛇咬了，被迫断去一条腿，令你心生寒意。",
[715]="夏季多蚊虫，众士兵都不胜其烦。你在军营附近发现了一些合用的草叶，研磨成驱蚊汁水分给大家，关系融洽许多。",
[716]="军中进行武艺小比，你展露的箭术一鸣惊人，入了将军青眼。你成为将军近卫之一，抓紧机会识字读书，磨练武艺的同时不忘学习兵法。",
[717]="烽烟四起，你在一场战事中一箭射杀敌首，震慑敌军，声名鹊起。",
[718]="急行军时遭遇了罕见的暴雨，雨势如天漏。在泥泞中奔驰的战马不慎打滑，你重重摔下马来，还被踩断了数根肋骨。",
[719]="你到城中办事，恰逢城主大摆武擂。看得技痒的你也上去比试了一番，竟连挑十人，引起了小小的轰动。",
[720]="秋季干燥，夜里山火突起，火势极快蔓延至营地，差点烧了粮草。救火时，你不慎被火势燎伤手臂，引起一场高烧。",
[721]="战争之中，生死一瞬。你眼见同队的老高在你半臂之距被一刀毙命，他昨天早上还替你多领了一个肉包子。",
[722]="行军途径一处河道，水产颇丰。扎营休息时，有数尾大鱼从河中跃起，你拔箭便射，三射三中，引起阵阵喝彩。",
[723]="你奉命行军时太过急躁，在酷暑的烈日下没有及时补水休息，不幸中暑昏迷。",
[724]="战事稍缓，你抽空回了趟家。爹娘凭借你的军饷，日子过得尚可。许久未见双亲，你十分动容，与爹娘聊了许多，尽叙思亲之情。",
[725]="大军征战数年，你胆识过人，奋力拼杀，为自己拼出了一条战功累累的血路，却也留下了一身伤痕。",
[726]="冬夜，你轮值巡逻时，意外发现有几只饿狼试图靠近营地。你领队将狼逐只射杀，消除了隐患。",
[727]="你离营办事，在一处茶摊歇脚。旁边坐了个滔滔不绝的老头，你听了两耳朵，只觉得对方说的“生死有命，无愧于心”有点道理。",
[728]="明枪易躲暗箭难防！战时竟有奸细混在队伍中，企图刺杀将军。情急之下，你替将军挡下致命一箭，却因箭上淬毒而元气大伤。",
[729]="一日，你领命至大营门口接人。来的是将军嫡子，年轻却战功卓越，已官至中郎将。对方见到你时，意外而惊喜地认出了你——原来他就是当年被你救下的那名青年。对方当即掏出一块玉佩相赠，不容你拒绝，以谢当年救命之恩。",
[730]="你非常爱护自己的兵器，经常在闲暇时打磨保养，保证它一直都足够锋利。",
[731]="你外出办事时经过一处城镇，随便找了个客栈留宿。无意中发现客栈的掌柜仗势欺人，你便趁着夜色教训了老板一顿，深藏功与名。",
[732]="投身军中的你经过多年历练，凭借百发百中的箭术而名声大噪，其中最广为流传的是一次军中大比，你于三百步开外辕门射箭，一箭正中画戟枪头。",
[733]="经过多场战役，你在军中更被称为箭神，声名远扬，民间更有传闻，报你之名便可止小儿夜啼。",
[734]="又是一年中秋夜，将军有令，让伙夫给全营加餐。你吃着大块的炖肉，听着远处不成调子的歌谣，看着圆月，突然有些思乡。",
[735]="你赶路时途径一座小城，入城时正巧碰上几名富家小姐结伴出行，与你擦肩而过。一时间，你只觉香风扑面，妙龄少女笑若莺啼，令你兀地红了脸庞。",
[736]="你在营中与人掰腕角力，咬牙坚持许久，最终还是败下阵来，输掉了一坛酒钱。",
[737]="隆冬大雪，一夜过去，雪厚得能没过小腿。所有人都忙着铲雪清理营地，你也打扫得十分认真…… 不料同伍的小李冷不丁往你后脖子塞了一捧雪，冻得你狠狠一哆嗦，回身就把他踹得在雪地上摔了个大马趴。",
[738]="营地在接收新到的一批战马时，其中一匹不知为何突然发狂，眼见其就要踩到交接的马夫，你连忙抽刀就砍，从马蹄下抢回一条人命。",
[739]="战场上刀剑无眼，你不幸身负重伤。此时，你贴身携带多年的奇特石块隐隐发烫，你莫名觉得它在呼唤你将其覆于伤处。你决定……？",
[740]="刀剑无眼",
[741]="应其所唤",
[742]="你下意识地将它覆于伤处，奇特事情发生了，只见石块的绿光一亮即收，下一瞬，伤处竟以肉眼可见的速度恢复……这莫不是什么神仙之物？！",
[743]="你思虑再三，还是决定去寻军医。费了好大功夫才堪堪捡回一命，身子是大不如前了。",
[744]="敌兵狡诈，动向诡谲，将军为了尽快打探敌情，决定派一支精锐小队前去查探情况。你决定……？",
[745]="刺探敌情",
[746]="主动请缨 [潜力判定]",
[747]="查探失败",
[748]="查探敌军军情失败，你未能逃出生天。",
[749]="<color=#549327>[判定成功]</color> 前往查探若有所获，功劳定然不小。多年磨练，你自忖有自保之力，主动请缨率队前去。凭借经验，你率领的小队果然摸清了敌军动向，得以及时汇报。此番立功，军职再升！",
[750]="<color=#c82c2c>[判定失败]</color> 前往查探若有所获，功劳定然不小。多年磨练，你自忖有自保之力，主动请缨率队前去。不料这正中敌军下怀，敌军准备周全，小队全军覆没……你也未能逃出生天。",
[751]="你不欲行无把握之事，决定留在军中。之后精锐小队传回军情，你随大军前进，此战亦胜。",
[752]="前线战事吃紧，又有两员将领不幸身亡。凭你积累的战功，有机会升任将军。你决定……？",
[753]="战功累累",
[754]="把握机会",
[755]="不欲张扬",
[756]="你有野心想要出人头地，所以把握机会努力经营。果然成功拿到升迁将军的任命文书。",
[757]="做人还是要脚踏实地一些，你自觉积累尚有不足，不欲去争这个名额。",
[758]="岁月如梭，你的大半年华都耗在了沙场上。身上的旧疾越来越难以忍耐，你决定……？",
[759]="峥嵘岁月",
[760]="退伍还乡",
[761]="旧疾复发",
[762]="伤病缠身，你选择了退伍还乡",
[763]="你在战场上旧疾复发，死于敌军刀下。",
[764]="多年的战场厮杀令人心生疲惫，见了太多生死相隔，你也是伤病缠身，还是趁此机会退伍还乡吧。",
[765]="为了多挣点军饷，你决定咬牙坚持。不料战场之上，旧疾复发的腿令你慢了一拍，敌军一刀劈下，你眼前一黑……",
[766]="你奉命办事，走水路乘船而往。行至半途，忽然喊声四起，人群大乱，一伙匪徒从船舱冲上夹板，不由分说砍翻了抵抗的船工，扬言不留下买命钱，谁也别想下船。你决定……？",
[767]="路遇匪徒",
[768]="挺身而出",
[769]="跳水逃脱",
[770]="水性不佳",
[771]="水路遇匪，你跳江逃离，却因水性不佳而亡。",
[772]="你本欲挺身上前与匪徒争斗，可不知是否因长时间的颠簸，你忽感头晕反胃，不一会儿就晕倒过去。待你醒来，身上财物已被尽数掠去……",
[773]="你见匪徒出手残忍，且人多势众，便趁无人在意时跳入江中，打算遁水而逃。奈何你水性欠佳，最后竟淹死在江里。",
[774]="一次行军，你所在的队伍中了敌人埋伏，混战之中，你身边的弟兄们纷纷倒下，你也渐渐被逼至悬崖边。精疲力尽之际，你决定……？",
[775]="敌人埋伏",
[776]="坠入崖中 [机缘判定]",
[777]="你与敌军拼死一搏，最终不敌落败，死于箭下。",
[778]="你被敌军逼至崖边，最终坠崖而亡。",
[779]="你拼死奋战，最终耗尽力气不敌落败，倒在了敌军的乱箭之下。",
[780]="<color=#549327>[判定成功]</color> 你纵身一跃跳了下去，挂在一颗歪脖子树上，发现底下有具枯骨，周遭放着本被岁月侵蚀破烂不堪的书籍。你小心翼翼地顺着树滑了下去，翻了翻那堆书册，将其中一本较为完好的揣入怀中。",
[781]="九死一生捡回一命的你找了个山洞中养伤，好奇地翻看起悬崖下捡到的那本书册。你隐约能感受到书中所记应是某种强身健体的方法，便试着效仿起来……",
[782]="九死一生",
[783]="你学着锻炼了数年，开始隐约感受到一股气流在体内游荡。某日气流四处乱窜，引得你经脉尽断七窍流血，眼前一黑便再也没有醒来……",
[784]="走马上任途中，你在一处小镇休整，发现几位流氓正在调戏一位姑娘，你出手教训并赶走了流氓，获得了姑娘的谢礼。",
[785]="你的队伍在你严格的训练之下，军纪严明，士兵士气高涨，成为了军中一支精英小队。",
[786]="敌军大举犯边，在边境烧杀抢掠，已破数城，边关告急。你的部队被调往边境抵抗侵略。",
[787]="你带领一支小队，对敌军的粮草部队进行拦截，成功截获了敌军最重要的一次粮草补给，使敌军军心涣散。",
[788]="在与敌军的一次遭遇战中，你身先士卒，率先撕开了敌军的防线，将敌军打得落花流水，大败而逃。",
[789]="你的部队行军经过山谷时，遭遇敌方埋伏，损失惨重。",
[790]="你驻防的城镇遭到敌军围攻，救援迟迟未至，你带领士兵依靠高耸城墙、有计划地使用火油和箭弩，艰难地打退了敌军一波一波的攻城，终于等到来援。",
[791]="你的部队在野外与敌军遭遇，被追击到江边，再无退路，你亲自击鼓，鼓舞士兵背水一战。全军求生欲强大，顿时士气大振，大败敌军。",
[792]="作为将领，你经常和部下一起训练，但是很快你就发现，很多人都跟不上你的训练强度，只能给部下们另外规划训练方法。",
[793]="休沐之日，你换上轻便的袍服，准备四处走走。束发时无意中发现，黑发之中已经掺杂了几根银丝……你突然意识到，年华易逝啊。",
[794]="你并未因为离开军中而放下武艺，每日都会在院中舞刀练剑，隔三差五便要去校场射上几轮箭。",
[795]="邻里有些孩童知道你当过将军，便缠着你要学带兵打仗。你也乐意教导他们，好动的便多教些武艺，爱念书的便多讲些兵法。",
[796]="年纪大了终究不比年轻的时候，一场风寒便让你觉得十分疲惫，休养了好些日子都还觉得精神不济。",
[797]="你时常泡上一壶清茶，在院中自得其乐地自弈。日落月升，时间就这么消磨掉了。",
[798]="佳节已至，城里张灯结彩。你走在热闹的街道上，看着身边的人们脸色洋溢的笑容，不禁感慨，昔日的沙场浴血换回百姓们的一方安宁，的确值得。",
[799]="与邻国的摩擦愈演愈烈，双方互派细作也愈发频繁……由于未能及时揪出奸细，你不得不率兵仓促应战。此战敌我兵力悬殊，你麾下的士兵纷纷倒下，你也渐渐被逼至悬崖边。精疲力尽之际，你决定……？",
[800]="兵力悬殊",
[801]="南征北战多年，你积累下赫赫战功。但随着年纪渐长，伤痛的影响越来越严重，所以你决定……？",
[802]="伤痛的影响",
[803]="继续坚守",
[804]="告老赋闲",
[805]="力竭而亡",
[806]="坚守沙场的你，最终战至力竭而亡。",
[807]="一生征战，你决心坚守在沙场之上。一次两军对战，年事已高的你依然率兵奋勇杀敌，战至力竭而亡。浴血捐躯，亦是荣光。",
[808]="军中猛将辈出，后继有人，你已经可以放心安享天年了。回京述职时，你顺势告老辞官，做个自在闲人。",
[809]="退伍后，你凭借从军的经验，也能接到一些护卫之类的活计，补贴家用。",
[810]="闲暇时，你还跟邻里讨教了如何种菜。一番施弄下来，蔬菜瓜果长势尚可，也能勉强自给自足。",
[811]="附近的孩子知道你的身份，缠着你教他们当兵打仗。你拗不过一群孩子的死缠烂打，答应教他们一些粗浅的功夫。",
[812]="有些不长眼的泼皮无赖看你是女子，便想从你这捞点好处，没想到却被你三两下揍得屁滚尿流地逃窜。",
[813]="几名富家公子千金想要进山狩猎玩耍，你护着他们在山林外围体验了一番，逮兔子猎山鸡，对方非常尽兴，给了你丰厚的报酬。",
[814]="你和镖师一起接了单生意，运货途中遇到了山匪，凭借从军的经验，你带着镖师将这伙山匪杀了个干净，不但顺利把货送到，还拿了官府的奖励。",
[815]="天气好的时候，你也会在村里四处逛逛，看看斗鸡、斗蛐蛐儿，和人唠唠家常，一日就过去了。",
[816]="近日有贼在附近几个村落流窜，不少人家丢了财物。你自告奋勇地加入村里组织的巡逻队，每日认真巡逻，仔细检查每个可能的藏身之处，最后果然捉住了那贼人。",
[817]="重操旧业的你时常进山捕猎，虽然伤痛让你再也无法单独猎杀虎、熊之类的猛兽，但捕捉小兽攒些皮毛售卖却是不难。",
[818]="退伍之后终究不比当年，一场风寒便让你觉得十分疲惫，休养了好些日子都还觉得精神不济。",
[819]="有些时候，你会带上村里的少年到山林外围练习捕猎，教他们辨认方向，分辨不同兽类的足迹……看着少年们精力旺盛的模样，你竟有几分欣慰。",
[820]="深秋时节，你猎到了一只肥硕的红狐，一身皮毛油光水滑，极为漂亮。你仔细地将红狐皮毛硝制好，带进城里售卖时果然被一位富家公子看中，卖出了极好的价钱。",
[821]="夜间，村里走水，火势蔓延极快。在众人忙于救火之时，你发现了一个鬼祟的身影，认出其正是邻村的无赖，想必就是此人纵火，你决定……？",
[822]="何人纵火",
[823]="暗中跟随",
[824]="上前捉人",
[825]="你料想对方还有同谋，便暗中跟随，果然看到他与另一无赖汇合。你上前三两下制服了这两人，押回村里供村长审问。村老做主给了你一些奖励的银钱，村民们也十分感激你抓到了罪魁祸首。",
[826]="你气得直接上前将人揍了一顿，然后押去给村长审问。大家都十分愤怒这无赖的行为，对你大加赞赏。",
[827]="你在自家的菜地旁挖到一块硕大的块茎，长得与红薯有些相似。凭借经验，你大致确定其并无毒性。此时已至正午，你正是腹饥，是否要尝个鲜，将之烹煮食用？",
[828]="煮来吃了",
[829]="坏了……这块茎竟有剧毒！你食用不到一刻便觉腹痛难忍，口鼻开始流血，终究两眼一黑，再也没能醒来……",
[830]="未能辨别的食材，还是不要食用为好。你最后还是把块茎扔了，摘了些新鲜的菜回家烹煮。",
[831]="一日，你照常进山捕猎砍柴，不料山中大雾忽起……不知走了多久，前方似有人声，你循声而去，雾也渐薄，最终竟来到一处石洞之内。只见石洞中正有两名老者捻须对弈，你不过看了一眼棋盘，竟不知不觉痴了……直至耳畔忽闻一声：“你观棋许久，还不离去？”你这才回过神来，棋盘上胜负已分，一抬头便发现两名老者都看着你。你决定……？",
[832]="老者对弈",
[833]="恭敬行礼",
[834]="仓皇离开",
[835]="烂柯百年",
[836]="深山观棋一局，忽逢机缘，你由此踏上仙途。",
[837]="仙家弈棋，百年一瞬。你冒然观棋，竟因此身亡。",
[838]="你自觉失礼，恭敬地对两位老者长揖到底，恭敬道：“在下未经许可便冒然观棋，打扰了两位的雅兴，实在抱歉。”其中一老者闻言笑道：“身具灵根，从容有度，倒是个苗子。既然相遇，便是有缘，你可愿随我修行？”听得此言，你登时欣喜若狂，连忙再度拜谢。对方见状，拿出一枚长得像枣子的果实叫你吃下。你依言照做，顿觉神清气爽，隐有脱胎换骨之感。两名老者也不多言，直接拂袖将你一卷，便御风离去了……",
[839]="冒然观棋太过失礼，你万分羞惭，竟是头也不回地匆匆离开。然而出了石洞，你顿觉无力，一下子瘫坐在地。此时一道声音遥遥传来：“仙家弈棋，地下百年。”闻言，你怔怔地看着自己皱纹满布的双手和毫无光泽的白发，竟是再也支撑不住地倒了下去……",
[840]="你照常出门狩猎，突然感到一阵心悸，天旋地转。你意识到或许是大限将至，此时一抹虚幻的玄妙身影出现在你的面前，说与你有缘，可赠你一枚寿元丹续命。你决定……？",
[841]="延长寿命",
[842]="父母已故，你只觉生死有命，婉拒了神秘身影的好意，坦然面对此生的终点。",
[843]="一生与山林为伴，自给自足。终是生死有命，已行至尽头。",
[844]="光阴似水，天时已至，此生已行到尽头。",
[845]="你逐渐康复，但也不复当年之勇，饱受他人嘲笑凌辱，却也无力反驳。不甘就此渡过余生的你，独自一人一弓步入深山，再也没有回来。",
[846]="不复当年",
[847]="重伤不复当年勇，你步入深山，了却残生。",
[848]="你逐渐康复，某次村中遇袭，仍旧站在村民最前头，但这次，你却已无力守护……",
[849]="重伤不复当年勇，你欲护村民，却因此而亡。",
[850]="<color=#c82c2c>[判定失败]</color> 你在下坠的过程中，隐约看到山崖间有一处石洞，更有几丝神秘的雾气自洞中溢散而出。你不禁叹息，若是能掉入那洞中，说不定就能死里逃生，另有一番造化……剧痛在触及地面的那一刻传来，你两眼一黑，便什么都不知道了……",
[851]="你欲摘崖边奇花，不料一脚踏空，因此坠亡。",
[852]="一生浴血沙场，终是生死有命，已行至尽头。",
[853]="一生浴血沙场，奋勇争先。终是生死有命，已行至尽头。",
[854]="一生枕戈待旦，换得国泰民安。去时无憾，终能含笑九泉。",
[855]="你生于一个猎户之家，在家中里排行老二，大哥名叫大郎，父母便给你取名叫{0}。",
[856]="一条毒蛇闯进家里，大哥被吓得瑟瑟发抖，你却冲上去捏住蛇的七寸，把它活活摔打至死",
[857]="你的父母在外出狩猎途中意外遭遇猛虎，双双惨死，从此只剩下你与大哥相依为命",
[858]="你的大哥顺利成亲，娶了一个十分漂亮的嫂子。你由衷地为大哥感到高兴",
[859]="为了不拖累大哥，你决定独自外出闯荡，行走江湖谋取生计",
[860]="你路过一处客栈，在里面喝了十八碗酒，然后跌跌撞撞地继续赶路，此时看到一处告示，上书”前有猛虎，即刻折返”，该如何是好呢？",
[861]="猛虎出没",
[862]="勇往直前",
[863]="该怂得怂",
[864]="你借着酒劲继续前行，中途果然跳出来一只老虎，被你揪住脖子活活打死，此举让你名声大振，成为了一名打虎英雄",
[865]="大丈夫能屈能伸，你赶紧回头就跑，再也没有经过这片是非之地",
[866]="因你打虎立下的威名，官府决定招揽你为都头，你总算有了一份稳定的生计",
[867]="你遇到了一位江洋大盗，追了他七天七夜后成功将其擒获，还从他身上搜出一本禁书《银瓶梅》",
[868]="你奉命剿灭一群山贼，但在半路遭到山贼埋伏，一番血战后，你险死还生，仅以身免",
[869]="在闹市巡逻途中，一名小贼竟然偷到了你的头上，被你当场抓获",
[870]="听闻某地有一个江湖骗子在招摇撞骗，你前去查看，发现他竟然真的会法术，令你大为震惊",
[871]="你结识了一名酒肉和尚，此人大口喝酒大口吃肉，一点没有出家人的样子，与你十分投机，故结为好友",
[872]="你回家探望大哥，却发现大哥已被嫂子毒死。嫂子当即表示，只要你不说出去，她什么都愿意做",
[873]="回家探亲",
[874]="杀人偿命",
[875]="原谅嫂子",
[876]="你杀死了这个谋害你大哥的妇人，让自己也沦为了一个杀人犯。你已无法再回官府，只能改名换姓流亡他乡。",
[877]="你观嫂子也有几分姿色，就这么杀了太可惜了，不如留她一命来侍奉你",
[878]="为了生计，你不得已落草为寇，与曾经你所厌恶的山贼土匪为伍，投靠了在太岳山脉占山为王的一个山寨",
[879]="你发现你们山寨里有一位道士，自称什么入云龙，法力十分高超，令你大开眼界",
[880]="你和几名土匪一同劫了官府运送的官银，满载而归返回山寨，大伙都十分高兴",
[881]="官府派出一支官兵前来剿匪，你亲率一支敢死队夜袭官兵营寨，把他们打得落花流水",
[882]="在你们的山寨附近有一个祝氏家族，据说是什么修仙家族，竟然杀死你们山寨的一个头目，这个梁子可算是结下了",
[883]="为了报复，你们山寨大举进攻祝氏家族，一路势如破竹，遇到的人全都不是你的对手",
[884]="就在此时，一名修仙者突然出手，顷刻间万剑袭来，你们山寨顿时死伤惨重，被其以一己之力打得毫无还手之力",
[885]="你亲自体会到修仙者的可怕实力，凡人在其面前犹如蝼蚁，纵然你一身武艺，也完全不是其对手",
[886]="被祝氏家族的修仙者击败后，山寨只得开始休养生息，不敢再去招惹他们",
[887]="你带领一群土匪出去打家劫舍，还劫了一名女子回来，给你当压寨夫人",
[888]="你发现当初结识的那名酒肉和尚也在山寨里面，你们久别重逢，相谈甚欢",
[889]="入云龙因其在山寨中地位超然，向来极少出手，不知为何这次却答应了和大伙一起再次攻打祝氏家族，这次己方也有修仙者助阵，想来不会像上次那般狼狈",
[890]="山寨再次攻打祝氏家族，你在此战中大展拳脚，可谓如入无人之境",
[891]="入云龙与祝氏家族的修士开始斗法，两人均施展出惊世法术，最终还是入云龙技高一筹，成功击败对方修士",
[892]="没有了修仙者的阻碍，祝氏家族已毫无还手之力，被你们山寨成功剿灭。你从中搜刮到了一把银辉孤刃，看上去是一件法器",
[893]="山寨中的日子十分苦闷，若是没有机会下山打劫，你便只能对着深山野林发呆",
[894]="听说朝廷有意派人前来你们山寨招安，对此一名弟兄评价道：“招安，招安，招鸟甚安！”",
[895]="你的压寨夫人给你生了一个儿子，你先是感到十分高兴，可想到这个孩子长大了以后估计也只能和你一样当土匪，又高兴不起来",
[896]="有消息称官府派出大军前来剿匪，声势浩大，这次是动真格的，反抗者一律格杀勿论",
[897]="一日，山寨中的道士说你是天伤星转世，有成为修行者之姿，问你要不要跟他学习法术",
[898]="天星转世",
[899]="你早就对修仙者的手段十分羡慕，当然满口答应下来。道士便教了你一些基础的法术，你果然一点就通",
[900]="你思索再三，还是决定精于武道，不去学习什么法术。若是依赖法术，就无法在武道上更进一步了",
[901]="官府派人发来最后通牒，让你们决定是否接受招安。一旦拒绝招安，他们将把整个山寨屠戮殆尽",
[902]="官府招安",
[903]="为了将来考虑，你决定赞成接受招安，其他人也大多是这么想的。最终山寨被顺利招安，你们摇身一变成为官兵",
[904]="你知道官兵都是什么货色，坚决反对招安。在你的鼓动之下，山寨也逐渐达成统一意见，不愿接受招安",
[905]="在被招安以后，你又被官府重新任命为都头，忙活大半生回到原点，让你哭笑不得",
[906]="拿着官府的俸禄，你过上了大口吃肉，大口喝酒的快活日子",
[907]="你遇到了一名江洋大盗，与其大战三百回合后成功将其捉拿归案",
[908]="你在运送官银的途中遇到一群土匪，经过一番英勇作战后，你成功击退了这群匪徒",
[909]="你的儿子突发恶疾身亡，你的妻子因悲痛过度也继而死去，你一夜愁白了头，仿佛世间再无牵挂",
[910]="你又遇到了当初那位酒肉和尚，他邀请你一起出家，他当和尚，你做行者，不知你意下如何？",
[911]="出家邀约",
[912]="如此也好",
[913]="并无此意",
[914]="你早已萌生过这样的念头，如今不过是正合你意，你与酒肉和尚一起出家，成为了一名行者",
[915]="你对世间红尘仍有所眷念，所以并未打算出家，婉言拒绝了酒肉和尚的建议",
[916]="成为一名出家人以后，你对世间的感悟变得愈发玄妙，开始领会到了一些凡人无法理解的事物",
[917]="你开始学会使用之前在祝氏家族处搜刮到的法器银辉孤刃，此刀甚是奇异，经其劈斩的枝丫生机不失，栽种于灵壤之中即可存活",
[918]="通过以往入云龙教导你的法术，你逐渐能够感悟到世间存在的灵气，已达初窥门径之境",
[919]="你日夜修行，背诵经文，心境愈发澄明，世间的一切已无法对你产生干扰",
[920]="你感觉自己逐渐看破了红尘，心中已无世俗的欲望",
[921]="你的好友酒肉和尚在一个信潮来临之夜圆寂，但此时你的心中已无半点波澜",
[922]="此后你抓紧时间修炼，期望在大限来临之前有所突破，成为一名脱离凡尘的仙人",
[923]="你日夜苦心修炼，然而此生浪费在凡俗中的时间实在太多，你已无足够时日达成突破",
[924]="你感觉自己大限降至，是否尝试炼制一些丹药用以续命？",
[925]="丹药续命",
[926]="炼制丹药",
[927]="顺其自然",
[928]="你尝试炼制了一些丹药，吞服之后感觉自己的寿限又延长了些许，却也不会太长",
[929]="出家多年，你早已看破红尘，生死有命，顺其自然罢了",
[930]="你花费了毕生时间精进武道，直至劳累过度咳血至死，还是未能以武入道",
[931]="终于你还是无力回天，带着无数感悟离开人世。数不尽的往事浮上心头，到底从哪一步开始你走错了呢？",
[932]="你拒绝朝廷的招安，和其他一起不愿介绍招安的弟兄们死守山寨，直到大批官兵来攻，一路血战直至力尽而亡",
[933]="你是一名穿越者，某日被一辆大货车撞死后，重生到这个世界一处小商贩之家，取名叫{0}",
[934]="伴随着“叮”的一声，身为穿越者你体内的系统开始觉醒，其名为最强的祖师系统",
[935]="你逐渐这个最强的祖师系统是怎么回事，它可以让你培养成世间最逆天的弟子，但代价是你自身永不能修仙",
[936]="你不禁破口大骂：坑爹呢！我自身永远是个凡人，如何培养出世间最逆天的修仙弟子？",
[937]="系统给你发布了第一个任务，让你去收一名天生杂灵根的废柴弟子，完成任务后可获得天赋奖励",
[938]="你花了九牛二虎之力，终于找到了这名天生杂灵根，据说修炼一辈子都达不到练气期的废柴弟子，问他：“小兄弟，想不想修仙啊？”",
[939]="你完成了系统给予的任务，如今系统给予你两个天赋可供选择：1.高深莫测，别人永远无法看透你的修为虚实；2.神眼洞察，你能一眼看穿他人的修为境界",
[940]="天赋选择",
[941]="高深莫测",
[942]="神眼洞察",
[943]="你获得了系统给予的天赋奖励【高深莫测】，开始走上最强的祖师之旅",
[944]="你获得了系统给予的天赋奖励【仙风道骨】，开始走上最强的祖师之旅",
[945]="你开始带领你的大弟子韩羽开始修炼，不过你给他安排的任务都是一些耕田砍柴的杂物，没有传授任何功法，毕竟你也没有任何功法可以传授",
[946]="你给自己的宗门取了个名字叫{0}，算是踏出了开宗立派的第一步",
[947]="韩羽干活十分刻苦，让你感觉相当满意，从此所有脏活累活都由他来干，你躺平即可",
[948]="有时韩羽也会问你，为何不传授他功法，你的回答都是：“这是磨练你的心性，天将降大任于斯人也，必先苦其心智，劳其筋骨”",
[949]="韩羽似懂非懂的点点头，连这种鬼话都信，看来他天生废柴不是没有原因的",
[950]="在闲暇之余，你不断地给韩羽洗脑，说：“我徒儿有大帝之姿，他日必将凌绝三界。”",
[951]="韩羽依然缠着你要修仙功法，你只好对他说：“修仙最重要的就是悟性，大道至简，悟在天成，你去冥想三年，看看能悟出来什么吧。”",
[952]="韩羽听了你的话，真的跑去冥想修炼了。你不禁觉得好笑，一个天生杂灵根的废柴究竟能悟出来什么",
[953]="还没等你想好怎么办，这名精神失常的人就自己冲上来，抓住你的肩膀问道：“医生，你看我还有救吗？”",
[954]="你感觉十分疑惑，这个世界的医生不是叫大夫吗？你沉思一番后开口说道：“你的状况很严重，但不是没有救，你先拜我为师，我教你怎么做。",
[955]="在你忽悠之下，这名精神失常的人也成为了你的弟子，他的名字叫杨宇，似乎和你一样是一名穿越者",
[956]="最近你感觉韩羽的情况有些不对劲，用系统给予的神眼洞察一看，发现他竟然已经达到了筑基期，这是怎么做到的？",
[957]="杨宇的情况十分诡异，他认为自己是一个现代人，如今身处的世界都是幻觉，以至于他在现实中被人当成精神病",
[958]="为了证实自己的猜想，你向杨宇问道：”奇变偶不变，下一句是？“，杨宇回答道：”符号看象限。“",
[959]="杨宇时常会把你看成自己的精神科医生，你都能顺着他的话扮成他的精神科医生，让杨宇感到十分惊奇",
[960]="韩羽的修炼最近似乎进展迅速，你再看见他的时候，他已经能御剑飞行了。你不禁疑惑，难道废材竟是你自己？",
[961]="你发现韩羽身上似乎隐藏着某种秘密，每到夜里他都会悄悄溜出去，然后早上才回来",
[962]="你发现韩羽总是会瞒着你偷偷服食丹药，也不知道他的这些丹药究竟是从哪里来的",
[963]="自从杨宇确定了你是他的师父而不是什么精神科医生后，他似乎终于对你死心塌地，行为表现也变得正常多了",
[964]="某天一名少女找到你，说要拜入你的门下，你一问才知道，她的名字叫林青儿，偶然在一次妖兽袭击中被韩羽所救，从他口中得知了你是韩羽的师父",
[965]="这样你的门下便多了一位赏心悦目的女弟子，可喜可贺，可喜可贺",
[966]="你发现这个林青儿似乎也不简单，你时常能看到她身上弥漫的魔气，有时让你都感到胆战心惊",
[967]="你听说太岳山脉最近准备召开一场宗门大会，于是你也带着弟子欣然赶去前往，算是露一露脸，以便日后收徒",
[968]="杨宇想让你传授他一些功法，你实在没有什么好教他的，只好信口胡编了一套。杨安问你这是否有用，你回答说：“你信则有用，不信则无。”",
[969]="几位掌门把目光投到你的身上，随后发现以他们的修为，竟然也看不透你的修为深浅，顿时惊为天人，赶紧把你奉为上宾",
[970]="几位掌门把目光投到你的身上，随后发现你身上竟无半点修为，顿时露出鄙夷的目光。但此时你却开口一一点破他们的修为境界，让他们感到十分震惊",
[971]="这几位掌门心想：一介凡人怎么可能看透他们的修为境界，除非此人其实是在扮猪吃老虎，刻意隐藏自己的修为，才让他们完全感觉不到",
[972]="想到此处，这群掌门都已汗流浃背了，赶紧请你上来，将你奉为上宾，不敢有丝毫怠慢。",
[973]="宗门大会里发生的事传开后，你顿时名声大振，整个太岳山脉都知道有你这么一位实力高深莫测的祖师爷，当天魔入侵时，无所谓，你会出手",
[974]="自从你名声大震后，你感觉手下几名弟子看你的眼光都不一样了。以往他们对你将信将疑，如今他们都坚信你是最强的祖师",
[975]="没想到杨宇真的炼成了你信口胡编的功法，成功达到筑基期，高兴地大喊：“哈哈，道爷我成了！我成了！哈哈哈！”",
[976]="你发现了韩羽身上似乎多了一个翠绿的小瓶子，不知道是从哪里来的，他对此十分宝贝，几乎从不拿出来给别人看",
[977]="一天，你遇到了一个精神失常的人，嘴里不断念叨着：“我分不清，我真的分不清啊！”，此时系统忽然给你发布任务，让你把此人收为弟子",
[978]="招募弟子",
[979]="收为弟子",
[980]="你在逗我",
[981]="你上前和这名精神失常的人搭话，试图把他收为弟子，但要如何说服一个精神不正常的人呢？",
[982]="你感觉系统这是在逗你，让你收个天生废柴就算了，现在还要收个傻子，难道你这个最强的祖师是捡破烂的？",
[983]="杨宇说自己的病情越来越严重，他不断地追问你，你到底是谁？是他的精神科医生，还是他的师父？",
[984]="病情严重",
[985]="精神科医生",
[986]="师父",
[987]="杨宇很生气，说：既然如此那就快点治好我，不要再装神弄鬼的了！你无奈地点点头，却也无能为力。某天早晨，你发现他人不见了",
[988]="听到你的回答，杨宇沉默了一阵后，忽然癫狂地笑道：哈哈哈，原来这边才是真的！那边全是幻觉！",
[989]="你赶到宗门大会现场，此时台上的几位掌门正在讨论最近天魔入侵事件，称修仙界即将有大难临头，改如何是好？",
[990]="天魔入侵",
[991]="无所谓，我会出手",
[992]="什么是天魔？",
[993]="此言一出，在座所有人的目光瞬间都停在了你的身上，看看是谁如此大言不惭",
[994]="几位掌门露出一幅看土包子的颜色，根本不搭理你，看来你被鄙视了",
[995]="你感觉自己大限将至，可此时你还没有将几位弟子培养成才，该如何是好",
[996]="尝试续命",
[997]="你只好拉下脸去找韩羽，让他给你寿元丹，没想到他真的有，还问祖师要几颗，看来这小子深藏不露啊",
[998]="由于系统的限制，无论你有多少寿命，最终都无法有半点修为，你感觉此生无趣，不如寿终正寝罢了",
[999]="杨宇失踪很久后，某日他突然再次出现在你面前，嘴里大喊着：“庸医，我取你狗命！”，然后一刀把你捅死了",
[1000]="在天魔入侵中，你履行了当年在宗门大会上承诺，亲自出手对抗天魔，结果毫无悬念地被如同蚂蚁般捏死",
[1001]="你作为一名凡人寿终正寝了，日后你的弟子都成为了威震仙界的大能，你也被他们追念为最强的祖师，可惜这些你都看不到了",
[1002]="你出生在一个夏夜，是个女孩，名叫{0}。你爹娘在城里支了个面摊谋生。",
[1003]="小贩之子",
[1004]="你出生于小贩之家。",
[1005]="做吃食的营生很忙碌，起早贪黑，你每天一大早跟着爹娘出摊，不吵不闹，很多人都夸你乖巧。",
[1006]="爹娘很疼你，每次给你煮的面都会多加一个鸡蛋，把你养得白白净净。",
[1007]="看着爹娘忙碌，稚童之龄的你也想帮一帮忙，你决定……？",
[1008]="稚童之龄的你",
[1009]="招呼客人",
[1010]="收拾碗筷",
[1011]="你努力地招呼着来吃面的客人，声音软糯，十分讨喜，让许多人的心都跟着软了。",
[1012]="你努力地帮爹娘收拾碗筷，虽然一次拿得不多，但多拿几次就好了，小小的身影在面摊里来来回回，走得稳稳当当。",
[1013]="有位教书的老先生是你家面摊的常客，看你渐渐长大，伶俐懂事，便让你免费去他的学堂念书识字。",
[1014]="你在老先生的学堂学得十分认真，从不落下任何功课。闲暇时候，你还会多学一些……？",
[1015]="勤奋的你",
[1016]="诗词歌赋",
[1017]="钱经算术",
[1018]="你喜欢听先生讲诗词歌赋，那些美好的句子、故事，虽然你不是全都能听懂，但总觉得挺美的。",
[1019]="你想着多学些钱经算术类的知识，懂得多一分，便早一日能给家里的面摊多帮些忙。",
[1020]="从小耳濡目染，你开始帮着爹娘发面、备料、煮面，甚至还能兼顾算账的活计。",
[1021]="今年面摊的生意不错，过年时，爹娘难得地买了肥鸡切了牛肉，一家人吃了顿丰盛的年饭。",
[1022]="今年生辰，娘亲说要送你一份礼物，让你自己挑选。你决定……？",
[1023]="生日礼物",
[1024]="要个荷包",
[1025]="求平安符",
[1026]="你想了想，让娘亲带你在面摊旁的杂货小贩那里买了个便宜但很精致的刺绣荷包，塞上醒神的草药，十分合适。",
[1027]="你想了想，让娘亲带你去城郊的寺里求了三枚平安符，爹娘和自己，一人一枚。一家人都贴身带着，也是心安。",
[1028]="你于面食上很有天赋，甚至还改良了发面的工艺，面摊的面条多了不同粗细的分类，生意愈发好了。",
[1029]="你到了可以说亲的年纪，附近的媒婆们早早相中了你的贤惠勤劳，想要给你说一门亲事。你决定……？",
[1030]="媒妁之言",
[1031]="嫁给书生",
[1032]="你嫁为人妇，但依然以面摊的营生为重。",
[1033]="你醉心钻研面条，决定以面摊的营生为重。",
[1034]="女大当嫁，你听从了爹娘和媒婆的劝说，最后与一名家境清贫但为人踏实的书生成了亲。但夫君醉心念书，家无甚积蓄，你还是以面摊的营生为重，也能帮补一二。",
[1035]="你对面摊的生意很有些打算和想法，有理有据地努力劝服了爹娘，先以家里的营生为重。",
[1036]="爹娘按照你的计划，改良了汤面的种类，客人们赞不绝口，小小的面摊经营得门庭若市。",
[1037]="春天，你跟着有经验的妇人去城外摘了许多野菜，却没与爹娘一起享用，而是腌成小菜搭着面条售卖，很受欢迎。",
[1038]="酷暑天气，热汤乏味，你便尝试着去了面汤，用凉水过面，做出了爽口的凉面，令食客们赞不绝口。",
[1039]="蝗灾导致粮食减产，面粉的价格也因此贵了许多，面摊的利润薄了不少。",
[1040]="仔细研究了各种作物，你发现土豆、荞麦、绿豆等也可做成类似面条的食物，口感新鲜，价格也比面粉便宜。",
[1041]="你私下调整了多次，直到自己满意了，才开始尝试售卖这些杂粮面，没想到反响很好，面摊的名声竟越来越大了。",
[1042]="有些挑担卖些零碎杂货的孩童，因为你家面摊生意旺，便经常凑在面摊附近吆喝买卖，你却没有跟其他摊主一样将这些孩子撵走。",
[1043]="爹娘染了风寒发起高烧，你既要照顾双亲又要看顾面摊的生意，有些力不从心，忙乱间煮坏了几碗面。",
[1044]="你不舍得浪费那几碗煮干了汤水、有些焦糊的面，加了些料子焖炒一番打算自己吃了，不料竟是浓郁鲜香，别有风味。",
[1045]="这个意外发现让你又有了灵感，一鼓作气研究出了焖面，面摊的生意又红火了不少。",
[1046]="有高门大户的管事前来，想要你入府当个专门煮面的厨子。你只回了句“不过是一碗面，人人都能吃得上才好”，便淡然婉拒了。",
[1047]="有个好吃的食客一日念叨，面条可带汤、可凉拌、可焖煮，不知烤着吃又是何滋味？你记在心上，发明了荷叶笋丁烤面，大获好评。",
[1048]="因为价格厚道口味好，城里的官差也时常来你家面摊吃面，有些不长眼的泼皮无赖想讹你交保护费，被官差们收拾得服服帖帖。",
[1049]="你对“面”之一道非常上心，有机会时，甚至会到临近的城镇学习别家面摊的做法，取长补短，融合到自家的面条做法里来。",
[1050]="听说城北新凿的那口井之井水清冽甘甜，你便雇了相熟的担夫，每日运来足量的井水供面摊使用，果然汤头鲜美又上层楼。",
[1051]="有两名书生来吃面，吃到一半争论起来，什么“民以食为天”、“饱食怠惰，不若腹饥利苦读”之类的，竟是吵得面红耳赤。",
[1052]="你看他们吵归吵，动筷却如飞，面碗三两下见了底，还意犹未尽地舔着唇。大道理你不懂，只上前问了句“可要再添一碗面？”",
[1053]="“再来一碗！”二人竟是异口同声。你笑道：“俗话说吃饱才有力气做事，想来念书也是一样。”二人听得此言，不再争吵，若有所思。",
[1054]="你自去煮面上面，二人吃完付账时竟一齐郑重冲你拜谢，其中一人道：“是我迷障了，老板娘心思通透，面摊虽小，锅中乾坤大。”",
[1055]="城里来了一批衣衫褴褛面黄肌瘦的灾民，一些富商开始施粥，你也力所能及地每日多煮些素面送去，直至官府彻底安顿好这批苦命人。",
[1056]="有个卖包子的妇人嫉妒面摊的生意好，便让她的镖师丈夫天天带着凶狠壮硕的镖师来面摊捣乱。你不堪其扰，正愁着怎么解决此事……",
[1057]="城里新上任的官老爷命衙役捉拿了这群镖师，当着全城人的面公开审理，让这群人再不敢仗势欺人，众百姓一片叫好。",
[1058]="你正要拜谢官老爷，不料对方侧身避开了，只道：“当年三碗面之恩，以此为报。”你恍然大悟，不由更加坚信善有善报的道理。",
[1059]="面摊来了个气质神秘的客人。你从未见过这么好看的人，像是从画里走出来似的。对方吃完面，叹道：“此味罕有，俗世果然有趣。”",
[1060]="城里来了名老道士，这老道很奇怪，摆摊算命每日却只算3卦，算卦的钱也是让人随意看着给点。",
[1061]="今日，你看见老道给老李家的凶婆娘李张氏算命，结果被那妇人拿着扫帚追打，不依不饶地从街头打到街尾，直闹到你家面摊边上。你看这老道狼狈的模样，决定……？",
[1062]="老道惹祸",
[1063]="劝说一番 [魅力判定]",
[1064]="不欲理会",
[1065]="老道与面",
[1066]="老道惹祸，被人追打。你出面相劝，帮了老道一把。",
[1067]="老道惹祸，被人追打。你出面相劝失败，无可奈何。",
[1068]="老道惹祸，你沉默围观。此后再也没见过对方。",
[1069]="<color=#549327>[判定成功]</color> 你和那李张氏也算打过照面，连忙上前好言好语地安抚了半天，总算是把人给劝得消了气，放过了这老道。从这一天起，老道的算命摊子就摆在了面摊的旁边。",
[1070]="<color=#c82c2c>[判定失败]</color> 眼见越来越多人聚过来围观，你连忙上前，想要劝说李张氏消气。然而四周一直有人起哄，如同火上浇油一般，最后竟闹得引来了官差将李张氏与老道一并带走。从此之后，你便再也没见过这老道了。",
[1071]="你看了看李张氏那怒气冲冲的模样，不欲惹火上身，只在一旁沉默地围观。最后这事闹得引来了官差将李张氏与老道一并带走。从此之后，你便再也没见过这老道了。",
[1072]="今日收摊，还余下一些面，你正准备自个吃了，抬头正巧对上了老道的眼神，那眼巴巴看着的样子......看着也是饿了，但他可没钱呐。你决定……？",
[1073]="可怜的老道",
[1074]="请他吃吧",
[1075]="吃独食",
[1076]="收摊时，你请那个算命的穷老道吃了碗面。",
[1077]="眼馋面条的老道没钱，你决定吃独食。此后再没也见过对方。",
[1078]="老道听你说这碗面不要钱，千恩万谢地接过，开心地吃了起来，因为吃得太急，被烫得“哈斯哈斯”地呼气。",
[1079]="你装作没看到这老道，做生意谁都不容易，你这不也饿着肚子，还是吃饱了早些收摊回去。你回家时，老道还在慢吞吞地收摊，你看着对方瘦削的背影，莫名地有些不忍……如果请他吃碗面，是否会好一点呢？这一夜，你辗转难眠，第二天顶着有些发晕的脑袋去面摊忙碌时，你发现老道没来摆摊。从此，对方再也没有出现过。",
[1080]="随后几天，老道仿佛掐着点似的，待你收摊时都会过来，有意无意地说些吉利话，你也就把剩下的面盛给了他吃，看着他连面汤都喝光的样子，莫名觉得他也挺可怜的。",
[1081]="……可怜个屁啊！这老道在你这吃了整整一年！每日从不间断，这吉利话怎么就不带重复的？！看这样子样子似乎能再吃个几年，附近的摊主都快拿你当笑话了！",
[1082]="今日收摊，你和往常一样，把剩下的面盛给了老道。他这回却吃得很慢，吃完后将碗筷摆好，从怀中取出一本书册塞到你手中，说是用来抵这面钱，你看了下书皮，写着“乞面条”，这都什么跟这么……抬头却已不见老道身影。",
[1083]="老道赠书",
[1084]="老道送了你一本《乞面条》，便再也没有出现。",
[1085]="此后你便再也没见过老道了，以往每天特意多留的面也不用留了。这日收摊后，你闲来无事，便取出那书册看看，这《乞面条》是一本游记，记录了老道游历各地的见闻，甚是有趣，原来他叫齐修？",
[1086]="齐修老道",
[1087]="一册游记，老道所著，其名：齐修。",
[1088]="不知怎的，你近来夜里时常发梦，老道那说的吉利话一遍一遍的在脑海中回响，以至于你白天忙活的时候都会分神……",
[1089]="这！这《乞面条》竟是仙书！你无意中发现，只要翻看此书时心中默念老道说的吉利话，书中的文字便时隐时现，什么练气凝神、千日筑基，功法口诀看过一遍便叫人无法忘掉！",
[1090]="这老道，竟是仙人么？你依照书中玄机，开始修行……数月后，面摊再也没有开张。你背上行囊，踏上了寻访仙门之路……若能寻得一处修仙宗门，拜进门中，说不定还能再打听到老道的消息呢？你微微一笑，脚步愈发轻快起来。",
[1091]="《乞面条》的机缘，让你得以开始修行，踏上仙途。",
[1092]="你在夏天的烈日下忙得头晕，午后吃面的人少了许多，你正想喝口凉水，不料面前竟递来几个饱满的莲蓬。你低头一看，莲蓬后是那几个挑担卖杂货的孩童有些害羞的笑脸。你笑着接过了莲蓬，剥开几颗莲子吃进嘴里，带着清凉的水汽，甜滋滋的。",
[1093]="你又要操持家务，又要去面摊忙碌，时日一长，夫家难免有些不满，让你颇为无奈。",
[1094]="今日是你的生辰，你夫君却一早就出门去参加诗会了，没有与你说半个字。你叹了口气来到面摊干活，却发现爹娘给你准备了一碗卧着鸡蛋和卤肉的面，你不禁微微红了眼眶。",
[1095]="你攒下一些银钱，想重新修葺一下有些破旧的厨房和院子，不料你夫君转头就把这笔钱拿去买了新书，没有与你商量。气得你和他大吵了一架。",
[1096]="冬天太冷，你忙进忙出地干活，汗水湿了又干，不慎受了风寒，做事时便颇有些力不从心。中午你赶回家煮饭晚了半个时辰，你夫君便不满地埋怨道：“做个饭都这么磨磨蹭蹭，我赶着吃完了还要看半本书呢！”你动作一顿，只觉得心比寒冬更凉。",
[1097]="每日在面摊忙碌，你记得许多熟客的喜好。看着熟悉的人，端上熟悉的面，间或闲聊几句，从早到晚，一日便过去了。你虽觉疲惫，但也十分满足。",
[1098]="除夕将至，今年面摊的生意很好，你与爹娘都买了新衣，割了猪肉牛肉，备下数只肥鸡肥鸭准备过年，全家都喜气洋洋的。",
[1099]="一名老饕富贾游玩到你所在的城镇，心血来潮要举办什么美食评选大会，城里的所有吃食摊档、食肆酒楼，都被他一一吃过。最终，富贾把头名大奖颁给了你的面摊，你握着那一大块金子，震惊得竟有些恍惚。",
[1100]="一群恶霸不知怎么在面摊旁打了起来，打着打着竟撞翻砸坏了不少面摊的东西，万幸没有把汤锅撞翻烫伤客人，但还是造成了不小的混乱。",
[1101]="一名风尘仆仆的年轻人来摊上吃面，也许是饿狠了，竟连吃了三碗，结账时他却拿不出足够的面钱。你决定……？",
[1102]="连吃三碗",
[1103]="通融一番",
[1104]="不能亏钱",
[1105]="对方神情窘迫不已，身上的衣服也满是补丁，定是有难处。你不欲为难可怜人，对方给了多少便收下多少。对方无比感激地给你鞠了三个躬。",
[1106]="起早贪黑挣点钱不容易，你要对方必须给够面钱。情急之下，这人竟掀了摊子上的汤锅拔腿就逃，你不幸被热汤烫伤",
[1107]="夜里快要收摊时，一名老乞丐凑到面摊前，想跟你讨一口热汤喝，你决定……？",
[1108]="老乞丐",
[1109]="日行一善",
[1110]="不答应",
[1111]="你看老人的年纪估摸很大了，想了想，给对方煮了一碗热腾腾的面。对方十分认真地吃完了面，连一口汤都没有剩下，然后笑着说了句“姑娘仁善”，便缓慢地离开了。你看着对方佝偻的身影，长长地叹了口气。",
[1112]="一人乞食，若是心软，便人人都来。你狠心拒绝了对方，只见老乞丐默默叹了口气，转身离开了。",
[1113]="有酒楼派人前来，许以重金想买你家各种面条的配方，你决定……？",
[1114]="重金收购",
[1115]="答应售卖",
[1116]="贪图小利",
[1117]="你贪图小利售卖配方，却因此砸了自家生意，家破人亡。",
[1118]="钱财动人心，你没忍住卖了配方。酒楼的大厨凭借这配方再作改良，引来老饕连连称赞。酒楼因此赚得盆满钵满，更转而诋毁你家面摊不干净。以讹传讹，面摊的生意再撑不下去。你爹娘一个没想开，投河自尽了。你悲愤交加之下，两眼一黑……",
[1119]="配方不仅是这小小面摊的立足之本，更是心血结晶。你真心喜爱钻研这一碗吃食的门道，千金不换，婉言回绝了对方。",
[1120]="时光飞逝，你的爹娘终究是年事已高，准备将这面摊交托到你手上。你决定……？",
[1121]="家业传承",
[1122]="不负所托",
[1123]="另辟蹊径",
[1124]="识人不清",
[1125]="识人不清的你被心思歹毒之辈谋了面摊，丢了性命。",
[1126]="你看着爹娘鬓边银白的发丝，不禁红了眼眶，认真点头，道：“我一定会好好经营，爹娘操劳了大半辈子，也该享享清福了。”",
[1127]="离了爹娘，你怕自己一人操持不过来，便决定与人合开这面摊。对方花了将近一年，才把各种配方和面条工艺掌握，能真正帮上你的忙。对方在家中设宴，亲自做了一桌菜说要答谢你，你吃到一半却觉得腹痛如绞，两眼发黑……在倒下去的最后一瞬，你听到对方得意地说了一句：“这面摊以后就是我的了……”",
[1128]="你与夫君并非同路人，你醉心面之一道，你夫君只在乎诗书功名。貌合神离的日子过久了，你决定……？",
[1129]="貌合神离",
[1130]="与他和离",
[1131]="继续忍耐",
[1132]="夫妻和离",
[1133]="夫妻和离，各自安好。你总算可以专心面摊之事。",
[1134]="你想了想，还是决定与夫君和离。本非同路人，一别天地宽，你搬回父母家中，总算可以全心全意地在面摊忙碌了。",
[1135]="但随之而来的还有一纸休书，只因他要与京中重臣之女结为夫妻。邻里街坊不免为你感到惋惜，你倒是彻底释然，忙不迭搬回了父母家中，只觉得松了口气，总算能过自己的日子了！",
[1136]="一纸休书",
[1137]="状元夫君一纸休书，你重获自由，专心面摊之事。",
[1138]="面摊的客人换了一拨又一拨，有些人从壮年到白发苍苍，某一日便再也没有来过。你看了看自己肩上又白了许多的发丝，还有越来越皱双手，决定……？",
[1139]="白发苍苍",
[1140]="继续经营",
[1141]="歇业休息",
[1142]="一生所执",
[1143]="一生执念，不过一个小小面摊。坚持经营，死亦无憾。",
[1144]="人生一世，醉心面之道，传了手艺，便含笑而终。",
[1145]="你一直坚持经营面摊，日日如此，风雨无阻。你的头发越来越白，动作越来越慢……一日，你弯腰给面汤下的火添柴时突然眼前一黑，便再没能站起来……",
[1146]="岁月催人老，也该休息啦。你算了算积蓄，决定关了面摊，过几年清闲生活。后来，你认了邻居家的四蛋做干儿子，只因对方喜欢吃面。你将面条的手艺传给了他，确认他学会了你的本事，便含笑而终了。",
[1147]="你正欲出门买些东西，刚走出门口便觉一阵天旋地转。\n你意识到或许是大限将至，此时一抹虚幻的玄妙身影出现在你的面前，说与你有缘，可赠你一枚寿元丹续命。你决定……？",
[1148]="你一生醉心于小小的面摊生意，钻研面条，不曾成家。年老时认了邻居家的四蛋做干儿子，只因对方喜欢吃面。你将面条的手艺传给了他，确认他学会了你的本事，便含笑而终了。",
[1149]="你每日起早贪黑地在面摊忙碌，今天的太阳不知为何特别毒辣，你越来越晕，突然眼前一黑……",
[1150]="你诞生在秋天，是个男孩。你娘是名绣娘，给你起名{0}。你爹从了军，很久才会回一趟家。",
[1151]="你娘独自带你，还要做些织绣物件摆摊售卖，过得很不容易。你生得机灵，很让娘省心。",
[1152]="临近年关，你娘的一幅绣品被富家小姐看中，卖了好价钱，高兴得带你去吃了顿好的。",
[1153]="夏季炎热，你发现街道那些大孩子常常提壶沿街叫卖茶水，你决定……？",
[1154]="叫卖茶水",
[1155]="加入他们",
[1156]="你向来机灵，很快就跟那群大孩子混熟。跟着他们一同叫卖茶水，你也能赚些零钱帮补家用。",
[1157]="现在正是李子成熟的时候，你便去城郊无主的李树摘果，再拿回家里的水井浸泡，到李子透着凉意，就上街兜售。",
[1158]="你运气不错，第一日兜售便遇上了富家子弟出游，一众锦衣玉食的公子小姐们瞧着野果新奇，纷纷买下尝鲜。",
[1159]="熟透的李子清甜中又带着凉意，解暑又好吃，竟包圆了果期，成了你的固定主顾，让你赚了一笔银钱。",
[1160]="家中余钱不多，你闲暇时就去相邻的书生家卖乖帮忙，又去私塾外的墙角偷听偷学，学到不少东西。",
[1161]="劈柴，煮饭，打扫，你主动揽下各种家务，已能替你娘分担许多。",
[1162]="郊外荷花盛开，莲蓬成熟。许多孩童和妇人都前去摘取莲蓬回城兜售，你也在其中。采摘时，你看到一名瘦弱的孩童被排挤，更有几名孩童上前抢夺他手中的莲蓬，你决定……？",
[1163]="抢夺莲蓬",
[1164]="助人一臂",
[1165]="你心中一软，干脆拉那孩童一起行动，避开人多的地方摘取莲蓬。对方感受到你的善意，回城时带你左拐右转，找了一处地方开始叫卖，竟像是熟知富家小姐公子们常行之路。新鲜的莲蓬很快卖空，你们相视一笑，皆很高兴。",
[1166]="你不认识那孩童，不欲多管闲事，不如抓紧时间多摘些莲蓬。这趟运气不错，你在一处偏僻的荷丛中找到了许多大个饱满的莲蓬，拿回城里很快就卖完了。",
[1167]="你经常陪着娘一起上街摆摊，帮忙的同时暗暗观察周围的摊贩如何做生意。",
[1168]="花灯节那夜，城里灯火如昼，摊贩挤满了主要的街道，你陪着娘出摊，却没占到往常的位置。你决定……？",
[1169]="花灯节",
[1170]="沿街叫卖",
[1171]="换个地方",
[1172]="你仗着身量小，动作灵活，干脆拿上一些绣品荷包之类的物件沿街叫卖，你口齿伶俐，惯会卖乖哄人，生意倒也不错。",
[1173]="你和娘决定到人流稀疏一些的街道去摆摊，不料运气不错，这一夜不少富家贵人经过这条街，出手阔绰，绣品荷包因此卖出去不少。",
[1174]="你爹战死沙场，消息和抚恤金一并传回。你娘为此哭伤了眼，再难刺绣。你被迫更快地成长，撑起这个家。",
[1175]="你娘托相熟的行脚商带着你跑了两年商，你每日忙碌奔波，收货卖货，见过不少城镇村庄的风景，学会识人。",
[1176]="你将成年，便是家中的顶梁柱。征兵在即，你有些意动，你娘却不愿你投奔沙场。你决定……？",
[1177]="征兵在即",
[1178]="做些生意",
[1179]="入伍从军",
[1180]="你决定摆摊卖些杂货，维持生计。",
[1181]="你未能如愿参军，只好做些小生意维持生计。",
[1182]="你终究还是放心不下母亲一人，这两年跑商也攒下些银钱，也有了人脉渠道，你便打算在城里摆个小摊买些杂货，维持生计。",
[1183]="入伍可领军饷，能让娘过得稳定些。你还是想去历练一番，终究劝服你娘，决心入伍从军。",
[1184]="怪风突起，把你刚摆好的货物中的一块红石吹走，石头滚到一位身着青袍的男子脚下，对方拾起放回摊位上，你想道谢时却发现人已走远。",
[1185]="你发现街道的其他商贩所售货物和自己差不多，心想不如卖些其他东西。结果新进的货物卖得不太好，旧货也一直积压，让你懊恼不已。",
[1186]="有位客人看上了你摊位的一个小铜像，想用极低的价格买走。裤衩都赔掉的生意自然是做不得的，一番讨价还价后，你成功让客人气急败坏地空手离去。",
[1187]="你正要收摊，突然来了个老头抛下重金，抓起一枚掐金丝的女式发簪撒腿就跑，动作之敏捷竟似比兔子还快。他付的这笔巨款也令你咋舌，真是怪哉。",
[1188]="你眼见城里恶霸要来收“保护费”，想偷偷开溜却被抓个正着。恶霸把你揍了一顿，临走前还一脚把货物踢飞，你只能自认倒霉。",
[1189]="你吆喝着卖货物，突然飘来一阵脂粉幽香，你侧头发现是位漂亮女子，不由感叹真美……回过神却发现摊上丢了东西，气得晚饭都少吃了两口。",
[1190]="可能运气不好，今天你一件货物都没卖出去，收摊离去时还风雨交加，你叹气道：“难道老天爷也不喜欢我么……”",
[1191]="你近日生意不好，街道上一起长大的玩伴见状给你支了一招“捆绑售卖”，你尝试之下，果然卖出了不少货物，便请对方吃了顿好的。",
[1192]="有位怪异的红发青年看上了你货物中一块外形有些奇特的石头，询问能否用一块白玉交换，那白玉光泽莹润，通体无暇，你一眼便知是块好玉！",
[1193]="你去一个村子里收货，在一个角落发现有个孩童正在把玩着一个烟斗。你一眼就看出这个烟斗价值不菲，用一串糖葫芦跟他换到了烟斗，后来这烟斗果真卖了个好价钱。",
[1194]="你出摊的时候嘴里叼着个包子路过一户养狗的人家，因为狗没有栓绳，狗嗅到包子的香气，朝你扑来，你避之不及，被狗狠狠咬了一口。",
[1195]="你正在家中收拾货物，突然听到门口有些响动。出去一看，竟是之前救下的那只狐狸在用爪子叩门。见你开门，狐狸吐出了一枚亮晶晶的珠子，便一溜烟地跑走了。你捡起那珠子，只觉得其灵动非常，放在身边颇有暖意，便决定将它贴身携带，心想果然好人有好报呀。",
[1196]="救下狐狸",
[1197]="救下狐狸，竟得报恩，狐狸给了你一颗灵珠。",
[1198]="最近频频有小孩失踪，官府也没有查出原因，街上的人很少，你的生意冷清，早早就收摊回家了。",
[1199]="你到村里收货，发现一个奇怪的小贩担着两个大箩筐。现在生意这么冷清，怎么还有人用这么大的箩筐收货，不怕赔钱么？你觉得奇怪，便悄悄跟随对方。",
[1200]="你发现这个小贩总喜欢向小孩打听家里有没有大人，于是你怀疑他是人贩子，赶紧报了官。最后果然你不出所料，这人就是最近小孩失踪的始作俑者。",
[1201]="由于你心细胆大地提供了准确情报，帮助官府顺利抓获人贩子，不仅得到了一笔丰厚的奖赏，许多人都更愿意来你的摊位买东西，你的生意登时红火起来。",
[1202]="你收摊时路过一家医馆，听见里面传来一个男人的惨叫声，久久不绝。你嗤之以鼻，这点痛都忍不住，简直不是个男人。",
[1203]="嗤之以鼻",
[1204]="路过医馆，听到一个男人惨叫，你嗤之以鼻。",
[1205]="今日街角的茶馆旁尚有空位，你便在此摆摊，正巧听到茶馆内的说书先生讲述古今奇闻异事。说书先生谈吐风趣，你听得入迷，险些忘了吆喝叫卖。",
[1206]="街口的糖画摊子围着许多孩童，摆摊的老者制作的糖画每一幅都栩栩如生。你看得眼馋，不禁回想起童年的自己，从来都没有多余的铜板能够买下一个属于自己的糖画。",
[1207]="东街成衣铺掌柜的女儿小翠手巧人美，可以根据客人的气质设计衣裳，无一不合身妥当。为了一睹小翠芳容，你攒下卖货的银钱，也去定制了一套新衣裳。",
[1208]="近来多雨，你找到门路，进来了一批质量上好的油纸伞，伞面还描绘着不同的鸟兽花草，甚是好看。这批伞在雨季果然很快售卖一空，入账的银钱让你不禁喜上眉梢。",
[1209]="春夏蚊虫渐多，你想了想，去医馆配了一些驱虫醒神的草药包，装进香囊里售卖，更是亲身佩戴以示效果。如此一来，果然销量不错。",
[1210]="你在媒人的介绍下成了亲，妻子贤惠温柔，操持家务，照顾娘亲，让你省了不少心。成家之后，你更有赚钱的动力了。",
[1211]="喜结良缘",
[1212]="红绳牵良缘，妻贤家和暖",
[1213]="你的妻子给你生了一儿一女，你出摊卖东西的时候，每每想到自家儿女那可爱的模样，便觉得更有劲儿了。",
[1214]="你收摊回到家中，看着家人的笑脸，还有热腾腾的饭菜，突然觉得一天的疲惫都减轻了不少。",
[1215]="又是一年花灯节，你却没有出去摆摊，而是与妻子携手在街上闲逛赏灯。灯火映照之下，你意外发现妻子鬓边掺杂着几根银丝，突然意识到，你们也不再年轻了。",
[1216]="你算了算这些年的积蓄，决定盘下一间小小的铺面。虽然还是卖些杂货，但胜在多年攒下的客源稳定，收入尚可，也总算是有了个遮风挡雨的地方，不用每日在街道上奔波了。",
[1217]="想到那石头不过是你之前在河边捡到的，能换好玉简直是赚大了！你便立刻答应了下来。",
[1218]="以玉换石",
[1219]="一位红发青年，用白玉换走了你捡到的奇怪石头。",
[1220]="整理货物时，你不慎扭伤了腰，只能慢吞吞地前去医馆正骨。你趴下时，只见气度儒雅的大夫对你微微一笑，绕到你的身后，双手用力一按……",
[1221]="“咔咔咔”的细微声响带着痛意直冲脑门，“啊啊啊啊啊啊啊——！”你的惨叫声久久不绝。",
[1222]="风水轮转",
[1223]="进了医馆正骨，你的惨叫久久回荡。",
[1224]="你刚把摊位的货物摆好，一回头便看到了一名绝美的女子，你觉得那话本里说的仙女或许就是这般模样吧。这女子微笑着从腰间取下一把宝剑递给你，询问是否能用这把剑换那块白玉。",
[1225]="你接过宝剑，只见剑鞘镶嵌着宝石；抽出一截，只见剑身寒光湛湛锋利无比，也不知是用什么材质打造的，足可吹毛断发，虽然有些不舍那白玉，但这宝剑定是价值连城。你想了想，答应了这笔交易。",
[1226]="以剑换玉",
[1227]="一名绝美女子，用宝剑换走了你的白玉。",
[1228]="你正在面摊吃午饭，一个乞丐凑上前来，神秘兮兮地掏出一本秘籍，说是剑仙李清圣所著，只卖有缘人。你要不要买一本？",
[1229]="乞丐卖书",
[1230]="买",
[1231]="不买",
[1232]="你买了下这本秘籍，刚一打开，发现除了第一页，后面都是白纸。你刚想跟那乞丐理论一番，却发现对方早就没了踪影。",
[1233]="这种骗人的把戏你见多了，才不会上当。",
[1234]="你收摊回家时，发现一群小孩正在用石头砸一只受伤的狐狸，你决定……？",
[1235]="受伤的狐狸",
[1236]="你掏出几个糖人朝这群孩童走去，说道：“谁不欺负狐狸，谁就能来我这领一个糖人。”这群孩童立刻放过狐狸，把你团团围住讨要糖人。狐狸瞅了你一眼，便一瘸一拐的离开了。",
[1237]="不过是只畜生罢了。你这样想着，慢悠悠地从一旁经过。",
[1238]="你收摊回家时途径一条巷子，几个蒙面人挡住了你的去路，让你交出身上的钱财，你决定……？",
[1239]="匪徒拦路",
[1240]="交",
[1241]="不交",
[1242]="财空命殒",
[1243]="收摊遇匪，你护财而死，财也没能守住。",
[1244]="破财消灾，钱没了可以再挣，命没了可真就什么都没有了。你老实地掏出所有钱财，保住了小命。",
[1245]="你好不容易赚了点钱，当然不肯乖乖交出。对方看你这么硬气，拔刀便砍，你最终命丧刀下，钱财也被洗劫一空……",
[1246]="华灯初上，你今日卖了不少东西，入账颇丰，便想着犒劳一下自己，不如到某处消遣一番。你决定……？",
[1247]="消遣一番",
[1248]="一试手气",
[1249]="勾栏听曲",
[1250]="你来到赌坊，想要碰碰运气，不想手气欠佳，不一会儿就把今天赚的钱都输光了。",
[1251]="你刚踏进瓦舍的大门，一众莺莺燕燕便围了过来，香风环绕，把你堵得面红耳赤，不由得脚底抹油飞速离开了。",
[1252]="一日，风大雨急，你打着伞匆匆地前去开店的路上，不小心和一人撞了个满怀。你二人互相扶着站稳了身子，你连连致歉，不料对方却盯着你颈上不小心甩出来的珠子，惊讶道：“唐突了……请问你颈上这珠子能卖予我吗？我愿出重金购买。”",
[1253]="你闻言抬眼，这才看清对方的容貌，竟是一名气度不凡的道士，你不由问道：“敢问道长可知这珠子的来历……？这是在下心爱之物，不会轻易卖出的。”“也罢，相逢即是有缘，欺瞒不是正道，我便告知你吧……”对方叹了口气，转道邀你去茶楼一谈。",
[1254]="一番交流下，你才得知，这珠子竟是成色罕见的灵珠，可谓是修仙之人所需之宝物。这道士便是一名修仙者，他仍是想买下你这枚灵珠，但你若实在不愿便不勉强。对方更探出你身具杂灵根，亦可随他踏上那修仙之路，只是资质不佳，也许不能走远罢了。你决定……？",
[1255]="修仙之路",
[1256]="跟他离开",
[1257]="卖他灵珠",
[1258]="雨中偶遇，一枚灵珠让你得以追随修士，踏上仙途。",
[1259]="凡人也能踏上仙途？你被这消息砸得恍惚了许久，最终决定将铺面交托给家人，跟这道士离开。哪怕资质不佳，你也不想放过这个机会！事在人为……你这么想着，开始期待之后的修仙之路……",
[1260]="你挣扎许久，最终还是决定将这灵珠卖给对方。怀璧其罪的道理你懂……这一世，你只想与家人平安团圆。道士果然以重金与你交换了这枚灵珠，自此，你更努力地发展生意，愈发悉心地请来先生教导儿女，传承家业，一生很快就过去了。",
[1261]="你算完今日的账，正准备打烊关店。却见到一名风尘仆仆的侠客模样的年轻人走进门来，望着你店铺最显眼的墙上挂着的那把宝剑，礼貌询问道：“在下急需一把上好的剑，不知能否以此物做个交易，传闻凭此物许愿，当可心想事成。”",
[1262]="以物换物",
[1263]="和他交换",
[1264]="金币换宝剑",
[1265]="略有所憾",
[1266]="宝剑配侠客，你却拥有了足以当传家宝的金币。",
[1267]="你拒绝了金币换宝剑的交易，但金币之大，也令你有些遗憾。",
[1268]="那金币足有巴掌大，你倒是没太在意什么心想事成的传说，反而暗暗估算了一下那分量，都能留着当传家宝了！于是笑着答应下来，宝剑换金币，双方都十分满意。",
[1269]="虽然那金币十分诱人，但你还是更喜欢宝剑，拒绝了对方。对方也未强求，低低叹了口气，便转身离开了。你看着对方的背影，想了想也许能当传家宝的金币，也有些肉疼地叹了口气。",
[1270]="你到城中办事，恰逢城主大摆武擂。看得技痒的你也上去比试了一番，竟连挑五人，引起了小小的轰动。",
[1271]="你奉命办事时赶路太急，在酷暑的烈日下没有及时补水休息，不幸中暑昏迷。",
[1272]="战事稍缓，你抽空回了趟家。娘亲凭借你的军饷，日子过得尚可。",
[1273]="冬夜，你轮值巡逻时，意外发现有几只饿狼试图靠近营地。你跟着队长将狼逐只杀死，消除了隐患。",
[1274]="伤病缠身，趁此机会退伍还乡",
[1275]="一次行军",
[1276]="九死一生捡回一命的你找了个山洞中养伤，好奇地翻看起悬崖下捡到的那本书册。你隐约能感受到书中所记应是某种强身健体的方法，决定……？",
[1277]="开始修习 [机缘判定]",
[1278]="<color=#549327>[判定成功]</color> 你学着锻炼了数年，开始隐约感受到一股气流在体内游荡，颇有成效。你十分欣喜，想了想书中提到的仙山奇谷、瀚海灵泉；还有那些腾云驾雾、一剑分海，一刀断水的修仙者……你决定离开凡俗之地，寻求仙途。",
[1279]="<color=#c82c2c>[判定失败]</color> 你学着锻炼了数年，开始隐约感受到一股气流在体内游荡。某日气流四处乱窜，引得你经脉尽断七窍流血，眼前一黑便再也没有醒来……",
[1280]="闲暇时，你还特地到附近的村子找村老讨教了如何种菜。一番施弄下来，自家小院的蔬菜瓜果长势尚可，也能勉强自给自足。",
[1281]="你和镖师一起接了单生意，运货途中遇到了山匪，凭借从军的经验，你配合镖师将这伙山匪杀了个干净，不但顺利把货送到，还拿了官府的奖励。",
[1282]="天气好的时候，你也会在城里四处逛逛，听听说书，喝喝茶看看戏，一日就过去了。",
[1283]="近日有贼在附近几个城镇流窜，不少人家丢了财物。你自告奋勇地加入村里组织的巡逻队，每日认真巡逻，仔细检查每个可能的藏身之处，最后果然捉住了那贼人。",
[1284]="有些时候，你会带着街道上那些半大的少年到山林外围练习捕猎，教他们辨认方向，分辨不同兽类的足迹……看着少年们精力旺盛的模样，你竟有几分欣慰。",
[1285]="夜间，街道走水，火势蔓延极快。在众人忙于救火之时，你发现了一个鬼祟的身影，认出其正是附近有名的无赖，想必就是此人纵火，你决定……？",
[1286]="神秘的纵火犯",
[1287]="你料想对方还有同谋，便暗中跟随，果然看到他与另一无赖汇合。你上前三两下制服了这两人，将人押去交给衙役。后来，官府给了你一些奖励的银钱，街坊们也十分感激你抓到了罪魁祸首。",
[1288]="你气得直接上前将人揍了一顿，然后押去交给衙役。大家都十分愤怒这无赖的行为，对你大加赞赏。",
[1289]="春天到了，你去城郊外挖些时令野菜尝鲜，意外挖到一块硕大的块茎，长得与红薯有些相似。凭借经验，你大致确定其并无毒性。此时已至正午，你正是腹饥，是否要带回家尝个鲜，将之烹煮食用？",
[1290]="一日，你兴致颇好，决定亲自上山砍柴，不料山中大雾忽起……不知走了多久，前方似有人声，你循声而去，雾也渐薄，最终竟来到一处石洞之内。",
[1291]="只见石洞中正有两名老者捻须对弈，你不过看了一眼棋盘，竟不知不觉痴了……直至耳畔忽闻一声：“你观棋许久，还不离去？”",
[1292]="你这才回过神来，棋盘上胜负已分，一抬头便发现两名老者都看着你。你决定……？",
[1293]="观棋对弈",
[1294]="冒然观棋太过失礼，你万分羞惭，竟是头也不回地匆匆离开。然而出了石洞，你却顿觉无力，一下子瘫坐在地。你怔怔地看着自己皱纹满布的双手和毫无光泽的白发，竟是再也支撑不住地倒了下去……",
[1295]="你自觉失礼，恭敬地对两位老者长揖到底，恭敬道：“在下未经许可便冒然观棋，打扰了两位的雅兴，实在抱歉。”",
[1296]="其中一老者闻言笑道：“身具灵根，从容有度，倒是个苗子。既然相遇，便是有缘，你可愿随我修行？”",
[1297]="听得此言，你登时欣喜若狂，连忙再度拜谢。对方见状，拿出一枚长得像枣子的果实叫你吃下。",
[1298]="你依言照做，顿觉神清气爽，隐有脱胎换骨之感。两名老者也不多言，直接拂袖将你一卷，便御风离去了……",
[1299]="年纪渐长之后，闲来无事你便爱喝两口茶。今日正欲出门买些茶叶，不料刚起身便觉一阵天旋地转。你意识到或许是大限将至，此时一抹虚幻的玄妙身影出现在你的面前，说与你有缘，可赠你一枚寿元丹续命。你决定……？",
[1300]="今日休沐，你正准备去城里修整一番，改善一下伙食，不料站起身就觉得眼前阵阵发黑。你意识到或许是大限将至，此时一抹虚幻的玄妙身影出现在你的面前，说与你有缘，可赠你一枚寿元丹续命。你决定……？",
[1301]="你正欲出门买些东西，刚走出门口便觉一阵天旋地转。你意识到或许是大限将至，此时一抹虚幻的玄妙身影出现在你的面前，说与你有缘，可赠你一枚寿元丹续命。你决定……？",
[1302]="忙碌一生，为生计奔波，赚点小钱，倒也心安。年事已高，你在一个夜晚悄然而逝。",
[1303]="须发皆白的你躺在床上，看着后辈，再次叮嘱道：做人需有良心，勤恳努力，买卖莫要欺客……你的絮叨越来越弱，直到再不可闻……",
[1304]="人生一世，家人团圆，家业兴旺，你亦无憾。",
[1305]="你生于一个富商之家，父母富甲天下，故给你取名为{0}",
[1306]="你赚到了此生第一桶金：将一把梳子卖给了一名和尚，商业天赋初现端倪",
[1307]="你通过一番巧舌如簧的说辞，把一名路人忽悠瘸了之后，再把一根拐杖卖给了他，临走时他还得谢谢你",
[1308]="你一时不慎在商市投资失败，把自己十六年来积累的财富赔了干净，又得从头再来了",
[1309]="你的父母意外身亡，你无奈只能回去继承百万家业，这便是有钱人家的烦恼",
[1310]="你听说这个世上有一个商会名叫万宝商会，其并非人族所建，而是由一群猫族建立的商会，要不要去看看？",
[1311]="万宝商会",
[1312]="前去拜访",
[1313]="你很好奇一群猫是如何建立商会的，于是前去拜访。途中遇到不少阻碍，但都被你花钱解决了",
[1314]="与其关心这种东西还不如专心赚钱，你决定不去找什么万宝商会，凡间的钱足够你赚了",
[1315]="你找到了此间传闻中的万宝商会，在缴纳了一笔可观的小费后，万宝商会的猫五爷接待了你",
[1316]="你与猫五爷相谈甚欢，最终成功达成合作，获得了从万宝商会进货的权利",
[1317]="听说商市中的天云良田最近可能价格高涨，你赶紧跟风买入了一批，希望能有好的回报",
[1318]="你从父母留下了财富中找到了一批灵石，据说这是修仙界的货币，其价值不可与凡间商品同日而语",
[1319]="据闻某地即将引来饥荒，你感觉开始屯粮，希望可以屯货居奇，以后高价卖出",
[1320]="从商多年，你发现钱没了可以再赚，良心没了，钱就赚得更多了",
[1321]="天云良田近日股价高涨，让你喜笑颜开，赶紧抓紧买入更多",
[1322]="你接下了万宝商会的货物，开始踏上前往南疆的旅程，太岳山脉与南疆相隔万里，恐怕此行需要耗费不少时间",
[1323]="饥荒如约而至，你把手中囤积的粮食大量卖出，获得了一笔丰厚收入",
[1324]="旅行途中，你遇到了一群饥肠辘辘的难民，向你讨粮食吃，你毫不犹豫地将他们赶走",
[1325]="你的货物正式进入南疆，你发现这里的人同样信奉孔孟，让你感到十分亲切",
[1326]="你的队伍受到南疆人的热情招待，只不过在吃完这里的食物后，你们的人均上吐下泻，只能原地休息",
[1327]="你顺利完成了万宝商会安排的差事，并从南疆全身而退，此行让你在太岳名声大振",
[1328]="你在经商途中遭到一群妖兽袭击，幸好一群{0}弟子及时出现，将你从妖兽口中救了下来",
[1329]="从此你和{0}搭上了关系，经常与其来往，从他们哪里交易获取了不少寿元丹",
[1330]="你在商市中大量持有的天云良田忽然价格暴跌，你一时间血本无归，让你感到十分沮丧",
[1331]="本着不能只有我吃亏的原则，你决定把{0}也拉入商市，让他们也体会一把过山车的感觉",
[1332]="{0}宗邀请你到他们的仙栈作客，你欣然到访，在仙栈中度过了美好的一夜",
[1333]="你担心自己的寿元降尽，开始大量囤积寿元丹，希望能在关键时救你一命",
[1334]="你听说这个世上有些人是先天牛马圣体，做的比别人多，吃的比别人少，让你十分感兴趣",
[1335]="万宝商会委托你办一件事，希望你能运送一批货物到南疆，是否接受这份差事呢？",
[1336]="商会委托",
[1337]="你欣然接下了这份差事，不就是运送一点货物吗？能有什么问题",
[1338]="你不知道这趟旅程会有何风险，还是不要贸然接受为好",
[1339]="南疆人听说你们也知道孔哥和孟哥，决定出题考考你们：“逝者如斯夫”是何意思？",
[1340]="南疆考验",
[1341]="时间如流水般流逝",
[1342]="尸体顺着水流下来",
[1343]="南疆对你的回答感到十分行为，直呼你是信孔哥和孟哥的好男儿",
[1344]="你成功将XX宗拉入商市，他们向你寻求意见，在商市中该如何投资是好？",
[1345]="投资建议",
[1346]="鸡蛋不放在一个篮子里",
[1347]="全押天云良田就对了",
[1348]="你感觉自己的寿元将尽，交易来的寿元丹是时候派上用场了，要如何服用寿元丹呢？",
[1349]="服用寿元丹",
[1350]="一口吃完",
[1351]="少量服用",
[1352]="寿元增加几十年",
[1353]="听到你的回答后，南疆人感到出离的愤怒，认为你亵渎了孔哥和孟哥，对你们发起了正义的群殴",
[1354]="XX宗听从了你的意见，高价重仓天云良田，结果赔的底裤都没了。你惨遭XX宗追杀，亡命天涯也终究还是躲不过",
[1355]="你一口吃下了所有寿元丹，结果没注意丹药还有饱食度，被大量寿元丹活活噎死",
[1356]="你出生在一个钟鸣鼎食的商贾世家，大名{0}。你在家中排行老二，平时下人们都称呼你为二少爷。",
[1357]="富商之子",
[1358]="你出生在商贾之家，家族财力雄厚。",
[1359]="按照风俗，家族为你举办了隆重的抓周仪式，数样精致的物件被一一摆放在你的面前，父母满怀期盼地看着你摇摇晃晃地向那堆物件爬去。你朝着其中一件东西伸出了手……",
[1360]="抓周仪式",
[1361]="一本书",
[1362]="一块玉佩",
[1363]="你抓起一本书开始乱翻乱扯，你的父亲却不在意，反而觉得你一定会成为好学之人。",
[1364]="你抓起了一块镶金的玉佩，“啊呜”一口，上面沾满了你的口水。玉佩硬得令你皱眉，没摆弄两下你就把它扔到一边去了。你的母亲却笑了起来，衔玉可是吉兆，只觉得自家孩儿不愧是富贵之子。",
[1365]="由于你出生那晚月晕厚重彩光四溢，乃天降祥瑞之兆，因此便从小被父母寄予厚望，希望你长大后能够出人头地光宗耀祖。",
[1366]="你从小要风得风要雨得雨，心情不好便砸东西，但长辈却觉得你这是不拘小节，甚至会专门买些瓷器给你砸着玩。",
[1367]="你的父亲花重金请了附近最好的老先生来教你念书。不料第一天就被你用石头砸伤了头，给气走了。",
[1368]="你带着护卫出门玩耍，排场很大，让你非常得意。途径一条较为僻静的街道时，你看到一群锦衣少年正在围殴一个小乞丐。你决定……？",
[1369]="路遇欺凌",
[1370]="加入其中",
[1371]="驱赶众人",
[1372]="欺负乞丐这种事情你还没做过，觉得有些新奇，便加入了他们。看着小乞丐在地上痛哭打滚求饶的模样，你莫名觉得有些厌烦，很快就带着护卫离开了。",
[1373]="你看了一眼，这群人的身份应该比不上你，便立刻让护卫把他们都赶走了。俗话说好狗不挡道，你嚣张惯了，不许旁人挡你的道。",
[1374]="日子太舒坦又让你觉得有些无聊。不愿念书的你便吵着要学些武艺。虽然也学得不甚走心，但有名师指点，总归是比普通人强了许多。",
[1375]="由于家中长辈的过分溺爱，导致你成长了一名纨绔子弟，从小便骄横霸道胆大包天，长大后更是不学无术，整日游手好闲胡作非为。",
[1376]="心血来潮的你嚷嚷着要学作画，你的母亲便以重金聘来一位才名远扬的画师入府教你。这回你倒算是耐得住性子，认真学了好些时日，也算画得有模有样。到你自觉满意之时，便多给了一笔钱财打发走了那画师。兴致勃勃地把自己关进书房的你决定画一幅……？ ",
[1377]="才名远扬的画师",
[1378]="美人图",
[1379]="花鸟图",
[1380]="你想了想前些日子在倚春楼见到的绝色美人，抬起袖子擦了擦口水，干脆挥笔画了张美人图，准备改日带去倚春楼博美人一笑。",
[1381]="你看着窗外在桃花树上跳来跳去的喜鹊，干脆画了幅花鸟图，正好当作父亲的寿礼了。你的父亲在寿宴那日拿到这幅画，果然十分开心，一挥手又给了你大笔银钱花用，也算是父子皆欢。",
[1382]="你无法无天惯了，但因家境十分殷实，所以惹出来的事端大都能花钱平息。虽说平日里的确过得十分潇洒惬意，却是与正道之路渐行渐远了。",
[1383]="身为家主的父亲不甘让你堕落下去，决心要让你回归正途，便将你叫至书房谈话并询问你对日后的打算。可你自小娇生惯养，整日花天酒地，哪有想过自己的未来。见你迟迟回答不上，父亲便点明了两条道路供你选择。你决定……？",
[1384]="未来的路",
[1385]="选择从政",
[1386]="哪也不去",
[1387]="你靠着父亲的打点，混了个县令当着玩。",
[1388]="游手好闲的你，决定继续当个纨绔少爷。",
[1389]="父亲依靠混迹生意场多年的人脉关系，并斥巨资贿赂官员，为你在朝中谋得了一个七品芝麻官县令的职位。县令官职虽小，但好歹也是高人一等的朝廷官员，你欣然同意并择日走马上任。",
[1390]="你拒绝了父亲的提议，表示自己哪里都不想去只想宅在家中，并搬出疼爱自己的长辈当做靠山，父亲长叹一声无奈之下只得就此作罢。没有了父亲的管制，你愈发肆无忌惮，成为了远近闻名的恶少。",
[1391]="你上任的那天城中百姓纷纷夹道欢迎，清水泼街、黄土垫道，前呼后拥好不威风。",
[1392]="乡里豪绅们摆下了酒席给你接风，你喝的酩酊大醉，还收受了不少银钱好处。",
[1393]="工部给地方上用于疏通河道的财政拨款，被你私自克扣了一部分，落入了自己腰包。",
[1394]="你私自发布公文，新增了各种名头的税赋，百姓被你榨干油水，生活苦不堪言。",
[1395]="你收受了乡绅的贿赂，在官司纠纷中极尽偏袒之事，围观群众纷纷骂你狗官。",
[1396]="你在家中大摆宴席，招待来自京中的巡查御史大人，其奢华程度令人咂舌。",
[1397]="你准备不少奇珍异宝和大笔银钱，一并送给了巡查御史大人，请求他在朝中为自己多多美言几句。",
[1398]="立春之日，你需要出面主持县里的迎春仪式，但你并未学习过这类仪式的礼仪流程，于是连连出错，惹得一众村老纷纷皱眉摇头，却是敢怒不敢言。",
[1399]="正所谓上梁不正下梁歪，你手下的主簿和衙役都是花钱买的，你们倒是臭味相投，一致对民搜刮油水。",
[1400]="秋季干燥，县里走水，火势蔓延极快，闹得人心惶惶。你得知灾情，并没有立刻组织人手救火，反倒先加派人手保证了自家府苑的安全，导致伤亡惨重。",
[1401]="一些乡绅为了巴结你，时常给你送来美貌的婢女，你通通照单全收。府中莺声燕语连连，令你十分满意。",
[1402]="途径一寺庙，你眼见一名壮硕和尚用左手向下抱住树干，右手抓紧树的上半截，腰往上一挺，竟将大树连根拔起，附近一众泼皮吓得跌坐在地。你竟也被吓得一身冷汗，生怕惹恼了这和尚，不由得赶紧离开。",
[1403]="隆冬大雪连下了数日，四处都是厚厚的积雪。寒冷的天气实在令人犯懒，你索性闭门不出，把政事一股脑地丢给手下处理，搞得百姓怨声载道。",
[1404]="你回府的途中，遇到一名衣衫褴褛的老乞丐卑微地朝你鞠躬乞讨，你却嫌对方气味难闻又碍眼，竟一脚把人踹翻在地，扬长而去。",
[1405]="邻县县令为官清廉，深受百姓爱戴……你听闻此事，却十分不屑一顾，反而认为对方不懂享乐，实在迂腐！",
[1406]="你带着手下官兵和众多家仆出城狩猎，骑着骏马擎着苍鹰，十足的意气风发。追兔猎狐，拉弓射稚，虽然没能见到虎熊之类的猛兽，但你们也算尽兴。",
[1407]="你时常设宴邀请同僚共聚，以此拉拢和你臭味相投的贪官污吏，彼此通融，沆瀣一气。",
[1408]="你进京述职，走了水路。夜里到甲板上透气赏月，你隐约见到河中有一游动的暗影，不禁凑到船舷边想要看个仔细……",
[1409]="只见河中若隐若现的鳞片反射着冷光，一闪而过的瞳仁猩红，好似一条巨蛇。你只觉得头皮发麻，不敢再看，跌跌撞撞地跑回船舱中，就寝后竟噩梦缠身，一宿都未睡好。",
[1410]="你给家族的产业大开方便之门，暗中做了不少动作打压县中的其他商贾，以此向族里邀功，又得了大笔的银钱珠宝以供花销。",
[1411]="听闻县中的才子举办诗会，你心血来潮，换了便服跑去凑热闹。看着众人斗诗斗文，你来了兴致，竟也赋诗一首……却是一首打油诗，惹得众人哄笑不止。",
[1412]="你维持着一贯作派，奢靡成性，府中每日采购昂贵的山珍海味，吃不完的直接倒掉，第二日再买新的……正是应了那句朱门酒肉臭。",
[1413]="你外出游玩时不慎跌落马下，摔断了腿。回府后命人去请县里最好的大夫前来诊治，却不料这大夫的女儿曾被你调戏轻薄过，他不动声色地给你开了让伤口更痛疗效却更差的药，导致你的伤拖了将近半年才痊愈。",
[1414]="你收到风声，手握实权的守边将军要回朝述职，将要途径此地。你意识到这是一个好机会，如果能和有实权的将领打好关系，你的日子会过得更舒坦。你决定……？",
[1415]="守边的将军",
[1416]="送其美人 [概率判定]",
[1417]="送银钱珍宝",
[1418]="拍到马腿",
[1419]="马屁拍到马腿上，你巴结不成，反被将军一剑杀死。",
[1420]="<color=#549327>[判定成功]</color> 你忙不迭地搜罗了极其貌美的佳人送给将军，不料对方与发妻情深，最恨别人献美。对方因此厌恶你，时常给你下些绊子，让你的日子很不好过。",
[1421]="<color=#c82c2c>[判定失败]</color> 你忙不迭地搜罗了极其貌美的佳人送给将军，不料对方与发妻情深，最恨别人献美。对方大怒之下，竟一剑捅穿了你的胸膛……这就是实权在握么，你临死前只有这一个念头，便永远陷入了黑暗。",
[1422]="钱财动人心，将军似乎颇为满意，也愿意给你行些方便。你的日子愈发逍遥了。",
[1423]="有同乡的富贾找到你，许以重金，想要你行个方便，给他那不成器的庶子谋个差事。你决定……？",
[1424]="不成器的庶子",
[1425]="答应下来",
[1426]="得寸进尺",
[1427]="钱财动人心，你想办法把他的儿子塞到了自己手下，做个普通的衙役。",
[1428]="你坐地起价，咬死不松口，逼那富贾多掏了一倍的银钱，才给他儿子谋了个衙役的差事。",
[1429]="秋高气爽，你扔下一堆政务，带着家仆外出狩猎。不料狩猎途中，忽然大雾弥漫，马匹纷纷受惊乱跑，待你好不容易控制住马匹，已经看不到家仆的身影……这时，前方隐约传来人声，你决定……？",
[1430]="隐约传来人声",
[1431]="循声前往",
[1432]="待在原地",
[1433]="无缘仙途",
[1434]="遇仙斗法，你心术不正却妄想修仙，终被仙人所杀。",
[1435]="你循声一路前行，大雾渐渐散去，眼前竟然是两名白衣仙人正在斗法！你心中狂喜不已，这可是天大的机缘！你干脆利落地跪下就拜，声称相逢即是有缘，恳请仙人带你修仙问道。不料耳边响起一声冷哼：“纵欲过度，心术不正之辈，竟妄想修仙，该杀！”话音落下时，你只感到颈间一凉，便什么都不知道了……",
[1436]="事出反常必有妖，你不欲乱走，决定在原地等待。不知过了多久，大雾终于散去，只见天色已暗，你在不远处发现了家仆的身影，连忙策马过去与他们会合，心有余悸地一同打道回府。",
[1437]="你大肆敛财，强征税赋，治下民不聊生怨声载道，起初仅是百姓聚众抗议，你依旧派衙役强行镇压，随后便一发不可收拾，竟愈演愈烈，发展成民变。你这才慌了起来，决定……？",
[1438]="强征税赋",
[1439]="偷偷逃走 [概率判定]",
[1440]="上京求援",
[1441]="自食其果",
[1442]="横征敛财，罔顾民生，终至自食其果，死在百姓手中。",
[1443]="<color=#549327>[判定成功]</color> 小命要紧，你连夜收拾细软，换上家仆的衣服，准备逃回家中暂避风头。一路上你极其小心，任何风吹草动都能吓得你无法安然入睡。你身心俱疲地逃回了家中，在族人的帮助下躲到一处偏僻的别院生活。然而你的精神状况愈发差了，终日杯弓蛇影，惊惶不安……",
[1444]="<color=#c82c2c>[判定失败]</color> 小命要紧，你连夜收拾细软，准备逃回家中暂避风头。不料未出城门就被人识破，愤怒的百姓围了上来对你拳打脚踢，竟生生将你围殴致死。",
[1445]="你让衙役强行为你抢出一条道路，上京求援。不料朝中早已掌握你贪赃枉法的累累罪证，等待你不是救援，而是午后问斩的判决。",
[1446]="自幼养尊处优，在优渥的条件下你长成了一副高大威猛、孔武有力的好体格。平日也经常里舞刀弄棒、骑马射箭，身手倒是练得不错。",
[1447]="你带着一众狗腿在城中溜达散步，在一处街角突然被迎面而来之人撞的七荤八素，你正要破口大骂对方不长眼，并准备让手下对其好好教训一番。",
[1448]="赫然发现对方居然也带着一群手下，其嚣张跋扈的阵仗丝毫不输自己，一问才知对方是新搬至城中的官宦子弟赵公子，你们不打不相识，臭味相投顿时结为好友。",
[1449]="为了庆祝二人相识，赵公子主动邀请你去倚春楼喝花酒，你也正有此意。你们在席间左拥右抱相谈甚欢，好不快活。",
[1450]="经过小巷时你遇见一帮地痞无赖，领头之人打量了你几眼，眼神不屑颇为无礼。你心怀不忿一言不合便动起手来，直至附近巡逻的官兵闻讯赶来，才收手作罢。",
[1451]="你经过一处闹市时脚底打滑不慎跌倒，起身查看后才发现罪魁祸首乃是一块香蕉果皮，于是你迁怒于路旁的水果摊，不由分说便将果摊掀了个底朝天并将摊主痛殴了一顿。",
[1452]="你听闻最近倚春楼新来了位绝色花魁，便约上了赵公子一同前去见识下传说中的天姿国色。那花魁果真名不虚传，你与赵公子都十分喜爱，不惜为其豪掷千金。",
[1453]="你见摊贩旁有名妇人生的明眸皓齿、美艳动人，便带着一众狗腿围住妇人欲行调戏之事，妇人一边哭啼一边缩着身子向后退，附近围观的群众皆面露不忿，但却敢怒不敢言。",
[1454]="今日阳光明媚天气大好，你寻了艘画舫赏景作乐，悦耳的丝竹之声配上杯中美酒，令你无比陶醉。",
[1455]="突然，平静的河面突然波涛汹涌，远处的水面也翻起巨大的浪花，只见一条通体纯白的蛟龙破开水面直冲天际，很快便消失在众人视野中。",
[1456]="你路过绸缎铺时突然从楼上落下一只花盆在你面前摔的粉碎，你立马找到店铺老板狮子大开口说自己受了惊吓心神不宁，需要买些名贵的药物来安神调理。老板明知你是讹诈却又无可奈何，只得花钱消灾。",
[1457]="你带着众多家仆出城狩猎，身着华贵的狐裘骑着高头骏马，左手牵着猎犬右臂擎着苍鹰，你挽弓搭箭的模样快意潇洒。可跑了快一个上午才猎到几只野兔，一行人难免兴致恹恹。",
[1458]="你见到一户人家正娶亲摆喜宴，便不请自来上门道贺，主人家只能硬着头皮招待你。",
[1459]="你坐在席间百无聊赖，见到新人拜堂时新娘那曼妙的身段，便突发奇想要看一看新娘子长啥样。",
[1460]="主人家十分愤怒但依旧不敢得罪你，只得小心翼翼的赔笑解释称这样的举动不合规矩难以办到，恳求你不要为难他们。",
[1461]="你听言顿时勃然大怒：“难办？那就别办了！”说完便将面前的酒席掀翻在地，随后扬长而去。",
[1462]="随着年龄慢慢增长，你被酒色掏空的身体状况也愈发日下，一次染上风寒之后你高烧不退昏迷在床，请大夫开了方子煎药服下后仍是没有任何好转，夜里竟说起胡话来。",
[1463]="大夫再次为你仔细把过脉后，无奈的摇头：“病入膏肓药石无医，老朽亦无任何办法，还是尽早准备后事吧。”",
[1464]="家里的山珍海味吃腻了，你听闻城里的酒楼上了些时令菜肴，便决定前去尝鲜。席上一道菜的价格便够平民百姓半年花销，玉匙银筷皆从家中带来，更有美貌婢女伺候你用饭，极尽奢靡享受。",
[1465]="你在茶楼里品茗听书，说书人在台上口若悬河，从民间逸事到仙家传说，跌宕起伏地讲了一整个下午，令人意犹未尽。待到傍晚，说书人正要离场，你却仍未听够，以重金强请对方又讲了两个时辰。",
[1466]="听说自家产业之一的琳琅斋新进了一批古玩，你便挑了个天气不错的日子过去看看。这批货物品质极佳，尤其是一只描金花瓶，颜色样式都十分令你满意。",
[1467]="你正欲把这花瓶回家，不料店里进来了个衣着光鲜的少爷，风风火火地就要买下这只花瓶。竟有不长眼的敢和你抢东西？你立刻让家仆上去揍人。对方叫嚷着自己是城南粮商家的小少爷，你一声冷笑后干脆亲自动手，揍得更狠了。",
[1468]="直把人揍得鼻青脸肿连连讨饶，你犹不解气，干脆将这描金花瓶砸了个稀碎，甩下一句：“这是二爷家的店，二爷我看中的东西还没人敢抢，就凭你？砸了也轮不到你。”这下你才彻底舒坦，在对方的惊愕之中扬长而去。",
[1469]="早上起床你就觉得眼皮狂跳，俗话说哪边跳财来着……你摇了摇头，并没有在意这点小细节，只觉得财运到了，用过早饭便前呼后拥着去了赌坊。不料手气极差，连赌连输，竟连身上的玉佩都赔了进去，气得你破口大骂，回家时脸都是黑的。",
[1470]="父母想要为你说一门亲事，联姻也有助于家族发展。但你恶名在外，没有哪家权贵之女看得上你。父母好言劝你收敛一些，你却不屑一顾，只道那些小姐瞎了眼才看不上你，你也看不上她们，还不如倚春楼的娇娘们可人。听到你这般言论，你的母亲差点气晕过去，父亲更是气得脸色铁青，直接把手里的名扇给拗折了。",
[1471]="今岁洪灾，不少富商的子女都在城内赈济，以聚民心。你得知此事，也要去凑个热闹。别人赠粮施粥，你就派馒头包子，却不是让人排队领取，而是直接往人群里扔。",
[1472]="看着饥民乞丐乱作一团争抢食物，哪怕是跌在地上粘了泥沙的食物也无人肯让，你竟觉得十分新鲜，大笑不止。此等荒唐行径，不禁令人侧目。",
[1473]="你看城里新来的戏班子有几名貌美的舞女，便一掷千金让这班子到府上给你连着唱了一个月的戏。每天夜里你的院落都灯火通明，莺声燕语热闹不息，真是快活更赛神仙。",
[1474]="你的母亲命你陪她前去城外的灵德寺祈福，你勉为其难地陪她前去，却不愿进殿诵经敬香，干脆跑到鱼池前喂鱼，差点没把寺里的一池锦鲤喂得撑死。",
[1475]="今日你运气不错在赌坊里大杀四方获利良多，但是有人怀疑你出老千作弊，你与对方争执不下且情况愈发激烈起来，这时你决定？",
[1476]="老千作弊",
[1477]="息事宁人",
[1478]="大打出手",
[1479]="你碍于赌坊的势力，带着众手下骂骂咧咧的先行离开了。",
[1480]="你带着手下和对方打斗了起来，一片混乱中对方拔出藏于腰间的短刃径直朝你冲来",
[1481]="打斗",
[1482]="暂避锋芒",
[1483]="正面硬刚",
[1484]="犹豫不决",
[1485]="你见对方乃亡命之徒，不由得心生胆怯，转身拔腿就跑。",
[1486]="你丝毫不怵对方手中的凶器，一脚将对方手中短刃踢飞，又一脚将对方踹翻在地。怎奈对方摔倒之时脑袋不偏不倚磕在桌角，倒在地上昏死过去，探其口鼻却只有出的气没有进的气了。",
[1487]="你见对方来势汹汹，不自觉的就怂了，刚想转身逃跑时却突然又想起不能在众人面前落了面子。内心天人交战之际对方早已冲至身前，手起刀落将短刃插入了你的胸口。",
[1488]="你眼见闹出了人命，惊慌失措之下急忙逃回了家中，稍稍平复了下紧张的心情后，你决定……？",
[1489]="命案",
[1490]="投案自首",
[1491]="暂避风头",
[1492]="流放罪人",
[1493]="畏罪潜逃",
[1494]="你意外杀人，因此被判流放，戴罪服役。",
[1495]="你意外杀人，在母亲的帮助下畏罪潜逃。",
[1496]="你前往书房找到父亲对其讲述了此事的经过，父亲深思一番后劝你前去官府投案自首，得以从轻发落。你与他人斗殴致人死亡，但却属过失杀人罪不至死，官府最终判你流放千里发配边关。",
[1497]="你向母亲讲述了此事的经过，母亲不忍你遭受牢狱之灾流放之苦，连忙帮你收拾细软行李让你连夜逃亡至别处暂避风头。",
[1498]="平时聚在你身边的几个狗腿子在外喝酒时和另一伙人互不对付，打了起来，结果被对方打得逃回你身边哭诉，希望你能出面给他们出气。你决定……？",
[1499]="替人撑腰",
[1500]="与你何干",
[1501]="替其出气",
[1502]="不过是群跟在你身边的草包，被揍了与你何干？只能怪他们自己不争气。你毫不留情地嘲讽了他们一顿，只觉得这群废物在外头打架竟然打输了，真是丢了你的脸面。",
[1503]="俗话说打狗也要看主人，打你手下的人，岂不是落了你的脸面？你果断叫了一批人，在这几个狗腿的带领下，前去找回了场子。",
[1504]="你正在城中闲逛，突然被一名道士拦住，非要给你算上一卦。只见对方掐指而言，说你本是气运加身的富贵命格，却未能好好珍惜，以致行差踏错，如今已然福薄如危卵。你听完，决定……？",
[1505]="算上一卦",
[1506]="揍他一顿",
[1507]="打发他走",
[1508]="你心想什么破道士，说些神神叨叨不中听的，不就是想骗钱么？你不耐烦地揍了他一顿，解气之后便大摇大摆地离开了，并未听到道士平静爬起来后无奈的叹息声。",
[1509]="你听完不屑道，自己是天生的富贵命，有家族兜底，只会大富大贵一辈子。你拿出碎银子想打发这骗钱的道士走，不料对方却不接，反而给了你一道符，说了句“亡羊补牢时犹未晚”就自行离开了。你捏这这符看了一圈，没觉得有啥特别，干脆随手一扔，便带着一众狗腿喝花酒去了。",
[1510]="赵公子生辰将至，身为你的狐朋狗友，自是忘不了邀你共聚一番。你决定……？",
[1511]="共聚一番",
[1512]="过府赴宴",
[1513]="外出设宴",
[1514]="你兴致勃勃地前往赵府赴宴，赵公子的排场果然令人满意，你们听曲看戏，把美酒当水一样连喝了三天三夜，最后烂醉如泥的你是被家仆抬回家的。",
[1515]="好兄弟生辰，自然要给足面子。你决定在倚春楼设宴，请赵公子玩个痛快！你们二人在倚春楼流连了三日三夜，有美人作陪，喝了不知多少杯酒水。最后双双醉得不省人事，是家仆将你们抬回家的。",
[1516]="你被发配到了一个边陲小镇，因体格强壮被安排到矿井干苦力，每天都要下到几十米深的矿坑里挖煤炭。",
[1517]="虽然进行着高强度的劳作，但是分发到手中的食物却少的可怜，吃不饱饭每天都要饿肚子进行工作。",
[1518]="塞外边疆的气候十分寒冷，你连一件像样的御寒衣物都没有，只得裹紧单薄的衣物被冻的瑟瑟发抖。",
[1519]="你挖完了一筐煤炭后刚想偷懒休息一下，谁知被监工发现，一边骂骂咧咧一边挥舞着皮鞭将你赶回了矿坑继续工作。",
[1520]="你再也无法忍受这种非人的待遇，下定决心准备逃跑。你仔细研究了一下周边的环境，趁着监工不注意时……",
[1521]="逃跑",
[1522]="逃入山林",
[1523]="跳入河中",
[1524]="你逃入了一处山林之中，茂密的林木阻挡了追兵的脚步，同时也让你迷失了方向。",
[1525]="你跳入一条大河之中，由于河水湍急追兵也不敢下河继续追赶，只得眼睁睁看着你奋力朝着对岸游去。",
[1526]="在一个小镇的告示栏上你发现了官府通缉自己的悬赏令，好在你流浪多日早已蓬头垢面，和画像上的形象相差甚远倒也无需担心被人认出。",
[1527]="在逃亡中你经过了一个破庙，发现此地人烟稀少正适合躲避官府追捕，你便在破庙找了个角落暂时安顿下来。",
[1528]="经过酒肆时你闻到了诱人的酒香，可你掂量了下自己的荷包所剩银钱已不多，逃亡还不知要持续到何时，只得咽下口水大步离开。",
[1529]="为了节省开销你只得买一些粗糙的食物，你看着手中难以下咽的干粮，回想起自己曾经锦衣玉食风光无两的日子，不由得感慨万千。",
[1530]="你遇到了一伙乞丐，他们看到你手中的食物两眼放光，仗着人多二话不说便将你团团围住，逼你交出食物。",
[1531]="打劫！",
[1532]="同意交出",
[1533]="拒绝交出",
[1534]="你不想多生是非惹来官府注意，只得交出了手中的食物。乞丐们拿走你的食物后饱餐了一顿，临走时还不忘羞辱了你一番。逃亡多年，为了活下去你忍辱负重，从不主动招惹事端，一改以往暴戾的性格，整个人都变得随和圆滑起来。",
[1535]="你闻言登时火冒三丈，回想起近日所遭受的种种悲惨际遇，一直压制在内心的抑郁之情如同火山爆发一般，令你失去了理智。身体孱弱的乞丐们根本经不住你的拳脚，三拳两脚之下便有人被打的口喷鲜血一命呜呼，众乞丐见你如此凶残纷纷四散逃命。官府在调查凶手时很快就发现了你通缉犯的身份，立刻加大了对你缉捕的力度，最终在重重围捕下你还是落入法网被抓捕归案。",
[1536]="每天夜里，只要你闭上双眼，耳边都是民众的咒骂声，像诅咒一般纠缠着你。你很快就因精神恍惚而莫名发起高烧，族人替你请来名医也是回天乏术……你一直含糊地念叨着“莫要为恶，终究反噬”，直到咽下最后一口气……",
[1537]="不得善终",
[1538]="横征敛财，罔顾民生，终究令你不得善终。",
[1539]="行刑那日，监官大声宣读了你的罪状。围观的百姓无不义愤填膺，抄起烂鸡蛋烂菜叶子和石头就砸向你。你被砸得狼狈不堪，一身脏臭，鼻青脸肿。行刑壮士挥刀的那一刻，你不禁后悔，若自己没有走上歪路，做一个正直的好官，一定不会落得如此下场……",
[1540]="午后问斩",
[1541]="贪赃枉法，罪证确凿，午后问斩就是你此生终点。",
[1542]="你倏然间从昏迷中转醒，一旁的父母心知乃是临死前的回光返照，顿时悲伤不已抱着你痛哭流涕。你感觉到自己大限将至，眼前便如走马灯一般回忆起短暂的人生，突然间定格在了某个画面，你深深的吐出最后一口气，溘然离世。",
[1543]="病危身故",
[1544]="沉湎酒色，身如败絮，一场小病就要了你的命。",
[1545]="一瞬间仿佛时间凝固一般，你只见周围所有人都停下了手中的动作看着你，而自己看向众人的视线却渐渐的模糊了，随后便慢慢的倒在了血泊之中……",
[1546]="横尸街头",
[1547]="你与人斗殴，被一刀穿胸而过，因此身亡。",
[1548]="浑浑噩噩，虚度光阴。岁月如指间沙，终究是到了尽头。",
[1549]="你凭借顽强的意志力，在茂密的山林里存活了下来，由于害怕追捕便在躲藏了多年。你穿着树皮蓬头垢面行走在林间，野人的传说渐渐传到了城镇内……多年之后，你悄无声息地死在了深山之中。",
[1550]="深山野人",
[1551]="自食恶果，躲入深山的你，终在山中了却残生。",
[1552]="你游的速度非常快，离河岸也越来越近，只是逐渐感到体力不支。突然你感到腿部一阵抽搐，冰冷的河水也倒灌入肺中，你的意识逐渐模糊继而被浪花所吞没……",
[1553]="葬身河底",
[1554]="为逃刑役，你跳入河中，却因此葬身河底。",
[1555]="官府将你押送回原籍，你因犯下数桩命案被判斩首，关入死牢待三日后午时问斩。时日无多的你在牢房内回想起这些年自己的所作所为，不禁悔不当初。最后死于刑场，也是你的因果报应了……",
[1556]="死罪难逃",
[1557]="劣迹斑斑，被判问斩，也是你的因果报应。",
[1558]="许多年过去了，当年那桩意外命案早已无人记得，你最终得以回到了家乡和家人团聚，安安分分的过完了后半生。临终前，你告诫后人，做人务必端正言行，心存善念，莫要与人为恶……",
[1559]="苦尽甘来",
[1560]="颠沛流离换来幡然醒悟，你安分地过完了一生。",
[1561]="你出生在一户远近闻名的商贾之家，家族财力雄厚，产业遍布各大城镇。你是家族的嫡系后辈，得族老赐名{0}。",
[1562]="你出生在商贾之家，家族财力雄厚",
[1563]="按照风俗，爹娘为你举办了隆重的抓周仪式，数样精致的物件被一一摆放在你的面前，他们满怀期盼地看着你摇摇晃晃地向那堆物件爬去。你朝着其中一件东西，伸出了胖乎乎的小手……",
[1564]="白玉宝剑",
[1565]="金算盘",
[1566]="布织小老虎",
[1567]="你抓住了一把小而精致的白玉宝剑左右挥舞，你的父母十分惊喜，觉得你将来一定能成为大将军。",
[1568]="你抓起了金灿灿的小算盘上下摇晃，你的父亲开心极了，觉得你一定能成为他的接班人。",
[1569]="你抓起了可爱的小老虎，“啊呜”一口，它的脑袋沾满了你的口水。你的母亲笑了起来，怎么看你怎么觉得可爱。 ",
[1570]="作为家中独子，你深受爹娘的宠爱，每天都过着锦衣玉食的生活。常年富足的饮食，使你的身体比同龄人更加壮实。",
[1571]="这一年你过得非常快乐，放风筝、荡秋千、抓蛐蛐、打雪仗，每天都玩得十分尽兴。",
[1572]="为了避免你玩物丧志，你娘特地请了一位声誉很好的私塾先生，每天上门教你念书。第一次上课，你决定……？",
[1573]="不想上学",
[1574]="好好读书",
[1575]="作弄先生",
[1576]="你的认真得到了先生的夸奖，他觉得你未来一定是个可造之材。",
[1577]="你偷偷把先生的书藏了起来，想看他找不到书本的窘迫模样。不料先生满腹经纶，上知天文下知地理，上课时根本不需要看书。他生动的讲解很快就把你吸引，你渐渐沉下心来，认真学习。",
[1578]="爹娘带你去花灯节玩耍，路过一个挂摊时被算命先生拦下，这人说你命里属水，一生多波折，但可用玉器固命，他这里恰好有一块上好的羊脂玉，愿意高价为你割爱。你的父母笑着听其说完，然后干脆利落地拒绝了他。到了下月初一，你娘亲自去庙里为你祈福，并以重金求回一块百年血玉所制的长命玉佩，希望你能健康成长。",
[1579]="你很聪明，每次都能快速领会先生教的内容，并且举一反三。渐渐地，你开始不满足于先生所授，主动地翻阅家中藏书以增长见识。你会优先选择……？",
[1580]="翻阅家中藏书",
[1581]="你更爱翻阅诗词歌赋的书籍，从中窥见不同人眼中的世界。",
[1582]="你对金钱相关之事十分敏锐，在算术上也很有天赋，很容易就沉浸在这些书籍之中。",
[1583]="一日，你在后院的小亭中翻看闲书，一道金光照在了你的身上，你觉得浑身暖洋洋的很舒服。待你回过神来，金光却消失了。",
[1584]="你随父亲在城中巡视自家产业，偶然发现高空中有数人踏剑飞过，转瞬无踪，你感到无比惊讶。你与父亲提及此事，他神情严肃地告诉你，那些人都是修道宗门里的活神仙，每个人都有大本事，挥手就能翻覆城池。你听到此言，面上不动声色，心底却滋生出强烈的向往。",
[1585]="随着年岁渐长，你已逐渐熟悉家中的产业。你爹决定让你试着接手一些家中的营生，以便未来接班。你决定……？",
[1586]="接手家业",
[1587]="考取功名",
[1588]="你决定接手家业，开始经商。",
[1589]="你决定考取功名，成为了一名县令。",
[1590]="家业之大，非一年半载能尽皆掌握。你有心为父分忧，决定听从你爹的安排。",
[1591]="你之聪慧得先生盛赞，有心考取功名创出一番作为。你爹知你抱负，不曾阻拦，更是替你打点到位。你果然一路顺遂，考取功名后，得了县令一职。",
[1592]="你开始接管家族业务，学习长辈的致富方法，家族家业广布大江南北，你在此期间竟然也听闻了不少仙人踪迹的传闻，近期发生过的江水断流，据传更是有仙人冻住了上游之水导致。",
[1593]="一颗族内收藏的丹药下肚，你浑身充满了力量，多年的疲劳彷佛一扫而空，你不禁感叹仙人的手法，可惜收藏已不多了。",
[1594]="你自幼衣食无忧，得到了良好教育和无尽的物质享受，但并未有丝毫放纵堕落。因你深知纵欲则财空，家业都是一点一滴积累起来的。",
[1595]="你出资修建桥梁道路，开设义塾，资助贫寒学子，更在灾年开仓放粮，救活无数百姓。",
[1596]="无论生意多么繁忙，你都会抽空陪伴家人，增进亲人间的感情，使得家族上下一团和气，成为当地人家羡慕的对象。",
[1597]="多年的苦心经营，你的财富已经相当可观，足矣供几代人的肆意挥霍，花不完，根本花不完。",
[1598]="你把玩着手里一块晶莹剔透的石头，听闻此乃“灵石”，仙人修炼的必备之物，当初花费重金得来的此物，并无发现有何奇异之处。",
[1599]="你把玩着手里一块把锋利的剑，听闻此乃“玄铁”所制，当初花费重金得来的此物，锋利无比坚不可摧足矣在凡间自保，轻抚剑身连连称奇。",
[1600]="一日夜行，竟遇山匪抢劫，对方人多势众心狠手辣，心想今日或许命丧于此，刀芒即将来临之际，贴身护符忽然散出耀眼光芒，山匪随机纷纷倒地，你看着祖传之物震惊不已。",
[1601]="你生活在奢华与尊荣之中，享受着无尽的优越感和权力，学尽百师，琴棋书画，无一不是尽善尽美。",
[1602]="你收到情报，今年茶山大旱，茶叶产量将锐减，于是提前囤积了大批茶叶。到了新茶上市时间，由于茶叶产量大减，价格快速上涨，你趁机抛售，所赚甚巨。",
[1603]="你购买了许多良田、矿山和作坊，得益于在各地收集的信息，你招募了能力极强的管事替你打理产业，并把相应的产品运送到最稀缺的地方赚取最大利润。",
[1604]="你正在自家产业的酒楼用餐，正好有几人喝得伶仃大醉，还砸坏了不少东西。你赶紧让掌柜将这几人送到厢房了休息，以免影响生意。这些人酒醒后发现自己行为不当，赔了不少财物道歉，旁人纷纷夸赞你有识人之能。",
[1605]="每一年的这一天，你都会前往城里香火最盛的寺庙上香祈福，祈佑你的产业生意兴隆。",
[1606]="你在大街上闲逛，突然被一颗石头砸中，你心生怒气，吼道：“哪里来的破石头！”话音刚落，数颗石头朝你兜头而下，如同下了一场冰雹。你定睛一看，这些竟然都是灵石！突然其中一颗砸中了你的脑袋，你眼前一黑，倒地不起……",
[1607]="夏夜乘凉，你听见后院传来笛声悠扬，循声而去，只见竹林深处有一名女子在月下独奏，曲声似有宁神的作用。一曲罢，你如梦初醒，却已不见佳人。",
[1608]="你时常举办诗会，与诸多才子一同吟诗作对，品茗弈棋，分外潇洒。",
[1609]="闲暇时，你与友人去听曲观戏，戏台上唱将军弯弓、誓杀敌寇；唱清官俯首，为民请愿……你看得十分动容，自觉收获良多，打赏了不少银钱给这个戏班。",
[1610]="你结交了不少官吏，其中有一人愈发贪得无厌，令你不喜。你不动声色地与其保持距离，其后果然听闻其因罪入狱的消息，只道是：贪得无厌难逃厄运。",
[1611]="为了防止钱庄管事作假，损害家族利益，你更改了制度，让不同的钱庄管事每年轮替，彼此核对账目，杜绝一手遮天的情况。",
[1612]="你向来是食不厌精脍不厌细，听闻自家酒楼花重金聘来了一名祖上出过御厨的名厨，便兴致勃勃地前往酒楼试一试这名厨子的手艺。 一试之下，果然不凡，你赞不绝口，在酒楼连吃了一个月方才尽兴。",
[1613]="今年的丝绸工艺又有进步，你十分喜欢，自留了不少新款，带回家中分享。你爹娘也很满意，遂命人将新绸裁成新衣，穿上外出时，惹来不少钦羡的目光。",
[1614]="一日，你外出晚归，意外看到几名家仆在府门外欺负一个瘦弱的孩童，很是跋扈嚣张。你立刻让管家将这几个仗势欺人的家仆逐走，狐假虎威之辈，不配在府中做事。",
[1615]="闲来无事的你收罗了许多古玩名画，干脆在城郊又买了块地，聘请名匠在城郊打造一处别院，专门用来存放这些藏品。",
[1616]="你最近左眼皮不断直跳，俗语有云：左眼跳财，右眼跳灾。你寻思最近可能会有财运将近，于是决定……？",
[1617]="财运将近",
[1618]="走进赌坊",
[1619]="购入玉矿",
[1620]="古人有云：逢赌必输，十赌九输。你连连失利，将这个月赚的钱全输给赌坊了。",
[1621]="你顺从直觉，购入大量玉矿，果然开出不少好玉，狠狠赚了一笔。",
[1622]="你与友人小聚刚散，微醺着回府，刚到家门口，就碰到一个衣衫褴褛的老乞丐朝你磕头，求你赏一口饭吃。你决定……？",
[1623]="衣衫褴褛的乞丐",
[1624]="与人为善",
[1625]="你惊得酒都醒了大半，也不嫌弃对方身上的脏污，直接将人扶了起来，再让下人拿了些热腾腾的饭菜给这位老人家，对方感激地朝你连连鞠躬，念叨着：“大善人定会事事顺遂，福缘满满。”",
[1626]="你有点头晕，只想快些进府睡觉，便挥手打发走了这名老乞丐。",
[1627]="纸醉金迷的生活渐渐令你觉得无趣，美酒佳肴也无法再令你心生波澜。人生苦短，还有许多风景未曾见过，于是你决定……？",
[1628]="人生苦短",
[1629]="寻仙问道 [聪慧判定]",
[1630]="游览山河",
[1631]="寻仙问道",
[1632]="纵情山水",
[1633]="家财万贯不如寻仙问道，你拜访仙门，通过了考核。",
[1634]="家财万贯不如寻仙问道，你拜访仙门，却不得而入。",
[1635]="坐拥千金不如踏遍天涯，你寻到了自己的道。",
[1636]="<color=#549327>[判定成功]</color> 你动用家族的全部人脉，终于找到了拜访仙门的方法。你心怀期待地找上传说中的修道宗门，想要拜入门中……考核之人乃是一名老者，见到你，不禁微笑道：”有福缘之辈且身具灵根，可入宗门。”",
[1637]="<color=#c82c2c>[判定失败]</color> 你动用家族的全部人脉，终于找到了拜访仙门的方法。你心怀期待地找上传说中的修道宗门，想要拜入门中……不料你在宗门的大阵之外跪了三日三夜，也不见任何动静……",
[1638]="你将家业交给得力的族人打理，开始纵情山水，不同的风土人情让你大开眼界，天地之大，无穷尽也……你就这样四处游玩，岁月如水，一生很快就过去了。",
[1639]="捕头向你汇报近期县内有一侠盗频繁作案，闹得本地乡绅人心惶惶，你虽心里佩服，但为了维持县内的局势，不得不颁布了侠盗的通缉令。",
[1640]="官场的勾心斗角和一些官员的不作为常常令你感到厌烦，但你又没有改变现状的好办法，便只能时常在院子里独饮叹息。",
[1641]="恰逢旱灾，民不聊生，你上奏请求开放国库救济灾民，却被以“国库入不敷出”为由驳回，气得你大骂了句“昏君“。",
[1642]="你发现近日府中伙食莫名好上不少，一番了解之下方才得知，原来是有些百姓为求好办事，经常来送礼，家仆们却瞒着你通通收下。气得你立刻换了一批家仆，再严厉声明不得收礼，家风为之一清。",
[1643]="你时常在县中走访，了解百姓所需，行事有度，断案公正。百姓们为感谢你的付出，筹集资金定制了一块“青天大老爷”的牌匾送给你，以表达对你的爱戴。",
[1644]="你识人精准，亲自挑选了一名务实的主簿，再招了一批勤快机灵的衙役。手下人办事周全，让你甚是满意。",
[1645]="立春之日，你亲自主持了县里的迎春仪式，一丝不苟地完成了祭祀流程，带着众人祈祷今岁丰收。",
[1646]="县中有一对性情急躁的兄弟，因为去世的老父遗留的一笔银钱，一个月内闹上公堂三回。每次看着他们在堂下互骂，你都觉得头疼，真是清官难断家务事啊。",
[1647]="这般下去也不是办法，你认真走访了这对兄弟的邻里，了解这家的实际情况，查明兄弟二人侍奉老父都算尽心，便做主让他二人各领半数银钱，更苦口婆心地劝说了许久，终于令这对兄弟放下成见，不至于再伤了和气。",
[1648]="你去坊市买东西，意外发现坊市的管理混乱，不利于长期发展。仔细斟酌后，你颁布了适合坊市贸易的条律，没过多久坊市就比先前热闹了数倍，来往的客商越发多了。",
[1649]="清晨用过早膳后，你都会抽空批阅民情书信和案卷，下笔慎重，力求公正无私。",
[1650]="你深知念书识字的重要性，督办了免费的学堂，更亲自拜访了县中几位颇有名望的老儒生，说服他们到学堂讲学。一些家境贫寒的孩童因此开始念书识字，让你十分欣慰。",
[1651]="秋季干燥，县里走水，火势蔓延极快，闹得人心惶惶。你果断下令，让衙役们前往各条街巷维持秩序，组织大家救火，有效地安抚了民心。",
[1652]="闲暇时，你特地走访治下各村，虚心请教村老们有关农耕的各种经验，整理成册后派衙役前往各方宣读，力求让农户们都能掌握更多有用的农耕方法。",
[1653]="今日休沐，你正在西街的面摊吃面，突然有人轻轻撞了你一下。察觉不对的你立刻锁定了目标，立刻追上去把人拿下……",
[1654]="你果然从对方身上搜出了自己的钱袋。再在周围问了一圈，才知道这竟是个惯偷，今天偷到你身上也算是到头了。你果断将人押回县衙，依律治罪。",
[1655]="正值元宵节，你兴致甚佳，用过晚膳后也出门赏花灯。看着县内一片灯火璀璨，百姓们欢声笑语，你感到非常自豪。",
[1656]="你时常研读朝中律法，以此印证自身作出的一些决策。日积月累之下，你的治政能力提升了不少。",
[1657]="隆冬大雪，天地一片银装素裹，此等雪景，别有一番韵味。你望着纷纷大雪，不由得笔走龙蛇，写的正是“瑞雪兆丰年”——对来年开春寄以美好的愿景。",
[1658]="有一伙匪盗流窜到了县内，你立刻派人严格盘查每日的进出县城的人员，让衙役挨家挨户核对户籍。最后在一处偏僻的院落揪出了这伙躲藏的盗匪，没有危害到百姓的安全。",
[1659]="你进京述职，返县中途，在一条官道上竟看见了一条巨大的蟒蛇，其盘起的身躯犹如一座小山，占据了道路中央的位置。",
[1660]="你不欲惊动巨蛇，让车夫设法从旁边绕过，不料经过其身侧时，它竟昂首直立而起，冲你点了点蛇头，就好似人们作揖行礼一般。你不敢怠慢地朝向巨蛇还礼。心中觉得神异，这也算是一桩奇事了。",
[1661]="今年丰收，你依照惯例巡视各村，因热情难却，你被小南村的村民留下来用了顿饭。吃着散发出浓浓米香的稻饭，看着农户们喜气洋洋的笑容，你不禁湿了眼眶。",
[1662]="邻县的县令贪婪无比，导致治下民不聊生。大批流民因此涌入你治下之地，了解缘由后，除了安顿流民你别无他法，只因那县令背后靠山极大，难以撼动……思及此事，你不由怒急攻心，气得吐了血。",
[1663]="你与志同道合的同僚小聚，聊民生聊律法聊诗画，兴起时以箸击节，引吭吟哦，很是畅快。",
[1664]="钱财动人心，你想办法把他的儿子塞到了自己手下，做个普通的衙役，每日巡逻几趟，间或跑跑腿，倒也还算得用。",
[1665]="此事有一就有二，你决心要有一番作为，不愿受钱财桎梏，婉言拒绝了对方。",
[1666]="你在县中走访时，发现一户只有祖孙两人相依为命的穷苦人家。老爷子上了年纪，还瞎了只眼，带着不到十岁的孙儿过得很是艰难。你决定……？",
[1667]="相依为命",
[1668]="暗中接济",
[1669]="设法相助",
[1670]="看到他们如此艰难，你于心不忍，回去后交代家中下人，在不透露你身份的情况下，每个月送些银钱粮肉来接济这对祖孙。",
[1671]="你先带这孩子到县中免费的学堂挂了名，去学堂念书识字，再让他每日给你府上挑两担柴，换些银钱。也算是给这对祖孙谋了份保障。",
[1672]="县里隔三差五就会受到洪涝灾害的侵袭，灾情严重，极为影响民生。你决定……？",
[1673]="洪涝灾害",
[1674]="兴水利",
[1675]="广囤粮",
[1676]="你决定兴修水利，加固河堤，广邀善于治水之士规划水道，发动民众育林固土……数年之后，再未出现特别严重的洪灾，成效显著。",
[1677]="你决定未雨绸缪，多囤粮食，保证仓库的干燥和安全。由于存粮充足，此后再有灾情，县内的百姓也都能平稳度过。",
[1678]="你处理完今日的事务，从县衙回府，刚到家门口，就碰到一名风尘仆仆的和尚朝你化缘。你决定……？",
[1679]="风尘仆仆的和尚",
[1680]="以礼相待",
[1681]="婉拒对方",
[1682]="你友好地还礼，让下人打了满满一钵斋饭给这名僧人，对方笑道：“施主仁善，有缘再会。”",
[1683]="你有些警惕，不知这僧人来路，你不欲牵扯过多，摇头婉拒了对方。和尚微微一叹，没有多说什么便径自离开了。",
[1684]="农忙时，你去各个村子巡视，傍晚时从邻村回城，刚到家门口，就碰到一位风尘仆仆的道士朝你化缘。你决定……？",
[1685]="风尘仆仆的道士",
[1686]="你友好地还礼，让下人准备了足量的饭菜拿给这位道长，对方笑道：“善人仁心，有缘再会。”",
[1687]="你有些警惕，不知这道长来路，你不欲牵扯过多，摇头婉拒了对方。道士微微一叹，没有多说什么便径自离开了。",
[1688]="月圆之夜，你难得清闲，正在府中后院赏月独饮……饮至酣处，你只觉得眼前朦胧起雾，雾中竟走出个白衣仙人，对你道：“你祖上与我宗有缘，后人皆在我宗考察之列。你自幼聪慧，在俗世为官也宅心仁厚，且有灵根，已通过我宗两次考验。如今机缘已至，可愿随我入宗，一窥仙途？”",
[1689]="一窥仙途",
[1690]="答应对方",
[1691]="仙缘入梦",
[1692]="机缘已至，你实现了年少的向往，由此踏上仙途。",
[1693]="你一心为民，只当仙缘入梦，一笑置之。",
[1694]="你瞬间想起了年少时的惊鸿一瞥，踏剑飞行……活神仙……尘封已久的向往再次变得无比强烈，你果断答应下来，跟随对方离开",
[1695]="你以为自己喝醉了，尚在梦中，笑着对仙人说道：“人有志，当从一而终。踏上仙途虽好，但我身为父母官，当为百姓鞠躬尽瘁。”对方听完，微微一笑，冲你一挥袖：“也好，那你就当这是一场梦吧。”你第二日在床上醒来，只觉得这个梦无比真实。但你并未多想，一笑置之。此后照常当你的县令，兢兢业业，全心为民，一生很快就过去了。",
[1696]="一日你刚起身，打开房门时便感到眼前阵阵发黑，有些喘不过气。你意识到或许是大限将至，此时一抹虚幻的玄妙身影出现在你的面前，说与你有缘，可赠你一枚寿元丹续命。你决定……？",
[1697]="晚年的你更加注重家族的教育与传承；你常常教导子孙，经商之道在于仁心与智慧并重，不仅要追求利润，更要顾及社会福祉。最后你躺在床上，说道“财聚人散、财散人聚”，便安然离世，而这句话也成为历代祖训。",
[1698]="你走了很远很远，见到了许多人穷极一生也未曾见过的风景。你最后留在了一个四季如春的水乡，青瓦白墙的院落内，桃花开得正胜，你在摇椅上嗅着花香，陷入了永眠的美梦中。",
[1699]="客死他乡",
[1700]="你走了很远，最后留在一个四季如春的水乡。",
[1701]="你少时富贵，成为县令后一心为民，被百姓爱戴，是一名真正的父母官。你常常教导子孙，不可骄狂自满，需持身守正。你于一个冬夜安然而逝，一生所行，皆无愧于心。",
[1702]="你于一个冬夜安然而逝，一生所行，皆无愧于心。",
[1703]="你瞪大了眼，这老者与一名老乞丐的模样渐渐重合，你看着对方洞悉一切的双眼，不禁欣喜若狂地磕头拜谢，由此踏上仙途。",
[1704]="机缘已至，你由此踏上仙途。",
[1705]="这仙缘，果真如此难寻么？你这般想着，心中郁郁，竟是在归家的途中便郁愤而逝了。",
[1706]="机缘未至，你终究与仙途无缘。",
[1707]="种子粘着小鸟的尾羽，被风吹到一片干燥的土地上。",
[1708]="一棵小草",
[1709]="小雨淅淅沥沥，种子的外壳裂开一道缝隙，冒出一个小小的尖儿。",
[1710]="小草的叶子在阳光下舒展开来，第六片叶子的嫩芽也冒了头。",
[1711]="根系在土壤里越扎越深。",
[1712]="狂风几乎把草叶折秃，四周砂石乱飞，还好根系扎得足够深，足够广，并未被连根拔起。",
[1713]="没有被狂风摧折的小草重新长出了第十一片叶子。这片叶子……？",
[1714]="第十一片叶子",
[1715]="又厚又宽",
[1716]="形状特别",
[1717]="这第十一片叶子，比别的叶片厚了许多，也宽了许多。",
[1718]="这第十一片叶子，竟像一片花瓣的形状，微微有些透明，甚是好看。",
[1719]="小草在微风中抖了抖叶子，有什么悄然滋生。",
[1720]="浑浑噩噩……有些暖，但是很黑。",
[1721]="似乎，被包裹着。周围……有东西。在本能驱使下……？",
[1722]="似乎被包裹着",
[1723]="茁壮根系",
[1724]="汲取养分",
[1725]="小草努力地让根须长得更加强韧……直至堪比参天大树的树根。",
[1726]="小草努力地伸展叶片，汲取阳光和月华中的养分……",
[1727]="朦胧的、细细碎碎的声音……什么是，声音？",
[1728]="有什么东西贴着你，翻来覆去的，把你弄得有些晕……你决定？",
[1729]="奇怪的东西",
[1730]="缠上去",
[1731]="一动不动",
[1732]="被拔走了",
[1733]="你被人连根拔起，生命就此终结。",
[1734]="你顺从本能缠了上去，不料那东西突然抓紧你用力一扯！一阵撕心裂肺的痛瞬间袭来，你只依稀听到一句：“哈哈哈！果然是棵快要开灵智的药草，这回发了！”，便什么都不知道了。",
[1735]="你不欲理会那折腾你的东西，晕乎乎地睡了过去……一名壮汉捏着棵野草翻来覆去地看了半天，终究没看出什么门道，转身离开了。",
[1736]="嗯？……为什么，看不见？你似乎有了意识……自身是……什么……",
[1737]="你终于睁开了眼睛，只见周围一片绿绿的，你好像也……绿绿的。",
[1738]="灵智初开",
[1739]="灵智初开的你，开始亲眼观察这个世界。",
[1740]="今年的雨季极长，你身处的这一片绿都被水淹得只剩了一层薄薄的绿尖，你在雨中抖了抖身上的水珠，决定……？",
[1741]="薄薄的绿尖",
[1742]="汲取水分",
[1743]="努力躲雨",
[1744]="这漫长的雨季意外地令你感到很痛快，你趁机拼命汲取水分。",
[1745]="你努力地让根须把草叶托高一些，尽量避免脆嫩的叶片被雨水泡烂。",
[1746]="你的听力越来越好了，不知道从哪传来的窃窃私语被你听了一耳朵……似乎是在讨论，明年会有什么月华帝流浆？",
[1747]="今晚的月亮又大又圆，月光中有什么让你蠢蠢欲动的东西，你无师自通地吸收了起来……你顿悟了，原来自己是一棵开了灵智的小草。",
[1748]="一只雀儿飞到了你的身边，圆溜溜的眼珠盯着你看了许久，突然猛地一啄！尖利的鸟喙眨眼间扯下一片草叶，你痛得狠狠一颤……你决定？",
[1749]="凶狠的雀儿",
[1750]="欺草太甚必反击",
[1751]="忍一时风平浪静",
[1752]="恶雀摧草",
[1753]="凶恶的雀儿连吃带刨，你的一生就此终结。",
[1754]="你忍无可忍，一叶子抽了回去！草叶的边缘锋利地划过雀儿的眼睑，激怒了对方。雀儿扑棱着翅膀狠狠地啄向你，三两下就把你的草叶吃了个干净。你痛不欲生地发出哀嚎，不料对方竟用爪子将你的根须都刨了出来扯断……",
[1755]="好草不和恶鸟斗！你悄悄地藏起了几片叶子，默默忍耐着……只见对方啄了三四片叶子之后，心满意足地“啾啾”鸣叫了两声，便振翅飞走了。",
[1756]="“嗝。”你终于把当年吸收的月华帝流浆的灵气消化完了，满足地打了个饱嗝。",
[1757]="初遇帝流浆",
[1758]="月华帝流浆令你获益匪浅，大感满足。",
[1759]="你看了看满地跑的田鼠和山猫，有点羡慕。于是尝试拔起根须挪动身子，不就是跑？你可是灵草，也能学会！",
[1760]="你刚学会拔根行走，却来了几个农夫说啥开垦荒地，一镰刀险些把你腰斩！你被惊出一身冷汗……不对！水分流失了，赶紧吸收回去！",
[1761]="夜色蒙蒙，万籁俱寂。小命要紧啊……你鬼鬼祟祟地拔起根须，连夜跑走。",
[1762]="你发现自己身上有一层薄薄的灵光，身边却都是平凡而清新的小绿叶，于是用力憋了一口气——“嘭”地学会了遮蔽灵光，低调生存。",
[1763]="有一窝肥大的蚯蚓钻到了你扎根的地盘，你张牙舞爪地威逼利诱它们在附近安家，负责每日帮你松土。",
[1764]="夏天的日头过于毒辣，你看看自己晒得发蔫的叶片，决定依靠大树好乘凉——搬到附近的老榕树脚下避暑。",
[1765]="你嗅到不远处有一潭灵泉，似乎无人发现，于是时不时在半夜偷溜过去汲取灵气……过了段时日，附近的村落流传起了夜半水鬼的怪谈。",
[1766]="胆大的孩童半夜摸到灵泉附近探险，你躲在暗处不爽地屏息晃动身影——月光下拉长的巨大怪影诡异张扬，吓得孩童哭嚎着逃回了家。",
[1767]="有只兔子精不知从哪听到了风声，过来和你争这汪灵泉。你打不过对方，被吃了大半叶片，在兔嘴下险险逃生。",
[1768]="秋霜一打，许多野草都开始枯黄凋落，你非常未雨绸缪，努力收集了许多枯草团成厚实的垫子，用来保暖防寒。",
[1769]="不远处有一小丛花藤，每到夜晚就会散发浓香，你十分喜欢，忍不住用根须把对方的根缠住，强行拉到了自己身边。",
[1770]="冬日大雪，附近的湖泊和河道都结了厚厚的冰。你听路过的猎人说冰层下的肥鱼鲜美，于是努力往河床延伸根须，开始凿洞。",
[1771]="你的根须窜过河床的洞，卷了几尾肥鱼回来，虽然品不出啥滋味，但埋在土里当肥料也不错。就是河水太冰了，下次不卷了。",
[1772]="富农家的胖儿子跑来地里疯玩，揪秃了不少草皮，还用石头砸伤了你。你悄悄伸出根须，狠狠绊了这熊小子一跟头，摔崩他两棵门牙。",
[1773]="有个小姑娘时常过来摘些花草摆弄。这回她把手伸到了你身上，你正感到大事不妙，不料对方没有辣手摧草，只是把你的两片叶子编成了个圆环。",
[1774]="清晨，你正在舒展叶片，一个小男孩跑来，“嗞”地一股热流兜头浇下……你怕吓到小孩，结结实实受了这泡童子尿。",
[1775]="你顶着一身味儿，心想：这岂不是……噫~~还是不要了！趁着四下无人，连忙一草扎进小溪里反复冲洗了十数遍。",
[1776]="你照常在月光下吐纳，突然觉得头顶有点痒痒的，不由得支起叶尖点了点痒处……？！竟然开花了！哎呀~不知怎么就有点小害羞。",
[1777]="第二日有农户经过，发现你这朵花挺好看的，便仔细地连着叶蔓一起摘了，说要带回家栽种。你又痛又难过，只能偶尔跑去看一看自己的花。",
[1778]="听说深山里有不少奇花异草，你便想进山逛逛，指不定能交个朋友。不料走到半途就被一群鹿追了半座山头，花草没见到，倒是逃没了半条命。",
[1779]="你隐匿身形跑到了人类的镇子里，正好碰上花灯节，街道上灯火通明，热闹非凡，让你大开眼界。",
[1780]="风中传来一抹淡淡的血腥味，你好奇心作祟，谨慎地前去查探，发现有只兔子精躲在乱石堆缝隙里舔舐后腿的伤口。你一眼就认出了对方——",
[1781]="这正是当年抢你灵泉的那只兔子精！天道好轮回，趁兔伤要兔命，你果断趁其不备，从后方用根须绞死了它，它的妖丹就是大仇得报的战利品。",
[1782]="风和日丽的午后，一个路都走不稳的小丫头摇摇晃晃地朝你走来，你嗅出她是当年赏了你一泡童子尿的那小子的后人，便准备吓唬吓唬她。",
[1783]="你“噌”地绕着她跑了一圈，还用叶子去缠她胖乎乎的小手。不料她却没被吓到，反而咯咯地笑着给你鼓起掌来，奶声奶气地喊：“小草，厉害！”",
[1784]="你不禁愣了一下，干脆直接开口：“哼！小心我吃了你！”她却还是笑着，轻轻地摸了摸你的叶片：“小草，不吃人，会讲话，顶呱呱！”",
[1785]="你莫名就有些开心起来，不再计较当年之事，别扭地说道：“我会说话这事，你不许说出去！不然就不理你了！”小丫头用力点了点头。",
[1786]="小小年纪的奶娃娃一直替你保守秘密，时不时就跑来找你玩耍。她成为了你的第一个朋友。",
[1787]="你看着这丫头渐渐长大，直至出嫁。出嫁那天她又来看你，絮絮叨叨说了许多，竟是要远嫁了。你突然觉得心里空落落的。",
[1788]="你用力拔下一片叶子交给她：“这个能治病救命，你拿着，当嫁妆。”她双眼一红，郑重地将叶片放好，回道：“谢谢你，再见了。”",
[1789]="你看附近的孩童去学堂，好奇之下隐匿身形偷偷尾随，跟着听了几堂课，学到不少道理。",
[1790]="有两只妖隼在附近打架，最终斗了个两败俱伤，齐齐从高空跌落下来。你挪过去卷了两枚妖丹回来消化，美滋滋地坐收渔利。",
[1791]="农户最近一直在讨论隔壁村老李头的庄稼长得过于好了，不知施了多少好肥。你偷偷溜去围观，从那田里挖出来一块木精，大补！",
[1792]="你看到小孩拿着树枝在地上写字，便也想学一学，不料学了个四不像，根须画出了鬼画符。吓得附近的村民请了道士来做法事辟邪。",
[1793]="你冥冥有感，觉得要入定修炼了，连忙找了个僻静石洞钻进去扎根顿悟。年月飞逝，果然增加了不少道行。",
[1794]="一日，两名修士在高空上打得激烈无比，哪怕设下禁制，这一带依然阴云压顶，飞沙走石。打斗中有什么亮晶晶的东西掉了下来，你屏息偷偷观察了很久，等到那二人逐渐远离，直至再无动静，你决定…？",
[1795]="打斗的修士",
[1796]="过去捡漏 [聪慧判定]",
[1797]="贪心不足",
[1798]="你贪图灵石，被灵石之主抓获，因此而亡。",
[1799]="<color=#549327>[判定成功]</color> 你趁着四下无人挪动过去，发现那竟是几块灵气浓郁的宝石！你立刻用根须将它们卷到泥土里慢慢消化，自身的灵力因此又增长了一大截。",
[1800]="<color=#c82c2c>[判定失败]</color> 你飞快地挪动过去，发现那竟是一块花纹奇特的灵石！正打算据为己有，只听身后响起一声冷哼：“区区一棵刚开灵智的草精也敢打本少爷这宝贝的注意？”你只感到一阵剧痛，便什么都不知道了……",
[1801]="那两个家伙凶得很，谁知道会不会回头来寻？你收敛起好奇心，小心使得万年船。",
[1802]="一只额生异角的斑斓大虎拨开草丛，来到你的面前。对方盯着你嗅了许久，血盆大口流下的唾液快要在你头顶下雨了，你决定……？",
[1803]="斑斓大虎",
[1804]="缩地遁走",
[1805]="屏息装死",
[1806]="被吃掉了",
[1807]="异虎识破了你的伪装，一口将你吃掉了。",
[1808]="一阵危机感涌上心头，你毫不迟疑地草叶一卷，顺着根须缩地遁走，堪堪逃过一劫。",
[1809]="你打算伪装成一棵普通的小草避祸。不料这异虎狞笑着大吼一声，张嘴便吞了你！",
[1810]="一名面相和善的老者腾云而至，翩然降落在你跟前。他笑眯眯地望着你，说道：“你这小草已启灵智，灵气浓郁，很是不凡。可要归入小老儿之宗门，踏上仙途？”你决定……？",
[1811]="和善的老者",
[1812]="轻信歹人",
[1813]="你轻信一名老者，被其炼作了丹药。",
[1814]="你看这老人家慈眉善目的，便点了点草叶，答应跟起离开。不料对方回了宗门，便一把将你投入了丹炉……",
[1815]="知人知面不知心，你直觉不对，趁对方不备，你叶子一晃便飞快地遁地逃走了。",
[1816]="数百年一遇的月华帝流浆又将到来，为了尽可能地汲取这次帝流浆的精气，你决定……?",
[1817]="月华帝流浆",
[1818]="精心准备",
[1819]="平常对待",
[1820]="再遇帝流浆",
[1821]="你做了万全准备，因此修为大进。",
[1822]="你准备欠妥，因此错失修为大进的良机。",
[1823]="你找了一处僻静的小山头扎根，周围只长了些最普通的野草。你借着野草隐蔽身形，全神贯注地吸收这一次的帝流浆，竟然修为大进，比起一些炼出妖丹的妖兽也不差什么了，已能口吐人言，距离化形也只差临门一脚。",
[1824]="你想着自己成年前也吸收过一次帝流浆，一回生二回熟，还是顺其自然吧。不料帝流浆降世之夜，你所在的地界挤满了各种妖兽，你不得分心防备这些家伙，精神紧张下，帝流浆还没有成年前那次吸收得多。",
[1825]="你感觉到了进阶的契机，也存了不少妖丹灵石用于突破。精怪化形实为天妒，你深知一旦决定突破，雷劫即至。你决定……？",
[1826]="进阶的契机",
[1827]="迎劫而上 [潜力判定]",
[1828]="不与天争",
[1829]="灰飞烟灭",
[1830]="雷劫令你脱胎换骨，终成人身，得入仙途。",
[1831]="精怪化形终遭天妒，你在雷劫下灰飞烟灭。",
[1832]="你畏惧天威，退缩不前，终究难逃一死。",
[1833]="<color=#549327>[判定成功]</color> 既开灵智，当与天争！你找了个安全之处，全力渡劫！雷劫临身，劈得你根叶毁损，你却一直苦苦坚持……不知过了多久，雷云终于消散，你长长吐出一口气，心随意转，瞬间就化成了个伶俐可爱的孩童模样",
[1834]="<color=#c82c2c>[判定失败]</color> 既开灵智，当与天争！你找了个安全之处，全力渡劫！雷劫劈下，一道、两道、三道……天威何其可怖，最后一道电光闪过，你已然在雷劫中灰飞烟灭。",
[1835]="你心中畏惧，想了许久，还是不敢渡劫……但你修为愈深，灵气也愈发浓郁，终究逃不过大能的法眼，将你拔去炼成了丹药。",
[1836]="这日早晨，你突然觉得精气衰弱，叶片突然蔫黄下去。你意识到或许是大限将至，此时一抹虚幻的玄妙身影出现在你的面前，说与你有缘，可赠你一枚寿元丹续命。你决定……？",
[1837]="春去秋来，光阴似水。你顽强生存的这一世，终至尽头。",
[1838]="你多方打探，长途跋涉，终于寻到了一处仙宗。在山门处叩拜许久，你运气极好地被一名内门师兄领进宗门，然后经历了一系列的入门考验，测灵根，评心性，观悟性……最后成为了一名练气期的外门炼丹弟子。",
[1839]="你来到外门弟子居，进入属于自己的房间，成功练气运行一个周天之后，感觉身体一轻，一股生机由内而外地散发开来，容光焕发得就像回到了年轻时一样，这令你很是欣喜。",
[1840]="仙途之初",
[1841]="你成功拜入仙宗，成为了一名外门炼丹弟子。",
[1842]="来到宗门坐落的仙山后，你接受了一系列的入门考验，测灵根，观悟性……最后成为了一名练气期的外门炼丹弟子。",
[1843]="昔日灵草，今朝化人。漫漫岁月皆成过往，灵草之身积累的点点滴滴化为深厚根基，自此，你以人身入仙途。",
[1844]="天地之广，己身之道为何？你尚不明晰，只待慢慢体悟，一步步亲自探寻求证。仙途道长，此行亦艰，你却没有丝毫畏惧，反而跃跃欲试，誓要以这新生之躯，悟得天地至理，证道成仙。",
[1845]="灵草化形",
[1846]="探求修行之路，证道成仙",
[1847]="师父命你去灵药园采摘灵草，但由于你粗心大意，导致灵草的根叶被挖断，被师父罚去面壁崖思过半个月。",
[1848]="你炼丹时不小心打了个喷嚏，导致平衡打破，最终一批炼丹的灵药全部报废，气得你差点把自己的丹炉砸了。",
[1849]="师父在炼丹房里待了三日三夜都不曾出来，你非常好奇，打开门缝偷偷观望，意外掌握了一些炼丹控火的窍门。",
[1850]="宗门最近大战在即，需要准备许多疗伤丹药，你忙了十日十夜，虽然辛苦，但好像炼丹手法有所提升。",
[1851]="风和日丽，诸事皆宜。你终于用自己的小丹炉炼制出几枚凝气丹，虽然丹药品相平平，但总算有点起色，令你十分开心。",
[1852]="你来到宗门的庶务殿，用多年积攒的宗门积分兑换了一枚筑基丹。不料离开时，却被宗门的内门弟子出手抢夺，你反抗无果，还被痛揍了一顿。",
[1853]="整日在炉火和药材之间来回忙碌，你渐渐觉得枯燥乏味，有些心灰意懒。每当望见窗外的师兄师姐们踏剑飞过，你的不甘和失落总是愈发强烈。",
[1854]="除了炼丹，你也时常前往宗门后山修炼。不料此行遭遇灵兽袭击，你拼着自己重伤击杀了灵兽，虽然捡回小命，却被迫在床上休养了数月。",
[1855]="宗门将要举办炼丹大会，你为此准备许久，不料在炼丹大会的当天，信心满满的你第一轮就被刷了下来。你不禁怀疑，难道自己真的没什么天分？",
[1856]="你偷偷从丹炉中借火，想要拿来烤叫花鸡。不料被师兄发现，将你教训了一顿，罚你打扫了一个月的丹房。",
[1857]="最近有个漂亮活泼的小师妹经常来向你请教一些丹药相关的问题，你不由暗暗窃喜，难道小师妹对你有意？",
[1858]="师父命你顾守丹炉，但这日你实在疲惫，心思涣散，小鸡啄米似地打着盹……再睁眼时，药材已在丹炉中化作一片焦黑。师父大发雷霆，将你揍得两个月下不了床。",
[1859]="雨后，你前往宗门后山，意外发现一些长得葱郁的野生灵草，药性不错，可用于炼丹。你悄悄地采摘了这批灵草，充作自己的私房炼丹材料。",
[1860]="你在宗门后山发现了一个隐秘的山洞，里面有一潭小小的灵泉，对修炼大有益处。",
[1861]="你在宗门散步时发现一颗有些特别的草，正准备把它拔出来研究时，这草竟然在你眼皮子底下消失了。",
[1862]="你炼丹时记错了两道药材的投放顺序，不小心炸了丹炉，耳鸣了三日才恢复。",
[1863]="你研究一个丹方多年，始终没能摸透关窍。正当你愁眉不展时，碰上师父心情大好，指点了你一二，令你茅塞顿开。",
[1864]="你对炼丹炉火的掌控愈发得心应手，不再隔三差五出现浪费灵药的情况。",
[1865]="你随师姐下山采买，看着师姐熟练地讨价还价，以低价采买到足够的物资，再从中昧下几枚灵石作为自己的私房钱。目瞪口呆的你不忘暗中学习师姐的行事风格，收获不小。",
[1866]="今日不甚忙碌，你前往宗门后山准备捉一些小型的灵兽打打牙祭，意外发现了一棵被雷劈断的枯木树干中隐有火光。",
[1867]=" 这莫非就是传说中的木中火？你用粗浅的法诀将其保存在一个石匣内，带回去交给师父，师父高兴得赏了你一大批灵材。",
[1868]="你炼出的丹药品质稳定，药效很好，虽然只是些低级的灵丹，但还是受到不少同门弟子的欢迎。你的人缘也渐渐好了起来。",
[1869]="你用攒下的灵石给自己的丹炉刻了个小型的聚灵阵，炼丹时的灵气输送效果事半功倍，成丹数量竟多了不少。",
[1870]="你听闻宗门附近有一处散修筹办的集市，空闲时便好奇地前去看看。集市上的各种物品令人眼花缭乱，你算算家底，用一些积攒的成丹换到了少见的灵草，也算买卖如意。",
[1871]="你前往灵药园采摘灵草，发现一片土壤的色泽有些异样。为防万一，你叫来侍弄灵草的药仆告知此事。",
[1872]="对方仔细检查后，发现土壤里藏了几条最喜吞食灵草根茎的噬根虫。顺利将噬根虫清理掉的药仆多摘了十数颗灵草给你，以表谢意。",
[1873]="你在炼制一炉灵丹时不小心多放了一味灵药，却意外地没有炸炉。惊奇之下，你尝了一枚成丹，意外地发现这丹药所能补充的灵力虽然不及原本那般充裕，但起效却快了一倍。",
[1874]="你在宗门后山修炼时遇见了一只受伤的灵鹿幼崽，对方朝着你哀哀低鸣，看着小鹿隐含求助之意的水汪汪的双眼，你叹了口气，拿出随身携带的疗伤丹喂了它一颗。",
[1875]="药效很快发挥作用，不一会儿，小鹿就站起来欢快地叫了两声，像是示意你跟上它。你随之前行，小鹿竟带你来到了一棵成熟的朱果树前，你欣喜地摘下朱果吃了，灵气顿时充盈全身。",
[1876]="一日，你在炼丹时似有所感。炼成丹药后便回房打坐观想，竟入顿悟之境。日夜倏忽而逝，待你睁眼时，已至练气后期。",
[1877]="练气后期",
[1878]="日积月累，水到渠成。观想顿悟，你已至练气后期。",
[1879]="你之耳目更为敏锐，炼丹时能察觉到更为细微的变化，每一炉丹药的成丹率又有了显著的提高。",
[1880]="你开始指导一些新入门的师弟师妹如何分辨灵草，如何观察炼丹炉火……看着他们生涩地学习，你不禁感慨时间过得真快。",
[1881]="你成功炼制了一批辟谷丹，效果还不错，节省了许多时间用来修炼。",
[1882]="炼丹之外，你花了很多精力来打磨自己的心境，做事更显圆滑沉稳。",
[1883]="近日，宗门欲派弟子前往同盟宗派进行交流切磋。此行需耗费不少时日，你借机兜售起了辟谷丹和疗伤丹，弟子们纷纷购买，让你赚了一大笔灵石。",
[1884]="你筹划许久，终于凑齐了筑基丹所需的灵药。找了一个良辰吉日稳炉入药，你费尽心力，总算成功炼出了第一炉筑基丹。",
[1885]="你炼丹时愈发急躁，竟试图将不同的丹火融合转化。这一炉丹，你先后投入了两种丹火……嘭！丹炉炸了。",
[1886]="你炼丹的手法激进了许多，开始尝试各种偏方。这一炉丹，你加入了一种毒草的汁液……轰！丹炉内火焰一瞬间沸腾，超出你的控制，将一炉灵药烧成了黑灰。",
[1887]="你炼丹的手法激进了许多，开始尝试各种偏方。这一炉丹，你加入了晒干后碾碎的毒虫粉末，炼出的丹药色泽诡异，你面不改色地吞服了一颗……流了三天鼻血。",
[1888]="你炼丹的手法激进了许多，开始尝试各种偏方。这一炉丹，你加入了妖兽的兽角粉末，炼出的丹药散发出诡异的气味，你面不改色地吞服了一颗……耳鸣数日方歇。",
[1889]="你闭关炼丹的时间更久了。第一炉丹，你吞下一颗；第二炉丹，你吞下一颗；第三炉丹，你吞下……整整五十炉丹，你就试了五十次，被丹药撑得腹部绞痛，眼底爆出血丝，你也恍若不觉。",
[1890]="你在整理丹药库存时，偶然发现了一小瓶标记为“轻灵丹”的药瓶。传闻此丹可以暂时提升体内灵力的流转速度，使人能在短时间内掌握腾空飞行之术。这对你来说，无疑是极大的诱惑。于是你决定……？",
[1891]="巧遇轻灵丹",
[1892]="偷偷服用",
[1893]="就此作罢",
[1894]="偷吃灵丹",
[1895]="偷吃轻灵丹的你御风高飞，却忘了时效，狼狈摔死。",
[1896]="你终究抵挡不住诱惑，偷偷服用了几颗轻灵丹。一股温暖的气流在体内涌动，你感觉自己的身体变得异常轻盈。你赶紧来到宗门后山体验飞行，越飞越高，越飞越畅快，全然忘记药效时限，结果狼狈地直坠而下，摔死了。",
[1897]="日行亏心事，夜半鬼敲门……你这么想着，摇了摇头，将这药瓶放回了对应的位置，并未偷偷服用。",
[1898]="你与同门师兄弟下山历练，在一处深山密林中遇到邪修袭击。慌乱之下，大家各自逃散，你决定……？",
[1899]="邪修袭击",
[1900]="逃回宗门",
[1901]="隐匿躲藏",
[1902]="邪修拦路",
[1903]="下山历练，遭遇邪修，你在逃亡时被邪修拦截杀害。",
[1904]="深知邪修凶残的你决定赶紧返回宗门上报求助，不料在半途被成群的邪修拦截，最终惨死于邪修手下。",
[1905]="你小心翼翼藏匿山林中，而邪修发现有其他弟子逃往宗门踪迹，全部追了过去，你因此躲过一劫。",
[1906]="长老吩咐你前去打扫他的专用炼丹房，你发现房内有许多散乱在地的炼丹手札，应该都是长老亲笔记录的宝贵心得。非常渴望翻阅这些手札的你决定……？",
[1907]="炼丹手札",
[1908]="偷偷翻看",
[1909]="老实整理",
[1910]="偷看手札",
[1911]="你趁打扫时偷看长老的炼丹手札，被长老斩杀。",
[1912]="你通过长老的炼丹手札学习经验，修为有所进步。",
[1913]="你趁着四下无人，偷偷翻开手札时触动了长老留下的禁制。长老很快赶回，大怒之下将你直接斩杀。",
[1914]="你按捺下想偷看的心思，老实打扫房间，整理散乱的手札。长老检查之后对你甚是满意，允许你翻阅手札学习经验，当作奖赏。你因此收获不小，不仅在炼丹一道有了明显进步，修为也有所进步。",
[1915]="你跟随同门前去参加一个由各大宗门联办的炼丹大会。这等盛事，天才辈出，你想要突围得胜，寻常手段肯定无用。于是你决定……？",
[1916]="炼丹大会",
[1917]="稳中求胜",
[1918]="险中求胜",
[1919]="技不如人",
[1920]="你前去参加炼丹大会，技不如人，未能胜出。",
[1921]="你前去参加炼丹大会，险中求胜，拔得头筹。",
[1922]="你沉心静气，炼制了一炉你最为擅长的丹药。最后发挥不错，你炼成的丹药为中上品，奈何有别宗弟子炼制出极品丹药，拔得头筹。你眼睁睁看着那名获胜者拿到了神秘丹方，被众人夸赞，怨恨和不甘悄悄滋长，没人留意到你咬紧了牙关。回宗之后，你开始疯狂炼丹。",
[1923]="你决定炼制一种非常偏门的丹药。虽然冒险，但你竟然成功了！你炼出了一枚只差些许就能达到极品的上品成丹，又因丹方冷僻，你顺利获得了此次炼药大会的神秘丹方作为奖励。",
[1924]="同宗的一位剑修师兄找到你，因为听闻你炼的丹药品质稳定，所以希望能跟你换取足量的各类常用丹药，用于备战之后的宗门比武。剑修师兄诚意十足，强调了数遍但凡他能提供的，都会满足你。你决定……？",
[1925]="丹药交换",
[1926]="换取功法",
[1927]="换取剑符",
[1928]="你心中一直向往剑道，因此毫不犹豫地与师兄换了一本入门剑诀功法。不料你实在是没有学剑的天赋，在师兄的指点下也未见丝毫进步。",
[1929]="你思忖自己似乎比较缺乏保命的手段，便与师兄交换了一些强力的剑符。这些剑符在外出历练时果然用处很大，其内蕴含的剑气帮你斩杀了不少妖兽和宵小，保住了你的小命。",
[1930]="你察觉到了进阶的契机，又慎重地将心境打磨得更加圆满。做完诸多准备，再三检查过后，你决定……？",
[1931]="借丹药突破",
[1932]="靠自己突破",
[1933]="你拿出了自己炼制的筑基丹，在准备进阶时服用。丹药效果很好，你平稳地成功突破至筑基期，但冥冥中总觉得似乎很难再进一步。",
[1934]="修行当与天争！你决定不依靠外力，凭自己的实力进阶。一层层打通关窍，努力、再努力……不妙！体内的灵气突然不受控制地开始逆行，你哇地吐出一口血，突破失败……眼前渐渐黑暗……",
[1935]="一个丹炉，熬化了药材，也熬尽了你的寿元。你不过初窥修行的门道，却再也无法继续漫漫仙途。",
[1936]="在炼丹大会的失利令你耿耿于怀，心魔渐深。你从此闭关炼丹，不惜以身试丹，最终竟因丹毒淤积体内而暴毙身亡。",
[1937]="心魔渐深",
[1938]="炼丹大会失利令你心魔渐深，最终因丹毒而亡。",
[1939]="大会结束后，你也踏上了返回宗门之路。途中在一处城镇稍作休整时，一群蒙面人围堵到了落单的你……最后，你倒在血泊中，眼睁睁地看着他们夺走了你的奖励丹方……",
[1940]="怀璧其罪",
[1941]="取胜的你，却因奖励丹方而遇袭，因此身亡。",
[1942]="宗门地处太岳山脉之中，进入宗门之后，你接受了一系列的入门考验，测灵根，评心性，观悟性……最后成为了一名外门弟子。",
[1943]="在外门弟子居的住所内，你成功练气运行一个周天之后，感觉身体一轻，一股生机由内而外地散发开来，容光焕发得就像回到了年轻时一样，这令你很是欣喜。",
[1944]="初入宗门，考验过后，你成为了一名外门弟子。",
[1945]="宗门位于天云洲一隅，进入宗门之后，你接受了一系列的入门考验，测灵根，评心性，观悟性……最后成为了一名外门弟子。",
[1946]="宗门地处南疆一隅，进入宗门之后，你接受了一系列的入门考验，测灵根，评心性，观悟性……最后成为了一名外门弟子。",
[1947]="宗门位于天山深处，进入宗门之后，你接受了一系列的入门考验，测灵根，评心性，观悟性……最后成为了一名外门弟子。",
[1948]="你多方打探，长途跋涉，终于在太岳山脉腹地寻到一处仙宗。",
[1949]="在山门处叩拜许久后，你运气不错，被一位内门师兄领进宗门，然后经历了一系列的入门考验，测灵根，评心性，观悟性……最后成为了一名外门弟子。",
[1950]="寻觅许久，得偿所愿，你成为了仙宗的一名外门弟子。",
[1951]="你多方打探，长途跋涉，终于在天云洲内寻到一处仙宗。",
[1952]="你多方打探，长途跋涉，终于在南疆一隅寻到一处仙宗。",
[1953]="穿过层层迷瘴之后，你运气不错，被一位内门师兄领进宗门，然后经历了一系列的入门考验，测灵根，评心性，观悟性……最后成为了一名外门弟子。",
[1954]="你多方打探，长途跋涉，终于在天山深处寻到一处仙宗。",
[1955]="在风雪中坚持了许久后，你运气不错，被一位内门师兄领进宗门，然后经历了一系列的入门考验，测灵根，评心性，观悟性……最后成为了一名外门弟子。",
[1956]="安顿下来后，你前往外门的管事长老处报道。长老轻描淡写地瞥了你一眼，你却仿佛从头到脚都被看透了似的。",
[1957]="对方摸出两枚令牌：“以你的资质，这两个地方的差事倒是都能试着做一做，你自己选一个罢。”你看着摊在眼前的两枚令牌，决定……？",
[1958]="副职选择",
[1959]="去炼丹堂",
[1960]="侍弄灵田",
[1961]="外门杂务",
[1962]="你领了炼丹堂的杂务令牌，也可学习炼丹。",
[1963]="你领了侍弄灵田的杂务令牌，决定和灵植打交道。",
[1964]="丹药何等重要！要是成了炼丹大师，那岂不是能被供起来？你这么想着，决定领了炼丹堂的杂务令牌，也能学一学炼丹。",
[1965]="侍弄灵田只需与灵植打交道，不用与人交流太多，倒是个闲差，也能抽出更多时间修炼。你想了想，决定领了灵田的杂务令牌，去侍弄灵田。",
[1966]="去炼器坊",
[1967]="去符箓坊",
[1968]="你领了炼器坊的杂务令牌，也可学习炼器。",
[1969]="你领了符箓坊的杂务令牌，顺便学习绘制符箓。",
[1970]="灵器法宝何等重要！要是成了炼器大师，那岂不是能被供起来？你这么想着，决定领了炼器坊的杂务令牌，也能学一学炼器。",
[1971]="符箓一道虽是左道旁门，却也十分精深，能学有所成亦有奇效。你这么想着，决定领了符箓坊的杂务令牌，也能学习绘制符箓。",
[1972]="结丹已成，可称一声金丹真人！仙宗对结丹弟子亦有奖赏，你由此晋升为内门弟子，更可择一内门长老拜为师尊……",
[1973]="一系列的变动赏赐让你忙碌了好一阵，才算是在内门安顿下来，也总算有了自己的师父。",
[1974]="内门弟子",
[1975]="结丹已成，你晋升为内门弟子，有了自己的师尊。",
[1976]="你的师父在宗门内颇负盛名，不仅剑道修为高深，亦精通多种术法。",
[1977]="在你恭敬行完拜师礼之后，他认真将你打量了一番，开口道：“为师可授你剑法，亦可授你术法。以你的资质切莫贪多，择其一即可，你意如何？”你听完师父此言，决定……？",
[1978]="当个剑修",
[1979]="当个法修",
[1980]="成为剑修",
[1981]="成为法修",
[1982]="师尊在上，授你剑诀，你成为了一名剑修。",
[1983]="师尊在上，授你术法，你成为了一名法修。",
[1984]="想到当年在外门看到的那些踏剑飞行的师兄师姐，你毫不犹豫地选择了当个剑修。仗剑而行，以剑证道，正是你之所求！师父看你决心已定，便赐你灵剑一柄，再传授了你心法和几部剑诀，命你好生参悟。",
[1985]="在外门时你也对各类旁门有所了解，符箓灵器皆能使用一二，如果能获得一门精妙法诀潜心钻研，定能有所成就。你决心当个法修，师父便再仔细探了探你的根基，然后给了你一件灵器，再传授了你一门金行术法和相契合的心法，命你好生参悟。",
[1986]="在外门时你也对各类旁门有所了解，符箓灵器皆能使用一二，如果能获得一门精妙法诀潜心钻研，定能有所成就。你决心当个法修，师父便再仔细探了探你的根基，然后给了你一件灵器，再传授了你一门木行术法和相契合的心法，命你好生参悟。",
[1987]="在外门时你也对各类旁门有所了解，符箓灵器皆能使用一二，如果能获得一门精妙法诀潜心钻研，定能有所成就。你决心当个法修，师父便再仔细探了探你的根基，然后给了你一件灵器，再传授了你一门水行术法和相契合的心法，命你好生参悟。",
[1988]="在外门时你也对各类旁门有所了解，符箓灵器皆能使用一二，如果能获得一门精妙法诀潜心钻研，定能有所成就。你决心当个法修，师父便再仔细探了探你的根基，然后给了你一件灵器，再传授了你一门火行术法和相契合的心法，命你好生参悟。",
[1989]="在外门时你也对各类旁门有所了解，符箓灵器皆能使用一二，如果能获得一门精妙法诀潜心钻研，定能有所成就。你决心当个法修，师父便再仔细探了探你的根基，然后给了你一件灵器，再传授了你一门土行术法和相契合的心法，命你好生参悟。",
[1990]="逝水流年，你对剑道的钻研已有小成，修为却仅有寸进。",
[1991]="你欲请师父解惑，师父却语重心长地对你说道：“修行一途，道阻且长，闭门参悟终有所限。",
[1992]="天地广阔，纵不能一一踏遍，亦可四处游历一番，开拓眼界的同时也可磨砺心境，有助于探求己身之道。”师父之言令你陷入沉思，考虑许久之后，你决定……？",
[1993]="留在宗门",
[1994]="外出游历",
[1995]="宗门庇护令你安心，你决定留在宗门内修行。",
[1996]="天地之大，你决定外出游历，寻找自己的机遇。",
[1997]="虽然世间繁华令人向往，但你自忖修为尚浅，在宗门的庇护之下方能安心修炼，你最终还是决定留在宗门。",
[1998]="既踏仙途，自当无畏而前！世间或许危机四伏，但焉知是祸非福？说不定另有造化亦未可知。你做好准备后，便离开了宗门外出游历，寻找自己的机遇。",
[1999]="逝水流年，你对术法的钻研已有小成，修为却仅有寸进。",
[2000]="化神修士，无一不是一方大能！你已进阶化神期，仙宗发下不少赏赐，更许你独辟一座灵峰用作修行……",
[2001]="一系列的赏赐让你忙碌了好一阵，细细感受着独属于自己的灵峰灵脉，无数资源，顿时令你喜上眉梢。",
[2002]="独辟灵峰",
[2003]="在宗门内，化神修士可独辟灵峰修行，你拥有了无数资源。",
[2004]="赏赐先至，数日之后，你将灵峰拾掇妥当之际，宗主遣一分身飘然而至，对你开口道：“修行有成，既得赏赐，亦需承担宗门责任。",
[2005]="长老之职",
[2006]="如今宗内长老之职有所空缺，你可择一出任，修行之外，当为宗门效力。”你看向宗主分身手中摊开的令牌，决定……？",
[2007]="出任接引长老",
[2008]="出任传功长老",
[2009]="宗门长老",
[2010]="宗主看重，自当作为。你出任宗门接引长老一职。",
[2011]="宗主看重，自当作为。你出任宗门传功长老一职。",
[2012]="宗门根基，尽在传承。能为宗门选拔潜力弟子，何乐不为？你接下一枚令牌，决定出任宗门的接引长老一职。",
[2013]="宗门根基，尽在传承。督促优秀弟子潜修，责无旁贷！你接下一枚令牌，决定出任宗门的传功长老一职。",
[2014]="出任戒律长老",
[2015]="出任镇狱长老",
[2016]="宗主看重，自当作为。你出任宗门戒律长老一职。",
[2017]="宗主看重，自当作为。你出任宗门镇狱长老一职。",
[2018]="赏罚分明，宗门才能肃清蛀虫，得以传承。戒律在手，职责在心，你接下一枚令牌，决定出任宗门的戒律长老一职。",
[2019]="防患于未然，施以雷霆手段方能震慑宵小，保宗门根基。牢狱森严，职责在心，你接下一枚令牌，决定出任宗门的镇狱长老一职。",
[2020]="外门弟子每天都要扎一个时辰的马步打基础，你偶尔会偷懒，直到有一次被巡查的长老发现……你每天扎马步的时间变成了两个时辰。",
[2021]="<color=#3375c0>[聪慧判定]</color> 修行之余，在每月中旬左右，你都抽空会前往宗门的藏经阁阅读典籍。",
[2022]="<color=#549327>[判定成功]</color> 虽然典籍上的内容有许多都十分晦涩，但沉下心来仔细研究，读懂之后的你正如拨云见日，获益匪浅。",
[2023]="<color=#c82c2c>[判定失败]</color> 但以你如今的修为和悟性，十有八九都看不懂……这些典籍所载的内容晦涩又精深，时常让你有一种深深的无力感。",
[2024]="你每天准时去外门的公厨吃饭，因为未辟谷的弟子不多，公厨颇为冷清，所以掌勺师傅很是热情，天天都给你舀满一大碗灵米和不同的肉菜，让你吃得十分痛快。",
[2025]="每天清晨和睡前，你都会静心打坐吐纳一番。日积月累，心境和修为皆有所提升。",
[2026]="虽然现在修习的心法只是普通的入门心法，但你不曾懈怠，每天都勤勉练习。你渐渐发现，随着对心法的体悟加深，修行时便越能事半功倍，修为增进愈加明显。",
[2027]="整日做些琐碎杂事，你渐渐觉得枯燥乏味。打扫院落时看到内门的师兄师姐们踏剑飞过山头，你的心情……？",
[2028]="期待兴奋",
[2029]="失落不甘",
[2030]="你想着日后学有所成，入得内门，当也能做名剑修，踏剑高飞……你不禁心头火热，一时间打扫院落的动作都加快了几分。",
[2031]="对比之下，每日都在外门做些杂事的自己，不知何时才能修行有成……你这么想着，越发失落不甘，决心要更加努力修炼，提升修为。",
[2032]="宗门每旬都会有不同的长老讲道，只要有空闲，你都会前去听道。虽然只能听懂很少的一部分，但依然令你受益匪浅。",
[2033]="你在宗门后山发现了一个隐秘的山洞，里面有一潭小小的灵泉，对修炼大有益处，你时常来此借灵泉修炼。",
[2034]="一次打坐吐纳时，你机缘巧合进入顿悟之境。日夜飞逝，待你从顿悟之境悠然醒转的那一刻，已至{0}。",
[2035]="练气圆满",
[2036]="借灵泉修炼，机缘巧合，打坐顿悟，你已至练气圆满。",
[2037]="长老在炼丹房里待了三日三夜都不曾出来，你非常好奇，打开门缝偷偷观望，意外掌握了一些炼丹控火的窍门。",
[2038]="此后炼丹时，偶尔一炉里能多出几枚成丹，被你悄悄昧下来充作私房，积少成多，也能换得一些合用的资源。",
[2039]="你炼丹时不小心打了个喷嚏，导致平衡打破，最终一批炼丹的灵药全部浪费，没能按时上交足额的丹药，被长老扣了一个月的俸禄。",
[2040]="<color=#3375c0>[机缘判定]</color> 风和日丽，诸事皆宜。你终于用自己的小丹炉成功炼制出一炉凝气丹。",
[2041]="<color=#549327>[判定成功]</color> 丹药品质意外地好，你服用之后打坐运功，修为果然有所提升。",
[2042]="<color=#c82c2c>[判定失败]</color> 虽然丹药品相平平，但总算有点起色，令你更有动力钻研炼丹一道。",
[2043]="长老叫你顾守丹炉，但这日你实在疲惫，心思涣散，小鸡啄米似地打着盹……再睁眼时，药材已在丹炉中化作一片焦黑。长老大发雷霆，亲自动手将你揍得两个月下不了床。",
[2044]="研究了新的丹方月余，你准备尝试炼一炉云露丹，用来提升自己的修为。眼见火候正好，到了投放灵药的时候，你决定……？",
[2045]="先放寒露草",
[2046]="先放火云草",
[2047]="寒露草属阴，在丹火中慢慢融化，你接着放入火云草中和药性……一炉云露丹顺利炼成，品相不错，你服用过后顿觉灵力充盈全身，连忙打坐闭关。出关时，修为大进。",
[2048]="火云草属阳，丹火沸腾不休……不好！只听得“嘭”一声巨响，你没能控制住火候，炸了丹炉，耳鸣了三日才恢复。",
[2049]="<color=#3375c0>[聪慧判定]</color> 宗门将要举办炼丹大会，诸多弟子都跃跃欲试，你也是其中之一，为此认真准备了许久。",
[2050]="<color=#549327>[判定成功]</color> 到了炼丹大会当天，你顺利闯过三轮，虽然止步于第四轮，但也得到了一些奖励的资源。凭借这些资源，你之修为又进一步。",
[2051]="<color=#c82c2c>[判定失败]</color> 不料在炼丹大会的当天，信心满满的你第一轮就被刷了下来。你不禁怀疑，难道自己真的没什么天分？",
[2052]="宗门有令，敌对仙宗战帖已下，全宗备战！大战在即，宗门上下都十分忙碌，炼丹堂亦不例外……",
[2053]="因炼丹堂需要准备许多疗伤丹药，连你在内的诸多弟子都忙得几近废寝忘食。",
[2054]="虽然十分辛苦，但你炼丹的手法娴熟了许多，不仅炼出的丹药品质更为稳定，连日的灵力极限运转之下，修为也有所提升。",
[2055]="各种灵草的习性不同，你要按时给喜欢湿润的多浇水，喜欢干燥的多松土；出太阳了要挡住喜阴的，下雨了要遮住向阳的……令你有些手忙脚乱。",
[2056]="采摘灵草时，由于你粗心大意，导致灵草的根叶被挖断，被长老扣了一个月的俸禄。",
[2057]="<color=#3375c0>[魅力判定]</color> 你来到宗门的庶务殿，想要用积攒多时的宗门贡献点数兑换一瓶凝气丹。不料你的贡献点却偏偏差了几点，",
[2058]="<color=#549327>[判定成功]</color> 今日当值的长老虽然是出了名的铁面无私，但他时常去灵田取药，也算相熟，你总会机灵卖乖地给对方摘成色更好的灵药。",
[2059]="对方瞧见是你，便不动声色地勾了你的贡献点，将一瓶凝气丹放到了你手中。你拿着这瓶丹药回到住处服用修炼，修为有所提升。",
[2060]="<color=#c82c2c>[判定失败]</color> 今日当值的长老又是出了名的铁面无私，冷漠地拒绝了你的兑换，你只能垂头丧气地离开了庶务殿。",
[2061]="灵谷成熟期时，你天天忙着收割清点，再运到仓库保存。如此忙碌了一旬有余，总算是告一段落，你的耐力和修为都有所提升。",
[2062]="你在给灵田松土时，发现一片土壤的色泽有些异样。你决定……？",
[2063]="仔细检查",
[2064]="随意检查",
[2065]="为防万一，你极为仔细地来回检查了三次，果然在土壤里揪出了几条最喜吞食灵草根茎的噬根虫，连忙将它们彻底清理干净。将此事上报后，长老颇为满意，给了你几粒云露丹作为奖励。你拿着丹药回到住处服用修炼，修为大进。",
[2066]="快到时辰吃饭了，你一心想着去公厨吃东西，随意检查了一遍就离开了。之后这片灵田的幼苗根茎被噬根虫啃食了大半，损失不小。长老因此大发雷霆，扣了你半年的俸禄不算，更罚你在灵田守田一年，吃住都在田边，不得回弟子居休息。",
[2067]="在侍弄灵田之余，你还时常抱着一本《灵草图鉴》翻来覆去地翻阅背诵，争取将各类灵草灵药熟记下来，尽量掌握它们的功效和用途。",
[2068]="宗门有令，敌对仙宗战帖已下，全宗备战！大战在即，宗门上下都十分忙碌，侍弄灵田的弟子亦不例外……",
[2069]="炼丹堂那边需要大量的灵草灵药炼丹，长老为此在灵田布下催生阵法，弟子们每天都需要采集大量灵草。",
[2070]="你为此忙碌半月有余，虽然辛苦，但对于灵力的运用有所提升，修炼的速度也加快了许多。",
[2071]="长老在炼器坊打造一批灵器，命你在一旁侍候，打个下手，你趁机多看多学，顺利掌握了一些控火炼器的窍门。",
[2072]="此后你在炼器时，效率提高了不少，能剩下更多时间用于修炼，修为有所提升。",
[2073]="你在熔炼玄铁的过程中不小心把火烧得太旺，火舌蹿起时躲闪不及，被燎掉了半条眉毛和一大把头发，虽然万幸没有受伤，但还是因此被炼器坊的其他弟子取笑了很久。",
[2074]="风和日丽，诸事皆宜，你终于成功打造出了一把下品灵剑。虽然在灵器之中，这只是一把无法镶嵌法阵的最普通的剑，但你还是十分开心。",
[2075]="昨夜没有睡好，你炼器时心思涣散，脑袋空空……回过神时，一柄剑胚已经被熔化，根本看不出原型，气得你去公厨多吃了三碗饭。",
[2076]="打扫库房时，你在陈列架上发现了一对漂亮的子母刀，于是决定……？",
[2077]="仔细端详",
[2078]="谨慎对待",
[2079]="你正打算拿起来仔细查看一番，不料这对子母刀锋利无匹，散发的锐气差点把你的手指头削掉。你心有余悸地逃回弟子居上药，半个月没敢再进库房。",
[2080]="这对子母刀应该锋利无匹，还是不要贸然触碰的好。你只站在原地谨慎地多看了几眼，便继续打扫库房了。",
[2081]="你奉命前去山下接收一批矿石，交接时你仔细清点数量，核对无误后及时将这批矿石带回，按时入库。",
[2082]="长老对此颇为满意，给了你不少灵石作为奖励。你开心地用这灵石买了些成色很不错的丹药，闭关修行数日，成为了一位{0}修士。",
[2083]="宗门有令，敌对仙宗战帖已下，全宗备战！大战在即，宗门上下都十分忙碌，炼器坊亦不例外……",
[2084]="因炼器坊需要打造诸多灵器，连你在内的诸多弟子都忙得几近废寝忘食。",
[2085]="虽然十分辛苦，但你炼器的手法娴熟了许多，不仅炼出的灵器品质更好，连日的灵力极限运转之下，修为也有所提升。",
[2086]="清晨，你把库房里积存的符纸拿到院子里清点数量顺便除尘，然而吃个午饭的功夫，你就忘了将符纸收回库房……",
[2087]="下午天降大雨，把大量符纸淋湿，长老大怒，扣了你三个月的俸禄。",
[2088]="你时常抱着一本《符箓通鉴》翻来覆去地研究，争取记住每一种符文的形状和绘制顺序。",
[2089]="你与其他弟子一起练习绘符，极为专注的你十分努力，一个下午绘制了百张清心符。长老检查时，你骄傲地交了上去，结果百张里只有一张能用。",
[2090]="于是你每日都要比旁人多画一个时辰的符作为练习，日积月累之下，你绘制的清心符品质越来越好，对灵力的运用也有了更深刻的认知，对修行亦有帮助，修为提升了不少。",
[2091]="你练习许久，终于能够控制灵力完整地绘制出一张敛息符。趁着夜色，你跃跃欲试地给自己贴上敛息符，准备去……？",
[2092]="宗门大殿",
[2093]="宗门后山",
[2094]="你决定宗门大殿逛一圈，不料刚走到大殿外，就被巡夜的师兄给拦了下来。这符竟然不到半刻就失效了，你在师兄有些迷惑的目光注视下，垂头丧气地折身朝自己的房间飘去。",
[2095]="你决定去宗门后山逛一圈，夜风习习，你的心情畅快不已，更在后山发现了一批成色很好的灵草，通通收入囊中。之后，你将灵草换成了合用的丹药，服用丹药修行之后，修为大进。",
[2096]="你拿着几张御火符来到宗门后山，找了棵枯树准备试一试这符的威力。",
[2097]="你抬手扬符，默念口诀之后大喝一声，将符掷向枯树……一朵乌云凭空出现，水从天降，“哗啦”一声将你淋成了落汤鸡。\n",
[2098]="这御火符怎么就成了御水符呢？你黑着脸往回走，回想自己绘制符箓的过程，百思不得其解……",
[2099]="论剑台每日都有剑修弟子切磋比剑，你时常带着一叠回春符过去，但凡哪位在论剑时不慎受伤，你就上前快速贴符，看看是否能正常起到治愈功效……",
[2100]="时间长了，回春符倒是被你练得挺熟，也因此结识了一些同门好友。",
[2101]="宗门有令，敌对仙宗战帖已下，全宗备战！大战在即，宗门上下都十分忙碌，符箓坊亦不例外……",
[2102]="符箓坊需要准备大量攻防相关的符箓，连你在内的诸多弟子都忙得几近废寝忘食。",
[2103]="虽然十分辛苦，但你绘符的手法娴熟了许多，不禁绘制的符箓品质更好，连日的灵力极限运转之下，修为也有所提升。",
[2104]="你静心凝神，运笔如飞……！终于，你成功绘制出了一张品质不错的聚灵符，符文灵光湛湛，静静躺在你眼前。此回绘符令你隐隐有所明悟，当即闭关。三日后出关时，修为大涨。",
[2105]="你察觉到了进阶的契机，又慎重地将心境打磨得更加圆满。做完诸多准备后，你决定……？",
[2106]="闭关进阶 [潜力判定]",
[2107]="再等一等",
[2108]="进阶筑基",
[2109]="进阶失败",
[2110]="不欲进阶",
[2111]="日积月累，一举突破。你顺利进阶至筑基期。",
[2112]="闭关进阶，功亏一篑。你筑基失败，反受重伤。",
[2113]="突破筑基的契机已至，但你未做好准备，不欲进阶。",
[2114]="<color=#549327>[判定成功]</color> 修行当与天争！你决定闭关突破。一层层打通体内关窍，努力坚持，额上渗出了细汗……终于，你长吁一口气，已成功进阶至筑基期，感觉自身的灵力发生了显著的变化，凝实了许多。",
[2115]="<color=#c82c2c>[判定失败]</color> 修行当与天争！你决定闭关突破。一层层打通关窍，努力、再努力……糟了！体内的灵气突然不受控制地开始逆行，你哇地吐出一口血，被筑基失败的反噬震成重伤，只能一边休养一边等待下一个进阶的契机……",
[2116]="修行之路，万般谨慎亦不为过。你心中忐忑，想了许久，还是决定再等一等，何时准备万全，又遇契机之时，再一举突破吧。",
[2117]="与敌对仙宗之大战旷日持久，终至胜负已分。你的宗门略胜一筹，敌对宗门则因此伤筋动骨，相当长的一段时间内不敢再犯，更向你宗上交了不少资源作为赔礼。",
[2118]="宗门上下喜气洋洋，发下不少赏赐，你也领到了一些奖励的修炼资源。闭关修行数年，修为有所提升。",
[2119]="<color=#3375c0>[资质判定]</color> 到了外门弟子的修行考校之日，你信心满满……",
[2120]="<color=#549327>[判定成功]</color> 结果发挥失常，只拿了个倒数第二。气得你决定每天多花两个时辰运行心法，打坐吐纳。日积月累之下，修为有所提升。",
[2121]="<color=#c82c2c>[判定失败]</color> 果然发挥得很不错，拿了个第二的好名次。诸多同门过来恭喜你，你亦谦虚还礼，可谓是其乐融融。",
[2122]="你在宗门后山修炼时遇见了一只受伤的灵鹿幼崽，对方朝着你哀哀低鸣，看着小鹿隐含求助之意的水汪汪的双眼，你叹了口气，拿出自己珍藏的疗伤丹喂了它一颗。",
[2123]="不愧是价值数百灵石的灵丹，不一会儿，小鹿就站起来欢快地叫了两声，像是示意你跟上它。",
[2124]="你随之前行，小鹿竟带你来到了一棵成熟的灵树前，你欣喜地摘下朱红色的果子吃了，灵气顿时充盈全身，你的修为竟有所提升。",
[2125]="完成日常的各类杂务之余，你花了很多精力来打磨自己的心境，行事举止之间，更显圆滑沉稳。",
[2126]="长老开始给你指派一些接引新弟子的任务，你需要指引一些新入门的师弟师妹熟悉外门的日常事务，看着他们青涩的模样，你不禁想起了当初的自己，感慨时间过得真快。",
[2127]="除了努力打坐冥想、吸纳灵气之外，你不忘用积攒的私房钱换取了一些打熬体魄的资源，保证自己在疏通经脉的同时体魄也能跟上。",
[2128]="你听闻宗门附近有一处散修筹办的集市，空闲时便好奇地前去看看。",
[2129]="集市上的各种物品令人眼花缭乱，你算算家底，各种讨价还价之后，也算买卖如意，顺利弄到一些合用的资源。回到宗门后，你闭关修炼，有这些资源相助，修为有所提升。",
[2130]="你前往藏经阁翻阅典籍时，发现练气期无法理解的一些内容在筑基期竟如茅塞顿开一般……以典籍所载与己身所学相互印证，实是获益匪浅。再行修炼，修为大涨。",
[2131]="一日，你在打坐运行心法时似有所感，不禁更为沉浸地观想吐纳，竟入顿悟之境，灵气疯狂涌入你的体内，充盈全身。日夜倏忽而逝，待你睁眼时，已至{0}。",
[2132]="筑基圆满",
[2133]="日积月累，水到渠成。观想顿悟，你已至筑基圆满。",
[2134]="雨过天晴，你前往宗门后山，意外发现一些长得葱郁的野生灵草，药性不错，可用于炼丹。你悄悄地采摘了这批灵草，充作自己的私房炼丹材料。",
[2135]="你开始指导一些师弟师妹如何分辨灵草，如何观察炼丹炉火……看着他们生涩地学习，你不禁想起了当初的自己，顿时有些感慨。",
[2136]="你研究一个丹方多年，始终没能摸透关窍。正当你愁眉不展时，碰上长老心情大好，指点了你一二，令你茅塞顿开。你立刻开始尝试炼丹，果然顺利炼成，换回不少资源用于修炼，修为有所提升。",
[2137]="今日不甚忙碌，你前往宗门后山修行，意外发现了一棵被雷劈断的枯木树干中隐有火光。这莫非就是传说中的木中火？你决定……？",
[2138]="带回上交",
[2139]="自己私吞",
[2140]="你用粗浅的法诀将木中火保存在一个石匣内，带回去交给长老，长老高兴得赏了你一大批炼丹的灵药。你用这批灵药炼成的清尘丹品质很好，你果断将这批丹药用于自身修行，修为大涨。",
[2141]="你用粗浅的法诀将木中火保存在一个石匣内，带回去自己使用。不料粗浅的法诀无法长久地保存火种，你不得法门，无奈之下强行将之用于炼丹，只炼了一炉丹这火便燃尽了。所幸炼出的丹药品质很好，你用于自身修行，修为有所提升。",
[2142]="你对炼丹炉火的掌控愈发得心应手，不再隔三差五出现浪费灵药的情况，上交的丹药品质也越来越好，令长老对你赞赏有加。",
[2143]="你炼出的丹药品质稳定，药效很好，受到不少同门弟子的欢迎，你的人缘也渐渐好了起来。",
[2144]="你用攒下的灵石给自己的丹炉刻了个小型的聚灵阵，炼丹时的灵气输送效果事半功倍，节省了不少时间用于修炼。",
[2145]="<color=#3375c0>[概率判定]</color> 你在炼制一炉灵丹时不小心多放了一味灵药，却意外地没有炸炉。惊奇之下，你尝了一枚成丹……",
[2146]="<color=#549327>[判定成功]</color> 意外地发现这丹药所能补充的灵力虽然不及原本那般充裕，但起效却快了一倍。明白效用之后你果断炼制了一批此类丹药拿去兜售，收益颇丰。",
[2147]="<color=#c82c2c>[判定失败]</color> 刚咽下去一会，你便腹痛如绞，直冲茅房……灵丹变作毒丹，你拉稀拉了三日，事后想起时都脸色发白。",
[2148]="你的耳目更为敏锐，炼丹时能察觉到更为细微的变化，每一炉丹药的成丹率又有了显著的提高。多出来的丹药被你留下用于自身修行，修为有所提升。",
[2149]="你已经能够熟记每种灵植的生长偏好和成熟期，使用布雨诀浇灌灵田时也更加游刃有余。经你打理的灵田，灵植长势都很不错，长老因此对你赞赏有加。",
[2150]="灵田所在的位置颇为偏僻，很少有人打扰。你喜欢在灵田旁边的一棵参天古树下打坐吐纳，偶尔有灵雀在树枝上歇息，甚至落在你的肩头停留一会儿，发出清脆的啾鸣，让人心情愉悦。",
[2151]="在这样的环境下运功修行，你隐隐有了一丝天人合一的明悟，心境和修为都有所提升。",
[2152]="你对灵力的掌控愈发得心应手，灵植成熟时可以操控灵力进行快速的大面积收割，效率提高了许多，省下不少时间用于修炼，修为有所提升。",
[2153]="你前往宗门后山修行时，在一棵大树下发现一棵有些特别的草，你决定……？",
[2154]="将它拔起",
[2155]="暗中观察",
[2156]="你走上前去，正准备把它拔出来研究时，这草竟然在你眼皮子底下消失了。你顿时有些懊恼自己太过大意，但也只能作罢。",
[2157]="你暗中观察了一会，最终确定这是棵开了灵智的野生灵药，这才掐着法诀上前布下禁制，果然顺利将灵药拔出。回去之后，你将这灵药上交给了长老，长老高兴得赏了你一瓶清尘丹，你拿着丹药闭关修行，修为有所提升。",
[2158]="在长老的指点下，你成功调整了灵田四周的聚灵阵，确保灵气能够更有针对性地供应到不同的灵田中，促进灵植生长。灵植的收成因此变得更好，你也顺利换取了更多资源用于修行。",
[2159]="灵草灵药与炼丹密不可分，你与炼丹堂的弟子接触频繁，多有往来，因此趁机学了几手粗浅的炼丹手法。",
[2160]="随着境界修为的提高，你控火的能力也进步了许多，熔炼矿石的效率提高了不少，省下更多的时间用于修行。",
[2161]="你开始指导一些师弟师妹如何分辨、熔炼矿石，如何控火……看着他们生涩地学习，你不禁想起了当初的自己，顿时有些感慨。",
[2162]="今日不甚忙碌，你前往宗门后山修行，在一个山洞中休息时，发现身后靠着的是一块中空的石壁。你小心翼翼地将石壁凿开，发现其中有一缕柔弱的火苗静静地燃烧着，这莫非就是传说中的石中火？你决定……？",
[2163]="你用粗浅的法诀将石中火保存在一个石匣内，带回去交给长老，长老高兴得赏了你一大批炼器的资源。你用这批资源炼出了几件品质很不错的灵器，拿去换到了很好的丹药用于修行，修为大涨。",
[2164]="你用粗浅的法诀将木中火保存在一个石匣内，带回去自己使用。不料粗浅的法诀无法长久地保存火种，你不得法门，无奈之下强行将之用于炼器，只炼出了一件灵器便燃尽了。所幸炼出的灵器品质很好，你果断把这灵器留着给自己防身。",
[2165]="你研究一道炼器法诀许久，始终没能摸透关窍。正当你愁眉不展时，碰上长老心情大好，指点了你一二，令你茅塞顿开。你立刻开始尝试炼器，果然顺利炼成，换回不少资源用于修炼，修为有所提升。",
[2166]="你对灵力的掌控愈发得心应手，炼器时，已经能将一些低级的法阵一气呵成地篆刻在灵器上，大大提高了灵器的威力。",
[2167]="炼器坊的弟子们时常聚在一起交流心得，你也积极参与。大家轮流抛出问题，提出可行之法，互相查漏补缺……一番讨论下来，众人都获益匪浅，关系也亲近不少。",
[2168]="随着境界修为的提高，你对灵力的控制愈发细致，绘制普通符箓时可以确保灵力平衡一气呵成，基本能够不再毁符，省下更多的时间用于修行。",
[2169]="风和日丽，诸事皆宜。你终于成功绘制出第一枚玉符，虽然只是低级的玉符，但也比纸符难了百倍不止，令你十分开心。",
[2170]="符箓坊的弟子们时常聚在一起交流心得，你也积极参与。大家轮流抛出问题，提出可行之法，互相查漏补缺……一番讨论下来，众人都获益匪浅，关系也亲近不少。",
[2171]="你绘制的符箓品质稳定，时效较长。虽然只是些普通的纸符，但还是受到不少同门弟子的欢迎。你的人缘也渐渐好了起来。",
[2172]="前往宗门后山修行时，你祭出的御火符和御水符指哪打哪，再也没有闹出过练气期的笑话。一些小型灵兽在你的符箓攻击下堪称手到擒来，这些灵兽对修行好处多多，你决定……？",
[2173]="打打牙祭",
[2174]="换取资源",
[2175]="你将灵兽稍作处理，决定拿来打打牙祭。食用之后，一股精纯的灵力在体内散开，你连忙闭关修炼将之消化，修为大涨。",
[2176]="你决定把处理后的灵兽拿去换取修炼的资源用于自身修行，修为有所提升。",
[2177]="你尝试将多个符箓组成符阵，殚精竭虑地研究了许久，始终没能摸透关窍。正当你愁眉不展时，碰上长老心情大好，指点了你一二，令你茅塞顿开。",
[2178]="你立刻再次尝试组成符阵，这次果然成功。成型的符阵威能提升许多，你拿这符阵换回不少合用的资源用于修炼，修为有所提升。",
[2179]="一日运功完毕，你突然察觉到了一丝玄而又玄的气息，想必这就是进阶结丹的契机。慎重地将心境打磨得更加圆满，做完诸多准备后，你决定……？",
[2180]="结丹已成",
[2181]="结丹失败",
[2182]="积累多年，闭关突破。你终于进阶至结丹期。",
[2183]="闭关进阶，功亏一篑。你结丹失败，反受重伤。",
[2184]="进阶结丹的契机已至，但你未做好准备，不欲突破。",
[2185]="<color=#549327>[判定成功]</color> 修行当与天争！你决定闭关突破。一层层打通体内关窍，努力坚持，额上渗出了细汗……轰！体内真元压缩到了极致，丹田骤然一空，正中之处，一粒浑圆金丹新凝而成，缓缓旋转起来……你长吁一口气，体内灵力由此发生了翻天覆地的变化，已成功进阶至结丹期。",
[2186]="<color=#c82c2c>[判定失败]</color> 修行当与天争！你决定闭关突破。一层层打通关窍，第一处，第二处……不妙！体内的灵气突然不受控制地开始逆行，你哇地吐出一口血，被结丹失败的反噬震成重伤，只能一边休养一边等待下一个进阶的契机……",
[2187]="<color=#3375c0>[资质判定]</color> 你用宗门贡献点换取了一口炼体药池的三日使用权，咬牙忍住了药池灵液的冲刷，抓紧时间打熬体魄……",
[2188]="<color=#549327>[判定成功]</color> 三日眨眼而过，你归还药池之后立刻闭关继续吸收灵液残余的功效，出关时，修为也有所增进。",
[2189]="<color=#c82c2c>[判定失败]</color> 然而药池功效过于猛烈，你仅仅打熬了一日便支撑不住离开了药池，连经脉都有所损伤。此回不仅浪费了不少贡献点，还需花费不少时日调养身体。",
[2190]="一位长老座下的师兄师姐在宗内举办道侣大典，你随师父前去参加祝贺。坐在席间，看着那对师兄师姐盛装打扮之下神仙眷侣、璧人成双的模样，不禁令你心生向往。",
[2191]="<color=#3375c0>[资质判定]</color> 一日，你与同门论道时，师父恰好经过，心情大好地点拨了你们几句……",
[2192]="<color=#549327>[判定成功]</color> 你顿觉云开雾散，连忙回房闭关体悟，出关时果然有所得，修为增进不少。",
[2193]="<color=#c82c2c>[判定失败]</color> 然而你还是觉得云里雾里的，回房后琢磨到后半夜也未能明悟，只得老实睡了一觉。",
[2194]="境界到了瓶颈期，你思来想去，最后决定前往内门庶务殿领取锁妖塔的通行令牌，准备进塔闯关磨练自己一番。",
[2195]="不料前几关就令你压力倍增，十关之后更是再也闯不过去。隔一段时日再去尝试也是同样的结果，在关卡内时常被妖兽逼迫得分外狼狈，令你懊恼不已。",
[2196]="你与外门公厨的掌勺师傅颇为投契，对方不知打哪儿弄来了几坛灵酒，邀你共饮。就着炙烤的灵兽肉，你们将灵酒喝了个精光。",
[2197]="<color=#3375c0>[潜力判定]</color> 大醉三天三夜的你因此误了宗门巡逻的任务，被当值长老告到你师父那里。你师父气得脸色铁青，罚你去面壁崖禁足思过，修为未有突破则不得解禁……",
[2198]="<color=#549327>[判定成功]</color> 你在面壁崖原地闭关，一心一意全力苦修……沉浸之中百年转瞬，金丹破，元婴生，你竟因祸得福，一举突破至元婴期。",
[2199]="元婴已成",
[2200]="在面壁崖思过苦修的你因祸得福，突破至元婴期。",
[2201]="<color=#c82c2c>[判定失败]</color> 你在面壁崖原地闭关，一心一意全力苦修……然而机缘缥缈，岂是苦修便能遇见的？",
[2202]="百年蹉跎，你仍未能更进一步。师父得知你苦修至此亦未能突破，终究心软下来，默默地解了你的禁足令，让你回到弟子居照常修行。",
[2203]="每日清晨起身，你不动用灵力，先认真劈剑千次，保证剑势准确。如此日积月累，你的剑道基础打得甚是扎实，得到了师父的夸赞。",
[2204]="<color=#3375c0>[资质判定]</color> 你梦见自己与人大战三百回合，刀光剑影之间，丝毫不落下风……",
[2205]="<color=#549327>[判定成功]</color> 第二日醒来时，你隐有所悟，当即闭关修行，出关时，修为又有进境。",
[2206]="<color=#c82c2c>[判定失败]</color> 第二日醒来时，你莫名觉得有些凉，睁眼一看，身上的被子竟被劈成了碎布，出鞘的剑就静静地躺在床下。",
[2207]="你时常与师兄师姐论剑，虽然输多胜少，但每次都得益不小。",
[2208]="今日大雨，电闪雷鸣，本欲去论剑台与同门切磋的你只能放弃……虽已辟谷，但反正闲来无事，你干脆躲在房里偷偷烤了只野兔吃，真香！",
[2209]="一日午后，你在尝试以气御剑的时候不小心手指一颤，那剑便扎到了师弟的屁股上……夕阳西下，两道你追我赶的身影终于停下了脚步。这一天，你被师弟追着绕宗门跑了三十圈。",
[2210]="<color=#3375c0>[资质判定]</color> 你沉浸在参悟道法的体悟之中，神识在虚空里蔓延无尽，几欲触探到天地的尽头……",
[2211]="<color=#549327>[判定成功]</color> 参悟结束之时，你只觉得神清气爽，神识也增强了几分。",
[2212]="<color=#c82c2c>[判定失败]</color> 参悟结束之时，你只觉得头晕眼花，一无所获，在房内昏睡了三日三夜。",
[2213]="你在练习术法时用力过猛，不小心将惯用的灵器砸出了一道裂痕……心疼不已的你只能咬牙掏出私房灵石，拜托炼器坊的长老帮你好好修补加固一番。",
[2214]="取回修补好的灵器后，你惊喜地发现其威能竟更甚从前，也算是因祸得福了。",
[2215]="趁着四下无人，你准备试一试术法与符箓结合使用的威力。一挥袖，符箓列阵排开，再一手掐诀，你大喝一声“爆”！灵力如雷炸开，符箓化作飞灰，登时浓烟滚滚，用来试法的巨石和木桩瞬间碎裂四溅……",
[2216]="你正在沾沾自喜，这威力比你预计的覆盖面更广，就听到一阵“咳咳”声传来，只见师父灰头土脸地穿过浓烟，沉着脸道：“试法记得去后山找个空旷的地方！”你立刻拱手称是，脚底抹油地溜了。",
[2217]="今日大雨，电闪雷鸣，本欲去斗法台与同门切磋的你只能放弃……虽已辟谷，但反正闲来无事，你干脆躲在房里偷偷烤了只山鸡吃，真香！",
[2218]="你与师姐切磋，锐气如金针骤雨，一手锐金诀使得出神入化……个屁！师姐手中长刀如臂指使，刀罡烈烈，一力降十会，将你打得狼狈逃窜。",
[2219]="你与师姐切磋，藤网铺天盖地，一手御木诀使得出神入化……个屁！师姐手中长刀如臂指使，刀罡烈烈，一力降十会，将你打得狼狈逃窜。",
[2220]="你与师姐切磋，水势如龙，一手控水术使得出神入化……个屁！师姐手中长刀如臂指使，刀罡烈烈，一力降十会，将你打得狼狈逃窜。",
[2221]="你与师姐切磋，火浪翻腾，一手控火术使得出神入化……个屁！师姐手中长刀如臂指使，刀罡烈烈，一力降十会，将你打得狼狈逃窜。",
[2222]="你与师姐切磋，山塌地陷，一手御土诀使得出神入化……个屁！师姐手中长刀如臂指使，刀罡烈烈，一力降十会，将你打得狼狈逃窜。",
[2223]="途经一座高山时，你误入妖隼巢穴，趁着成年妖隼外出狩猎尚未归来，你果断隐匿身形偷了几枚妖卵，离开时也极为谨慎地抹除了自己的气息和踪迹。",
[2224]="之后在一处散修集市上，这几枚妖卵果然卖出了好价钱，令你大赚一笔。",
[2225]="<color=#3375c0>[资质判定]</color> 夜宿荒野，清风徐徐，漫天星子璀璨，无边无垠，你久久地仰望这片星辰……",
[2226]="<color=#549327>[判定成功]</color> 对自然造化又有一番新的感悟。之后，你再运转心法修行时，修为有所提升。",
[2227]="<color=#c82c2c>[判定失败]</color> 星空的深邃令你沉醉不已，直到翌日赶路时，你的心情仍是很好。",
[2228]="游历途中，你来到一座修行者建立的城池，恰逢城内武擂初开，十分热闹。你围观了一阵，看得心痒，便也上擂一试身手。未曾想竟连挑三人，虽然不敌第四人，但你还是拿到了一笔奖励。",
[2229]="途经一片清幽竹林时，你与一名音修偶遇，交谈数句便觉得颇为投缘。对方兴起之下以琴会友，弦起叮咚，琴音似冷泉击白石，曼妙非常。你亦随之席地而坐，击节相和，陶然沉醉。",
[2230]="<color=#3375c0>[资质判定]</color> 传闻东边有秘境现世，你运气不错，在入口开放的最后一天及时赶到，进入其中。",
[2231]="<color=#549327>[判定成功]</color> 在步步为营的小心探索之下，你顺利寻获了一些合用的丹药和灵器，离开秘境之后，你找了个隐蔽之处耐心消化所得，修为明显有所提升。",
[2232]="<color=#c82c2c>[判定失败]</color> 可惜仍是慢人一步，你小心探索了许久，最终只寻获了少量不甚合用的灵器。离开之后，你将灵器卖出，倒也算有所收获。",
[2233]="你在一处酒楼歇息，正在二楼雅座品尝招牌的灵兽肉羹时，两位威势赫赫的修士正好拾级而上，你不由得好奇地稍稍外放神识试图打探一番，不料却听到一声冷哼在脑内炸响，你瞬间喉头一甜，吐出一口鲜血。",
[2234]="脸色惨白的你立刻收回神识，勉力抬眼看去，只见那两名修士神色冰冷地扫了你一眼，便继续向上去往雅间了。",
[2235]="你顿觉后怕不已，幸好只是肺腑受伤，好好休养尚能恢复……修士性情无常，果然不该贸然打探，你苦笑着牢牢记下了这个教训。",
[2236]="听闻多宝楼汇聚天下奇珍，是修真界一等一的商行，如今多宝楼正在举办夺宝会，广邀天下修士前来闯关。",
[2237]="你正好也顺势去凑这个热闹，虽然闯过的关卡不多，但也得了些合用的珍宝。",
[2238]="游历太岳中途，你来到一座隐藏在云雾之中的奇山，其形如神女之足立于地面，需御气之术极佳者方能登顶。",
[2239]="你虽然只能上到山腰，却也见到了嶙峋奇石自成一景，无数藤萝点缀其上，皆是灵气浓郁。",
[2240]="日出之时，绚烂霞辉如羽，轻柔地覆于奇山之上，此景至美，令你心境开阔，久久难以忘怀。",
[2241]="四处游历，不知走过多少山水，你终至天云洲边界之处。再向外就是海域，海面极其广阔，目不能穷。",
[2242]="你登上灵船出海，欲赏壮丽海景，只见这数层楼高的巨船乘风破浪稳稳前行，碧蓝波涛之中灵鱼跃起，海兽吐息更似涌泉。",
[2243]="海中零星散落大小岛屿，云雾环岛而绕，琼楼玉宇隐约可见，真真令人眼界大开。",
[2244]="南疆密林之中，毒瘴毒虫虽是防不胜防，但凶险之下亦有际遇。",
[2245]="你穿过大片密林，竟来到一处开阔之地，仿佛不曾有人打扰一般，眼前竟是数池灵泉，其色五彩，皆是清澈见底。",
[2246]="不知名的透明灵鱼游弋其中，灵动非常。如此奇景令人眼前一亮，你更是小心地取用了不同的灵泉之水，一番尝试之下，对修炼大有益处。",
[2247]="人迹罕至的雪境天山深处，一场暴风雪过后，你离开山洞继续前行，意外来到一处山谷，不知名的奇特冰花摇曳绽放，蔓延成大片花海，在晴雪后的阳光下折射出五彩斑斓的梦幻光芒。",
[2248]="冰蝶三五成群，在花海中穿梭飞舞；谷中时不时有风拂过，回响如歌。你长久地凝望着眼前这片美景，如此震撼人心，足以令人念念不忘。",
[2249]="游历多时，与修士的切磋和与妖兽的较量，不仅令你取长补短，更让你之积累日渐雄厚，愈发完善己身之道，心境亦有提升。",
[2250]="待资源备齐，进阶契机也至，你寻了一处安全之地布下禁制，水到渠成地突破至元婴期。",
[2251]="游历多时，积累雄厚，你水到渠成地突破至元婴期。",
[2252]="游历中途，你发现一条湍急河流，哪怕在河水最浅的地方也难以站稳。你想了想，干脆在此修行一段时日。每天起身后，你便站在河中练习劈剑，日劈千次……五年后，你一剑可断水一息。",
[2253]="<color=#3375c0>[聪慧判定]</color> 你来到一处十分热闹的散修集市，各类资源物品令你大开眼界，可惜你囊中羞涩……",
[2254]="<color=#549327>[判定成功]</color> 但经过一番讨价还价，你最终还是买到了想要的剑术典籍，总算不虚此行。",
[2255]="<color=#c82c2c>[判定失败]</color> 看中的一本剑术典籍被另一位出手阔绰的修士买走，只能眼巴巴地独自叹气。",
[2256]="听闻青云剑阁正在举办论剑大会，这可是赫赫有名的剑道大宗，你连忙赶去参加。与诸多剑修同道切磋论道，果然获益匪浅。",
[2257]="<color=#3375c0>[概率判定]</color> 一次夜行，你正在穿过一处僻静树林，忽然遇袭！数名邪修显露身形朝你攻来，修为皆是不俗，抬手就是毒辣狠招！",
[2258]="<color=#549327>[判定成功]</color> 你沉着应对，危急关头愈发心思雪亮，竟在生死攸关之际悟得剑气，瞬间形势逆转，斩敌首于无形，剑道锋锐初现锋芒！",
[2259]="<color=#c82c2c>[判定失败]</color> 仓促对敌，以一敌众难免左支右绌，你只能咬牙豁命相拼，最终凭着肋下被刺穿换得斩敌二人，凭借敛息符险之又险地仓皇逃离……此战伤重难愈，令你元气大伤，休养了许久都未能彻底恢复。",
[2260]="你来到一处十分热闹的散修集市，各类资源物品令你大开眼界。可惜你囊中羞涩，看中的一件上品灵器被另一位出手阔绰的修士买走，只能眼巴巴地独自叹气。",
[2261]="听闻西南无极宗正在举办论道大会，这可是久负盛名的法修大宗，你连忙赶去参加。与诸多法修同道切磋论道，果然获益匪浅。",
[2262]="你前往一处上古大能的洞府遗迹探宝，意外触发一个隐秘的阵法，恰好需要金行法诀才能破阵……想必这就是自己的机缘吧！顺利破阵的你进入了一处地下宫殿，搜寻到不少稀有的丹药和资源。",
[2263]="你前往一处上古大能的洞府遗迹探宝，意外触发一个隐秘的阵法，恰好需要木行法诀才能破阵……想必这就是自己的机缘吧！顺利破阵的你进入了一处地下宫殿，搜寻到不少稀有的丹药和资源。",
[2264]="你前往一处上古大能的洞府遗迹探宝，意外触发一个隐秘的阵法，恰好需要水行法诀才能破阵……想必这就是自己的机缘吧！顺利破阵的你进入了一处地下宫殿，搜寻到不少稀有的丹药和资源。",
[2265]="你前往一处上古大能的洞府遗迹探宝，意外触发一个隐秘的阵法，恰好需要火行法诀才能破阵……想必这就是自己的机缘吧！顺利破阵的你进入了一处地下宫殿，搜寻到不少稀有的丹药和资源。",
[2266]="你前往一处上古大能的洞府遗迹探宝，意外触发一个隐秘的阵法，恰好需要土行法诀才能破阵……想必这就是自己的机缘吧！顺利破阵的你进入了一处地下宫殿，搜寻到不少稀有的丹药和资源。",
[2267]="<color=#549327>[判定成功]</color> 你沉着应对，危急关头愈发心思雪亮，先以防御灵器牢牢护住心脉，再伺机用术法引爆连环符阵。",
[2268]="瞬间形势逆转，一众盗匪被炸得尸骨无存。此战全胜，令你心境又上一层楼！",
[2269]="<color=#c82c2c>[判定失败]</color> 仓促对敌，以一敌众难免左支右绌，你只能咬牙豁命相拼。",
[2270]="最终凭着肋下被刺穿换得杀敌二人，再以障眼法迷惑剩下的盗匪，险之又险地仓皇逃离……此战伤重难愈，令你元气大伤，休养了许久都未能彻底恢复。",
[2271]="游历中途，巧遇清风平原秘境开启，做足准备之后，你果断进入秘境。内中灵草繁多，你一路采集，遇到的零星妖兽也都能轻松解决。",
[2272]="直至来到一片灵草极为丰茂之地，灵气浓稠如浆，你当即明白此地将有秘宝现世，而一匹威势惊人的雷鳞马正在悠然踱步，彷如巡视自己的领地。你决定……？",
[2273]="正面对战 [概率判定]",
[2274]="设计埋伏 [聪慧判定]",
[2275]="<color=#549327>[判定成功]</color> 身为剑修，唯战便是！你拔剑跃出，剑气如虹，朝雷鳞马当头斩下！雷鳞马未能闪避及时，登时遭受重创，你决定……？",
[2276]="乘胜追击 [根骨判定]",
[2277]="诱敌消耗 [聪慧判定]",
[2278]="<color=#549327>[判定成功]</color> 一击得手，你越战越勇，有如神助。剑气锋锐无匹，割开层层硬鳞竟似砍瓜切菜一般……雷鳞马哀嚎不已，血流如注，你当机立断地封其退路，运起十成十的灵力一剑挥出，斩断了雷鳞马的头颅！",
[2279]="护宝妖兽已死，你成功获得了秘宝，更不忘拾掇了雷鳞马的妖丹和一身骨肉，都是上好的材料。离开秘境之后，你将材料售卖，赚了一笔不菲的灵石，然后果断布下禁制开始闭关，借秘宝之力，修为又有进境。",
[2280]="<color=#c82c2c>[判定失败]</color> 你一击得手，激动之下不免有些大意，雷鳞马捉得空隙，奋力跃起朝你蹬蹄，你避之不及，登时内腑受创，喷出一口血来。",
[2281]="你深知此时再退更难，不如拖着伤躯与之搏命！最终，拼着右肩受创，你终于成功斩杀了雷鳞马。你的血混着雷鳞马的血一起流下，将你染成了血人……",
[2282]="稍微恢复了一些气力后，你连忙将秘宝妥善收好，便匆匆离开了秘境……闭关养伤之余，借着秘宝之力，你刻苦修行，修为也算有所进境。",
[2283]="<color=#549327>[判定成功]</color> 雷鳞马实力强悍，你一击得手，便欲引其游走消耗一番，应能轻松些解决。在你小心谨慎地引导之下，雷鳞马果然中计，且追且战之间被你耗去大半体力，疲态尽显，你当机立断不再游走，干脆利落地连劈数剑，剑芒锋锐，终于将其斩杀。",
[2284]="<color=#c82c2c>[判定失败]</color> 雷鳞马实力强悍，你一击得手，便欲引其游走消耗一番……不料雷鳞马十分警觉，察觉你的意图之后，果断嘶鸣一声，快速与你拉开距离，转瞬就逃了个无影无踪。",
[2285]="你愣神之际，足下大地却开始隐隐震动，你立刻放出神识查探一番，登时脸色大变，成群的雷鳞马正在朝此地赶来……小命要紧，走为上策！你只能遗憾地放弃秘宝，抓紧时间逃离了此地。",
[2286]="<color=#c82c2c>[判定失败]</color> 身为剑修，唯战便是！你拔剑跃出，剑气如虹，朝雷鳞马当头斩下！",
[2287]="然而雷鳞马行动敏捷，四蹄连踏，险险避开了你的攻击，反而趁势朝你踹来，你避之不及，登时内腑受创，喷出一口血来。情急之下，你决定……？",
[2288]="放手一搏 [机缘判定]",
[2289]="<color=#549327>[判定成功]</color> 你深知此时再退更难，不如放手一搏，剑修当勇！你凝神以对，气势始终未落下风。最后，拼着左臂受创，你终于一剑刺穿了雷鳞马的脖颈，巨大的兽躯轰然倒地，再也没了声息……",
[2290]="<color=#c82c2c>[判定失败]</color> 你深知此时再退更难，不如放手一搏，剑修当勇！然而雷鳞马实力强悍，渐渐地，你灵力不支，身上的伤口越来越多，落入下风……",
[2291]="最终，拼着右肩受创，你争得一个空档砸出传送符，瞬间远遁……重伤之下，你只能仓皇逃离秘境，寻一处安全所在好好养伤。",
[2292]="雷鳞马实力强悍，又被激怒，十分难以招架。受伤的你当机立断，运起秘法连忙拼命逃出秘境，保命要紧。",
[2293]="<color=#549327>[判定成功]</color> 你谨慎地找准时机，剑气迅疾如电，登时穿透了雷鳞马的身躯。雷鳞马痛苦地嘶鸣着，显然是受到了重创。你决定……？",
[2294]="<color=#549327>[判定成功]</color> 偷袭得手，你自然不会放过此等机会！你愈发谨慎地找准时机，从刁钻的角度攻向雷鳞马，锋锐的剑气在其身上留下了越来越多的伤口……",
[2295]="雷鳞马哀嚎不已，血流如注，你当机立断地封其退路，运起十成十的灵力一剑挥出，雷鳞马倒地不起，不多时便断绝了生机。",
[2296]="<color=#c82c2c>[判定失败]</color> 偷袭得手，你激动之下不免有些大意，雷鳞马捉得空隙，奋力跃起朝你蹬蹄，你避之不及，登时喷出一口血来。",
[2297]="雷鳞马凶悍不已，此时你也不能再退，只能强撑着伤躯与之相博！最终，拼着右肩受创，你终于斩断了雷鳞马的头颅。你的血混着雷鳞马的血一起流下，将你染成了血人……",
[2298]="<color=#549327>[判定成功]</color> 雷鳞马实力强悍，你偷袭得手，便欲引其游走消耗一番，以最小的代价换取胜利。",
[2299]="在你小心谨慎地引导之下，雷鳞马果然中计，且追且战之间被你耗去大半体力，疲态尽显，你当机立断不再游走，干脆利落地连劈数剑，剑芒锋锐，终于将其斩杀。",
[2300]="<color=#c82c2c>[判定失败]</color> 雷鳞马实力强悍，你偷袭得手，便欲引其游走消耗一番……不料雷鳞马察觉你的意图之后，竟快速与你拉开距离，转瞬就逃了个无影无踪。",
[2301]="你正欲追上，不料却察觉到一些强悍的气息在向此地逼近，连忙放出神识细探，登时脸色大变，竟有成群的妖兽即将到达此地……小命要紧！你只能遗憾地放弃秘宝，抓紧时间逃离了此地。",
[2302]="<color=#c82c2c>[判定失败]</color> 你谨慎地寻找时机，趁着雷鳞马转身的一个空隙，迅猛地拔剑从其身后偷袭！",
[2303]="然而雷鳞马十分警觉，竟险险避开了这道凛冽的剑气，反而趁势朝你踹来，你避之不及，登时内腑受创。情急之下，你决定……？",
[2304]="<color=#549327>[判定成功]</color> 此时退缩反而更加危险，不如放手一搏！你愈发谨慎地找准时机，从刁钻的角度攻向雷鳞马……最后，拼着左臂受创，你终于一剑刺穿了雷鳞马的脖颈，巨大的兽躯轰然倒地，再也没了声息。",
[2305]="<color=#c82c2c>[判定失败]</color> 此时退缩反而更加危险，不如放手一搏！然而雷鳞马岂是易与之辈，渐渐地，身上的伤口越来越多的你灵力几近透支，眼前阵阵发黑……",
[2306]="你深知不能再战，咬牙拼着右肩受创，你争得一个空档砸出传送符，瞬间远遁……重伤的你仓皇逃离秘境，匆忙寻了一处僻静之地好好养伤。",
[2307]="被激怒的雷鳞马愈发狂躁凶悍，数次差点直接咬断你的脖颈。暗道不妙的你咬了咬牙，赶忙运起秘法拼命逃离此地。这时候还管他什么秘宝，小命第一啊。",
[2308]="据传，太岳山脉有秘宝出世，得之可淬体炼神，正是你如今所需。你一路打听线索，披星戴月赶到秘宝出世之地。",
[2309]="只见一只双目炯炯有神的猴王占据了此处，体型极为壮硕，猴爪锋利得令人胆寒。你决定……？",
[2310]="先下手为强 [概率判定]",
[2311]="扮猪吃老虎 [机缘判定]",
[2312]="<color=#549327>[判定成功]</color> 剑之道，迎难而上，无坚不摧！你拔剑而起，以悍勇之姿朝猴王袭去，剑气与空气相撞，竟成铿锵之声！",
[2313]="猴王抬臂欲挡，不料剑气锋锐，竟在其肩上狠狠划开了一道狰狞的口子，深可见骨。猴王登时又怒又痛，吼声不断，你决定……？",
[2314]="劝服对方 [魅力判定]",
[2315]="<color=#549327>[判定成功]</color> 你先手占了上风，却未有丝毫大意，更是熟练地将剑诀连番使出，势如排山倒海，剑气一浪接一浪，逼使猴王连连后退，左支右绌地应战。",
[2316]="此消彼长之下，你出手愈快愈凌厉，而猴王伤痕累累，竟有了逃跑之意。你立刻断其后路，全力一剑穿心而过！猴王轰然倒地。",
[2317]="猴王既死，你连忙四处搜寻，果然找到了被其藏起来的秘宝。得手之后迅速离开，寻了个僻静之处布下禁制，你安然闭关消化所得，修为又进一步。",
[2318]="<color=#c82c2c>[判定失败]</color> 先手占了上风，你不免有些急切地想要尽快拿下猴王。而对方岂是易与之辈，在伤痛的刺激之下，猴王凶性更盛，竟与你缠斗了起来。",
[2319]="打了许久，双方皆有负伤。灵力的剧烈消耗让你的丹田都有些抽痛，不能再拖下去！最终，拼着腹部被狠狠抓伤，你找准空隙斜劈一剑，斩断了猴王的头颅。",
[2320]="猴王既死，你拖着伤躯找到了被藏起来的秘宝，连忙祭出符箓远遁而走。此行虽然受伤不轻，但秘宝到手，还是赚了。闭关之后，你的修为又进一步。",
[2321]="<color=#549327>[判定成功]</color> 虽然先手占了上风，但猴王的实力令你丝毫不敢大意。听闻猴妖多智，你不欲两败俱伤，若能劝服对方交出秘宝，便是再好不过。",
[2322]="打定主意，你谨慎地与猴王保持距离，舌绽莲花般沟通了许久，扣在手中的宝剑也时不时轻轻嗡鸣……终于，你劝服对方交出了秘宝。",
[2323]="得到秘宝的你遵守约定，迅速离开了对方的据地，找了安全之处消化所得，修为又进一步。",
[2324]="<color=#c82c2c>[判定失败]</color> 虽然先手占了上风，但猴王的实力令你丝毫不敢大意。听闻猴妖多智，若能劝服对方交出秘宝，便是再好不过。",
[2325]="打定主意，你谨慎地与猴王拉开距离，正欲劝说对方，不料这猴王竟是趁机飞速后撤，你拔腿便追，却因不熟地形而被对方成功逃脱。",
[2326]="猴王占据地利，躲得无影无踪，你四处搜寻了一番也未能发现秘宝。无奈之下只能作罢，你叹了口气，两手空空地离开了此地。",
[2327]="<color=#c82c2c>[判定失败]</color> 剑之道，迎难而上，无坚不摧！你之剑气以雷霆之势朝猴王斩去，不料对方动作敏捷，勾着树枝连蹿几下便避开了攻击。",
[2328]="熟悉地形的猴王占据优势，出其不意地出现在了你的身后！你避之不及，被其狠狠抓伤后背，鲜血瞬间濡湿了衣衫。你决定……？",
[2329]="<color=#549327>[判定成功]</color> 猴王凶猛，此时已落下风，更不能退，否则小命难保。你愈发沉稳，进退有度，剑气过处必见血光！最终，你拼着腹部受创，换得空档全力挥出一剑，斩下了猴王的头颅。",
[2330]="猴王已灭，你顾不上包扎伤处，急忙找到了被藏起来的秘宝，迅速离开了此地。调息养伤之后闭关修炼，你的修为又进一步。",
[2331]="<color=#c82c2c>[判定失败]</color> 猴王凶猛，此时已落下风，更不能退，否则小命难保。然而猴王实力强悍，渐渐地，你灵力不支，身上的伤口越来越多，落入下风……",
[2332]="最终，拼着左肩受创，你抢出一剑逼退猴王，争得一个空档砸出传送符远遁……重伤之下，你只能仓皇逃离此地，寻一处安全所在好好养伤。",
[2333]="被激怒的猴王凶猛无比，几近狂躁，十分难以招架。伤口的剧痛令你异常清醒，立刻运起秘法拼命逃离此地，小命第一！",
[2334]="<color=#549327>[判定成功]</color> 听闻猴王凶猛，你欲智取，假作弱小修士误入此地，露出神色慌乱的模样。猴王不以为意地举爪朝你拍下，以为能轻松将你碾死。",
[2335]="不料你一个矮身快速出剑，一道凛冽剑气直透对方肋下，带出一蓬血雾。猴王登时受到重创，哀嚎不已，你决定……?",
[2336]="<color=#549327>[判定成功]</color> 你示弱取得优势，却未敢大意，更为谨慎地将剑诀使出，剑气从无落空，逼使猴王带伤迎战，伤口越来越多……",
[2337]="此消彼长之下，你出手愈发刁钻，而猴王伤痕累累，竟有了逃跑之意。你立刻断其后路，全力一剑穿心而过！猴王轰然倒地。",
[2338]="<color=#c82c2c>[判定失败]</color> 一个照面便占了上风，你不免有些急切，出剑未有先前谨慎。然而猴王岂是易与之辈，在伤痛的刺激之下，凶性更盛，竟连出狠招，缠斗之下，你身上的伤口也多了起来。",
[2339]="灵力的剧烈消耗让你的丹田都有些抽痛，不能再拖下去！最终，拼着腹部被重创，你找准空隙斜劈一剑，斩断了猴王的头颅。",
[2340]="猴王既死，你拖着伤躯找到了被藏起来的秘宝，连忙祭出符箓远遁而走。养好伤后，你闭关苦修，修为又进一步。",
[2341]="<color=#549327>[判定成功]</color> 虽然以示弱取得优势，但猴王的实力令你丝毫不敢大意。听闻猴妖多智，你不欲两败俱伤，若能劝服猴王交出秘宝，便是再好不过。",
[2342]="打定主意，你谨慎地与猴王保持距离，舌绽莲花般沟通了许久，扣在手中的宝剑也时不时轻轻嗡鸣……终于，对方轻轻点头，同意交出秘宝换其全身而退。",
[2343]="得到秘宝的你迅速离开了猴王的据地，找了安全之处消化所得，修为又进一步。",
[2344]="<color=#c82c2c>[判定失败]</color> 虽然一个照面便占了上风，但猴王的实力令你丝毫不敢大意。听闻猴妖多智，若能劝说猴王交出秘宝，便是再好不过。",
[2345]=" <color=#c82c2c>[判定失败]</color> 听闻猴王凶猛，你欲智取，假作弱小修士误入此地，露出神色慌乱的模样。不料对方仿佛嗅出了什么气息，极为慎重地朝你扑来，举爪便是全力。",
[2346]="你连忙回退闪躲，却还是被狠狠抓伤了后背，鲜血瞬间濡湿了衣衫。你决定……？",
[2347]="<color=#549327>[判定成功]</color> 你的计划失败，此刻已落下风，更不能退，否则小命难保。你愈发沉稳，迎战凶狠的猴王亦未乱了阵脚，剑气过处必见血光！最终，你拼着腹部受创，换得空档全力挥出一剑，斩下了猴王的头颅。",
[2348]="<color=#c82c2c>[判定失败]</color> 你的计划失败，此刻已落下风，更不能退，否则小命难保。然而猴王实力强悍，渐渐地，你灵力不支，身上的伤口越来越多，落入下风……",
[2349]="被激怒的猴王凶猛无比，几近狂躁，十分难以招架。伤口的剧痛令你异常清醒，立刻运起秘法拼命逃离此地，走为上策！",
[2350]="天云洲近海处有上古遗迹现世，此秘境数百年开启一回，藏有多种失传的上古灵丹。各路人马闻风而动，你亦是其中之一。",
[2351]="一路有惊无险，机缘巧合之下，你意外来到了一处偏殿，殿内存有无极丹，此乃不可多得的在提升修为之外更能凝练神识的失传丹药……",
[2352]="正当你准备取回无极丹时，心中突然警铃大作，下意识地矮身避开了身后突然袭来的攻击。",
[2353]="你提起戒备迅速回身望去，只见一名邪修牢牢盯着你，露出了不怀好意的狠辣神色，你决定……？",
[2354]="锋芒不让 [机缘判定]",
[2355]="以退为进 [聪慧判定]",
[2356]="<color=#549327>[判定成功]</color> 邪修攻势凶猛，你亦锋芒不让。三尺青锋在手，人剑合一，剑随意至，剑气如狂风过境般席卷而去！",
[2357]="对方似乎没想到你之剑术如此强悍，愣神之下竟被你的凌厉剑气狠狠刺伤了侧腹，登时血流如注。你决定……？",
[2358]="诱敌消耗 [魅力判定]",
[2359]="<color=#549327>[判定成功]</color> 初回交手你便略胜一筹，剑意也愈发高涨起来，信心倍增地继续进攻。剑气强势扫过，空气中隐有爆鸣之声，邪修连运御火之术，却难挡剑气横扫之锋锐！",
[2360]="剑势盛则你愈勇，邪修身上的伤口越来越多，脸色惨白，竟有退却之意。你立刻抓准时机全力挥剑，剑光自邪修颈间一闪而没，下一瞬，对方轰然倒地。",
[2361]="邪修已死，你立刻取回无极丹并离开秘境。回到安全之处后，你闭关修行，借灵丹之力，修为又有进境。",
[2362]="<color=#c82c2c>[判定失败]</color> 初回交手你便略胜一筹，剑意也愈发高涨起来。然而邪修根基深厚，受伤后更是使出十成十的狠辣手段与你相搏！你来我往缠斗许久，双方皆添新红。",
[2363]="灵力的剧烈消耗让你的丹田都有些抽痛，再拖下去必败！你咬牙加快进攻，不惜以伤换命，在邪修打断你肋骨的同时一剑砍断了对方的头颅。",
[2364]="邪修已死，剧烈的疼痛让你难以支撑太久，取得无极丹后便急忙祭出符箓远遁而走。离开秘境之后，你寻到安全之处调养了许久，之后再借灵丹之力修炼，修为又有进境。",
[2365]="<color=#549327>[判定成功]</color> 邪修既已受伤，你心念一转，更为慎重求稳，若能引其游走消耗一番，可省下不少力气。打定主意，你且战且退，挥出的剑气角度更为刁钻，迫使对方花费更多心神应对。",
[2366]="你刻意风筝般地耗去大半时辰，眼见邪修气喘吁吁，脸色更加苍白，便知时机已至，干脆利落地回身拉进距离，锋锐剑气呼啸而出，将邪修捅了个对穿。",
[2367]="确认邪修已死，你迅速取回无极丹并离开秘境，找了安全所在体悟战斗所得，再闭关消化灵丹之力，修为又有进境。",
[2368]="<color=#c82c2c>[判定失败]</color> 邪修既已受伤，你心念一转，更为慎重求稳，若能引其游走消耗一番，可省下不少力气。打定主意，你且战且退……",
[2369]="邪修却看穿了你的谋划，冷笑一声后连掐数诀，以火墙为阻拉开距离，待你突破火墙时，对方早已逃之夭夭不见踪影……",
[2370]="你四下一看，这厮逃走时竟连无极丹也一并拿走了，气得你咬牙切齿，只能设法再寻别的宝物。不料竟是不得机缘，最终你只能两手空空地离开了秘境。",
[2371]="<color=#c82c2c>[判定失败]</color> 邪修攻势凶猛，你亦锋芒不让。然而邪修对敌经验多你十倍有余，你一招不慎，便被其捉了空档，灵火狠狠灼伤了你的肩背，登时痛得脸色煞白。情急之下，你决定……？",
[2372]="<color=#549327>[判定成功]</color> 此时若退，定然九死一生，不如放手一搏！你愈发谨慎，进退有度，出剑极稳，气势始终未落下风。最终，你拼着腹部受创，以伤换命地一剑刺穿了邪修的脖颈，令其气绝而亡。",
[2373]="你撑着一口气把无极丹取回，便立刻祭出符箓远遁而去。离开秘境后，闭关养伤之余，借着灵丹之力，你刻苦修行，修为又有进境。",
[2374]="<color=#c82c2c>[判定失败]</color> 此时若退，定然九死一生，不如放手一搏！然而邪修狠辣非常，一手御火术用得极为刁钻，令你防不胜防，你身上的伤口也越来越多，渐渐落入陷境……",
[2375]="最终，拼着右臂折断，你抢出一剑逼退对方数步，争得一个空档砸出传送符远遁……重伤之下，你拼命地逃离秘境，一心只想着寻一处安全所在静心养伤。",
[2376]="邪修之辈，出手狠辣阴险，十分难以招架。伤口火燎般的剧痛令你异常清醒，虚晃一剑之后，你立刻运起秘法拼命逃离秘境，保命要紧。",
[2377]="<color=#549327>[判定成功]</color> 邪修手段诡谲，出手狠厉，你不欲硬碰硬，顺势以退为进，连消带打地化解对方的攻势，再趁机反击。",
[2378]="邪修一招不及收势，你果断出剑，剑气直穿对方肋下，带出一蓬血雾。邪修登时发出一声痛苦的闷哼。你决定……？",
[2379]="<color=#549327>[判定成功]</color> 以退为进一击得手，你有了底气，剑意也愈发高涨。剑随意动，凌厉剑气强势扫过，空气中隐有爆鸣之声，邪修连运御火之术，却难挡剑气横扫之锋锐！",
[2380]="<color=#c82c2c>[判定失败]</color> 以退为进一击得手，你有了底气，剑意也愈发高涨。然而邪修根基深厚，受伤后更是使出十成十的狠辣手段与你相搏！你来我往缠斗许久，双方皆添新红。",
[2381]="<color=#c82c2c>[判定失败]</color> 邪修手段诡谲，出手狠厉，你不欲硬碰硬，顺势以退为进，连消带打地化解对方的攻势，再趁机反击。",
[2382]="然而邪修对敌经验老道，你一步退，便被逼得步步退，仓促之间被对方捉住空隙，以火箭射穿了你的肩胛，你登时疼得血色尽褪，决定……？\n",
[2383]="<color=#549327>[判定成功]</color> 负伤欲退定是步步艰险，不如放手一搏！你愈发谨慎，进退有度，出剑极稳，气势始终未落下风。最终，你拼着腹部受创，以伤换命地一剑刺穿了邪修的脖颈，令其气绝而亡。",
[2384]="<color=#c82c2c>[判定失败]</color> 负伤欲退定是步步艰险，不如放手一搏！然而邪修狠辣非常，一手御火术用得极为刁钻，令你防不胜防，你身上的伤口也越来越多，渐渐落入陷境……",
[2385]="正面对战 [以火克金]",
[2386]="暗中偷袭 [机缘判定]",
[2387]="<color=#549327>[判定成功]</color> 雷鳞马属金，你之御火诀修炼得也算有些火候，当能以火克金！决心速战速决的你快速冲向雷鳞马，连掐数十诀。",
[2388]="铺天盖地的滚滚火浪朝雷鳞马兜头扑下！灵火烧焦皮肉的气味瞬间散开，雷鳞马嘶鸣不已，显然是受到了重创。你决定……？",
[2389]="<color=#549327>[判定成功]</color> 火攻得手，你顿时有了底气，下手愈发果断。灵火变化万千，一时似火箭熊熊，一时如流星疾坠……雷鳞马哀嚎不已，焦黑的皮肉之下血流如注。",
[2390]="你看出对方已是强弩之末，连忙运起十成十的灵力布下火牢，雷鳞马左冲右突亦无法逃脱，终于倒地不起，生机断绝。",
[2391]="护宝妖兽已死，你成功获得了秘宝。顺利离开秘境之后，寻了僻静之处布下禁制开始闭关，借秘宝之力，你之修为又有进境。",
[2392]="<color=#c82c2c>[判定失败]</color> 你火攻得手，激动之下不免有些大意，暴怒的雷鳞马奋力跃起朝你蹬蹄，你避之不及，登时内腑受创，喷出一口血来。",
[2393]="你深知此时再退更难，不如拖着伤躯与之搏命！最终，拼着右肩受创，你总算捉得空隙，将灵火附着在灵器之上，刺穿了雷鳞马的脖颈，巨兽轰然倒地，再没了声息。",
[2394]="<color=#549327>[判定成功]</color> 雷鳞马实力强悍，你火攻得手，便欲引其游走消耗一番，应能轻松些解决。",
[2395]="在你小心谨慎地引导之下，雷鳞马果然中计，且追且战之间被你耗去大半体力，疲态尽显，你当机立断不再游走，干脆利落地化火为箭，将雷鳞马扎了个对穿。",
[2396]="<color=#c82c2c>[判定失败]</color> 雷鳞马实力强悍，你火攻得手，便欲引其游走消耗一番……不料雷鳞马十分警觉，察觉你的意图之后，果断嘶鸣一声，快速与你拉开距离，转瞬就逃了个无影无踪。",
[2397]="<color=#c82c2c>[判定失败]</color> 雷鳞马属金，你之御火诀修炼得也算有些火候，当能以火克金！你快速冲向雷鳞马，一柄火剑在手中幻化而出，朝着雷鳞马劈下！",
[2398]="然而雷鳞马行动敏捷，一个晃身险险避开了你的攻击，反而趁势朝你踹来，你被踹中腹部，登时喷出一口血来。情急之下，你决定……？",
[2399]="<color=#549327>[判定成功]</color> 你深知此时再退更难，不如放手一搏！你凝神以对，御火诀用得没有丝毫浪费。最终，拼着左臂受创，\n你终于用火剑刺穿了雷鳞马的脖颈，巨大的兽躯轰然倒地，再也没了声息……",
[2400]="<color=#c82c2c>[判定失败]</color> 你深知此时再退更难，不如放手一搏！然而雷鳞马实力强悍，渐渐地，你灵力不支，操纵的灵火越来越弱，落入下风……",
[2401]="雷鳞马实力强悍，又被激怒，令人十分难以招架。受伤的你当机立断，运起秘法连忙拼命逃离此地，保命要紧。",
[2402]="<color=#549327>[判定成功]</color> 雷鳞马属金，你修御火诀，火能克金，底气便多了几分。你谨慎地找准时机，趁着雷鳞马转身的一个空隙。",
[2403]="引火为箭，登时扎穿了雷鳞马的身躯。雷鳞马痛苦地嘶鸣着，显然是受到了重创。你决定……？",
[2404]="<color=#549327>[判定成功]</color> 偷袭得手，你自然不会放过此等机会！你愈发谨慎地找准时机，从刁钻的角度攻向雷鳞马，灼热的火箭在其身上留下了越来越多的伤口……",
[2405]="雷鳞马哀嚎不已，血流如注，你当机立断地封其退路，运起十成十的灵力凝成火矛扎穿了雷鳞马的脖颈。巨兽轰然倒地，不多时便断绝了生机。",
[2406]="雷鳞马凶悍不已，此时你也不能再退，只能强撑着伤躯与之相博！最终，拼着右肩受创，你终于用火鞭绞断了雷鳞马的脖颈。你的血混着雷鳞马的血一起流下，将你染成了血人……",
[2407]="在你小心谨慎地引导之下，雷鳞马果然中计，且追且战之间被你耗去大半体力，疲态尽显，你当机立断不再游走，干脆利落地化火为枪，将雷鳞马扎了个对穿。",
[2408]="<color=#c82c2c>[判定失败]</color> 雷鳞马属金，你修御火诀，火能克金，底气便多了几分。你谨慎地寻找时机，趁着雷鳞马转身的一个空隙，引火为箭，从其身后偷袭！",
[2409]="然而雷鳞马十分警觉，竟险险避开了这道火箭，反而趁势朝你踹来，你避之不及，登时内腑受创。情急之下，你决定……？",
[2410]="<color=#549327>[判定成功]</color> 此时退缩反而更加危险，不如放手一搏！你愈发谨慎地找准时机，凝出火箭，从刁钻的角度攻向雷鳞马……最终，拼着左臂受创，你以一柄火剑贯穿了雷鳞马的脖颈，巨大的兽躯轰然倒地，再也没了声息。",
[2411]="<color=#549327>[判定成功]</color> 外出历练，当以战磨练自身。你打定主意，快速冲向雷鳞马，连掐数十诀，灵力化作箭雨纷纷，朝着雷鳞马飞射而去。",
[2412]="雷鳞马避之不及，有数枚灵箭扎透了它的身躯，令其嘶鸣不已，显然是受到了重创。你决定……？",
[2413]="<color=#549327>[判定成功]</color> 一击得手，你顿时有了底气，下手愈发果断。灵力在术法的控制下变化万千，一时似箭，一时如针……雷鳞马哀嚎不已，身上的创口越来越多，血流如注。",
[2414]="你看出对方已是强弩之末，连忙运起十成十的灵力编织成网，雷鳞马左冲右突亦无法逃脱，反而被灵立凝成的绳索越绞越紧，直至倒地不起，生机断绝。",
[2415]="<color=#c82c2c>[判定失败]</color> 你一击得手，激动之下不免有些大意，暴怒的雷鳞马奋力跃起朝你蹬蹄，你避之不及，登时内腑受创，喷出一口血来。",
[2416]="你深知此时再退更难，不如拖着伤躯与之搏命！最终，拼着右肩受创，你总算捉得空隙，将灵力附着在灵器之上，硬生生刺穿了雷鳞马的脖颈，巨兽轰然倒地，再没了声息。",
[2417]="<color=#549327>[判定成功]</color> 雷鳞马实力强悍，你一击得手，便欲引其游走消耗一番，应能轻松些解决。",
[2418]="在你小心谨慎地引导之下，雷鳞马果然中计，且追且战之间被你耗去大半体力，疲态尽显，你当机立断不再游走，干脆利落地以灵力凝成长矛，将雷鳞马扎了个对穿。",
[2419]="<color=#c82c2c>[判定失败]</color> 外出历练，当以战磨练自身。你打定主意，快速冲向雷鳞马，一柄灵力凝成的长矛在手中幻化而出，朝雷鳞马扎去！",
[2420]="然而雷鳞马行动敏捷，一个晃身险险避开了你的攻击，反而趁势朝你踹来，你被踹中腹部，登时内腑受创。情急之下，你决定……？",
[2421]="<color=#549327>[判定成功]</color> 你深知此时再退更难，不如放手一搏！你凝神以对，出手谨慎，没有浪费丝毫灵力。最终，拼着左臂受创，你终于以灵力凝成的长矛刺穿了雷鳞马的脖颈，巨大的兽躯轰然倒地，再也没了声息……",
[2422]="<color=#c82c2c>[判定失败]</color> 你深知此时再退更难，不如放手一搏！然而雷鳞马实力强悍，渐渐地，你灵力不支，身上伤口也越来越多，落入下风……",
[2423]="<color=#549327>[判定成功]</color> 小心使得万年船，偷袭更能抢占先机。你谨慎地观察了许久，趁着雷鳞马转身的一个空隙，引灵力为箭，登时扎穿了雷鳞马的身躯。雷鳞马痛苦地嘶鸣着，显然是受到了重创。你决定……？",
[2424]="<color=#549327>[判定成功]</color> 偷袭得手，你自然不会放过此等机会！你愈发谨慎地找准时机，从刁钻的角度攻向雷鳞马，在其身上留下了越来越多的伤口……",
[2425]="雷鳞马哀嚎不已，血流如注，你当机立断地封其退路，运起十成十的灵力化作巨刀斩下！雷鳞马倒地不起，不多时便断绝了生机。",
[2426]="雷鳞马凶悍不已，此时你也不能再退，只能强撑着伤躯与之相博！最终，拼着右肩受创，你终于用一柄灵器斩断了雷鳞马的头颅。你的血混着雷鳞马的血一起流下，将你染成了血人……",
[2427]="在你小心谨慎地引导之下，雷鳞马果然中计，且追且战之间被你耗去大半体力，疲态尽显，你当机立断不再游走，干脆利落地连投数柄灵力凝结成的长矛，扎穿了雷鳞马的头颅和脖颈。",
[2428]="<color=#c82c2c>[判定失败]</color> 小心使得万年船！你谨慎地寻找时机，趁着雷鳞马转身的一个空隙，引灵力为箭，从其身后偷袭！",
[2429]="然而雷鳞马十分警觉，竟险险避开了这道灵箭，反而趁势朝你踹来，你避之不及，登时内腑受创。情急之下，你决定……？",
[2430]="<color=#549327>[判定成功]</color> 此时退缩反而更加危险，不如放手一搏！你愈发谨慎地找准时机，从刁钻的角度攻向雷鳞马……最终，拼着左臂受创，你以一柄灵矛贯穿了雷鳞马的脖颈，巨大的兽躯轰然倒地，再也没了声息。",
[2431]="先下手为强 [以金克木]",
[2432]="扮猪吃老虎 [魅力判定]",
[2433]="<color=#549327>[判定成功]</color> 据你打探的情报，猴王乃木属大妖，你修习之锐金诀若能熟练运用，应有五行克制之效。",
[2434]="你欲以快制胜，飞身而上，抬手就是金气成矛，狠狠朝猴王捅去。此招极快极狠，猴王避之不及，肩胛被狠狠捅穿，哀嚎不已。你决定……？",
[2435]="<color=#549327>[判定成功]</color> 你先手占了上风，却未有丝毫大意，而是沉着果断地连运法诀，金气如雨如针，铺天盖地无孔不入，猴王的一身皮毛难以抵御锐利金气，接连受创。",
[2436]="此消彼长之下，猴王伤痕累累，竟有了逃跑之意。你立刻断其后路，金气成箭，将猴王扎成了血葫芦，生机断绝。",
[2437]="打了许久，双方皆有负伤。灵力的剧烈消耗让你的丹田都有些抽痛，不能再拖下去！最终，拼着腹部被狠狠抓伤，你找准空隙，凝金气成灵剑，斩断了猴王的头颅。",
[2438]="猴王既死，你拖着伤躯找到了被藏起来的秘宝，连忙祭出符箓远遁而走。虽然受伤不轻，但目的达成，总算不枉此行。养好伤后，你闭关苦修，修为又进一步。",
[2439]="打定主意，你谨慎地与猴王保持距离，舌绽莲花般沟通了许久，手中掐着的法诀也一直在变幻，隐隐威慑对方……终于，你劝服猴王交出了秘宝。",
[2440]="<color=#c82c2c>[判定失败]</color> 据你打探的情报，猴王乃木属大妖，你修习之锐金诀若能熟练运用，应有五行克制之效。你抬手掐诀，金气幻化成箭，朝猴王射去。",
[2441]="不料对方行动敏捷，三两下避开了你的攻击，更是趁机拉进距离，举爪朝你狠狠抓下！闪躲不及的你右臂负伤，深可见骨。你决定……？",
[2442]="<color=#549327>[判定成功]</color> 猴王凶猛，此时已落下风，更不能退，否则小命难保。你愈发沉稳，没有浪费一丝灵力，锐金诀使出，每一式都见血光！最终，你拼着腹部受创，换得空档全力挥出金气凝结成的长刀，斩下了猴王的头颅。",
[2443]="最终，拼着左肩受创，你猛地聚灵为刀，金气光刃锋锐，逼得猴王退了数步，为你争得一个空档砸出传送符远遁……重伤之下，你只能仓皇逃离此地，寻一处安全所在好好养伤。",
[2444]="<color=#549327>[判定成功]</color> 听闻猴王凶猛，你欲智取，假作灵力低微的修士误入此地，瑟瑟发抖地看向猴王。对方不以为意地举爪朝你拍下，以为能轻松将你碾死。",
[2445]="不料你一个矮身，金属灵力凝成的利箭狠狠穿透了猴王肋下，带出一蓬血雾。猴王登时受到重创，哀嚎不已，你决定……?",
[2446]="劝服对方 [机缘判定]",
[2447]="<color=#549327>[判定成功]</color> 你示弱取得优势，却未敢大意，更为谨慎地将锐金诀使出，锐利金气从无落空，逼使猴王带伤迎战，伤口越来越多……",
[2448]="此消彼长之下，你出手愈发刁钻，而猴王伤痕累累，竟有了逃跑之意。你立刻断其后路，金气成矛穿心而过！猴王轰然倒地。",
[2449]="<color=#c82c2c>[判定失败]</color> 一个照面便占了上风，你不免有些急切，出手未有先前谨慎。然而猴王岂是易与之辈，在伤痛的刺激之下，凶性更盛，竟连出狠招，缠斗之下，你身上的伤口也多了起来。",
[2450]="灵力的剧烈消耗让你的丹田都有些抽痛，不能再拖下去！最终，拼着腹部被重创，你找准空隙全力使出金气疾雨，将猴王扎成了血葫芦。",
[2451]="打定主意，你谨慎地与猴王保持距离，舌绽莲花般沟通了许久，金气也在你的法诀之下幻化成不同模样，震慑对方……终于，猴王轻轻点头，同意交出秘宝换其全身而退。",
[2452]="<color=#c82c2c>[判定失败]</color> 听闻猴王凶猛，你欲智取，假作灵力低微的修士误入此地，瑟瑟发抖地看向猴王。不料对方仿佛嗅出了什么气息，极为慎重地朝你扑来，举爪便是全力。",
[2453]="<color=#549327>[判定成功]</color> 你的计划失败，此刻已落下风，更不能退，否则小命难保。你愈发沉稳，迎战凶狠的猴王亦未乱了阵脚。",
[2454]="手中锐金诀熟练运用，术法变幻无穷，抵御对方的攻势。最终，你拼着腹部受创，换得空档挥出金气凝结的长刀，斩下了猴王的头颅。",
[2455]="最终，拼着左肩受创，近距离挥出金气凝结的长鞭将猴王逼退数步，争得一个空档砸出传送符远遁……重伤之下，你只能仓皇逃离此地，寻一处安全所在好好养伤。",
[2456]="<color=#549327>[判定成功]</color> 机缘险中求，强敌更能激发自身潜能。你快速飞身而上，手中法诀变幻，灵气化作漫天箭雨，朝猴王袭去。",
[2457]="灵箭密集，猴王闪躲之下未能全部避开，身上被扎出数个血洞，哀嚎不已。你决定……？",
[2458]="<color=#549327>[判定成功]</color> 你先手占了上风，却未有丝毫大意，而是沉着果断地继续将术法使出，灵力如雨如针，无孔不入锐利无比，令猴王庞大的身躯接连受创。",
[2459]="此消彼长之下，猴王伤痕累累，竟有了逃跑之意。你立刻断其后路，灵力凝成长枪，将猴王扎了个对穿，生机断绝。",
[2460]="打了许久，双方皆有负伤。灵力的剧烈消耗让你的丹田都有些抽痛，不能再拖下去！最终，拼着腹部被狠狠抓伤，你找准空隙，将灵力附着在灵器之上，狠狠斩断了猴王的头颅。",
[2461]="<color=#c82c2c>[判定失败]</color> 机缘险中求，强敌更能激发自身潜能。你抬手掐诀，术法运出，灵气成矛，朝猴王狠狠捅去！",
[2462]="<color=#549327>[判定成功]</color> 猴王凶猛，此时已落下风，更不能退，否则小命难保。你愈发沉稳，没有浪费一丝灵力，术法接连运出，每一式都见血光！最终，你拼着腹部受创，换得空档全力挥出灵力凝成的长剑，斩下了猴王的头颅。",
[2463]="最终，拼着左肩受创，你猛地聚灵为刀，灵刃锋锐，逼得猴王退了数步，为你争得一个空档砸出传送符远遁……重伤之下，你只能仓皇逃离此地，寻一处安全所在好好养伤。",
[2464]="不料你一个矮身，灵力凝成的利箭穿透了猴王的肩胛骨，对方登时受到重创，哀嚎不已，你决定……?",
[2465]="<color=#549327>[判定成功]</color> 你示弱取得优势，却未敢大意，更为谨慎地将术法使出，进攻的招式从无落空，逼使猴王带伤迎战，伤口越来越多……",
[2466]="此消彼长之下，你出手愈发刁钻，而猴王伤痕累累，竟有了逃跑之意。你立刻断其后路，灵力成矛穿心而过！猴王轰然倒地。",
[2467]="灵力的剧烈消耗让你的丹田都有些抽痛，不能再拖下去！最终，拼着腹部被重创，你找准空隙全力射出灵箭，将猴王扎成了血葫芦。",
[2468]="打定主意，你谨慎地与猴王保持距离，舌绽莲花般沟通了许久，手中掐着的法诀也一直在变幻，隐隐威慑对方……终于，猴王轻轻点头，同意交出秘宝换其全身而退。",
[2469]="<color=#c82c2c>[判定失败]</color> 听闻猴王凶猛，你欲智取，假作灵力低微的修士误入此地，瑟瑟发抖地看向猴王。",
[2470]="不料对方仿佛嗅出了什么气息，极为慎重地朝你扑来，举爪便是全力。你连忙回退闪躲，却还是被狠狠抓伤了后背，鲜血瞬间濡湿了衣衫。你决定……？",
[2471]="一招接着一招，你之术法变幻无穷，抵御对方的攻势。最终，你拼着腹部受创，换得空档挥出灵力凝结的长刀，斩下了猴王的头颅。",
[2472]="最终，拼着左肩受创，近距离凝结出数支灵箭将猴王逼退一段距离，争得一个空档砸出传送符远遁……重伤之下，你只能仓皇逃离此地，寻一处安全所在好好养伤。",
[2473]="一路有惊无险，机缘巧合之下，你意外来到了一处偏殿，殿内存有无极丹，此乃不可多得的在提升修为之外更能增加神识的失传丹药……",
[2474]="锋芒不让 [以水克火]",
[2475]="<color=#549327>[判定成功]</color> 邪修行御火诀，攻势凶猛；你运御水诀，亦锋芒不让，澎湃巨浪铺天盖地般朝对方席卷而去！",
[2476]="对方未能料到你乃水行修士，对其有克制之力，愣神之下竟被你藏在水浪中的水属灵箭扎穿了腹部，登时血流如注。你决定……？",
[2477]="<color=#549327>[判定成功]</color> 初回交手你便略胜一筹，顿时有了底气，信心倍增地继续进攻。水属术法一道接一道地运出，攻击角度刁钻凌厉，邪修连运御火之术，却难阻连绵攻势！",
[2478]="缠斗许久，邪修身上的伤口越来越多，脸色惨白，竟有退却之意。你立刻抓准时机挥出水属灵鞭，干脆利落地绞断了对方的头颅。",
[2479]="<color=#c82c2c>[判定失败]</color> 初回交手你便略胜一筹，顿时更为激进地展开攻势。然而邪修根基深厚，受伤后更是使出十成十的狠辣手段与你相搏！你来我往缠斗许久，双方皆添新红。\n",
[2480]="灵力的剧烈消耗让你的丹田都有些抽痛，再拖下去必败！你咬牙加快进攻，不惜以伤换命，在邪修打断你肋骨的同时以水属灵力凝成的长矛刺穿了对方的心口。",
[2481]="你刻意风筝般地耗去大半时辰，眼见邪修气喘吁吁，脸色更加苍白，便知时机已至，干脆利落地回身拉进距离，水属灵力凝成利刃，将邪修捅了个对穿。",
[2482]="<color=#c82c2c>[判定失败]</color> 邪修行御火诀，攻势凶猛，你运御水诀，亦锋芒不让，然而邪修对敌经验多你十倍有余。",
[2483]="你一招不慎，便被其捉了空档，灵火狠狠灼伤了你的肩背，登时痛得脸色煞白。情急之下，你决定……？",
[2484]="<color=#549327>[判定成功]</color> 此时若退，定然九死一生，不如放手一搏！你愈发谨慎，进退有度，气势始终未落下风。最终，你拼着腹部受创，以伤换命地以水属灵力凝成的长刀斩断了邪修的脖颈，令其气绝而亡。",
[2485]="最终，拼着右臂折断，你以数枚水箭逼退对方数步，争得一个空档砸出传送符远遁……重伤之下，你拼命地逃离秘境，一心只想着寻一处安全所在静心养伤。",
[2486]="邪修一招不及收势，你立刻凝成水属灵矛直穿对方肋下，带出一蓬血雾。邪修登时发出一声痛苦的闷哼。你决定……？",
[2487]="<color=#549327>[判定成功]</color> 以退为进一击得手，你有了底气，战意也愈发高涨。水属术法一道接一道地运出，攻击角度刁钻凌厉，邪修连运御火之术，却难阻连绵攻势！",
[2488]="缠斗许久，邪修身上的伤口越来越多，脸色惨白，竟有退却之意。你立刻抓准时机全力挥出水刃，寒光自邪修颈间一闪而没，下一瞬，对方轰然倒地。",
[2489]="<color=#c82c2c>[判定失败]</color> 以退为进一击得手，你有了底气，战意也愈发高涨。然而邪修根基深厚，受伤后更是使出十成十的狠辣手段与你相搏！",
[2490]="你来我往缠斗许久，双方皆添新红。灵力的剧烈消耗让你的丹田都有些抽痛，再拖下去必败！你咬牙加快进攻，不惜以伤换命，在邪修打断你肋骨的同时以水属灵力凝成的长矛刺穿了对方的心口。",
[2491]="然而邪修对敌经验老道，你一步退，便被逼得步步退，仓促之间被对方捉住空隙，以火箭射穿了你的肩胛，你登时疼得血色尽褪，决定……？",
[2492]="<color=#549327>[判定成功]</color> 负伤欲退定是步步艰险，不如放手一搏！你愈发谨慎，进退有度，气势始终未落下风。最终，你拼着腹部受创，以伤换命地以水属灵力凝成的长刀斩断了邪修的脖颈，令其气绝而亡。",
[2493]="正当你准备取回无极丹时，心中突然警铃大作，下意识地矮身避开了身后突然袭来的攻击。你提起戒备迅速回身望去，只见一名邪修牢牢盯着你，露出了不怀好意的狠辣神色，你决定……？",
[2494]="<color=#549327>[判定成功]</color> 邪修行御火诀，攻势凶猛；你连掐数诀，亦锋芒不让，灵力化作漫天箭雨般朝对方袭去！箭雨密集，对方未能全部避开，竟被数枚灵剑扎穿了肩胛，登时血流如注。你决定……？",
[2495]="<color=#549327>[判定成功]</color> 初回交手你便略胜一筹，顿时有了底气，信心倍增地继续进攻。术法一道接一道地运出，攻击角度刁钻凌厉，邪修连运御火之术，却难阻连绵攻势！",
[2496]="缠斗许久，邪修身上的伤口越来越多，脸色惨白，竟有退却之意。你立刻抓准时机挥出灵鞭，以十成力道干脆利落地绞断了对方的头颅。",
[2497]="<color=#c82c2c>[判定失败]</color> 初回交手你便略胜一筹，顿时更为激进地展开攻势。然而邪修根基深厚，受伤后更是使出十成十的狠辣手段与你相搏！你来我往缠斗许久，双方皆添新红。",
[2498]="灵力的剧烈消耗让你的丹田都有些抽痛，再拖下去必败！你咬牙加快进攻，不惜以伤换命，在邪修打断你肋骨的同时将灵力全部注入灵器之内，利刃瞬间刺穿了对方的心口。",
[2499]="你刻意风筝般地耗去大半时辰，眼见邪修气喘吁吁，脸色更加苍白，便知时机已至，干脆利落地回身拉进距离，灵力凝成利刃，将邪修捅了个对穿。",
[2500]="<color=#c82c2c>[判定失败]</color> 邪修行御火诀，攻势凶猛；你连掐数诀，亦锋芒不让。然而邪修对敌经验多你十倍有余，你一招不慎，便被其捉了空档，灵火狠狠灼伤了你的肩背，登时痛得脸色煞白。情急之下，你决定……？",
[2501]="<color=#549327>[判定成功]</color> 此时若退，定然九死一生，不如放手一搏！你愈发谨慎，进退有度，气势始终未落下风。最终，你拼着腹部受创，以伤换命地以灵力凝成长刀，斩断了邪修的脖颈，令其气绝而亡。",
[2502]="最终，拼着右臂折断，你以数枚灵箭逼退对方数步，争得一个空档砸出传送符远遁……重伤之下，你拼命地逃离秘境，一心只想着寻一处安全所在静心养伤。",
[2503]="邪修一招不及收势，你立刻以灵力凝成长枪，直穿对方肋下，带出一蓬血雾。邪修登时发出一声痛苦的闷哼。你决定……？",
[2504]="<color=#549327>[判定成功]</color> 以退为进一击得手，你有了底气，战意也愈发高涨。术法一道接一道地运出，攻击角度刁钻凌厉，邪修连运御火之术，却难阻连绵攻势！",
[2505]="缠斗许久，邪修身上的伤口越来越多，脸色惨白，竟有退却之意。你立刻抓准时机全力挥出灵刃，寒光自邪修颈间一闪而没，下一瞬，对方轰然倒地。",
[2506]="你来我往缠斗许久，双方皆添新红。灵力的剧烈消耗让你的丹田都有些抽痛，再拖下去必败！你咬牙加快进攻，不惜以伤换命，在邪修打断你肋骨的同时以灵力凝成长矛，刺穿了对方的心口。",
[2507]="<color=#549327>[判定成功]</color>负伤欲退定是步步艰险，不如放手一搏！你愈发谨慎，进退有度，气势始终未落下风。最终，你拼着腹部受创，以伤换命地以灵力凝成长刀，斩断了邪修的脖颈，令其气绝而亡。",
[2508]="今日不知怎的，你有些心浮气躁，打坐运功时只觉得灵力运转迟滞，十分难受。你干脆起身出门，在宗门内四处闲逛，一日就这么无所事事的过去了。",
[2509]="<color=#3375c0>[资质判定]</color> 唔，嗯……嗯？！你不过是在修炼时打了个盹……",
[2510]="<color=#549327>[判定成功]</color> 睁眼时，百年弹指，元神凝练，修为又进一步。",
[2511]="<color=#c82c2c>[判定失败]</color> 睁眼时虽是神清气爽，但百年弹指，一无所获。",
[2512]="在宗门藏经阁翻阅典籍时，你意外发现一部棋局残谱，据传是一位宗门前辈飞升之前留下的，千百年来一直无人能解。",
[2513]="你本打算当个消遣随便看看，不料看着看着竟彻底沉迷了进去……从此你一心钻研这本残谱，如痴如醉，荒废修行不知多少岁月。",
[2514]="待你自这棋局残谱之中脱离，走出藏经阁时，只见风景已易，诸多陌生面孔来往匆匆。问过守阁长老方才知晓，你这一钻研，竟是过去了半个甲子",
[2515]="悟己，悟道，悟天地……你悟着悟着，悟入梦中。梦醒时，岁月如逝水。",
[2516]="境界又至瓶颈期，你再试锁妖塔，遗憾止步于百层之内；寻来珍贵丹药强行提升，导致根基虚浮，再行运功时，险些令你跌落回结丹境界……后怕不已的你最终决定老实地打坐观想，却是难有寸进。",
[2517]="<color=#3375c0>[资质判定]</color> 你在宗门藏经阁找到几部契合己身心法的剑诀，如获至宝，贪心地想全都学了……",
[2518]="<color=#549327>[判定成功]</color> 为此，你日夜钻研，几近废寝忘食，终于将这几部剑诀彻底融会贯通。由此，修为又有进境。",
[2519]="<color=#c82c2c>[判定失败]</color> 不料却是悟性有限，贪多而嚼不烂，关起门来研究了数十年都不得要领。",
[2520]="“锵”！你手腕一麻，灵剑应声而落，师弟则剑锋已至，离你咽喉只差毫厘。“我又胜啦！”师弟高兴地嚷嚷着，“走，今天也比够了，咱们喝酒去。”",
[2521]="你看着师弟兴致勃勃的模样，只得默默地收起灵剑，点点头与他一同离开。身侧之人神采飞扬，一路无言的你心里却在苦笑，不知自己何时便成了那前浪，只配被那些天之骄子飞速越过，拍在滩头……",
[2522]="你试图重新打造一柄本命灵剑，为此消耗诸多资源打造了一枚极好的剑胚，却在锻造灵剑的最后一道工序时力竭，以至功亏一篑。",
[2523]="体内灵力空空，剑胚亦废，你气得脸色铁青，心痛不已，数个月都没缓劲过来。",
[2524]="夏季酷暑，你在宗门后山找到一个得天独厚的山洞，内有寒潭，环境清凉，正是适合避暑修行。",
[2525]="在此闭关的你尝试通过冥想领悟剑意，以图心神与剑合一，提升自己的剑道境界……但环境太过舒适，冥想、冥想，不如一觉酣梦好眠，梦醒不知今夕何年。",
[2526]="听闻师父即将闭关，在此之前，准备指点一番座下的弟子们，你亦前去与师父过招受教。",
[2527]="一剑，两剑，五剑！……很好，气喘吁吁的你瘫软在地，一边听师父讲道，一边想了想自己从最初的一招即败，到现在能扛五招，也算有所进步吧。",
[2528]="<color=#3375c0>[资质判定]</color> 你在宗门藏经阁找到几部契合己身心法的奇门术法，如获至宝，贪心地想全都学了……",
[2529]="<color=#549327>[判定成功]</color> 为此，你日夜钻研，几近废寝忘食，终于将这几部术法彻底融会贯通。由此，修为又有进境。",
[2530]="“你输了。”随着这句话音在耳边落下，你尚且不及作出应对，便被一座水牢死死囚住，无法挣脱。在你将要窒息的刹那，水牢无声自散，你瞬间跌坐在地，猛地喘气，一身湿透狼狈不堪。",
[2531]="不远处的师妹巧笑倩兮，朝你拱了拱手：“小妹技痒，做得过了些，师兄海涵呐~”你无力地摆了摆手示意无妨，内心却苦笑不已……",
[2532]="这就是天水灵根的天之骄女么，进步神速如斯，你不过是对方修行途中的一块磨刀石罢了。",
[2533]="不远处的师妹巧笑倩兮，朝你拱了拱手：“小妹技痒，做得过了些，师姐海涵呐~”你无力地摆了摆手示意无妨，内心却苦笑不已……",
[2534]="你试图为自己的防身宝甲再加一道强力的防御法阵，却在篆刻到最后一笔时力竭，以至功亏一篑。体内灵力空空，宝甲升阶不成反而变废，你气得脸色铁青，数个月都没缓劲过来。",
[2535]="冬季严寒，你在宗门后山找到一个得天独厚的山洞，内有熔浆地脉，温泉汩汩，环境暖融，正是适合寒冬修行。",
[2536]="在此闭关的你尝试通过冥想拓宽识海，以图神识进一步增强，提升自己的术法境界……但环境太过舒适，冥想、冥想，不如一觉酣梦好眠，梦醒不知今夕何年。",
[2537]="敛息，瞬移，金芒如刺！……很好，气喘吁吁的你瘫软在地，一边听师父讲道，一边想了想自己从最初的一招即败，到现在能扛五招，也算有所进步吧。",
[2538]="敛息，瞬移，百木成箭！……很好，气喘吁吁的你瘫软在地，一边听师父讲道，一边想了想自己从最初的一招即败，到现在能扛五招，也算有所进步吧",
[2539]="敛息，瞬移，水漫金山！……很好，气喘吁吁的你瘫软在地，一边听师父讲道，一边想了想自己从最初的一招即败，到现在能扛五招，也算有所进步吧。",
[2540]="敛息，瞬移，火凤燎原！……很好，气喘吁吁的你瘫软在地，一边听师父讲道，一边想了想自己从最初的一招即败，到现在能扛五招，也算有所进步吧。",
[2541]="敛息，瞬移，石坠千斤！……很好，气喘吁吁的你瘫软在地，一边听师父讲道，一边想了想自己从最初的一招即败，到现在能扛五招，也算有所进步吧。",
[2542]="游历中途，你路遇一行脚商，对方虽然只有筑基修为，却落落大方令人心生好感，极为善谈。你看了看他口若悬河地推销的货物，倒也有几样合用的资源，便讨价还价买了下来，也算是买卖合意。",
[2543]="心血来潮，你突然想回到尚未踏上修行之路前生活的地方看一看……百年沧桑，物非人去，终不似当年。",
[2544]="你望着眼前不再熟悉的景色，半晌，倏忽一笑，只觉得前尘皆去，心境澄明，竟是有所提升。",
[2545]="你前往一处上古秘境历练，被传送阵抛进了一片长满灵药的山谷，尽情采摘了一遍之后，你欲离开，只能设法渡过环谷而绕的大河。",
[2546]="你小心翼翼地行至河心，却见河面缓缓显现一个漩涡，硕大的黑虬头颅浮出水面，直直盯着你。",
[2547]="你心下一惊，却不动声色地仔细观察起来，登时两相僵持……细看之下，这黑虬老态尽显，怕是大限将至，不知活了多少年岁……",
[2548]="你暗叹一声，恭敬朝黑虬行礼，道：“在下只是路过，无意与尊驾为难，这便离去，还望尊驾莫要阻拦。”",
[2549]="虬龙闻言，正是纹丝不动，果然早开灵智，可通人语。你放下心来，连忙赶路，踏上岸时，却听见一道苍老的声音传来：“小儿心善，老朽感念，以此相赠。”",
[2550]="身后响起风声，你下意识地回首一抓，竟是一团龙气扑面而来，满含温和善意，内中竟包裹着数枚鳞片和龙须，都是可遇不可求的修行至宝。",
[2551]="你连忙再次朝那黑虬行礼：“多谢尊驾，就此别过！”黑虬此时头颅一点，便潜回河面之下，再无声息。如此机缘，实在令你惊叹不已。",
[2552]="<color=#3375c0>[资质判定]</color> 途经一座凡人城镇，城郊的一处道观巍然而立，青烟缭绕，颇有几分仙家气韵，你心下好奇不已……",
[2553]="<color=#549327>[判定成功]</color> 干脆在这道观歇脚，更与道观住持玄机子对弈了一局。棋局虽小，可见江山，触类旁通，你由此领悟不少修行之理，受益匪浅。",
[2554]="<color=#c82c2c>[判定失败]</color> 干脆在这道观歇脚，更与道观住持玄机子对弈了数局，竟是负多胜少。你不禁感慨，真是人外有人，天外有天，凡俗之地亦有奇人妙观，不可小觑。",
[2555]="时光飞逝，多宝楼的夺宝会再开，广邀天下修士前来闯关。如今的你已是元婴修为，正好再去试上一试！",
[2556]="此回闯关的你可谓风采尽显，在根基比拼和神识比拼的关卡都拿下很好的名次，顺利获得了之后进阶化神期时至关重要的珍宝资源。",
[2557]="穿越崇山峻岭时，你误入一处迷雾山林。迷雾诡谲，山林之内幻象丛生，你时刻提醒自己保持清醒，以坚定的道心逐一破除幻境，终于脱身而出。因祸得福，你的心境又有提升。",
[2558]="平原之地，水草丰美，良田如云，然水患亦多。雨季已至，你正好途经一处凡人村落，山洪来得突然，情急之下，你竭力设下护阵阻拦洪流，移土搬山，将水患平息，及时拯救了即将被洪水吞没的村庄和村民。",
[2559]="众人朝你便拜，口中喃喃“多谢神仙相救”，你不欲与凡间牵连过深，动念之间便已离去。只道是冥冥之中自有天意，此地百姓命不该绝。",
[2560]="深入蛮夷之地，你不慎陷入一处毒沼，所幸以你如今的修为，净化这片毒沼不算难事。",
[2561]="你抛出符阵，以雄浑灵力推动净化符阵扩散开去，毒气随之一清。霎时百花盛开，远处更有灵兽三三两两地朝你跪伏，似在感激你之善行，正可谓万物有灵。",
[2562]="你在探索冰湖外围时，不慎坠入一处深渊。你本以为定是九死一生，不料深渊之下暗藏玄机，柳暗花明，竟来到一座古墓之中。",
[2563]="小心探索之下，你发现了此墓之主留下的手札，记载了其毕生修炼的心得，于你大有益处，真是意外之喜。",
[2564]="游历多时，你之积累雄厚，进阶突破所需的资源亦已备齐。外出许久，你的心境阅历都与当初大有不同，终究到了踏上归途的时候。",
[2565]="回到宗门，你立刻闭关……打坐运功，气息稳步攀升，你的身躯仿佛化作一个无底漩涡，灵气呼啸犹如实质般被你鲸吞入体……轰！紫府开，乾坤现，你已顺利突破至化神期。",
[2566]="回宗进阶",
[2567]="游历多时，积累雄厚，你回到宗门闭关，突破至化神期。",
[2568]="西境有上古剑冢现世，你日夜兼程，总算没有落人一步。胆大心细的你巧解机关、智破迷阵、力抗威压……最终，除了数柄上好灵剑之外，你总算收获了与己身之道契合的剑道传承，实是获益匪浅。",
[2569]="游历中途，邪修拦路，唯有战！邪修狡诈嗜血，阴招邪术层出不穷，你不曾有丝毫胆怯，一往无前，自当所向披靡。",
[2570]="剑意冲霄，斩！斩！斩！一蓬血雾飞散，邪修亡于你之剑下。你看了看手臂上深可见骨的伤口，却是忍不住露出了笑容，此战胜！",
[2571]="<color=#3375c0>[概率判定]</color> 在一处上古洞府遗迹中，机缘巧合之下，你收获了不少天材地宝，折返离开的途中却被一群不怀好意的修士堵住了去路。看着对方眼中毫不掩饰的贪婪神色，你只能拼尽全力一战！",
[2572]="<color=#549327>[判定成功]</color> 命悬一线的危机感令你不敢有丝毫分神，全神贯注以剑迎敌的你愈发忘我，直至人剑合一，唯有剑气横扫千军，无坚不摧！……直至最后一人倒下，你才从玄而又玄的意境中脱离，竟是又有进境！",
[2573]="<color=#c82c2c>[判定失败]</color> 然而对方人多势众，你逐渐落入下风，支撑得愈发艰难。",
[2574]="暗道不妙的你咬牙将心头血逼出，喷于剑上，趁着血祭导致的剑气暴涨的瞬间扔出大把符箓，勉力脱出重围，头也不回地拼命逃离……精血亏空的你休养了许久方才有所好转。",
[2575]="<color=#3375c0>[概率判定]</color> 在一处秘境之中，你与一头高阶虎妖相遇，其身躯犹如铜皮铁骨一般，一身妖力凝如实质，张口便可吐出利刃般锋利的旋风。你将周身剑意运转到极致，剑气如啸，与虎妖狠狠相撞，眨眼间碰撞不下百十回……",
[2576]="<color=#549327>[判定成功]</color> 终于，半身浴血的你艰难地在其身上留下千百创口，终于斩杀了这头虎妖。几近虚脱的你瘫坐在地，但看着已然没了气息的对手，想到对方一身骨肉以及妖血妖丹之妙用，忍不住心头火热，此战收获颇丰！",
[2577]="<color=#c82c2c>[判定失败]</color> 不妙！灵力消耗过大的你渐渐落于下风，咬牙拼着一记旋风重创左肩，你豁命般在虎妖身上留下一道深可见骨的伤口，趁着对方吃痛连忙头也不回地逃离……",
[2578]="险而又险地摆脱了虎妖之后，你狼狈地设法离开秘境，重伤之躯休养许久方才有所好转。",
[2579]="<color=#3375c0>[概率判定]</color> 游历中途，你误入一处猴妖盘踞的山林，情急之下只能仓促应战。",
[2580]="<color=#549327>[判定成功]</color> 狭路相逢勇者胜，你将剑意发挥到了十成十，剿灭了绝大部分猴妖，只余零星几只逃到了更隐蔽的深山老林之中，再不见踪影。",
[2581]="你顺势接手了猴妖群的珍藏宝贝，除了诸多灵果灵草和一些破损的储物袋之外，竟还有几坛猴儿酒，真是意外之喜。",
[2582]="<color=#c82c2c>[判定失败]</color> 猴妖群占尽地利，灵活地从各种刁钻角度发动偷袭，灵力消耗越来越大的你脸色渐渐苍白，最终只能不甘心地带着一身伤痕，狼狈地逃离了这片山林。",
[2583]="<color=#3375c0>[概率判定]</color> 游历中途，你发现本该富庶的平原之地水患却非同寻常，百姓过得十分艰难，一番查探之下发现竟是一群河妖作怪！为民除害义不容辞，你拔剑便战！",
[2584]="<color=#549327>[判定成功]</color> 任凭对方借水之力搅得巨浪滔天，你亦从容以对，将这群水妖逐一击破，直至全部斩于剑下。",
[2585]="罪魁祸首既灭，水患也立刻平息，百姓们热泪盈眶地俯身便拜，你却避而不受，踏剑凌空潇洒离去。",
[2586]="<color=#c82c2c>[判定失败]</color> 然而对方仰仗着纵横交错的河道水源，妖力近乎源源不绝，更是招来同伙，对你渐成围殴之势……心知不妙的你最终只能带着一身伤痛踏剑便逃，一人之力终究单薄啊……",
[2587]="<color=#3375c0>[概率判定]</color> 游历中途，你误入一处毒虫盘踞的洞穴，情急之下只能仓促应战。",
[2588]="<color=#549327>[判定成功]</color> 你将剑意发挥到了十成十，剑气如长眼一般四散绞杀，最终顺利剿灭了这凶恶毒虫。\n障碍扫清之后，你在洞穴中找到许多被毒虫霸占的资源宝物，也算是收获颇丰。",
[2589]="<color=#c82c2c>[判定失败]</color> 毒虫铺天盖地，无孔不入，你虽然已经十分小心，还是免不了被一些毒虫蜇伤。",
[2590]="毒素渐渐蔓延，身体逐渐发麻的你心知不妙，连忙服下丹药暂且压制，头也不回地逃离了这处洞穴。余毒难清，你调理了许久方才有所好转，但依然心有余悸，身体也大不如前。",
[2591]="<color=#3375c0>[概率判定]</color> 游历中途，暴风雪忽至。情急之下你找了处山洞暂避，不料却闯入了一群冰蛾的领地。",
[2592]="<color=#549327>[判定成功]</color> 比人脸还大的冰蛾纷纷煽动翅膀向你扑来，你心中一凛，拔剑凝神以对！",
[2593]="一只、十只、百只……剑气如芒，顽强地以你为中心扩散开去，切割围剿这群冰蛾。终于，一地冰粉，皆是蛾尸。你疲惫地喘息着，却意外发觉自身剑意又凝实了许多。",
[2594]="<color=#c82c2c>[判定失败]</color> 比人脸还大的冰蛾纷纷煽动翅膀向你扑来，你心中一凛，拔剑凝神以对！一只、十只、百只……不行！实在太多了！",
[2595]="你感觉到体内灵力的急速流失，当机立断转身逃离这处山洞。在暴风雪中艰难跋涉的你好不容易找到一处巨岩暂避，虽然冻伤严重，但好歹一条小命是保住了。",
[2596]="南边有上古遗迹现世，你日夜兼程，总算没有落人一步。胆大心细的你巧解机关、智破迷阵、力抗威压……最终，除了数件上好的灵器之外，你总算收获了与己身之道契合的术法传承，实是获益匪浅。",
[2597]="游历中途，邪修拦路，唯有战！邪修狡诈嗜血，阴招邪术层出不穷，你不曾有丝毫胆怯，一往无前，自当所向披靡……",
[2598]="金锐之气凝成雷龙咆哮而出，一蓬血雾飞散，邪修气绝当场。你看了看手臂上深可见骨的伤口，却是忍不住露出了笑容，此战胜！",
[2599]="无边木力化作凶藤利叶朝对方围剿而去，一蓬血雾飞散，邪修气绝当场。你看了看手臂上深可见骨的伤口，却是忍不住露出了笑容，此战胜！",
[2600]="空中水汽凝成水龙席卷而去，一蓬血雾飞散，邪修气绝当场。你看了看手臂上深可见骨的伤口，却是忍不住露出了笑容，此战胜！",
[2601]="火凤显形，戾叫之下焰羽燎原，一蓬血雾飞散，邪修气绝当场。你看了看手臂上深可见骨的伤口，却是忍不住露出了笑容，此战胜！",
[2602]="石虎咆哮而踏，在百丈地裂之中猛然朝对方攻去，一蓬血雾飞散，邪修气绝当场。你看了看手臂上深可见骨的伤口，却是忍不住露出了笑容，此战胜！",
[2603]="<color=#3375c0>[概率判定]</color> 在一处秘境中，机缘巧合之下，你收获了不少天材地宝，折返离开的途中却被一群不怀好意的修士堵住了去路。看着对方眼中毫不掩饰的贪婪神色，你只能拼尽全力一战！\n",
[2604]="<color=#549327>[判定成功]</color> 命悬一线的危机感令你不敢有丝毫分神，灵器加持之下，术法如臂指使，铺天盖地般笼罩对方！……直至最后一人倒下，你才从玄而又玄的意境中脱离。",
[2605]="暗道不妙的你咬牙将心头血逼出，喷于灵器上，趁着血祭导致的灵力暴涨的瞬间扔出大把符箓，勉力脱出重围，头也不回地拼命逃离……精血亏空的你休养了许久方才有所好转。",
[2606]="<color=#3375c0>[概率判定]</color> 在一处秘境之中，你与一头高阶豹妖相遇，其身躯犹如铜皮铁骨一般，一身妖力凝如实质，张口便可吐出利刃般锋利的旋风。",
[2607]="<color=#549327>[判定成功]</color>试探过后，你不禁大喜！此妖铜皮铁骨为金锐之气所克！你将周身灵力运转到极致，金芒席卷，与豹妖狠狠相撞，眨眼间碰撞不下百十回……",
[2608]=" 终于，半身浴血的你艰难地在其身上留下千百创口，再借灵器之利，终于斩杀了这头豹妖。",
[2609]="几近虚脱的你瘫坐在地，但看着已然没了气息的对手，想到对方一身骨肉以及妖血妖丹之妙用，忍不住心头火热，此战收获颇丰！",
[2610]="<color=#c82c2c>[判定失败]</color> 不妙！灵力消耗过大的你渐渐落于下风，咬牙拼着一记旋风重创左肩，你豁命般在豹妖身上留下一道深可见骨的伤口，趁着对方吃痛连忙头也不回地逃离……",
[2611]="险而又险地摆脱了豹妖之后，你狼狈地设法离开秘境，重伤之躯休养许久方才有所好转。",
[2612]="<color=#549327>[判定成功]</color> 试探过后，你不禁大喜！此妖口中的旋风为木气所克！你将周身灵力运转到极致，催生藤蔓纠缠成盾挡下旋风，再将木气化针化箭，与豹妖狠狠相撞，眨眼间碰撞不下百十回……",
[2613]="终于，半身浴血的你艰难地在其身上留下千百创口，再借灵器之利，终于斩杀了这头豹妖。",
[2614]="<color=#549327>[判定成功]</color> 试探过后，你不禁大喜！此妖畏水！你将周身灵力运转到极致，水龙席卷，与豹妖狠狠相撞，眨眼间碰撞不下百十回……",
[2615]="终于，半身浴血的你艰难地以水牢将其困住，再借灵器之利，终于斩杀了这头豹妖。",
[2616]=" <color=#3375c0>[概率判定]</color> 在一处秘境之中，你与一头高阶豹妖相遇，其身躯犹如铜皮铁骨一般，一身妖力凝如实质，张口便可吐出利刃般锋利的旋风。",
[2617]="<color=#549327>[判定成功]</color> 试探过后，你不禁大喜！此妖畏火！你将周身灵力运转到极致，烈炎席卷，与豹妖狠狠相撞，眨眼间碰撞不下百十回……",
[2618]="终于，半身浴血的你艰难地在其身上留下大片焦黑，再借灵器之利，终于斩杀了这头豹妖。",
[2619]="<color=#549327>[判定成功]</color> 试探过后，你不禁大喜！此妖口中的旋风为土气所克！你将周身灵力运转到极致，以土石凝结成盾挡下旋风，再凝出土石巨人，与豹妖狠狠相撞，眨眼间碰撞不下百十回……\n",
[2620]="终于，半身浴血的你艰难地将其砸倒在地，再借灵器之利，终于斩杀了这头豹妖。",
[2621]="<color=#3375c0>[五行判定]</color> 游历中途，你误入一处猴妖盘踞的山林，情急之下只能仓促应战。",
[2622]="<color=#549327>[判定成功]</color> 猴妖毛发硬如钢针，所幸你修习之锐金诀锋锐无比，对付这群猴妖恰能事半功倍……",
[2623]="金雨如利剑般袭向猴群，你耗费了一番力气，剿灭了绝大部分猴妖，只余零星几只逃到了更隐蔽的深山老林之中，再不见踪影。",
[2624]="<color=#3375c0>[五行判定]</color> 游历中途，你发现本该富庶的平原之地水患却非同寻常，百姓过得十分艰难，一番查探之下发现竟是一群河妖作怪！",
[2625]="<color=#549327>[判定成功]</color> 任凭对方借水之力搅得巨浪滔天，你亦从容以对，控水之术如臂使指，力压水妖一头，直至将其逐一击破，全部气绝当场。",
[2626]="罪魁祸首既灭，水患也立刻平息，百姓们热泪盈眶地俯身便拜，你却避而不受，潇洒御风离去。",
[2627]="<color=#549327>[判定成功]</color> 任凭对方借水之力搅得巨浪滔天，你亦从容以对，控土之术如臂使指，水来土掩！以土克水，你力压水妖一头，直至将其逐一击破，全部气绝当场。",
[2628]="<color=#549327>[判定失败]</color> 为民除害义不容辞，你挺身便战！然而对方仰仗着纵横交错的河道水源，妖力近乎源源不绝，更是招来同伙，对你渐成围殴之势……心知不妙的你最终只能带着一身伤痛逃离，一人之力终究单薄啊……",
[2629]="<color=#3375c0>[五行判定]</color> 游历中途，你误入一处毒虫盘踞的洞穴，情急之下只能仓促应战。",
[2630]="<color=#549327>[判定成功]</color> 木气生机浓重，对毒瘴有克制之力，你以木气护体，藤条四散抽打，如长眼一般四散绞杀，最终顺利剿灭了这凶恶毒虫。障碍扫清之后，你在洞穴中找到许多被毒虫霸占的资源宝物，也算是收获颇丰。",
[2631]="<color=#3375c0>[五行判定]</color> 游历中途，暴风雪忽至。情急之下你找了处山洞暂避，不料却闯入了一群冰蛾的领地。",
[2632]="<color=#549327>[判定成功]</color> 比人脸还大的冰蛾纷纷煽动翅膀向你扑来，你心中一凛，凝神以对！一只、十只、百只……",
[2633]="火浪如云，克制冰蛾之力，顽强地以你为中心扩散开去，围剿这群冰蛾，直至一只不存。你疲惫地喘息着，在山洞深处搜出不少冰蛾囤积的资源收入囊中。",
[2634]="<color=#c82c2c>[判定失败]</color> 比人脸还大的冰蛾纷纷煽动翅膀向你扑来，你心中一凛，凝神以对！一只、十只、百只……不行！实在太多了！",
[2635]="南疆毒谷有奇光散溢，三月未散，是孕育千年的青圭果即将成熟的预兆。此果乃是罕有的奇珍，有凝练元神之功效。",
[2636]="你穿越层层毒瘴进入毒谷深处，势要取得青圭果。然而越是深入越是寂静得反常，你凝神戒备，只见浓雾之中正有一只巨大的毒蛾盘踞，俨然是虫王之姿。你决定……？",
[2637]="冲向毒蛾 [概率判定]",
[2638]="设法埋伏 [机缘判定]",
[2639]="<color=#549327>[判定成功]</color> 身形瞬动，你飞快地冲向毒蛾。长剑在手，剑气疾如风驰电掣，朝对方斩去，带着割裂空气的凌厉。",
[2640]="毒蛾察觉到危险，连忙振翅欲躲，然而速度却不及剑气之快，登时被扎穿羽翅，发出痛苦的鸣叫声。你决定……？",
[2641]="乘胜追击",
[2642]="此刻占了上风，你毫不犹豫地继续快攻，剑气纵横成网，封住毒蛾退路。然而一方虫王岂是易与之辈，吃痛之下，反击愈发猛烈。",
[2643]="毒蛾的鳞粉和毒雾令人防不胜防，缠斗之中你难免有所疏漏，毒雾逐渐侵袭脏腑，让你感觉呼吸都变得火烧火燎起来。",
[2644]="久战不利，你咬了咬牙，拼着肩胛被鳞粉腐蚀，换得近身的机会，凝聚了十成十灵力的一剑，狠狠刺穿了毒蛾的脑袋。",
[2645]="你连忙服下灵药压制毒性，在毒蛾的领地之内找到了青圭果，而后迅速离开。寻了清净之地祛毒疗伤后，你果断闭关修炼，借灵果之力成功让元神凝练了数倍，修为亦更进一步。",
[2646]="<color=#549327>[判定成功]</color> 毒蛾乃一方虫王，虽有负伤但依然根基深厚，如今你占了优势，若能引其游走消耗一番，当可省下不少力气。",
[2647]="你谨慎地拉开距离，游走为战，耐心地耗去其大半灵力，眼见毒蛾疲态尽显，你果断回身拉进距离，连斩十数剑，剑光锋芒大盛，终于将其斩杀。",
[2648]="毒蛾已死，你顺利在其领地之内找到了成熟的青圭果，欣喜地离开了此地。找了安全之处闭关消化所得，你的元神凝练之余，修为亦有进境。",
[2649]="<color=#c82c2c>[判定失败]</color> p1-毒蛾乃一方虫王，虽有负伤但根基深厚，如今你占了优势，若能引其游走消耗一番，当可省下不少力气。",
[2650]="你谨慎地拉开距离，欲游走为战，不料毒蛾十分警觉，竟趁机快速朝你反方向逃离，转瞬就消失得无影无踪。",
[2651]="眼见追之不及，你摇了摇头，转而四处搜寻青圭果的下落，最终却是一无所获，只得遗憾地离开了毒谷。",
[2652]="<color=#c82c2c>[判定失败]</color> 身形瞬动，你飞快地冲向毒蛾。长剑在手，剑气疾如风驰电掣，朝对方斩去，带着割裂空气的凌厉。",
[2653]="然而毒蛾却敏捷地躲开了你的攻击，趁你收势不及，朝你猛地喷出毒雾。你屏息晚了一霎，便觉头晕目眩。情急之下，你决定……？",
[2654]="<color=#549327>[判定成功]</color> 毒蛾已被激怒，此时若退恐怕小命不保，不如放手一搏。你打定主意，果断服下灵药压制毒性，全力抢攻！",
[2655]="心愈静，剑愈快，唯快不破！剑气如水银般倾泻而出，杀机四溢。一时间，毒蛾都被这样的气势慑住，行动慢了一瞬。你没有浪费这一线生机，拼着被毒蛾的鳞粉腐蚀左臂，狠厉一剑将毒蛾拦腰斩断。",
[2656]="毒蛾身亡，你迅速寻到了青圭果，妥帖藏好后立刻离开了毒谷。寻访名医祛毒疗伤之后，你在安全之处闭关修炼，借灵果之力，元神凝练之余，修为也更进一步。",
[2657]="<color=#c82c2c>[判定失败]</color> 毒蛾已被激怒，此时若退恐怕小命不保，不如放手一搏。然而毒蛾根基深厚，你虽服下灵药，但在接连动用灵力的情况下，毒性依然蔓延得很快，渐渐落入下风……",
[2658]="如此继续，小命难保，你的神思渐渐涣散，不得不咬破舌尖换一瞬清明。最终，拼着腹部受创，你抢出一剑逼退毒蛾数步，争得一个空档砸出传送符远遁……",
[2659]="毒性深入肺腑的情况下，你只能仓皇逃离毒谷，寻一处安全所在好好祛毒养伤。",
[2660]="毒蛾既为一方虫王，毒性猛烈霸道无比。为防猛毒深入肺腑，你只能祭出传送符远遁，拼命逃离毒谷，寻名医祛毒保命为重。",
[2661]="<color=#549327>[判定成功]</color> 借浓雾遮掩，你悄无声息地接近毒蛾，力求偷袭成功。手中长剑微挑，无声的剑气迅疾地击中了毒蛾的腹部，带出颜色诡异的血浆。",
[2662]="毒蛾颤抖着翻滚了两下，发出痛苦的鸣叫声，随后展翅盯住了你所在的方向。你决定……？",
[2663]="趁其痛取其命！你毫不犹豫地发动了进攻，剑气纵横成网，封住毒蛾退路。然而一方虫王岂是易与之辈，吃痛之下，反击愈发猛烈。",
[2664]="<color=#549327>[判定成功]</color> 毒蛾乃一方虫王，虽有负伤但依然根基深厚，如今你偷袭成功，若能引其游走消耗一番，当可省下不少力气。",
[2665]="你游走为战，谨慎地与之保持距离，耐心地耗去其大半灵力，眼见毒蛾疲态尽显，你果断回身拉进距离，连斩十数剑，剑光锋芒大盛，终于将其斩杀。",
[2666]="<color=#c82c2c>[判定失败]</color> 毒蛾乃一方虫王，虽有负伤但依然根基深厚，如今你偷袭成功，若能引其游走消耗一番，当可省下不少力气。",
[2667]="你谨慎地拉开距离，欲游走为战，不料毒蛾灵智过人，似乎料到了你的企图，竟然趁机快速朝你反方向逃离，转瞬就消失得无影无踪。",
[2668]="<color=#c82c2c>[判定失败]</color> 借浓雾遮掩，你悄无声息地接近毒蛾。然而毒蛾十分警觉，被剑气带出的灵力波动所惊动，振翅避开了你的偷袭。",
[2669]="趁你撤身不及，毒蛾迅速朝你袭来，翅羽上的鳞片竟似刀割般深深划伤了你的左肩，更落下不少有毒的鳞粉继续腐蚀你的血肉。情急之下，你决定……？",
[2670]="<color=#549327>[判定成功]</color> 毒蛾已被激怒，此时若退恐怕小命不保，不如放手一搏。你打定主意，果断服下灵药压制毒性，全力抢攻！心愈静，剑愈快，唯快不破！",
[2671]="剑气如水银般倾泻而出，铺天盖地，杀机四溢。一时间，毒蛾都被这样的气势慑住，行动慢了一瞬。你没有浪费这一线生机，狠厉一剑将毒蛾拦腰斩断。",
[2672]="毒蛾既死，你迅速寻到了青圭果，妥帖藏好后立刻离开了毒谷。寻访名医祛毒疗伤之后，你在安全之处闭关修炼，借灵果之力，元神凝练之余，修为也更进一步。",
[2673]="<color=#c82c2c>[判定失败]</color> 毒蛾已被激怒，此时若退恐怕小命不保，不如放手一搏。然而毒蛾根基深厚，凶猛的攻势令人十分难以招架。",
[2674]="你虽服下灵药，但在接连动用灵力的情况下，毒性依然蔓延得很快，渐渐落入下风……如此继续，小命难保，你的神思渐渐涣散，不得不咬破舌尖换一瞬清明。",
[2675]="最终，拼着腹部受创，你抢出一剑逼退毒蛾数步，争得一个空档砸出传送符远遁……毒性深入肺腑的情况下，你只能仓皇逃离毒谷，寻一处安全所在好好祛毒养伤。",
[2676]="半旬前，一座宏伟遗迹出现在天山腹地之内。近日接连有消息传出，其内藏有秘宝，对提升境界大有益处。",
[2677]="你迅速赶往天山，进入遗迹之内，一路过关斩将，终于抵达传闻中藏有秘宝的冰宫入口。你谨慎地放出神识探去，只见一名威压惊人的雪女在内中来回飘荡，呈守卫之态。你决定……？",
[2678]="正面抢攻 [概率判定]",
[2679]="冒雪埋伏[根骨判定]",
[2680]="<color=#549327>[判定成功]</color> 极寒之地，慢一步则步步慢，不如快速抢攻！你冲进冰宫，剑尖轻点，剑气陡然爆发，如星辰坠落般砸向雪女。",
[2681]="对方在同一时间有了应对，然而剑气之快，令其无法完全避开，一道剑光没入雪女的左肩，带出一蓬几近透明的血雾，令其发出了痛苦的啸叫。你决定……？",
[2682]="一击得手，你出剑更显凌厉！横剑扫过，剑气如同飓风般朝雪女席卷而去，对方被伤痛激起了凶性，狰狞地展开了反击。",
[2683]="整个冰宫沦为战场，暴雪冰锥和剑气往来交错，斗得难解难分。雪女不愧为冰宫守卫，强悍地猛攻之下，你身上也多出不少伤口。",
[2684]="感受着逐渐变得迟缓的动作，你猛地喝出一口白气，拼着侧腹被冰锥扎穿，换得间隙一剑刺穿了雪女的心口。",
[2685]="雪女既死，你连忙取走秘宝，低调地离开了遗迹。远离天山的你寻了处僻静所在安心养伤，恢复后闭关修炼，借秘宝之力，修为再进一步。",
[2686]="<color=#549327>[判定成功]</color> 虽然一击得手，但雪女的威压令你丝毫不敢大意。对方似有灵智，斗至两败俱伤实属下策，若能劝服其交出秘宝，方为上上策。",
[2687]="下定决心，你谨慎地与雪女保持距离，诚恳而努力地劝说着，更将灵剑还鞘以示不欲再次伤害对方……终于，对方的神态缓和下来，同意交出秘宝。",
[2688]="得到秘宝的你遵守约定，迅速退出冰宫转身离去。安全离开了遗迹的你找了僻静之处消化所得，修为又进一步。",
[2689]="<color=#c82c2c>[判定失败]</color> 虽然一击得手，但雪女的威压令你丝毫不敢大意。对方似有灵智，斗至两败俱伤实属下策，若能劝服其交出秘宝，方为上上策。",
[2690]="下定决心，你谨慎地与雪女保持距离，正欲劝说对方，不料雪女突然一抬手，你瞬间被暴风雪遮住了视野……",
[2691]="待风雪消散，冰宫内空空如也，雪女和秘宝都已消失无踪。未曾料想雪女跑得如此坚决，无奈之下，你只能哭笑不得地离开了冰宫，在秘境中搜寻到了一些冰属灵草，此行也不算空手而归了罢。",
[2692]="<color=#c82c2c>[判定失败]</color> 极寒之地，慢一步则步步慢，不如快速抢攻！你冲进冰宫，剑尖轻点，剑气陡然爆发，如星辰坠落般砸向雪女。",
[2693]="对方瞬间有了应对，速度竟不慢于迅疾剑气，几个晃动便避开了你的攻击，更是趁机抬手朝你狠狠抓下，闪避不及的你登时胸腹受创，抓痕如刀割一般，痛彻骨髓。受创之下，你决定……？",
[2694]="<color=#549327>[判定成功]</color> 雪女强悍，此时既已受创，再退更是凶险，不如放手一搏。",
[2695]="你的剑招更为大开大合，剑气悍然与雪女的攻击相撞，斗得整座冰宫连连震颤……最终，你拼着左臂被雪女的利爪撕裂，抢出一剑斩下了对方的头颅。",
[2696]="雪女既死，你顾不上包扎伤处，急忙取回冰宫中的秘宝，迅速离开了遗迹。寻了安全之处养好伤后，你果断闭关修炼，借秘宝之力，修为再进一步。",
[2697]="<color=#c82c2c>[判定失败]</color> 雪女强悍，此时既已受创，再退更是凶险，不如放手一搏。",
[2698]="然而雪女在冰宫中优势尽显，被冰雪包围的你出剑的速度越来越慢，渐渐落入下风……",
[2699]="最终，你拼着被迫吸入一大口冰雾，换来近距离抢出一剑逼退雪女数步，争得间隙砸出传送符远遁……肺腑受创之下，你只能仓皇逃离遗迹，寻一处安全所在好好养伤。",
[2700]="雪女既为冰宫守卫，实力强悍无需多言。为防极寒之气进一步侵蚀肺腑，你只能祭出传送符远遁，飞快地逃离遗迹，寻一处安全所在驱寒疗伤方为上策。",
[2701]="<color=#549327>[判定成功]</color> 雪女实力定然强悍，正面对敌恐落下风，冒雪设伏或有奇效。你趁其转身，身形瞬动，一道凌厉的剑气无声地袭向对方后心之处！",
[2702]="雪女有所察觉，却已然来不及完全闪避，晃身之下仍然被剑气穿透了蝴蝶骨，身形顿时一垮，令其发出了痛苦的啸叫。你决定……？",
[2703]="偷袭得手，你信心又增几分，一鼓作气趁胜追击！横剑扫过，剑气如同飓风般朝雪女席卷而去，对方被伤痛激起了凶性，狰狞地展开了反击。",
[2704]="<color=#549327>[判定成功]</color> 虽然偷袭得手让你多了几分底气，但雪女的威压令人丝毫不敢大意。对方似有灵智，若能劝服其交出秘宝，方为上上策。",
[2705]="<color=#c82c2c>[判定失败]</color> 虽然偷袭得手让你多了几分底气，但雪女的威压令人丝毫不敢大意。对方似有灵智，若能劝服其交出秘宝，方为上上策。",
[2706]="下定决心，你谨慎地与雪女保持距离，正欲劝说对方，不料雪女突然一抬手，你瞬间被暴风雪遮住了视野……待风雪消散，冰宫内空空如也，雪女和秘宝都已消失无踪。",
[2707]="未曾料想雪女跑得如此坚决，无奈之下，你只能哭笑不得地离开了冰宫，在秘境中搜寻到了一些冰属灵草，此行也不算空手而归了罢。",
[2708]="<color=#c82c2c>[判定失败]</color> 雪女实力定然强悍，正面对敌恐落下风，冒雪设伏或有奇效。你趁其转身，身形瞬动，一道凌厉的剑气无声地袭向对方后心之处！",
[2709]="然而雪女十分警觉，行动敏捷地侧身避开了这道偷袭的剑气，更是如飓风般瞬间拉进了与你的距离，尖锐的指甲狠狠扎穿了你的左臂，登时血流如注。情急之下，你决定……？",
[2710]="<color=#549327>[判定成功]</color> 雪女强悍如斯，此时既已受创，再退更是凶险，不如放手一搏。",
[2711]="你沉下心，出剑更为刁钻凶狠，凌厉的剑气悍然与雪女的攻击相撞，腾起大片冰霜……最终，你拼着侧腹被雪女的利爪撕裂，抢出一剑斩下了对方的头颅。",
[2712]="<color=#c82c2c>[判定失败]</color> 雪女强悍如斯，此时既已受创，再退更是凶险，不如放手一搏。然而雪女在冰宫中优势尽显，被冰雪包围的你行动越来越僵硬，身上新增许多伤口，渐渐落入下风……",
[2713]="雪女既为冰宫守卫，实力强悍无需多言。伤口的剧痛令你冷汗直流，心知优势尽失，你只能飞快地祭出传送符远遁，全速逃离遗迹，寻一处安全之地养伤方为上策。",
[2714]="游历至北地，是夜，你露宿山谷。不料子夜刚过，谷内忽然阴风阵阵，黑雾弥漫，煞气冲天，你登时被森寒煞气包围。只见黑雾之中，一名鬼将的身影逐渐清晰，其暗红的双眼缓缓锁定了你，你决定……？",
[2715]="锋芒不让",
[2716]="以退为进",
[2717]="修行至今，身经百战，既与邪祟狭路相逢，自当锋芒不让。你手腕一挑，剑光如练般袭向鬼将，对方亦朝你冲来……",
[2718]="鬼影幢幢，剑光纷纷，鬼气割破了你的法衣和脸颊，留下细碎的伤口，却更加激起了你的战意！越战越急，越战越凶，胜负将分……",
[2719]="长剑在你手中嗡鸣，正可谓剑气啸长空，过处惊鬼神，一剑定乾坤！剑光直没鬼将心口，下一瞬，对方的身躯化作粉尘随风而逝。",
[2720]="黑雾尽散，明月当空，此战已胜，你不禁开始回忆所有细节，在脑内再度演练起来，隐隐有所明悟。",
[2721]="鬼将已动，猛攻将至，正中你之下怀。以静制动，以退为进，以守为攻，你手中的剑与你的心神一样沉稳，剑光交错，防守得滴水不漏……",
[2722]="鬼气与剑光在黑雾中悍然相撞，每一下都是百十回交锋……渐渐地，鬼气越来越弱，剑光越来越盛，胜负将分！",
[2723]="你并指划过剑身，下一瞬，剑气啸长空，过处惊鬼神，一剑定乾坤！剑光划过鬼将的脖颈，对方登时身首异处，化作粉尘随风而逝。",
[2724]="南疆毒谷有奇光散溢，三月未散，是孕育千年的青圭果即将成熟的预兆。此果乃是罕有的奇珍，有凝练元神之功效。你穿越层层毒瘴进入毒谷深处，势要取得青圭果。",
[2725]="然而越是深入越是寂静得反常，你凝神戒备，只见浓雾之中正有一只巨大的毒蛾盘踞，俨然是虫王之姿。你决定……？",
[2726]="冲向毒蛾 [以木克土]",
[2727]="<color=#549327>[判定成功]</color> 毒蛾属土，你修炼木灵诀已久，当能以木克土。身形瞬动，你飞快地冲向目标，抬手便是澎湃木气凝成漫天青针，朝毒蛾狠狠扎去！",
[2728]="毒蛾察觉到危险，连忙振翅欲躲，然而速度却不及青针迅疾，登时被扎穿羽翅，发出痛苦的鸣叫声。你决定……？",
[2729]="此刻占了上风，你毫不犹豫地继续快攻，木气纵横成网，封住毒蛾退路。然而一方虫王岂是易与之辈，吃痛之下，反击愈发猛烈。",
[2730]="久战不利，你咬了咬牙，拼着肩胛被鳞粉腐蚀，换得近身的机会，运出木气化作长鞭，狠狠绞碎了毒蛾的脑袋。你连忙服下灵药压制毒性，在毒蛾的领地之内找到了青圭果，而后迅速离开。",
[2731]="寻了清净之地祛毒疗伤后，你果断闭关修炼，借灵果之力成功让元神凝练了数倍，修为亦更进一步。",
[2732]="你谨慎地拉开距离，游走为战，耐心地耗去其大半灵力，眼见毒蛾疲态尽显，你果断回身拉进距离，木气凝成绳网，看似柔软实则锋利无比，终于将其绞杀。",
[2733]="<color=#c82c2c>[判定失败]</color> 毒蛾乃一方虫王，虽有负伤但根基深厚，如今你占了优势，若能引其游走消耗一番，当可省下不少力气。",
[2734]="<color=#c82c2c>[判定失败]</color> 毒蛾属土，你修炼木灵诀已久，当能以木克土。身形瞬动，你飞快地冲向目标，木气凝成尖锐长矛，朝毒蛾用力捅去！",
[2735]="木属灵力如浪涛般倾泻而出，滚滚木气化作杀气四溢。一时间，毒蛾都被这样的气势慑住，行动慢了一瞬。你没有浪费这一瞬时机，拼着被毒蛾的鳞粉腐蚀左臂，木气成刀，干脆利落地将毒蛾拦腰斩断。",
[2736]="<color=#c82c2c>[判定失败]</color> 毒蛾已被激怒，此时若退恐怕小命不保，不如放手一搏。",
[2737]="然而毒蛾根基深厚，你虽服下灵药，但在接连动用灵力的情况下，毒性依然蔓延得很快，渐渐落入下风……如此继续，小命难保，你的神思渐渐涣散，不得不咬破舌尖换一瞬清明。",
[2738]="最终，拼着腹部受创，你抢出一招逼退毒蛾数步，争得一个空档砸出传送符远遁……毒性深入肺腑的情况下，你只能仓皇逃离毒谷，寻一处安全所在好好祛毒养伤。",
[2739]="<color=#549327>[判定成功]</color> 借浓雾遮掩，你悄无声息地接近毒蛾，力求偷袭成功。手中浓郁木气凝结，化作利箭，无声而迅疾地击中了毒蛾的腹部，带出颜色诡异的血浆。",
[2740]="趁其痛取其命！你毫不犹豫地发动了进攻，木气纵横成网，封住毒蛾退路。然而一方虫王岂是易与之辈，吃痛之下，反击愈发猛烈。",
[2741]="毒蛾的鳞粉和毒雾令人防不胜防，缠斗之中你难免有所疏漏，毒雾逐渐侵袭脏腑，让你感觉呼吸都变得灼热起来。",
[2742]="久战不利，你咬了咬牙，拼着肩胛被鳞粉腐蚀，换得近身的机会，以十成十的灵力化出木剑，狠狠刺穿了毒蛾的脑袋。",
[2743]="你游走为战，谨慎地与之保持距离，耐心地耗去其大半灵力，眼见对方疲态尽显，你果断运诀，木气成箭接连射出，将毒蛾扎成了筛子。",
[2744]="<color=#c82c2c>[判定失败]</color> 借浓雾遮掩，你悄无声息地接近毒蛾。然而毒蛾十分警觉，被木气凝结带出灵力波动所惊动，振翅避开了你的偷袭。",
[2745]="木属灵力如浪涛般倾泻而出，滚滚木气化作杀气四溢。一时间，毒蛾都被这样的气势慑住，行动慢了一瞬。你没有浪费这一瞬时机，拼着被毒蛾的鳞粉腐蚀左臂，木气成刀，狠狠地将毒蛾拦腰斩断。",
[2746]="毒蛾身亡，你迅速寻到了青圭果，妥帖藏好后立刻离开了毒谷。祛毒疗伤之后，你在安全之处闭关修炼，借灵果之力，元神凝练之余，修为也更进一步。",
[2747]="<color=#549327>[判定成功]</color> 你仗着身法迅捷，欲以快制胜，飞速冲向目标，抬手掐诀，澎湃灵力凝成漫天灵针，朝毒蛾狠狠扎去！",
[2748]="此刻占了上风，你毫不犹豫地继续快攻，灵力纵横成网，封住毒蛾退路。然而一方虫王岂是易与之辈，吃痛之下，反击愈发猛烈。",
