[2754]="趁其痛取其命！你毫不犹豫地发动了进攻，灵力纵横成网，封住毒蛾退路。然而一方虫王岂是易与之辈，吃痛之下，反击愈发猛烈。",
[2755]="久战不利，你咬了咬牙，拼着肩胛被鳞粉腐蚀，换得近身的机会，以十成十的灵力化成灵剑，狠狠刺穿了毒蛾的脑袋。",
[2756]="你游走为战，谨慎地与之保持距离，耐心地耗去其大半灵力，眼见对方疲态尽显，你果断运诀，以灵力作箭接连射出，将毒蛾扎成了筛子。",
[2757]="体内的灵力如浪涛般倾泻而出，你连续掐诀，术法变化之下杀气四溢。一时间，毒蛾都被这样的气势慑住，行动慢了一瞬。你没有浪费这一瞬时机，拼着被毒蛾的鳞粉腐蚀左臂，以灵力凝成长刀，狠狠地将毒蛾拦腰斩断。",
[2758]="如此继续，小命难保，你的神思渐渐涣散，不得不咬破舌尖换一瞬清明。",
[2759]="正面抢攻 [以土克水]",
[2760]="冒雪设伏 [根骨判定]",
[2761]="<color=#549327>[判定成功]</color> 你修习厚土诀也算有所成，雪女属水，当能以土克之！决意抢攻的你飞身进入冰宫，灵力化作浑厚土气附着于灵器之上，悍然砸向雪女。",
[2762]="对方一时被土气压制，闪避不及，左肩被狠狠砸中，露出可怖的裂痕，令其发出了痛苦的啸叫。你决定……？",
[2763]="趁胜追击",
[2764]="抢攻得手，你出招更显凌厉！握紧灵器狠狠一挥，厚土之力如同飓风般朝雪女席卷而去，对方被伤痛激起了凶性，狰狞地展开了反击。",
[2765]="整个冰宫沦为战场，暴雪冰锥和蕴含厚土之力的灵力往来交错，斗得难解难分。雪女不愧为冰宫守卫，强悍地猛攻之下，你身上也多出不少伤口。",
[2766]="感受着逐渐变得迟缓的动作，你猛地喝出一口白气，拼着侧腹被冰锥扎穿，换得间隙猛地用灵器刺穿了雪女的心口。",
[2767]="雪女既死，你迅速取走秘宝，低调地离开了遗迹。远离天山的你寻了处僻静所在安心养伤，恢复后闭关修炼，借秘宝之力，修为再进一步。",
[2768]="<color=#549327>[判定成功]</color> 虽然抢攻得手，但雪女的威压令你丝毫不敢大意。对方似有灵智，斗至两败俱伤实属下策，若能劝服其交出秘宝，方为上上策。",
[2769]="下定决心，你谨慎地与雪女保持距离，诚恳而努力地劝说着，更将灵器收起，以示不欲再次伤害对方……终于，对方的神态缓和下来，同意交出秘宝。",
[2770]="<color=#c82c2c>[判定失败]</color> 你修习厚土诀也算有所成，雪女属水，当能以土克之！决意抢攻的你飞身进入冰宫，灵力化作浑厚土气附着于灵器之上，悍然砸向雪女。",
[2771]="然而对方极为敏捷，一个快速闪身便避开了你的攻击，更是趁机凝成冰锥朝你射出，在你左肩留下一个血窟窿，极寒之气随即渗入骨髓。受创之下，你决定……？",
[2772]="<color=#549327>[判定成功]</color> p1-雪女强悍，此时既已受创，再退更是凶险，不如放手一搏。你的攻势更为大开大合，附着厚土之力的灵器悍然与雪女的攻击相撞，斗得整座冰宫连连震颤……",
[2773]="最终，你拼着左臂被雪女的利爪撕裂，在间隙中抢出一招，用灵器利落地斩下了对方的头颅。",
[2774]="<color=#c82c2c>[判定失败]</color> 雪女强悍，此时既已受创，再退更是凶险，不如放手一搏。然而雪女在冰宫中优势尽显，被冰雪包围的你灵力运转愈发迟缓，渐渐落入下风……",
[2775]="最终，你拼着被迫吸入一大口冰雾，换来近距离抢出一招逼退雪女数步，争得间隙砸出传送符远遁……肺腑受创之下，你只能仓皇逃离遗迹，寻一处安全所在好好养伤。",
[2776]="<color=#549327>[判定成功]</color> 雪女实力强悍，正面对敌恐落下风，冒雪设伏或有奇效。你趁其转身，身形瞬动，附着厚土之力的灵器无声地袭向对方后心之处！",
[2777]="雪女有所察觉，却已然来不及完全闪避，晃身之下仍然被灵器击穿了蝴蝶骨。厚土之气如蚀骨之毒，令其发出了痛苦的啸叫。你决定……？",
[2778]="偷袭得手，你信心又增几分，一鼓作气趁胜追击！灵器挥动之间，厚土之力如同飓风般朝雪女席卷而去，对方被伤痛激起了凶性，狰狞地展开了反击。",
[2779]="整个冰宫沦为战场，暴雪冰锥和厚土之力往来交错，斗得难解难分。雪女不愧为冰宫守卫，强悍地猛攻之下，你身上也多出不少伤口。",
[2780]="感受着逐渐变得迟缓的动作，你猛地喝出一口白气，拼着侧腹被冰锥扎穿，换得间隙以灵器狠狠刺穿了雪女的心口。",
[2781]="<color=#c82c2c>[判定失败]</color> 雪女实力定然强悍，正面对敌恐落下风，冒雪设伏或有奇效。你趁其转身，身形瞬动，附着厚土之力的灵器无声地袭向对方后心之处！",
[2782]="然而雪女十异常警觉，飞速侧身避开了你的偷袭，更是如飓风般瞬间拉进了与你的距离，尖锐的指甲狠狠扎穿了你的左臂，登时血流如注。情急之下，你决定……？",
[2783]="<color=#549327>[判定成功]</color> 雪女强悍如斯，此时既已受创，再退更是凶险，不如放手一搏。你沉下心，出招更为刁钻凶狠，雄浑的厚土之力悍然与雪女的攻击相撞，腾起大片冰霜……",
[2784]="最终，你拼着侧腹被雪女撕裂，抢出一招，灵器之上光华一瞬而没，利落地斩下了对方的头颅。",
[2785]="<color=#c82c2c>[判定失败]</color> 雪女强悍如斯，此时既已受创，再退更是凶险，不如放手一搏。然而雪女占尽地利，被寒冰包围的你灵力运转愈发迟缓，身上新增许多伤口，渐渐不支……",
[2786]="半旬前，一座宏伟遗迹出现在天山腹地之内。近日接连有消息传出，其内藏有秘宝，对提升境界大有益处。你迅速赶往天山，进入遗迹之内，一路过关斩将，终于抵达传闻中藏有秘宝的冰宫入口。",
[2787]="你谨慎地放出神识探去，只见一名威压惊人的雪女在内中来回飘荡，呈守卫之态。你决定……？",
[2788]="<color=#549327>[判定成功]</color> 极寒之地，慢一步则步步慢，不如快速抢攻！你冲进冰宫，连掐数十诀，灵气凝成利箭，如星辰坠落般砸向雪女。",
[2789]="对方在同一时间有了应对，然而此招极快，令其无法完全避开，一支灵箭没入雪女的左肩，带出一蓬几近透明的血雾，令其发出了痛苦的啸叫。你决定……？",
[2790]="一击得手，你出招更显凌厉！灵力在空中交织成带刺的巨网，朝雪女罩下，对方被伤痛激起了凶性，狰狞地展开了反击。",
[2791]="整个冰宫沦为战场，冰针冰刃和各式术法往来交错，雪女不愧为冰宫守卫，在其强悍地猛攻之下，你身上也多出不少伤口。",
[2792]="感受着逐渐变得迟缓的动作，你猛地喝出一口白气，拼着侧腹被冰锥扎穿，换得间隙凝成灵鞭，绞断了雪女的脖颈。",
[2793]="下定决心，你谨慎地与雪女保持距离，诚恳而努力地劝说着，更将双手摊开，以示不欲再次伤害对方……终于，对方的神态缓和下来，同意交出秘宝。",
[2794]="<color=#c82c2c>[判定失败]</color> 极寒之地，慢一步则步步慢，不如快速抢攻！你冲进冰宫，连掐数十诀，灵气凝成利箭，如星辰坠落般砸向雪女。",
[2795]="对方瞬间有了应对，敏捷地几个晃动便避开了你的攻击，更是趁机抬手朝你狠狠抓下，闪避不及的你登时胸腹受创，抓痕如刀割一般，痛彻骨髓。受创之下，你决定……？",
[2796]="<color=#549327>[判定成功]</color> 雪女强悍，此时既已受创，再退更是凶险，不如放手一搏。你的攻势更为大开大合，灵力凝成巨浪，悍然与雪女的攻击相撞，斗得整座冰宫连连震颤……",
[2797]="最终，你拼着左臂被雪女的利爪撕裂，抢出一招，以灵力凝成的长刀狠狠斩下了对方的头颅。",
[2798]="<color=#c82c2c>[判定失败]</color> 雪女强悍，此时既已受创，再退更是凶险，不如放手一搏。然而雪女在冰宫中优势尽显，被冰雪包围的你出招的速度越来越慢，渐渐落入下风……",
[2799]="<color=#549327>[判定成功]</color> 雪女实力强悍，正面对敌恐落下风，冒雪设伏或有奇效。你趁其转身，身形瞬动，以灵力凝成长矛，无声地袭向对方后心之处！",
[2800]="雪女有所察觉，却已然来不及完全闪避，晃身之下仍然被长矛击穿了蝴蝶骨，身形登时一垮，发出了痛苦的啸叫。你决定……？",
[2801]="偷袭得手，你信心又增几分，一鼓作气趁胜追击！术法接连使出，灵力澎湃如狂风呼啸朝雪女席卷而去，对方被伤痛激起了凶性，狰狞地展开了反击。",
[2802]="整个冰宫沦为战场，冰针冰刃和各式术法往来交错，斗得难解难分。雪女不愧为冰宫守卫，强悍地猛攻之下，你身上也多出不少伤口。",
[2803]="感受着逐渐变得迟缓的动作，你猛地喝出一口白气，拼着侧腹被冰锥扎穿，换得间隙凝成灵力长剑，狠狠刺穿了雪女的心口。",
[2804]="<color=#c82c2c>[判定失败]</color> 雪女实力定然强悍，正面对敌恐落下风，冒雪设伏或有奇效。你趁其转身，身形瞬动，以灵力凝成长矛，无声地袭向对方后心之处！",
[2805]="<color=#549327>[判定成功]</color> 雪女强悍如斯，此时既已受创，再退更是凶险，不如放手一搏。你沉下心，出招更为刁钻凶狠，澎湃的灵力悍然与雪女的攻击相撞，腾起大片冰霜……",
[2806]="最终，你拼着侧腹被雪女撕裂，抢出一招，灵力迅速凝成长刀，利落地斩下了对方的头颅。",
[2807]="游历至北地，是夜，你露宿山谷。不料子夜刚过，谷内忽然阴风阵阵，黑雾弥漫，煞气冲天，你登时被森寒阴气包围。只见黑雾之中，一名鬼将的身影逐渐清晰，其暗红的双眼缓缓锁定了你，你决定……？",
[2808]="修行至今，身经百战，既与邪祟狭路相逢，自当锋芒不让。法袍在灵力的凝聚过程中翻飞，术法随着你的指诀接连运出，袭向冲来的鬼将……",
[2809]="鬼影幢幢虚实难测，术法变化万千，鬼气割破了你的法衣和脸颊，留下细碎的伤口，却更加激起了你的战意！越战越急，越战越凶，胜负将分……",
[2810]="你凝神屏息，灵器在手中绽放出耀眼的光芒，浓郁的灵力附着其上，一招定乾坤！灵器携带术法之威，如流光般没入鬼将心口，下一瞬，对方的身躯化作粉尘随风而逝。",
[2811]="鬼将已动，猛攻将至，正中你之下怀。以静制动，以退为进，以守为攻，你沉心静气地快速掐诀，灵力凝成巨网，一瞬百化，防守得滴水不漏……",
[2812]="鬼气与灵力在黑雾中悍然相撞，每一下都是百十回交锋……渐渐地，鬼气越来越弱，术法越变越猛，胜负将分！",
[2813]="你连掐数百诀，下一瞬，灵力如风暴般炸开又急速汇聚，凝结成明亮得犹如实质一般的长鞭，狠狠绞住了鬼将的脖颈，对方登时身首异处，化作粉尘随风而逝。",
[2814]="<color=#3375c0>[资质判定]</color> 闭关打坐修炼。山中无历日，寒尽不知年……",
[2815]="<color=#549327>[判定成功]</color> 出关时，修为更进一步。",
[2816]="<color=#c82c2c>[判定失败]</color> 修行却入瓶颈，心愈躁则不稳，无奈之下，只能出关再寻机缘。",
[2817]="<color=#3375c0>[资质判定]</color> 夏日晴空，你于山巅远眺，正巧见一雏鹰自悬崖跳下，竭力扑腾，终于在坠地之前展翅高飞……",
[2818]="<color=#549327>[判定成功]</color> 好一个鹰击长空！你内心动容，体悟之下，心境有所提升。",
[2819]="<color=#c82c2c>[判定失败]</color> 雏鹰尚能勉力飞翔，缘何自身修行却入瓶颈？你长叹一声，默然伤神。",
[2820]="<color=#3375c0>[资质判定]</color> 寒冬凛冽，草木成枯。你于雪中静思，感受着萧杀之下，深埋在厚厚土层之中的倔强生机……",
[2821]="<color=#549327>[判定成功]</color> 年年岁岁，枯荣轮转，你由此悟出生死相牵之道，随即闭关。出关之时，修为大涨。",
[2822]="<color=#c82c2c>[判定失败]</color> 年年岁岁，枯荣轮转，而己身之道究竟为何？你陷入苦思，却终究不得明悟。",
[2823]="<color=#3375c0>[资质判定]</color> 闭关静心悟道。岁月不知数，花开又几春……",
[2824]="<color=#549327>[判定成功]</color> 出关时，对己身之道理解更为深刻，修为亦有进境。",
[2825]="<color=#c82c2c>[判定失败]</color> 万千大道，何道与己契合？心境已生波澜，你无奈出关，只能静待下一次机缘。",
[2826]="极南之地有地火喷发，千里之外亦有震动。你听闻此事，动身前去一探究竟。热气蒸腾，火焰如柱，岩浆横流，你一一避开，终于在一处山腹内寻到一块至纯火精，其内蕴含的能量令你欣喜非常。",
[2827]="回宗之后，你立刻闭关，将这块火精的能量逐步吸收……待最后一丝能量融入体内灵海，你之气息开始逐节攀升……双目一睁，精光湛然！你长吁一口气，已至炼虚境界。",
[2828]="炼虚已成",
[2829]="火精能量助你突破，你顺利进阶至炼虚期。",
[2830]="长钟响，山门开。你看着青涩的新弟子三三两两地走进宗门，前往悟心堂接受一系列的入门考验，顿觉岁月飞逝。",
[2831]="今日巡视传功殿，一下逮住三名打瞌睡偷懒的内门弟子。你命这三人到殿外的空地站好，左手轻轻一握便聚起三块大石，一人一块，压得三个弟子咬牙支撑。",
[2832]="“既然瞌睡，便站在这醒醒神吧，扛三个时辰即可。”你微微一笑，飘然离去，毫不意外地听到身后响起三道如出一辙的吸气声。",
[2833]="骄狂自大！戒。贪墨成性！戒。迷糊忘事！戒……戒律堂内，每一个静心蒲团上都盘坐着一名弟子，你慎重地挨个检查，拔除对应的怪癖，将他们引回正途。",
[2834]="敌对宗门叫嚣约战，当战便战！战局明朗，敌对宗门兵败如山倒，你顺势接收了大批俘虏。牢狱森森，拷问不断……成功从俘虏嘴里撬出不少秘境宝图、灵物资源，宗门底蕴又厚数分。",
[2835]="<color=#3375c0>[资质判定]</color> 今日无事，正可与同修共饮。玉液琼浆天上有，饮尽千杯欲摘星……",
[2836]="<color=#549327>[判定成功]</color> 知己相伴，心境通透，则万念通达。酒醒时，修为又有进境。",
[2837]="<color=#c82c2c>[判定失败]</color> 一醉何年？虚度百载亦无妨，不过刹那光阴。",
[2838]="<color=#3375c0>[资质判定]</color> 你与宗内的其他长老论道，以求取长补短，互相印证……",
[2839]="<color=#549327>[判定成功]</color> 一场论道下来，对比金丹元婴期之眼界悟性，所得堪称云泥之别。你随即闭关将论道所得彻底消化，出关之时，修为有所进境。",
[2840]="<color=#c82c2c>[判定失败]</color> 然而一场论道下来，你与其他长老未能互相说服对方，各执己见得险些大动肝火，闹了个不欢而散。",
[2841]="你的师父大限将至，闭死关至坐化而未能出，同门皆悲戚不已，你也红了眼眶，心境难免有所动荡。修行之路何其艰难，放缓了无数时光的生老病死方为寻常，飞升之辈终究万中无一。",
[2842]="<color=#3375c0>[资质判定]</color> 今日悟道，一时不察，心魔作祟……",
[2843]="<color=#549327>[判定成功]</color> 所幸你并未被其所惑，而是在其诱惑之下再次坚定道心，随后毫不动摇地将之及时斩杀。心魔灭，心境大有提升，修为亦随之大进。",
[2844]="<color=#c82c2c>[判定失败]</color> 一番艰难地自我抗争之后，你终于斩杀了心魔，然而终究是元气大伤，修养了许久才勉强将心境重新稳固。",
[2845]="有道是物极必反。听闻极北之地有极阳之水，得之可炼体，亦可提升修为境界。你做好万全准备，前去一探究竟。",
[2846]="横跨冰原，避开无数深渊裂谷，在炼虚期之修为亦觉得难捱的寒风之中艰难跋涉……",
[2847]="功夫不负有心人，你终于寻到了传说中的极阳之水，更收集了不少极北寒泉，一并带回宗门。",
[2848]="极寒极阳，相融相合，你闭关耐心地打熬自身体魄，稳步提升修为……随着体魄打磨圆满，你之修为也水到渠成地突破至合体期。",
[2849]="已至合体",
[2850]="寒阳相合，打熬体魄，提升修为，你顺利进阶至合体期。",
[2851]="你不定期暗中前往依附宗门的各个家族巡视，查看是否极具潜力的好苗子是否都已纳入门中，不曾被刻意打压或是意外遗漏。",
[2852]="一名内门弟子在传功时，险些走火入魔，幸好你及时察觉，将其救回。",
[2853]="看着这名弟子脸色惨白的模样，你微微一叹，给了对方一颗清心丹，让他回去好好休息。 同时也暗自警惕，修行一途，需时刻警醒，稍有不慎便是粉身碎骨。",
[2854]="在宗门内拉帮结派，逞凶斗殴，罚！你看着押入戒律堂的数名内门骄子，毫不留情地给几人扣上神魂锁，然后罚入寒池三年，以示惩戒。",
[2855]="有奸细试图潜入宗门之内，却未能逃过你的金睛火眼。千里之堤溃于蚁穴，你绝不放任奸细妄为，押回狱中一番拷问，果然又有收获。",
[2856]="合体修士，对天地法则之感悟已然更进一步，己身之道也日趋完满……宗门杂事在你眼中渺如浮尘，自有后辈接替。你之所求，不过一心向道！",
[2857]="山中一日，世上百年。你打坐运功，参悟大道，外界风云变幻，恍若隔世。",
[2858]="<color=#3375c0>[资质判定]</color> 良辰吉日，正可闭关。你于洞府中静坐，以心观万物，以神悟道法……",
[2859]="<color=#549327>[判定成功]</color> 待你出关，修为又进。山中桃花依旧，宗门弟子不知又添了几代，可谓时光荏苒，岁月如梭。",
[2860]="<color=#c82c2c>[判定失败]</color> 然而山中桃花依旧，你之修为却入瓶颈。修行之路，果真是逆天而行，越至后期，越难更进一步。",
[2861]="<color=#3375c0>[资质判定]</color> 闭关许久，你意外陷入欲念漩涡。生有善念，恶似影随，你被不断放大的阴暗面悄然蚕食……",
[2862]="<color=#549327>[判定成功]</color> 正陷混沌之时，宗门的静心钟按时响起，悠悠钟鸣九响，撞入你之脑海，将沉沦于欲念之海的你猛然惊醒。",
[2863]="你一鼓作气净化了作祟的阴暗欲念，更是由此捕捉到突破的契机。耐心体悟之下，出关时，修为又进一步。",
[2864]="<color=#c82c2c>[判定失败]</color> 所幸宗门的静心钟按时响起，悠悠钟鸣九响，撞入你之脑海，将沉沦于欲念之海的你猛然惊醒。",
[2865]="用尽全力净化了作祟的阴暗欲念，你仍然后怕不已，此一遭险些跌落境界，令你不得不花了极大心力巩固修为，打磨心境。",
[2866]="<color=#3375c0>[资质判定]</color> 自然为友，天地为师。洞府之中，闭关的你神识漫游无尽，虚空之中奥妙无穷……",
[2867]="<color=#549327>[判定成功]</color> 直至领悟天人合一的境界，你功成出关，修为又有进境。而洞口蛛网层叠，藤萝幽幽，不知过去多少年岁。",
[2868]="<color=#c82c2c>[判定失败]</color> 然而虚空无尽，不知耗去多少年月，你心境陡生波澜，被迫从入定中醒转，与进境的契机失之交臂。",
[2869]="念随心动，你指间点出两道虚影，生得一般无二，正是你神识化身。二者或比剑法，或斗术法，你来我往，势均力敌。无数玄妙的轨迹落入你的眼中，演练十次、百次、千万次……",
[2870]="尚有欠缺之处在不断的演练中逐渐圆满，你与己身相搏，亦是一场自省论道，待虚影功成而散，你顿时入定……气息逐节攀升，关窍一一打通……待你睁开双目，浑身气息愈发深远缥缈，令人无法参透。如此，已然晋入大乘。",
[2871]="晋入大乘",
[2872]="自省论道，入定突破，你顺利进阶至大乘期。",
[2873]="晋入大乘，你感知到自身所限，明白不能再拘于一宗之内。于是你再次离开宗门游历天下，赏奇景、访旧友，随意而为，方能再有进境。",
[2874]="<color=#3375c0>[资质判定]</color> 你在一处四季如春的山谷流连了许久，此地奇花如海，绚烂绽放……",
[2875]="<color=#549327>[判定成功]</color> 你在繁花的簇拥中打坐体悟，与万花相连，用心感受此地的勃勃生机，呼吸之间暗合天地韵律，修为有所进境。",
[2876]="<color=#c82c2c>[判定失败]</color> 然而花期短暂，你眼见万花凋零，不由思及自身，求道之路何其艰辛，一时间慨叹不已。",
[2877]="<color=#3375c0>[资质判定]</color> 你与一刀修相约，于极寒山巅展开一场旷世对决。强大的威压漫天彻地，冰雾蓬飞四溅……你们斗至酣处，虚实瞬换，千百回相交，灵力激荡至山崩地裂，冰雪滚滚如洪流咆哮而下……",
[2878]="<color=#549327>[判定成功]</color> 互不相让，生死相博，畅快至极！你们斗了十天十夜，终至力竭，你虽输了半招，心境却有提升。离开后闭关消化所得，修为又进一步。",
[2879]="<color=#c82c2c>[判定失败]</color> 互不相让，生死相博，畅快至极！斗了十天十夜，终至力竭，你输得心服口服，主动相邀对方畅饮三天，不醉不归！",
[2880]="<color=#3375c0>[资质判定]</color> 四处游历，拜访各地大宗的你，有时兴之所至，也会在别宗讲道授业……",
[2881]="<color=#549327>[判定成功]</color> 讲道时，你亦能查漏补缺，愈发完善己身之道。日积月累之下，修为又有进境。",
[2882]="<color=#c82c2c>[判定失败]</color> 修仙一途，靠的正是代代传承，你所讲之道，往往言简意赅，由浅入深，每每看到听道的后辈似有所悟，你亦觉欣慰。",
[2883]="旧友相邀，你与其前往凡人俗世转了一圈。人间改朝换代，城池变迁，曲成新调；凡人寿命短暂如朝露，依旧忙碌奔波，为新的晨光，也为后代盛世……你与旧友虽为过客，仍旧会被这俗世烟火的蓬勃朝气感染，亦有动容。",
[2884]="你于一处终日被山岚笼罩的青山上开辟了自己的洞府，在外围设下禁制，内中按照心意布置出样式古朴的青瓦小舍、亭台楼阁。",
[2885]="其间竹林簌簌，桃李成林，溪泉成景，令你十分满意。 在这一方天地之内待客、自省、修行……",
[2886]="昼夜轮替，四时更番，终于，你捕捉到一丝玄而又玄的气息，随即闭关开始突破……一念通彻，天道烙印降下，你已步入渡劫期。",
[2887]="步入渡劫",
[2888]="一念通彻，你成功步入渡劫期。",
[2889]="步入渡劫期后，天道烙印刻在体内，你冥冥中能够感知到自己将于何时渡劫，随即迅速行动起来，不断打磨道心的同时，也需尽早为渡劫飞升多做准备。",
[2890]="<color=#3375c0>[资质判定]</color> 你开始频繁出入各种秘境险地，搜寻天材地宝，动用一切手段拜访炼器大师，只为全力打造最好的渡劫法宝……",
[2891]="<color=#549327>[判定成功]</color> 也许是一直行善积德，得天道垂怜，你运气不错，陆续寻找到数种极珍稀的资源，也成功说服炼器大师出手，最终打造出了五件极品渡劫法宝，令你心下大定。",
[2892]="<color=#c82c2c>[判定失败]</color> 可惜天不遂人愿，几次寻宝都被人捷足先登，又逢天下第一的炼器大师闭关未出……最终未能备下渡劫法宝，令你十分不安。",
[2893]="做好渡劫的准备之后，你便开始给旧友传讯，邀人前来旁观你渡劫飞升之事。",
[2894]="天劫将至，极其玄奥的天道气息显露端倪。霎时八方云动，汹涌翻滚扩散，你感受到一种极其可怖的威压在高空中蔓延开来，立时聚精会神严阵以待。下一刻，天雷如同一道黑紫色的光柱，从劫云之中凌厉劈下……！",
[2895]="雷劫眨眼之间就近在眼前，周遭灵气化作滚滚浪涛，仿佛连空间都将要扭曲一般。不及多想，你纵身而起，将渡劫法宝倏然祭出！",
[2896]="……第一道雷，第二道雷，第三道雷……天雷一道接着一道，不带停歇地悍然劈下，渡劫法宝在赫赫天威之下化作飞灰，你只能长啸一声，运起全部力量释放而出，以对雷劫！",
[2897]="轰！！！通身法衣破烂，形容狼狈的你终究是抵不住天威，狰狞的雷光将你吞噬殆尽，在无尽的疼痛中，你感觉自己的生机在一点点流逝。",
[2898]="最后那一刻，眼前浮现出一张熟悉又陌生的面容，你瞬间记起了所有……“原来，我是……”漫天雷云消散一空，你微弱的话音散落在风中，没有任何人再能听见……",
[2899]="前尘梦醒",
[2900]="天劫之下，前尘犹如梦醒。此生虽尽，道途且长。",
[2901]="雷劫眨眼之间就近在眼前，周遭灵气化作滚滚浪涛，仿佛连空间都将要扭曲一般。不及多想，你纵身而起！",
[2902]="然而劫雷何其可怖，第一道雷便打得你经脉寸断，第二道雷再劈得你五感皆失……\n第三道雷轰然而下，你被电光笼罩，刹那间灰飞烟灭……",
[2903]="没有渡劫法宝护身的你，在天劫中灰飞烟灭。",
[2904]="修行如逆水行舟，不进则退。寿元耗尽，再也无法继续漫漫仙途。",
}
